/// Stable, restoreable route identity.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub(crate) enum SettingsRoute {
    #[default]
    Home,
    Modified,
    Manual,
    Appearance,
    Themes,
    TextFonts,
    CursorMotion,
    CursorStyles,
    WindowTabs,
    TabColor,
    Wallpaper,
    KeyboardInput,
    Terminal,
    Security,
    SoftwareUpdate,
    Packages,
    Harness,
    Ai,
    Tabs,
    Messages,
    About,
    Sound,
}

impl SettingsRoute {
    pub(crate) const ALL: [Self; 22] = [
        Self::Home,
        Self::Modified,
        Self::Manual,
        Self::Appearance,
        Self::Themes,
        Self::Wallpaper,
        Self::TextFonts,
        Self::CursorMotion,
        Self::CursorStyles,
        Self::Sound,
        Self::WindowTabs,
        Self::TabColor,
        Self::KeyboardInput,
        Self::Terminal,
        Self::Harness,
        Self::Ai,
        Self::Tabs,
        Self::Security,
        Self::SoftwareUpdate,
        Self::Packages,
        Self::Messages,
        Self::About,
    ];

    pub(crate) const fn path(self) -> &'static str {
        match self {
            Self::Home => "/home",
            Self::Modified => "/modified",
            Self::Manual => "/manual",
            Self::Appearance => "/appearance",
            Self::Themes => "/themes",
            Self::TextFonts => "/text-fonts",
            Self::CursorMotion => "/cursor-motion",
            Self::CursorStyles => "/cursor-styles",
            Self::WindowTabs => "/window-tabs",
            Self::TabColor => "/tab-color",
            Self::Wallpaper => "/wallpaper",
            Self::KeyboardInput => "/keyboard-input",
            Self::Terminal => "/terminal",
            Self::Security => "/security",
            Self::SoftwareUpdate => "/updates",
            Self::Packages => "/packages",
            Self::Harness => "/harness",
            Self::Ai => "/ai",
            Self::Tabs => "/tabs",
            Self::Messages => "/messages",
            Self::About => "/about",
            Self::Sound => "/sound",
        }
    }

    pub(crate) const fn label(self) -> &'static str {
        match self {
            Self::Home => "Top Settings",
            Self::Modified => "Modified",
            Self::Manual => "Manual",
            Self::Appearance => "Appearance",
            Self::Themes => "Themes",
            Self::TextFonts => "Text & Fonts",
            Self::CursorMotion => "Cursor & Motion",
            Self::CursorStyles => "Cursor Styles",
            Self::WindowTabs => "Window",
            Self::TabColor => "Tab Color",
            Self::Wallpaper => "Wallpaper",
            Self::KeyboardInput => "Keyboard & Input",
            Self::Terminal => "Terminal",
            Self::Security => "Security",
            Self::SoftwareUpdate => "Software Update",
            Self::Packages => "Packages",
            Self::Harness => "Harness",
            Self::Ai => "AI CLIs",
            Self::Tabs => "Tab Control",
            Self::Messages => "Messages",
            Self::About => "About",
            Self::Sound => "Sound",
        }
    }

    pub(crate) fn from_path(path: &str) -> Option<Self> {
        // The page's former path still opens it.
        if path == "/cursor-kitty" {
            return Some(Self::CursorStyles);
        }
        if path == "/agents" {
            return Some(Self::Harness);
        }
        if matches!(
            path,
            "/tab-control"
                | "/control-panel"
                | "/fleet"
                | "/monitor"
                | "/fleet-monitor"
                | "/system-monitor"
        ) {
            return Some(Self::Tabs);
        }
        Self::ALL.into_iter().find(|route| route.path() == path)
    }

    /// The rail entry a sub-page lives under.
    pub(crate) const fn rail_parent(self) -> Option<Self> {
        match self {
            Self::Themes => Some(Self::Appearance),
            Self::Ai | Self::Tabs => Some(Self::Harness),
            _ => None,
        }
    }

    /// Whether the rail lists a row for this route whatever page shows.
    #[cfg(test)]
    pub(crate) const fn on_rail(self) -> bool {
        self.rail_parent().is_none()
    }

    #[cfg(test)]
    fn rail_len() -> usize {
        Self::ALL
            .into_iter()
            .filter(|route| route.on_rail())
            .count()
    }

    const fn section(self) -> Option<Section> {
        match self {
            Self::Appearance => Some(Section::Appearance),
            Self::TextFonts => Some(Section::Typography),
            Self::CursorMotion => Some(Section::Cursor),
            Self::CursorStyles => Some(Section::CursorStyles),
            Self::Sound => Some(Section::Sound),
            Self::WindowTabs => Some(Section::Window),
            Self::KeyboardInput => Some(Section::Input),
            Self::Terminal => Some(Section::Terminal),
            Self::Security => Some(Section::Security),
            Self::Harness => Some(Section::Harness),
            Self::Home
            | Self::Modified
            | Self::Manual
            | Self::Themes
            | Self::TabColor
            | Self::Wallpaper
            | Self::SoftwareUpdate
            | Self::Packages
            | Self::Ai
            | Self::Tabs
            | Self::Messages
            | Self::About => None,
        }
    }
}

struct PendingConfig {
    patch: ConfigPatch,
    submitted: Vec<(String, crate::native_text_input::TextInputState)>,
    follows: Vec<OperationId>,
    kind: WriteKind,
    shown_before: BTreeMap<String, Option<String>>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum WriteKind {
    Change,
    Revert { to: String },
    KeepColours { label: String },
}

impl WriteKind {
    fn landing_words(&self, change: ChangeWords) -> ChangeWords {
        let status = match self {
            Self::Change => return change,
            Self::Revert { to } => format!("Reverted to {to}"),
            Self::KeepColours { label } => {
                format!("Kept {label}'s colors and your type settings")
            }
        };
        ChangeWords { status, ..change }
    }

    fn refused_words(&self, why: &str) -> Option<String> {
        match self {
            Self::Change => None,
            Self::Revert { to } => Some(format!("Couldn\u{2019}t revert to {to}: {why}")),
            Self::KeepColours { label } => {
                Some(format!("Couldn\u{2019}t keep {label}'s colors: {why}"))
            }
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Underlay {
    raw: Option<String>,
    seed: Option<Option<String>>,
}

fn show_config_value(
    fields: &mut [EditField],
    raw: &mut BTreeMap<String, String>,
    index: Option<usize>,
    key: &str,
    value: Option<&str>,
) {
    if let Some(value) = value {
        raw.insert(key.to_string(), value.to_string());
    } else {
        raw.remove(key);
    }
    let Some(field) = index.and_then(|index| fields.get_mut(index)) else {
        return;
    };
    if !matches!(field.kind, EditKind::Bool) {
        field.seed = value.map(str::to_string);
    } else if let Some(value) = value {
        field.seed = Some(value.to_string());
    } else if let Some(default) = switch_default(key) {
        field.seed = Some(default.to_string());
    }
}

enum PendingAction {
    Config(PendingConfig),
    ConfigEditor,
    Undo(UndoOffer),
    External,
    Update,
    Packages,
    Clipboard,
    PathCopy,
    Message,
    MessageCopy,
    LogFolder,
    Themes,
}

impl PendingAction {
    fn shown_edits(&self) -> Vec<(&str, Option<&str>)> {
        match self {
            Self::Config(request) => request
                .patch
                .edits
                .iter()
                .map(|edit| (edit.key.as_str(), edit.value.as_deref()))
                .collect(),
            Self::Undo(offer) => offer
                .restores
                .iter()
                .map(|(key, value)| (key.as_str(), value.as_deref()))
                .collect(),
            _ => Vec::new(),
        }
    }
}

