#[derive(Clone, Debug, PartialEq, Eq)]
struct ThemePickerExtras {
    filter: crate::native_text_input::TextInputState,
    loaded: usize,
    files: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PickerCell {
    Option(usize),
    Action(usize),
}

const THEME_PICKER_ACTION_CELLS: usize = 3;

const THEME_FILES_HEADING: &str = "Theme files";

#[derive(Clone, Debug, PartialEq, Eq)]
enum PickerRow {
    Heading(&'static str),
    Cells(std::ops::Range<usize>),
}

fn picker_rows(
    count: usize,
    columns: usize,
    headed: bool,
    section: impl Fn(usize) -> Option<&'static str>,
) -> Vec<PickerRow> {
    let columns = columns.max(1);
    let mut rows = Vec::new();
    let mut start = 0;
    while start < count {
        let heading = section(start);
        let mut end = start + 1;
        while end < count && (!headed || section(end) == heading) {
            end += 1;
        }
        if headed
            && let Some(heading) = heading
            && section_captioned(heading)
        {
            rows.push(PickerRow::Heading(heading));
        }
        let mut first = start;
        while first < end {
            let last = (first + columns).min(end);
            rows.push(PickerRow::Cells(first..last));
            first = last;
        }
        start = end;
    }
    rows
}

fn section_captioned(heading: &str) -> bool {
    heading != ThemeSection::Current.label()
}

fn picker_heading_height() -> f32 {
    group_heading_label_height()
}

fn picker_row_height(row: &PickerRow) -> f32 {
    match row {
        PickerRow::Heading(_) => picker_heading_height(),
        PickerRow::Cells(_) => scaled_control_height(),
    }
}

fn picker_rows_height(rows: &[PickerRow], gap: f32) -> f32 {
    rows.iter().map(picker_row_height).sum::<f32>() + rows.len().saturating_sub(1) as f32 * gap
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PickerMeasure(u32);

impl PickerMeasure {
    const fn new(value: f32) -> Self {
        Self(value.to_bits())
    }

    const fn get(self) -> f32 {
        f32::from_bits(self.0)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ChoicePicker {
    key: String,
    options: Vec<ChoiceOption>,
    selected: usize,
    offset: Cell<usize>,
    room: Cell<PickerMeasure>,
    gap: Cell<PickerMeasure>,
    columns: Cell<usize>,
    followed: Cell<Option<usize>>,
    reveal_pending: Cell<Option<usize>>,
    shown: Vec<usize>,
    seed_named: Vec<usize>,
    fonts: bool,
    filter: String,
    themes: Option<ThemePickerExtras>,
    trailing: Cell<usize>,
    slot: Option<aterm_types::Appearance>,
}

impl ChoicePicker {
    fn new(
        key: &str,
        options: impl IntoIterator<Item = String>,
        current: &str,
        show_reset: bool,
        current_is_authored: bool,
        effective_default: &str,
    ) -> Self {
        let current = if current_is_authored {
            current.trim()
        } else {
            current.strip_suffix(" (default)").unwrap_or(current).trim()
        };
        let current = trail_style_row_value(key, current);
        let option_label = |value: &str| setting_choice_label(key, value);
        let options = options.into_iter().collect::<Vec<_>>();
        let mut means = options.clone();
        let mut authored = options
            .into_iter()
            .map(|value| ChoiceOption::plain(option_label(&value), Some(value)))
            .collect::<Vec<_>>();
        if let Some(index) = means
            .iter()
            .position(|value| value.eq_ignore_ascii_case(effective_default))
        {
            let option = &mut authored[index];
            if !option.label.eq_ignore_ascii_case("default") {
                option.label = format!("{} (default)", option.label);
            }
            option.value = None;
        } else if show_reset {
            authored.insert(
                0,
                ChoiceOption::plain(
                    format!("Use default ({})", option_label(effective_default)),
                    None,
                ),
            );
            means.insert(0, effective_default.to_string());
        }
        if current_is_authored
            && !means
                .iter()
                .any(|value| value.eq_ignore_ascii_case(current))
        {
            authored.push(ChoiceOption::plain(
                format!("{} (current)", option_label(current)),
                Some(current.to_string()),
            ));
            means.push(current.to_string());
        }
        let selected = if current_is_authored {
            means
                .iter()
                .position(|value| value.eq_ignore_ascii_case(current))
        } else {
            authored.iter().position(|option| option.value.is_none())
        }
        .unwrap_or(0);
        Self::assemble(key, authored, selected, None)
    }

    fn assemble(
        key: &str,
        options: Vec<ChoiceOption>,
        selected: usize,
        themes: Option<ThemePickerExtras>,
    ) -> Self {
        let shown = (0..options.len()).collect();
        Self {
            key: key.to_string(),
            options,
            selected,
            offset: Cell::new(0),
            room: Cell::new(PickerMeasure::new(f32::INFINITY)),
            gap: Cell::new(PickerMeasure::new(6.0)),
            columns: Cell::new(1),
            followed: Cell::new(None),
            reveal_pending: Cell::new(None),
            shown,
            seed_named: Vec::new(),
            fonts: false,
            filter: String::new(),
            themes,
            trailing: Cell::new(0),
            slot: None,
        }
    }

    fn for_themes(
        themes: &crate::app_config::ThemeCatalog,
        current: &str,
        explicit: bool,
        current_is_authored: bool,
    ) -> Self {
        Self::for_themes_in(
            themes,
            theme_picker_rows(themes),
            current,
            explicit,
            current_is_authored,
        )
    }

    fn for_themes_in(
        themes: &crate::app_config::ThemeCatalog,
        mut rows: Vec<ChoiceOption>,
        current: &str,
        explicit: bool,
        current_is_authored: bool,
    ) -> Self {
        let limits = themes.limits();
        let loaded = themes.ready_names().count();
        let extras = ThemePickerExtras {
            filter: crate::native_text_input::TextInputState::new(String::new()),
            loaded,
            files: limits.seen.max(themes.listing().count()),
        };
        let current = if current_is_authored {
            current.trim()
        } else {
            current.strip_suffix(" (default)").unwrap_or(current).trim()
        };
        let names = |option: &ChoiceOption, wanted: &str| {
            option
                .value
                .as_deref()
                .or(option.theme.as_ref().map(|theme| theme.id.as_str()))
                .is_some_and(|value| value.eq_ignore_ascii_case(wanted))
                && option.disabled_reason().is_none()
        };
        if current_is_authored && !rows.iter().any(|option| names(option, current)) {
            rows.insert(
                0,
                ChoiceOption {
                    label: format!("Current{FACT_SEPARATOR}{current}"),
                    value: Some(current.to_string()),
                    free_text: false,
                    theme: Some(Box::new(ThemeChoice {
                        section: ThemeSection::Current,
                        id: current.to_string(),
                        description: None,
                        appearance: None,
                        swatches: Vec::new(),
                        reason: None,
                        summary: format!("Current, {current}"),
                    })),
                },
            );
        }
        let selected = if explicit && !current_is_authored {
            rows.iter()
                .position(|option| option.value.is_none())
                .unwrap_or(0)
        } else if current_is_authored {
            rows.iter()
                .position(|option| names(option, current))
                .unwrap_or(0)
        } else {
            rows.iter()
                .position(|option| option.value.is_none())
                .unwrap_or(0)
        };
        Self::assemble(prefs::EDIT_THEME, rows, selected, Some(extras))
    }

    fn fonts(key: &str, options: Vec<ChoiceOption>, saved: usize) -> Self {
        let mut picker = Self::assemble(key, options, saved, None);
        picker.fonts = true;
        picker
    }

    const fn title<'a>(&self, field_label: &'a str) -> &'a str {
        match self.slot {
            Some(aterm_types::Appearance::Dark) => "Dark theme",
            Some(aterm_types::Appearance::Light) => "Light theme",
            None => field_label,
        }
    }

    fn opener_focus(&self) -> UiKey {
        UiKey::new(match self.slot {
            Some(side) => theme_slot_action(side),
            None => format!("settings/control/{}", self.key),
        })
    }

    const fn searchable(&self) -> bool {
        self.fonts
    }

    fn set_filter(&mut self, filter: String) -> bool {
        if !self.fonts || filter == self.filter {
            return false;
        }
        let wanted = fold_font_name(&filter);
        self.shown = (0..self.options.len())
            .filter(|index| {
                let option = &self.options[*index];
                option.free_text || fold_font_name(&option.label).contains(&wanted)
            })
            .collect();
        self.filter = filter;
        self.offset.set(0);
        true
    }

    const fn slots(&self) -> usize {
        self.shown.len() + self.trailing.get()
    }

    fn option_section(&self, index: usize) -> Option<&'static str> {
        self.options
            .get(index)?
            .theme
            .as_ref()
            .map(|theme| theme.section.label())
    }

    fn cell_section(&self, position: usize) -> Option<&'static str> {
        match self.shown.get(position) {
            Some(index) => self.option_section(*index),
            None => Some(THEME_FILES_HEADING),
        }
    }

    const fn headed(&self) -> bool {
        self.themes.is_some()
    }

    fn spans_row(&self, position: usize) -> bool {
        self.headed()
            && self
                .shown
                .get(position)
                .and_then(|index| self.options[*index].theme.as_ref())
                .is_some_and(|theme| theme.section.spans_row())
    }

    fn rows(&self) -> Vec<PickerRow> {
        picker_rows(
            self.slots(),
            self.columns.get(),
            self.headed(),
            |position| self.cell_section(position),
        )
    }

    fn unfiltered_rows(&self, columns: usize) -> Vec<PickerRow> {
        let options = self.options.len();
        picker_rows(
            options + self.trailing.get(),
            columns,
            self.headed(),
            |position| {
                if position < options {
                    self.option_section(position)
                } else {
                    Some(THEME_FILES_HEADING)
                }
            },
        )
    }

    fn carried_heading(&self, rows: &[PickerRow], first: usize) -> Option<&'static str> {
        if !self.headed() {
            return None;
        }
        match rows.get(first)? {
            PickerRow::Cells(cells) => self
                .cell_section(cells.start)
                .filter(|heading| section_captioned(heading)),
            PickerRow::Heading(_) => None,
        }
    }

    fn rows_fitting(&self, rows: &[PickerRow], first: usize) -> usize {
        let room = self.room.get().get();
        let gap = self.gap.get().get();
        let carried = self.carried_heading(rows, first).is_some();
        let mut used = if carried {
            picker_heading_height()
        } else {
            0.0_f32
        };
        let mut count = 0;
        for row in rows.iter().skip(first) {
            let next = used + if count > 0 || carried { gap } else { 0.0 } + picker_row_height(row);
            if count > 0 && next > room + 0.5 {
                break;
            }
            used = next;
            count += 1;
        }
        if count > 1
            && first + count < rows.len()
            && matches!(rows[first + count - 1], PickerRow::Heading(_))
        {
            count -= 1;
        }
        let least =
            if matches!(rows.get(first), Some(PickerRow::Heading(_))) && first + 1 < rows.len() {
                2
            } else {
                usize::from(first < rows.len())
            };
        count.max(least)
    }

    fn window(&self, rows: &[PickerRow]) -> std::ops::Range<usize> {
        let first = self.offset.get().min(rows.len());
        first..first + self.rows_fitting(rows, first)
    }

    fn visible_cells(&self) -> Vec<PickerCell> {
        let rows = self.rows();
        rows[self.window(&rows)]
            .iter()
            .filter_map(|row| match row {
                PickerRow::Cells(cells) => Some(cells.clone()),
                PickerRow::Heading(_) => None,
            })
            .flatten()
            .map(|position| match self.shown.get(position) {
                Some(index) => PickerCell::Option(*index),
                None => PickerCell::Action(position - self.shown.len()),
            })
            .collect()
    }

    fn visible_indices(&self) -> Vec<usize> {
        self.visible_cells()
            .into_iter()
            .filter_map(|cell| match cell {
                PickerCell::Option(index) => Some(index),
                PickerCell::Action(_) => None,
            })
            .collect()
    }

    #[cfg(test)]
    fn is_visible(&self, index: usize) -> bool {
        self.visible_indices().contains(&index)
    }

    fn visible_sections(&self) -> Vec<ThemeSection> {
        let mut sections = Vec::new();
        for index in self.visible_indices() {
            if let Some(section) = self.options[index]
                .theme
                .as_ref()
                .map(|theme| theme.section)
                && !sections.contains(&section)
            {
                sections.push(section);
            }
        }
        sections
    }

    fn position_of(&self, index: usize) -> Option<usize> {
        self.shown.iter().position(|shown| *shown == index)
    }

    const fn action_key(ordinal: usize) -> &'static str {
        match ordinal {
            0 => THEMES_FOLDER_ACTION,
            1 => THEMES_IMPORT_ACTION,
            _ => THEMES_BROWSE_KEY,
        }
    }

    fn focus_position(&self, key: &UiKey) -> Option<usize> {
        if let Some(index) = self.option_index(key) {
            return self.position_of(index);
        }
        (0..self.trailing.get())
            .find(|ordinal| key.as_str() == Self::action_key(*ordinal))
            .map(|ordinal| self.shown.len() + ordinal)
    }

    fn position_key(&self, position: usize) -> UiKey {
        match self.shown.get(position) {
            Some(index) => UiKey::new(format!("settings/choice/{}/{index}", self.key)),
            None => UiKey::new(Self::action_key(position - self.shown.len())),
        }
    }

    fn reveal(&self, index: usize) {
        if let Some(position) = self.position_of(index) {
            self.reveal_pending.set(Some(index));
            self.scroll_to(Some(position));
        }
    }

    fn option_index(&self, key: &UiKey) -> Option<usize> {
        key.as_str()
            .strip_prefix("settings/choice/")?
            .strip_prefix(self.key.as_str())?
            .strip_prefix('/')?
            .parse::<usize>()
            .ok()
            .filter(|index| *index < self.options.len())
    }

    fn configure_window(&self, columns: usize, room: f32, gap: f32, anchor: Option<usize>) {
        let reflowed = self.columns.get() != columns.max(1)
            || self.room.get() != PickerMeasure::new(room.max(0.0))
            || self.gap.get() != PickerMeasure::new(gap);
        let old = self.rows();
        let leading = old[self.offset.get().min(old.len())..]
            .iter()
            .find_map(|row| match row {
                PickerRow::Cells(cells) => Some(cells.start),
                PickerRow::Heading(_) => None,
            });
        self.columns.set(columns.max(1));
        self.room.set(PickerMeasure::new(room.max(0.0)));
        self.gap.set(PickerMeasure::new(gap));
        let rows = self.rows();
        self.offset.set(
            leading
                .and_then(|leading| Self::row_of(&rows, leading))
                .map_or(0, |row| Self::with_heading(&rows, row)),
        );
        let moved = self.followed.replace(anchor) != anchor;
        let anchor = self
            .reveal_pending
            .take()
            .and_then(|index| self.position_of(index))
            .or(anchor.filter(|_| reflowed || moved));
        self.scroll_to(anchor);
    }

    fn scroll_by(&self, rows: isize) -> bool {
        let all = self.rows();
        let cells: Vec<usize> = all
            .iter()
            .enumerate()
            .filter(|(_, row)| matches!(row, PickerRow::Cells(_)))
            .map(|(index, _)| index)
            .collect();
        let Some(last) = cells.len().checked_sub(1) else {
            return false;
        };
        let offset = self.offset.get();
        let at = cells.iter().position(|row| *row >= offset).unwrap_or(last);
        let target = (at as isize).saturating_add(rows).clamp(0, last as isize) as usize;
        self.offset.set(Self::with_heading(&all, cells[target]));
        self.scroll_to(None);
        self.offset.get() != offset
    }

    fn row_of(rows: &[PickerRow], position: usize) -> Option<usize> {
        rows.iter().position(|row| match row {
            PickerRow::Cells(cells) => cells.contains(&position),
            PickerRow::Heading(_) => false,
        })
    }

    fn with_heading(rows: &[PickerRow], row: usize) -> usize {
        match row.checked_sub(1).map(|above| &rows[above]) {
            Some(PickerRow::Heading(_)) => row - 1,
            _ => row,
        }
    }

    fn scroll_to(&self, position: Option<usize>) {
        let rows = self.rows();
        let mut first = self.offset.get().min(rows.len().saturating_sub(1));
        if let Some(row) = position.and_then(|position| Self::row_of(&rows, position)) {
            let top = Self::with_heading(&rows, row);
            if top < first {
                first = top;
            } else if row >= first + self.rows_fitting(&rows, first) {
                first = (first..=row)
                    .find(|from| *from + self.rows_fitting(&rows, *from) > row)
                    .unwrap_or(row);
            }
        }
        let last_first = (0..rows.len())
            .find(|from| *from + self.rows_fitting(&rows, *from) >= rows.len())
            .unwrap_or(0);
        self.offset.set(first.min(last_first));
    }

    fn page_rows(&self) -> usize {
        let rows = self.rows();
        self.window(&rows)
            .filter(|row| matches!(rows[*row], PickerRow::Cells(_)))
            .count()
            .max(1)
    }

    fn step(&self, from: usize, rows: isize, steps: isize) -> usize {
        let Some(last) = self.slots().checked_sub(1) else {
            return from;
        };
        let from = from.min(last);
        if rows == 0 {
            return (from as isize)
                .saturating_add(steps)
                .clamp(0, last as isize) as usize;
        }
        let cells: Vec<std::ops::Range<usize>> = self
            .rows()
            .into_iter()
            .filter_map(|row| match row {
                PickerRow::Cells(cells) => Some(cells),
                PickerRow::Heading(_) => None,
            })
            .collect();
        let row = cells
            .iter()
            .position(|cells| cells.contains(&from))
            .unwrap_or(0);
        let column = from - cells[row].start;
        let target = (row as isize).saturating_add(rows);
        if target < 0 || target >= cells.len() as isize {
            return if rows.abs() == 1 {
                from
            } else if target < 0 {
                0
            } else {
                last
            };
        }
        let cells = &cells[target as usize];
        (cells.start + column).min(cells.end - 1)
    }

    fn filter_text(&self) -> &str {
        self.themes
            .as_ref()
            .map_or("", |extras| extras.filter.value())
    }

    fn seed_filter(&mut self, query: &str) -> bool {
        let named = self.named_by(query);
        if named.is_empty() || self.themes.is_none() {
            return false;
        }
        let Some(text) = self.seed_text(query, &named) else {
            return false;
        };
        if let Some(extras) = self.themes.as_mut() {
            extras.filter = crate::native_text_input::TextInputState::new(text);
        }
        self.refilter();
        self.seed_named = named;
        true
    }

    fn seed_text(&self, query: &str, named: &[usize]) -> Option<String> {
        let core = |word: &str| {
            word.trim_matches(|ch: char| !ch.is_alphanumeric())
                .to_lowercase()
        };
        let typed: Vec<&str> = query.split_whitespace().collect();
        let specific: Vec<&str> = typed
            .iter()
            .copied()
            .filter(|word| !THEME_GENERIC_NOUNS.contains(&core(word).as_str()))
            .collect();
        let names = ThemeNaming::of(query).map_or_else(Vec::new, |naming| naming.names);
        [typed.join(" "), specific.join(" "), names.join(" ")]
            .into_iter()
            .filter(|text| !text.is_empty())
            .find(|text| {
                let typed = text.to_lowercase();
                let reach = self.filter_reach(&typed);
                named
                    .iter()
                    .all(|index| theme_choice_matches(&self.options[*index], &typed, reach))
            })
    }

    fn named_by(&self, query: &str) -> Vec<usize> {
        if self.themes.is_none() {
            return Vec::new();
        }
        let Some(naming) = ThemeNaming::of(query) else {
            return Vec::new();
        };
        (0..self.options.len())
            .filter(|index| {
                let option = &self.options[*index];
                let Some(theme) = option.theme.as_ref() else {
                    return false;
                };
                if !matches!(
                    theme.section,
                    ThemeSection::Dark | ThemeSection::Light | ThemeSection::Yours
                ) || theme.reason.is_some()
                {
                    return false;
                }
                naming.names(&option.label, &theme.id, theme.appearance)
            })
            .collect()
    }

    fn seed_focus(&self) -> usize {
        if self.shown.contains(&self.selected) {
            return self.selected;
        }
        let named: Vec<usize> = self
            .shown
            .iter()
            .copied()
            .filter(|index| self.seed_named.contains(index))
            .collect();
        let rows = if named.is_empty() {
            &self.shown
        } else {
            &named
        };
        self.slot
            .and_then(|side| {
                rows.iter().copied().find(|index| {
                    self.options[*index]
                        .theme
                        .as_ref()
                        .is_some_and(|theme| theme.appearance == Some(side))
                })
            })
            .or_else(|| rows.first().copied())
            .unwrap_or(self.selected)
    }

    fn filter_reach(&self, query: &str) -> MatchReach {
        MatchReach::of(
            self.options
                .iter()
                .any(|option| theme_choice_matches(option, query, MatchReach::Words)),
        )
    }

    fn refilter(&mut self) {
        let query = self.filter_text().trim().to_lowercase();
        let reach = self.filter_reach(&query);
        self.shown = (0..self.options.len())
            .filter(|index| theme_choice_matches(&self.options[*index], &query, reach))
            .collect();
        self.seed_named.clear();
        self.offset.set(0);
    }
}

const THEME_GENERIC_NOUNS: [&str; 5] = ["theme", "themes", "mode", "color", "colour"];

struct ThemeNaming {
    names: Vec<String>,
    side: Option<aterm_types::Appearance>,
}

impl ThemeNaming {
    fn of(query: &str) -> Option<Self> {
        let mut side = None;
        let mut names = Vec::new();
        for word in query
            .trim()
            .to_lowercase()
            .split(|ch: char| !ch.is_alphanumeric())
            .filter(|word| !word.is_empty())
        {
            if let Some(appearance) = parse_appearance_word(word) {
                side = Some(appearance);
            } else if !THEME_GENERIC_NOUNS.contains(&word) {
                names.push(word.to_string());
            }
        }
        (!names.is_empty()).then_some(Self { names, side })
    }

    fn names(&self, label: &str, id: &str, appearance: Option<aterm_types::Appearance>) -> bool {
        if self.side.is_some_and(|side| appearance != Some(side)) {
            return false;
        }
        let label = label.to_lowercase();
        let id = id.to_lowercase();
        let words: Vec<&str> = [label.as_str(), id.as_str()]
            .into_iter()
            .flat_map(|text| text.split(|ch: char| !ch.is_alphanumeric()))
            .filter(|word| !word.is_empty() && parse_appearance_word(word).is_none())
            .collect();
        self.names
            .iter()
            .all(|name| words.iter().any(|word| word.starts_with(name.as_str())))
    }
}

fn theme_choice_matches(option: &ChoiceOption, query: &str, reach: MatchReach) -> bool {
    if query.is_empty() {
        return true;
    }
    let matches = |candidate: &str| {
        crate::native_config_language::candidate_match_score(candidate, query, reach)
    };
    if matches(&option.label.to_lowercase()).is_some() {
        return true;
    }
    let Some(theme) = option.theme.as_ref() else {
        return false;
    };
    matches(&theme.id.to_lowercase()).is_some()
        || theme
            .description
            .as_deref()
            .is_some_and(|description| matches(&description.to_lowercase()).is_some())
        || theme.appearance.is_some_and(|appearance| {
            matches(match appearance {
                aterm_types::Appearance::Dark => "dark",
                aterm_types::Appearance::Light => "light",
            })
            .is_some()
        })
}

/// One semantic transition of a Settings list's bounded scroll.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SettingsPageScrollCommand {
    Absolute(usize),
    Lines(i32),
}

/// Clamp the scroll before and after every transition.
#[must_use]
pub(crate) fn settings_page_scroll_transition(
    current: usize,
    limit: usize,
    command: SettingsPageScrollCommand,
) -> usize {
    let current = current.min(limit);
    match command {
        SettingsPageScrollCommand::Absolute(target) => target.min(limit),
        SettingsPageScrollCommand::Lines(lines) if lines < 0 => {
            current.saturating_sub(lines.unsigned_abs() as usize)
        }
        SettingsPageScrollCommand::Lines(lines) => {
            current.saturating_add(lines as usize).min(limit)
        }
    }
}

/// One Settings view's unsaved field drafts, split the way a seamless update treats them.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
