fn semantic_value_for_field(
    field: &EditField,
    input: Option<SemanticInput>,
    themes: &crate::app_config::ThemeCatalog,
) -> Option<String> {
    match input {
        Some(SemanticInput::Text(value)) if value.trim().is_empty() => None,
        Some(SemanticInput::Text(value)) => {
            Some(choice_token_for_words(field, &value).unwrap_or(value))
        }
        Some(SemanticInput::Bool(value)) => Some(value.to_string()),
        Some(SemanticInput::Number(value)) => Some(value.to_string()),
        Some(SemanticInput::TextPosition { .. } | SemanticInput::ColorPick { .. }) => None,
        None if matches!(field.kind, EditKind::Bool) => {
            let current = SettingsState::display_value(field)
                .parse::<bool>()
                .unwrap_or(false);
            Some((!current).to_string())
        }
        None if let EditKind::Enum { options } = field.kind => cycle_choice(
            trail_style_row_value(field.key, SettingsState::display_value(field)),
            options,
            field.seed.is_some(),
        ),
        None if matches!(field.kind, EditKind::Theme) => {
            let options = settings_theme_options(themes);
            let refs: Vec<&str> = options.iter().map(String::as_str).collect();
            cycle_choice(
                SettingsState::display_value(field),
                &refs,
                field.seed.is_some(),
            )
        }
        None => field.seed.clone(),
    }
}

/// A value typed for `field` on `aterm ctl settings set`, as the writer takes it.
pub(crate) fn control_input_value(field: &EditField, value: &str) -> Result<String, String> {
    match field.kind {
        EditKind::Bool => Ok(match value.trim().to_ascii_lowercase().as_str() {
            "on" => "true".to_string(),
            "off" => "false".to_string(),
            _ => value.to_string(),
        }),
        EditKind::Enum { options } => {
            let token = choice_token_for_words(field, value).unwrap_or_else(|| value.to_string());
            if prefs::typed_toml_item(field.key, &token).is_ok() {
                return Ok(token);
            }
            let listed = options
                .iter()
                .map(|option| {
                    let mut words = vec![setting_choice_label(field.key, option)];
                    let segment = segment_label(field.key, option);
                    if !words.contains(&segment) && segmented_choices(field, option).is_some() {
                        words.push(segment);
                    }
                    words.retain(|word| !word.eq_ignore_ascii_case(option));
                    if words.is_empty() {
                        (*option).to_string()
                    } else {
                        format!("{option} ({})", words.join(", "))
                    }
                })
                .collect::<Vec<_>>()
                .join(", ");
            Err(format!(
                "invalid value for {}: {:?}; it must be one of: {listed}",
                field.key,
                value.trim()
            ))
        }
        _ => Ok(value.to_string()),
    }
}

fn choice_token_for_words(field: &EditField, words: &str) -> Option<String> {
    let EditKind::Enum { options } = field.kind else {
        return None;
    };
    let words = words.trim();
    let words = words.strip_suffix(" (default)").unwrap_or(words).trim();
    if options
        .iter()
        .any(|option| option.eq_ignore_ascii_case(words))
    {
        return None;
    }
    options
        .iter()
        .find(|option| {
            setting_choice_label(field.key, option).eq_ignore_ascii_case(words)
                || segment_label(field.key, option).eq_ignore_ascii_case(words)
        })
        .map(|option| (*option).to_string())
}

fn field_accepts_text_input(field: &EditField) -> bool {
    !matches!(
        field.kind,
        EditKind::Bool | EditKind::Enum { .. } | EditKind::Theme
    ) && numeric_slider_value(field).is_none()
}

fn apply_pointer_selection(
    input: &mut crate::native_text_input::TextInputState,
    projected_byte: usize,
    extend: bool,
) {
    let projected_byte = projected_byte.min(input.projection().text.len());
    let committed_byte = input.preedit().map_or(projected_byte, |preedit| {
        let replaced = input.selection().range();
        let marked_start = replaced.start;
        let marked_end = marked_start.saturating_add(preedit.text.len());
        if projected_byte <= marked_start {
            projected_byte
        } else if projected_byte >= marked_end {
            replaced
                .end
                .saturating_add(projected_byte.saturating_sub(marked_end))
        } else if projected_byte - marked_start <= marked_end - projected_byte {
            replaced.start
        } else {
            replaced.end
        }
    });
    let anchor = if extend {
        input.selection().anchor
    } else {
        committed_byte
    };
    input.set_selection(anchor, committed_byte);
}

fn apply_text_input_event(
    input: &mut crate::native_text_input::TextInputState,
    event: TextInputEvent,
) {
    match event {
        TextInputEvent::Preedit { text, selection } => input.set_preedit(text, selection),
        TextInputEvent::Commit(text) => input.commit_preedit(&text),
        TextInputEvent::Backspace => input.delete_backward(),
        TextInputEvent::Delete => input.delete_forward(),
        TextInputEvent::Left { extend } => input.move_left(extend),
        TextInputEvent::Right { extend } => input.move_right(extend),
        TextInputEvent::Home { extend } => input.move_to_start(extend),
        TextInputEvent::End { extend } => input.move_to_end(extend),
        TextInputEvent::KillToEnd => input.kill_to_end(),
        TextInputEvent::KillToStart => input.kill_to_start(),
        TextInputEvent::DeleteWordBackward => input.delete_word_backward(),
        TextInputEvent::WordLeft { extend } => input.move_word_left(extend),
        TextInputEvent::WordRight { extend } => input.move_word_right(extend),
        TextInputEvent::SelectAll => input.select_all(),
        TextInputEvent::Undo => {
            input.undo();
        }
        TextInputEvent::Redo => {
            input.redo();
        }
        TextInputEvent::Submit | TextInputEvent::Cancel => input.cancel_preedit(),
    }
}

fn trail_style_row_value<'a>(key: &str, value: &'a str) -> &'a str {
    if matches!(
        key,
        prefs::EDIT_CURSOR_TRAIL_STYLE | prefs::EDIT_CURSOR_TRAIL_STYLE_BEFORE_OFF
    ) {
        prefs::cursor_trail_style_canonical(value).unwrap_or(value)
    } else {
        value
    }
}

fn cycle_choice(current: &str, choices: &[&str], explicit: bool) -> Option<String> {
    let current = if explicit {
        current.trim()
    } else {
        current.strip_suffix(" (default)").unwrap_or(current).trim()
    };
    let index = choices
        .iter()
        .position(|choice| choice.eq_ignore_ascii_case(current));
    choices
        .get(index.map_or(0, |index| (index + 1) % choices.len().max(1)))
        .map(|choice| (*choice).to_string())
}

fn choice_label(value: &str) -> String {
    match value {
        "auto" => "Automatic".to_string(),
        "builtin" => "Built-in".to_string(),
        "linear-corrected" => "Linear corrected".to_string(),
        "implicit" => "Auto".to_string(),
        "disabled" => "Off".to_string(),
        "explicit" => "If asked".to_string(),
        "adaptive" => "Adaptive".to_string(),
        "always" => "Always".to_string(),
        "reduced" => "Reduce motion".to_string(),
        "full" => "Always animate".to_string(),
        "srgb" => "sRGB".to_string(),
        "display-p3" => "Display P3".to_string(),
        "openai-compatible" => "OpenAI-compatible".to_string(),
        "title-description" => "Title, then description".to_string(),
        "description-title" => "Description, then title".to_string(),
        "long-term" => "Long-term".to_string(),
        "short-term" => "Short-term".to_string(),
        "leave" => "Leave as is".to_string(),
        value => sentence_case_token(value),
    }
}

fn regular_choice_control_width() -> f32 {
    270.0 * settings_text_scale().min(1.25)
}

fn theme_pair_fitted(key: &str, value: &str, words: &str) -> String {
    if key != prefs::EDIT_THEME {
        return words.to_string();
    }
    let room = regular_choice_control_width() - 52.0;
    match prefs::theme_pair_short_label(value) {
        Some(short) if crate::native_ui::native_button_label_width(words) > room => short,
        _ => words.to_string(),
    }
}

/// The words a choice shows for `value`.
pub(crate) fn setting_choice_label(key: &str, value: &str) -> String {
    let value = value.trim();
    if let Some(raw) = value.strip_suffix(" (default)") {
        return format!("{} (default)", setting_choice_label(key, raw));
    }
    if key == prefs::EDIT_THEME {
        return prefs::theme_pair_label(value).unwrap_or_else(|| value.to_string());
    }
    if key == prefs::EDIT_MOTION && motion_value_is_auto(value) {
        return choice_label("auto");
    }
    if key == prefs::EDIT_WINDOW_THEME && value.eq_ignore_ascii_case("auto") {
        return if cfg!(target_os = "macos") {
            "Match macOS"
        } else {
            "Match terminal"
        }
        .to_string();
    }
    if key == prefs::EDIT_PALETTE_GENERATE {
        let words = match value.to_ascii_lowercase().as_str() {
            "theme" => Some("Follow theme"),
            "always" => Some("Always derive"),
            "never" => Some("xterm table"),
            _ => None,
        };
        if let Some(words) = words {
            return words.to_string();
        }
    }
    if key == prefs::EDIT_TRAIL_SOUND_STYLE
        && value.eq_ignore_ascii_case(prefs::DEFAULT_TRAIL_SOUND_STYLE)
    {
        return "Follow the trail".to_string();
    }
    if key == prefs::EDIT_CURSOR_TRAIL_STYLE {
        return match value.trim().strip_suffix(" (default)") {
            Some(raw) => format!("{} (default)", cursor_style_name(raw)),
            None => cursor_style_name(value),
        };
    }
    if key == prefs::EDIT_BACKGROUND_MATERIAL
        && let Some(label) = background_material_label(value)
    {
        return label.to_string();
    }
    match value.trim().strip_suffix(" (default)") {
        Some(raw) => format!("{} (default)", choice_label(raw.trim())),
        None => choice_label(value),
    }
}

fn background_material_label(value: &str) -> Option<&'static str> {
    let windows = cfg!(windows);
    Some(match value.trim().to_ascii_lowercase().as_str() {
        "none" | "" => "No blur",
        "hud" if windows => "Frosted glass",
        "hud" => "Dark frosted glass",
        "sidebar" if windows => "Tinted desktop color",
        "sidebar" => "Frosted glass",
        "under-window" | "underwindow" | "under_window" if windows => "Desktop color",
        "under-window" | "underwindow" | "under_window" => "Subtle blur",
        _ => return None,
    })
}

fn motion_value_is_auto(value: &str) -> bool {
    value
        .split_whitespace()
        .next()
        .is_some_and(|token| token.eq_ignore_ascii_case("auto"))
}

fn sentence_case_token(value: &str) -> String {
    let mut label = value.replace(['-', '_'], " ");
    if let Some(first) = label.get_mut(0..1) {
        first.make_ascii_uppercase();
    }
    label
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CursorStyleGroup {
    Companions,
    Trails,
    Off,
}

impl CursorStyleGroup {
    const fn caption(self) -> Option<&'static str> {
        match self {
            Self::Companions => Some("Companions"),
            Self::Trails => Some("Trails"),
            Self::Off => None,
        }
    }
}

const fn cursor_style_group(
    row: &aterm_effects::cursor_glow::spellings::TrailStyleRow,
) -> CursorStyleGroup {
    match row.style {
        None => CursorStyleGroup::Off,
        Some(aterm_effects::cursor_glow::GlowStyle::RainbowKitty) => CursorStyleGroup::Companions,
        Some(_) => CursorStyleGroup::Trails,
    }
}

/// The values the Cursor Styles page lists, Off first.
#[cfg(test)]
pub(crate) fn listed_cursor_style_values() -> impl Iterator<Item = &'static str> {
    prefs::CURSOR_TRAIL_STYLES.iter().copied()
}

/// The name a `cursor_trail_style` value goes by.
pub(crate) fn cursor_style_name(value: &str) -> String {
    let value = value.trim();
    if let Some(label) = aterm_effects::cursor_glow::spellings::label(value) {
        return label.to_string();
    }
    let resolved = crate::app_config::resolve_trail_style(value);
    let drawn = resolved
        .canonical
        .and_then(aterm_effects::cursor_glow::spellings::label)
        .unwrap_or(prefs::DEFAULT_CURSOR_TRAIL_STYLE);
    if value.is_empty() {
        drawn.to_string()
    } else {
        format!("{drawn} (unknown \"{value}\")")
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ListedCursorStyle {
    value: String,
    name: String,
    description: String,
    group: CursorStyleGroup,
    default: bool,
}

impl ListedCursorStyle {
    fn label(&self) -> String {
        if self.default {
            format!("{} (default)", self.name)
        } else {
            self.name.clone()
        }
    }
}

const OFF_PLAIN_DESCRIPTION: &str = "No trail; the cursor stays plain";
const OFF_GLOW_DESCRIPTION: &str = "No trail; typing still makes the cursor glow";

fn listed_cursor_styles(state: &SettingsViewState) -> Vec<ListedCursorStyle> {
    let off_glows = field_bool(
        state,
        prefs::EDIT_CURSOR_MOMENTUM_GLOW,
        crate::app_config::DEFAULT_DECORATIVE_EFFECTS,
    ) && !field_bool(state, prefs::EDIT_SERIOUS_MODE, false);
    let off_description = if off_glows {
        OFF_GLOW_DESCRIPTION
    } else {
        OFF_PLAIN_DESCRIPTION
    };
    let default_style = crate::app_config::default_cursor_trail_style();
    let before_off = cursor_style_before_off(state);
    let builtin = |row: &aterm_effects::cursor_glow::spellings::TrailStyleRow| {
        let group = cursor_style_group(row);
        ListedCursorStyle {
            default: row.name.eq_ignore_ascii_case(default_style),
            value: row.name.to_string(),
            name: row.label.to_string(),
            description: {
                let description = if group == CursorStyleGroup::Off {
                    off_description
                } else {
                    row.blurb
                };
                match before_off.as_deref() {
                    Some(style) if row.name.eq_ignore_ascii_case(style) => {
                        format!("{BEFORE_OFF_MARK} \u{b7} {description}")
                    }
                    Some(style) if group == CursorStyleGroup::Off => format!(
                        "{BEFORE_OFF_MARK}: {} \u{b7} {description}",
                        cursor_style_name(style)
                    ),
                    _ => description.to_string(),
                }
            },
            group,
        }
    };
    aterm_effects::cursor_glow::spellings::TRAIL_STYLES
        .iter()
        .map(builtin)
        .collect()
}

fn cursor_style_row_key(value: &str) -> String {
    format!("settings/cursor-style/{}", key_fragment(value))
}

fn cursor_style_for_row(state: &SettingsViewState, key: &str) -> Option<String> {
    key.strip_prefix("settings/cursor-style/")?;
    listed_cursor_styles(state)
        .into_iter()
        .find(|style| cursor_style_row_key(&style.value) == key)
        .map(|style| style.value)
}

fn cursor_style_list_live(state: &SettingsViewState) -> bool {
    state.route == SettingsRoute::CursorStyles && state.search.trim().is_empty()
}

fn cursor_style_candidate(state: &SettingsViewState) -> Option<String> {
    cursor_style_candidate_from(state).map(|(style, _)| style)
}

fn cursor_style_candidate_from(state: &SettingsViewState) -> Option<(String, StyleTrial)> {
    if !cursor_style_list_live(state) {
        return None;
    }
    let writing = state.writes_in_flight(prefs::EDIT_CURSOR_TRAIL_STYLE);
    let focus = state.common.last_focus.as_ref();
    let found = [state.common.hovered.as_ref(), focus]
        .into_iter()
        .flatten()
        .filter(|key| writing || state.chosen_style_row.as_ref() != Some(*key))
        .find_map(|key| {
            let source = if focus == Some(key) {
                StyleTrial::Keyboard
            } else {
                StyleTrial::Pointer
            };
            cursor_style_for_row(state, key.as_str()).map(|style| (style, source))
        });
    let on_preview = focus.is_some_and(|focus| focus.as_str().starts_with("settings/preview"));
    if found.is_none() && on_preview {
        return state
            .preview_candidate
            .borrow()
            .clone()
            .map(|style| (style, StyleTrial::Kept));
    }
    state
        .preview_candidate
        .replace(found.as_ref().map(|(style, _)| style.clone()));
    found
}

fn cursor_style_trial(state: &SettingsViewState) -> Option<String> {
    cursor_style_trial_from(state).map(|(style, _)| style)
}

fn cursor_style_trial_from(state: &SettingsViewState) -> Option<(String, StyleTrial)> {
    cursor_style_candidate_from(state)
        .filter(|(candidate, _)| !candidate.eq_ignore_ascii_case(&saved_cursor_style(state)))
}

fn saved_cursor_style(state: &SettingsViewState) -> String {
    let projected = top_projected_trail_value(state);
    let resolved = crate::app_config::resolve_trail_style(&projected);
    if resolved.style.is_none() {
        return "off".to_string();
    }
    match resolved.canonical {
        Some(canonical) => canonical.to_string(),
        None => projected.trim().to_string(),
    }
}

fn cursor_style_before_off(state: &SettingsViewState) -> Option<String> {
    if crate::app_config::resolve_trail_style(&top_authored_trail_value(state))
        .style
        .is_some()
    {
        return None;
    }
    let kept = state
        .raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE_BEFORE_OFF)
        .or_else(|| {
            (state
                .raw_value(prefs::RETIRED_CURSOR_TRAIL)
                .is_some_and(|master| master.trim() == "false"))
            .then(|| {
                state
                    .raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE)
                    .unwrap_or_else(|| prefs::DEFAULT_CURSOR_TRAIL_STYLE.to_string())
            })
        })?;
    let resolved = crate::app_config::resolve_trail_style(&kept);
    if resolved.unknown || resolved.style.is_none() {
        return None;
    }
    resolved.canonical.map(str::to_string)
}

const BEFORE_OFF_MARK: &str = "Your style before Off";

fn cursor_style_is_saved(state: &SettingsViewState, style: &str) -> bool {
    let raw = state
        .raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE)
        .unwrap_or_else(|| crate::app_config::default_cursor_trail_style().to_string());
    let raw = raw.trim();
    let authored = if aterm_effects::cursor_glow::GlowStyle::style_names_classic_mono(raw) {
        raw
    } else {
        prefs::cursor_trail_style_canonical(raw).unwrap_or(raw)
    };
    style.eq_ignore_ascii_case(&saved_cursor_style(state)) && style.eq_ignore_ascii_case(authored)
}

fn trail_knob(key: &str) -> Option<aterm_effects::cursor_glow::TrailKnob> {
    use aterm_effects::cursor_glow::TrailKnob;
    Some(match key {
        prefs::EDIT_CURSOR_TRAIL_LENGTH => TrailKnob::Length,
        prefs::EDIT_CURSOR_TRAIL_RADIUS => TrailKnob::Radius,
        prefs::EDIT_CURSOR_TRAIL_RING => TrailKnob::Ring,
        prefs::EDIT_CURSOR_TRAIL_COLOR => TrailKnob::Color,
        prefs::EDIT_CURSOR_TRAIL_ACCENT => TrailKnob::Accent,
        prefs::EDIT_CURSOR_FIRE_SHIMMER => TrailKnob::FireShimmer,
        _ => return None,
    })
}

fn trail_style_uses(style: &crate::app_config::ResolvedTrailStyle, key: &str, bar: bool) -> bool {
    let Some(glow) = style.style else {
        return false;
    };
    trail_knob(key).is_none_or(|knob| {
        glow.reads_knob(knob, aterm_effects::cursor_glow::KnobContext::widest(bar))
    })
}

fn trail_knob_idle_reason(
    glow: aterm_effects::cursor_glow::GlowStyle,
    key: &str,
    ctx: aterm_effects::cursor_glow::KnobContext,
) -> Option<EffectDisclosure> {
    use aterm_effects::cursor_glow::KnobContext;
    let knob = trail_knob(key)?;
    if glow.reads_knob(knob, ctx) {
        return None;
    }
    let reads = |ctx: KnobContext| glow.reads_knob(knob, ctx);
    if reads(KnobContext { ring: true, ..ctx }) {
        return Some(EffectDisclosure::new(
            EffectNoteKind::Inactive,
            "This color tints the landing ring, which is off while Ring on jumps is Off",
            "Inactive: Ring on jumps Off",
            "Currently inactive: Ring on jumps is Off",
        ));
    }
    if reads(KnobContext { dark: true, ..ctx }) {
        let semantic = match knob {
            aterm_effects::cursor_glow::TrailKnob::Radius => {
                "On a light background this style draws no glow at the cursor for it to size; the value applies on dark themes"
            }
            aterm_effects::cursor_glow::TrailKnob::Accent => {
                "On a light background this style draws no wake for it to shade; the value applies on dark themes"
            }
            _ => {
                "On a light background this style draws no tail for it to shape; the value applies on dark themes"
            }
        };
        return Some(EffectDisclosure::new(
            EffectNoteKind::Inactive,
            semantic,
            "Inactive: dark themes only",
            "Currently inactive: it shows only on dark themes",
        ));
    }
    if reads(KnobContext { bar: true, ..ctx }) {
        return Some(EffectDisclosure::new(
            EffectNoteKind::Inactive,
            "This style colors a block cursor from its own palette; the value tints the bar cursor's glow",
            "Inactive: bar cursor only",
            "Currently inactive: it tints only a bar cursor",
        ));
    }
    None
}

fn trail_knob_context(
    state: &SettingsViewState,
    patch: Option<&ConfigPatch>,
    motion: crate::native_app::ViewMotionCx,
) -> aterm_effects::cursor_glow::KnobContext {
    let raw =
        candidate_explicit_text(state, patch, prefs::EDIT_CURSOR_TRAIL_STYLE).unwrap_or_default();
    aterm_effects::cursor_glow::KnobContext {
        dark: !working_theme_is_light(state, motion.system_dark),
        bar: !configured_cursor_is_block(state),
        ring: candidate_setting_bool(state, patch, prefs::EDIT_CURSOR_TRAIL_RING, true),
        classic_tinted: candidate_explicit_text(state, patch, prefs::EDIT_CURSOR_TRAIL_COLOR)
            .is_some()
            || aterm_effects::cursor_glow::GlowStyle::style_names_classic_mono(raw.trim()),
        over_text: false,
    }
}

fn choices_for_field(
    field: &EditField,
    themes: &crate::app_config::ThemeCatalog,
) -> Option<Vec<String>> {
    match field.kind {
        EditKind::Enum { .. } if field.key == prefs::EDIT_PREDICTIVE_ECHO => {
            // `always` may expose password keystrokes: the picker offers only Off and Adaptive.
            Some(vec!["off".to_string(), "adaptive".to_string()])
        }
        EditKind::Enum { options } => {
            Some(options.iter().map(|option| (*option).to_string()).collect())
        }
        EditKind::Theme => Some(settings_theme_options(themes)),
        _ => None,
    }
}

fn fold_font_name(name: &str) -> String {
    name.chars()
        .filter(|ch| !ch.is_whitespace() && *ch != '-' && *ch != '_')
        .flat_map(char::to_lowercase)
        .collect()
}

fn font_slot_style(key: &str) -> (&'static str, &'static str) {
    match key {
        prefs::EDIT_FONT_FAMILY_ITALIC => ("an italic face", "Italic text"),
        prefs::EDIT_FONT_FAMILY_BOLD_ITALIC => ("a bold italic face", "Bold italic text"),
        _ => ("a bold face", "Bold text"),
    }
}

fn font_slot_key(slot: &str) -> Option<&'static str> {
    Some(match slot {
        "regular" => prefs::EDIT_FONT_FAMILY,
        "bold" => prefs::EDIT_FONT_FAMILY_BOLD,
        "italic" => prefs::EDIT_FONT_FAMILY_ITALIC,
        "bold italic" => prefs::EDIT_FONT_FAMILY_BOLD_ITALIC,
        "symbol" => prefs::EDIT_SYMBOL_FONT,
        "emoji" => prefs::EDIT_EMOJI_FONT,
        _ => return None,
    })
}

fn key_font_slot(key: &str) -> Option<&'static str> {
    Some(match key {
        prefs::EDIT_FONT_FAMILY => "regular",
        prefs::EDIT_FONT_FAMILY_BOLD => "bold",
        prefs::EDIT_FONT_FAMILY_ITALIC => "italic",
        prefs::EDIT_FONT_FAMILY_BOLD_ITALIC => "bold italic",
        prefs::EDIT_SYMBOL_FONT => "symbol",
        prefs::EDIT_EMOJI_FONT => "emoji",
        _ => return None,
    })
}

fn font_refusal_consequence(key: &str) -> &'static str {
    match key {
        prefs::EDIT_FONT_FAMILY => "The terminal keeps the font it had",
        prefs::EDIT_SYMBOL_FONT | prefs::EDIT_EMOJI_FONT => "The automatic font is used",
        _ => "This style is drawn from the regular face",
    }
}

fn font_picker_key(key: &str) -> bool {
    matches!(
        key,
        prefs::EDIT_FONT_FAMILY
            | prefs::EDIT_FONT_FAMILY_BOLD
            | prefs::EDIT_FONT_FAMILY_ITALIC
            | prefs::EDIT_FONT_FAMILY_BOLD_ITALIC
            | prefs::EDIT_SYMBOL_FONT
            | prefs::EDIT_EMOJI_FONT
    )
}

fn theme_font_for(state: &SettingsViewState, key: &str) -> Option<(String, String)> {
    state.theme_fallback_for(key).filter(|(value, _)| {
        key != prefs::EDIT_FONT_FAMILY || aterm_render::display_face_ids_for_family(value).is_none()
    })
}

fn drawn_faces_for_unset_row<'a>(
    state: &'a SettingsViewState,
    key: &str,
) -> Option<&'a aterm_render::DrawnFaces> {
    if theme_font_for(state, key).is_some() {
        return None;
    }
    state.drawn_faces.as_ref().filter(|_| {
        !state.raw_values.contains_key(key)
            || state
                .field_by_key(key)
                .and_then(|field| field.seed.as_deref())
                .is_none_or(|value| value.trim().is_empty())
    })
}

fn font_style_slot(key: &str) -> Option<usize> {
    match key {
        prefs::EDIT_FONT_FAMILY_BOLD => Some(0),
        prefs::EDIT_FONT_FAMILY_ITALIC => Some(1),
        prefs::EDIT_FONT_FAMILY_BOLD_ITALIC => Some(2),
        _ => None,
    }
}

fn font_style_modifier(state: &SettingsViewState, key: &str) -> Option<&'static str> {
    let draw = &drawn_faces_for_unset_row(state, key)?.styles[font_style_slot(key)?];
    match (
        draw.synthetic.contains(aterm_render::StyleBits::BOLD),
        draw.synthetic.contains(aterm_render::StyleBits::ITALIC),
    ) {
        (true, true) => Some("Synthetic bold italic"),
        (true, false) => Some("Synthetic bold"),
        (false, true) => Some("Synthetic italic"),
        (false, false) => draw.face.is_none().then_some("Drawn regular"),
    }
}

fn font_automatic_label(state: &SettingsViewState, key: &str) -> String {
    // A font the saved theme names is what an unset row draws.
    if let Some((value, theme)) = theme_font_for(state, key) {
        return format!("{value} (from theme {theme})");
    }
    let automatic = state
        .font_families
        .as_deref()
        .and_then(|families| families.automatic.clone());
    let drawn = drawn_faces_for_unset_row(state, key);
    let named = match (key, font_style_slot(key)) {
        (prefs::EDIT_FONT_FAMILY, _) => automatic,
        (_, Some(slot)) => drawn.and_then(|drawn| {
            drawn.styles[slot]
                .face
                .clone()
                .or_else(|| drawn.regular.clone())
                .or(automatic)
        }),
        (prefs::EDIT_SYMBOL_FONT, _) => drawn.and_then(|drawn| drawn.symbol.clone()),
        (prefs::EDIT_EMOJI_FONT, _) => drawn.and_then(|drawn| drawn.emoji.clone()),
        _ => None,
    };
    named.map_or_else(
        || "Automatic".to_string(),
        |name| format!("Automatic ({name})"),
    )
}

fn font_choices(state: &SettingsViewState, key: &str) -> Vec<String> {
    let Some(families) = state.font_families.as_deref() else {
        return if key == prefs::EDIT_FONT_FAMILY {
            aterm_render::bundled::selectable_families()
                .iter()
                .map(|family| (*family).to_string())
                .collect()
        } else {
            Vec::new()
        };
    };
    match key {
        prefs::EDIT_FONT_FAMILY => families
            .bundled
            .iter()
            .chain(&families.installed)
            .cloned()
            .collect(),
        prefs::EDIT_FONT_FAMILY_BOLD => families.bold.clone(),
        prefs::EDIT_FONT_FAMILY_ITALIC => families.italic.clone(),
        prefs::EDIT_FONT_FAMILY_BOLD_ITALIC => families.bold_italic.clone(),
        prefs::EDIT_SYMBOL_FONT => families.symbol.clone(),
        prefs::EDIT_EMOJI_FONT => families.emoji.clone(),
        _ => Vec::new(),
    }
}

fn font_choice_picker(state: &SettingsViewState, key: &str) -> ChoicePicker {
    let saved = state
        .field_by_key(key)
        .and_then(|field| field.seed.as_deref())
        .map(str::trim)
        .filter(|saved| !saved.is_empty());
    let option = ChoiceOption::plain;
    let reset = theme_font_for(state, key).map_or_else(
        || font_automatic_label(state, key),
        |(value, _)| format!("Use theme's ({value})"),
    );
    let mut options = vec![option(reset, None)];
    for family in font_choices(state, key) {
        options.push(option(family.clone(), Some(family)));
    }
    let same = |a: &str, b: &str| fold_font_name(a) == fold_font_name(b);
    let mut selected = 0;
    if let Some(saved) = saved {
        selected = options
            .iter()
            .position(|option| {
                option
                    .value
                    .as_deref()
                    .is_some_and(|value| same(value, saved))
            })
            .unwrap_or_else(|| {
                options.push(option(
                    format!("{saved} (current)"),
                    Some(saved.to_string()),
                ));
                options.len() - 1
            });
    }
    options.push(ChoiceOption {
        free_text: true,
        ..option("Other…".to_string(), None)
    });
    ChoicePicker::fonts(key, options, selected)
}

/// Every theme the native picker can apply.
pub(crate) fn settings_theme_options(themes: &crate::app_config::ThemeCatalog) -> Vec<String> {
    merge_theme_options(themes.ready_names().map(str::to_string))
}

fn theme_picker_rows(themes: &crate::app_config::ThemeCatalog) -> Vec<ChoiceOption> {
    let builtins = aterm_types::scheme::builtin_theme_list();
    let default_name = builtins.first().map(|builtin| builtin.name);
    let builtin_row = |builtin: &aterm_types::scheme::BuiltinTheme| {
        let scheme = aterm_types::scheme::builtin(builtin.name).unwrap_or_default();
        let section = match builtin.appearance {
            aterm_types::Appearance::Dark => ThemeSection::Dark,
            aterm_types::Appearance::Light => ThemeSection::Light,
        };
        let is_default = Some(builtin.name) == default_name;
        ChoiceOption {
            label: builtin.name.to_string(),
            value: (!is_default).then(|| builtin.name.to_string()),
            free_text: false,
            theme: Some(Box::new(theme_choice_with_colours(
                section,
                builtin.name,
                builtin.name,
                Some(builtin.description.to_string()),
                &scheme,
            ))),
        }
    };
    let mut rows: Vec<ChoiceOption> = builtins
        .iter()
        .filter(|builtin| builtin.appearance == aterm_types::Appearance::Dark)
        .chain(
            builtins
                .iter()
                .filter(|builtin| builtin.appearance == aterm_types::Appearance::Light),
        )
        .map(builtin_row)
        .collect();
    for (id, meta) in themes.ready_themes() {
        if aterm_types::scheme::builtin_theme(id).is_some() {
            continue;
        }
        let Ok(package) = themes.resolve_package(id) else {
            continue;
        };
        let label = crate::app_config::theme_file_label(id, meta);
        let notes: Vec<String> = meta
            .description
            .clone()
            .into_iter()
            .chain(
                package
                    .typography
                    .summary()
                    .map(|summary| format!("Aa {summary}")),
            )
            .chain(crate::app_config::skipped_keys_reason(meta))
            .collect();
        let description = (!notes.is_empty()).then(|| notes.join(FACT_SEPARATOR));
        let theme = theme_choice_with_colours(
            ThemeSection::Yours,
            id,
            &label,
            description,
            &package.colors,
        );
        rows.push(ChoiceOption {
            label,
            value: Some(id.to_string()),
            free_text: false,
            theme: Some(Box::new(theme)),
        });
    }
    for (id, status) in themes.listing() {
        let Some(reason) = status.reason() else {
            continue;
        };
        rows.push(ChoiceOption {
            label: id.to_string(),
            value: None,
            free_text: false,
            theme: Some(Box::new(ThemeChoice {
                section: ThemeSection::NeedsAttention,
                id: id.to_string(),
                description: None,
                appearance: None,
                swatches: Vec::new(),
                summary: format!("{id}, did not load: {reason}"),
                reason: Some(reason),
            })),
        });
    }
    rows
}

fn theme_choice_with_colours(
    section: ThemeSection,
    id: &str,
    label: &str,
    description: Option<String>,
    scheme: &aterm_types::ColorScheme,
) -> ThemeChoice {
    let rgb = |color: aterm_types::Rgb| [color.r, color.g, color.b];
    let background = rgb(scheme.background);
    let swatches: Vec<[u8; 3]> = std::iter::once(background)
        .chain(scheme.ansi.iter().copied().map(rgb))
        .collect();
    let text = aterm_messages::ink::contrast(rgb(scheme.foreground), background);
    let faint = scheme
        .ansi
        .iter()
        .filter(|slot| aterm_messages::ink::contrast(rgb(**slot), background) < 3.0)
        .count();
    let appearance = scheme.appearance;
    let summary = format!(
        "{label}, {}, text contrast {text:.1}:1, {faint} {} below 3:1",
        match appearance {
            aterm_types::Appearance::Dark => "dark",
            aterm_types::Appearance::Light => "light",
        },
        if faint == 1 { "colour" } else { "colours" },
    );
    ThemeChoice {
        section,
        id: id.to_string(),
        description,
        appearance: Some(appearance),
        swatches,
        reason: None,
        summary,
    }
}

fn merge_theme_options(user_names: impl IntoIterator<Item = String>) -> Vec<String> {
    let mut options: Vec<String> = aterm_types::scheme::builtin_names()
        .into_iter()
        .map(str::to_string)
        .collect();
    for name in user_names {
        if !options
            .iter()
            .any(|existing| existing.eq_ignore_ascii_case(&name))
        {
            options.push(name);
        }
    }
    options
}

fn effective_default_for_field(key: &str) -> String {
    let fields = prefs::editable_fields(&Config::default());
    fields.iter().find(|field| field.key == key).map_or_else(
        || "default".to_string(),
        |field| unset_choice_value(field, SettingsState::display_value(field)).to_string(),
    )
}

fn unset_choice_value<'a>(field: &EditField, placeholder: &'a str) -> &'a str {
    let placeholder = placeholder.trim();
    if let Some(value) = placeholder.strip_suffix(" (default)") {
        return value.trim();
    }
    if let EditKind::Enum { options } = field.kind
        && let Some((value, _)) = placeholder
            .strip_suffix(')')
            .and_then(|rest| rest.split_once(" ("))
        && options
            .iter()
            .any(|option| option.eq_ignore_ascii_case(value.trim()))
    {
        return value.trim();
    }
    placeholder
}

fn segment_candidate(state: &SettingsViewState, key: &str) -> Option<String> {
    let index_of = |focus: &UiKey| {
        let (segment_key, index) = focus
            .as_str()
            .strip_prefix("settings/segment/")?
            .rsplit_once('/')?;
        (segment_key == key)
            .then(|| index.parse::<usize>().ok())
            .flatten()
    };
    let index = state
        .common
        .hovered
        .as_ref()
        .and_then(index_of)
        .or_else(|| state.common.last_focus.as_ref().and_then(index_of))?;
    let field = state.field_by_key(key)?;
    let (segments, _) = segmented_choices(field, SettingsState::display_value(field))?;
    segments.into_iter().nth(index).map(|segment| segment.value)
}

fn picker_choice<'a>(state: &'a SettingsViewState, key: &str) -> Option<&'a ChoiceOption> {
    let picker = state
        .choice_picker
        .as_ref()
        .filter(|picker| picker.key == key)?;
    let choice_index = |focus: &UiKey| {
        let prefix = format!("settings/choice/{key}/");
        focus.as_str().strip_prefix(&prefix)?.parse::<usize>().ok()
    };
    let hovered = state
        .common
        .hovered
        .as_ref()
        .and_then(choice_index)
        .filter(|index| picker.position_of(*index).is_some());
    let focused = state
        .common
        .last_focus
        .as_ref()
        .and_then(choice_index)
        .filter(|index| picker.position_of(*index).is_some());
    let candidate = hovered.or(focused);
    let index = candidate.unwrap_or(picker.selected);
    picker.options.get(index)
}

#[cfg(test)]
fn picker_candidate<'a>(state: &'a SettingsViewState, key: &str) -> Option<&'a str> {
    picker_choice(state, key)?.value.as_deref()
}

fn field_text(state: &SettingsViewState, key: &str, fallback: &str) -> String {
    // The row is resolved lazily, through the O(1) key index, in the one arm that
    // reads it: the preview spec alone calls this ~50 times per event-loop
    // iteration while a Settings tab is up.
    if let Some(candidate) = segment_candidate(state, key) {
        return candidate;
    }
    match picker_choice(state, key) {
        Some(ChoiceOption {
            value: Some(candidate),
            ..
        }) => candidate.trim().to_string(),
        Some(ChoiceOption { value: None, .. }) => effective_default_for_field(key),
        None => {
            // Presence is authoritative: a retained empty draft means “remove
            // this override”, not “preview the stale committed seed”.  The
            // active field includes IME projection; inactive siblings retain
            // their committed draft bytes after focus moves.
            if let Some(input) = state.field_inputs.get(key) {
                let draft = if state.editing_field.as_deref() == Some(key) {
                    input.projection().text
                } else {
                    input.value().to_string()
                };
                let draft = draft.trim();
                return if draft.is_empty() {
                    fallback.trim().to_string()
                } else {
                    draft.to_string()
                };
            }
            let Some(field) = state.field_by_key(key) else {
                return fallback.trim().to_string();
            };
            if field.seed.is_some() {
                return SettingsState::display_value(field).trim().to_string();
            }
            let display = SettingsState::display_value(field).trim();
            display
                .strip_suffix(" (default)")
                .unwrap_or(display)
                .trim()
                .to_string()
        }
    }
}

fn field_bool(state: &SettingsViewState, key: &str, fallback: bool) -> bool {
    field_text(state, key, if fallback { "true" } else { "false" })
        .parse::<bool>()
        .unwrap_or(fallback)
}

fn field_number<T>(state: &SettingsViewState, key: &str, fallback: T) -> T
where
    T: std::str::FromStr + Copy,
{
    field_text(state, key, "")
        .split_whitespace()
        .next()
        .and_then(|token| token.parse::<T>().ok())
        .unwrap_or(fallback)
}

fn preview_field_text(state: &SettingsViewState, key: &str, fallback: &str) -> String {
    state.environment_override(key).map_or_else(
        || field_text(state, key, fallback),
        |active| active.effective.clone(),
    )
}

fn preview_font_px(state: &SettingsViewState, applied: f32) -> f32 {
    if state.environment_override(prefs::EDIT_FONT_PX).is_some() {
        return preview_unscaled_font_px(state, applied).0;
    }
    let scale_of = |text: &str| {
        text.split_whitespace()
            .next()
            .and_then(|v| v.parse::<f32>().ok())
            .filter(|v| v.is_finite())
            .map(|v| v.clamp(0.8, 1.25))
    };
    let saved_scale = state
        .field_by_key(prefs::EDIT_FONT_SIZE_SCALE)
        .and_then(|field| field.seed.as_deref())
        .and_then(scale_of)
        .unwrap_or_else(|| state.theme_typography_scale());
    let draft_scale = scale_of(&preview_field_text(state, prefs::EDIT_FONT_SIZE_SCALE, ""))
        .unwrap_or(saved_scale);
    let (px, from_applied) = preview_unscaled_font_px(state, applied);
    if from_applied {
        px * draft_scale / saved_scale
    } else {
        px * draft_scale
    }
}

fn preview_unscaled_font_px(state: &SettingsViewState, applied: f32) -> (f32, bool) {
    let key = prefs::EDIT_FONT_PX;
    let range = prefs::range_of(key);
    let admitted = |text: &str| {
        text.split_whitespace()
            .next()?
            .parse::<f32>()
            .ok()
            .filter(|px| {
                px.is_finite() && range.is_none_or(|r| (r.min..=r.max).contains(&f64::from(*px)))
            })
    };
    if let Some(active) = state.environment_override(key) {
        return (admitted(&active.effective).unwrap_or(applied), true);
    }
    if let Some(input) = state.field_inputs.get(key) {
        let draft = if state.editing_field.as_deref() == Some(key) {
            input.projection().text
        } else {
            input.value().to_string()
        };
        if draft.trim().is_empty() {
            return (applied, true);
        }
        if let Some(px) = admitted(&draft) {
            return (px, false);
        }
    }
    state
        .field_by_key(key)
        .and_then(|field| field.seed.as_deref())
        .and_then(admitted)
        .map_or((applied, true), |px| (px, false))
}

fn preview_field_number<T>(state: &SettingsViewState, key: &str, fallback: T) -> T
where
    T: std::str::FromStr + Copy,
{
    preview_field_text(state, key, "")
        .split_whitespace()
        .next()
        .and_then(|token| token.parse::<T>().ok())
        .unwrap_or(fallback)
}

fn preview_effective_minimum_contrast(state: &SettingsViewState) -> f32 {
    let configured = field_number(state, prefs::EDIT_MINIMUM_CONTRAST, 1.0_f32);
    let configured = if configured.is_finite() {
        configured.clamp(1.0, 21.0)
    } else {
        1.0
    };
    let opacity = field_number(state, prefs::EDIT_BACKGROUND_OPACITY, 1.0_f32);
    let opacity = if opacity.is_finite() {
        opacity.clamp(0.0, 1.0)
    } else {
        1.0
    };
    aterm_render::vibrancy::effective_minimum_contrast(configured, opacity)
}

fn preview_indexed_minimum_contrast(state: &SettingsViewState) -> f32 {
    let set = field_text(state, prefs::EDIT_MINIMUM_CONTRAST, "")
        .split_whitespace()
        .next()
        .is_some_and(|token| token.parse::<f32>().is_ok());
    if set {
        1.0
    } else {
        crate::app_config::DEFAULT_INDEXED_MINIMUM_CONTRAST
    }
}

fn settings_number_including_retained_draft(
    state: &SettingsViewState,
    key: &str,
    fallback: f32,
) -> f32 {
    if let Some(input) = state.field_inputs.get(key) {
        return input
            .value()
            .split_whitespace()
            .next()
            .and_then(|value| value.parse::<f32>().ok())
            .unwrap_or(fallback);
    }
    let committed = state.field_by_key(key).map(SettingsState::display_value);
    committed
        .and_then(|value| value.split_whitespace().next())
        .and_then(|value| value.parse::<f32>().ok())
        .unwrap_or(fallback)
}

fn constrained_minimum_contrast(state: &SettingsViewState) -> Option<(f32, f32)> {
    let configured =
        settings_number_including_retained_draft(state, prefs::EDIT_MINIMUM_CONTRAST, 1.0);
    let configured = if configured.is_finite() {
        configured.clamp(1.0, 21.0)
    } else {
        1.0
    };
    let opacity =
        settings_number_including_retained_draft(state, prefs::EDIT_BACKGROUND_OPACITY, 1.0);
    let opacity = if opacity.is_finite() {
        opacity.clamp(0.0, 1.0)
    } else {
        1.0
    };
    let effective = aterm_render::vibrancy::effective_minimum_contrast(configured, opacity);
    (effective > configured + f32::EPSILON).then_some((configured, effective))
}

fn window_top_follows_sides(
    view: &SettingsViewState,
    key: &str,
    sides: Option<&str>,
) -> Option<ConfigEdit> {
    if key != prefs::EDIT_WINDOW_PADDING {
        return None;
    }
    let sides = sides
        .and_then(|value| value.trim().parse::<f32>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(crate::PAD_LOGICAL_PX)
        .clamp(0.0, crate::app_config::MAX_WINDOW_PADDING_PX);
    let saved = view.raw_value(prefs::EDIT_WINDOW_PADDING_TOP);
    let top = saved
        .as_deref()
        .and_then(|value| value.trim().parse::<f32>().ok())?;
    (top > sides + f32::EPSILON).then(|| ConfigEdit {
        key: prefs::EDIT_WINDOW_PADDING_TOP.to_string(),
        expected: ExpectedConfigValue::Exact(saved),
        value: Some(compact_number(sides)),
    })
}

fn window_padding_sides(state: &SettingsViewState) -> f32 {
    let base = settings_number_including_retained_draft(
        state,
        prefs::EDIT_WINDOW_PADDING,
        crate::PAD_LOGICAL_PX,
    );
    if base.is_finite() {
        base.clamp(0.0, crate::app_config::MAX_WINDOW_PADDING_PX)
    } else {
        crate::PAD_LOGICAL_PX
    }
}

fn constrained_window_top_padding(state: &SettingsViewState) -> Option<(f32, f32)> {
    let base = window_padding_sides(state);
    let configured = settings_number_including_retained_draft(
        state,
        prefs::EDIT_WINDOW_PADDING_TOP,
        crate::PAD_TOP_LOGICAL_PX,
    );
    if !configured.is_finite() {
        return None;
    }
    let effective = configured.clamp(0.0, base);
    (configured > effective + f32::EPSILON).then_some((configured, effective))
}

fn post_patch_window_top_constraint(
    state: &SettingsViewState,
    patch: &ConfigPatch,
) -> Option<(f32, f32)> {
    if !patch.edits.iter().any(|edit| {
        matches!(
            edit.key.as_str(),
            prefs::EDIT_WINDOW_PADDING | prefs::EDIT_WINDOW_PADDING_TOP
        )
    }) {
        return None;
    }
    let mut base = settings_number_including_retained_draft(
        state,
        prefs::EDIT_WINDOW_PADDING,
        crate::PAD_LOGICAL_PX,
    );
    let mut top = settings_number_including_retained_draft(
        state,
        prefs::EDIT_WINDOW_PADDING_TOP,
        crate::PAD_TOP_LOGICAL_PX,
    );
    for edit in &patch.edits {
        let parsed = |fallback| {
            edit.value
                .as_deref()
                .and_then(|value| value.split_whitespace().next())
                .and_then(|value| value.parse::<f32>().ok())
                .unwrap_or(fallback)
        };
        match edit.key.as_str() {
            prefs::EDIT_WINDOW_PADDING => base = parsed(crate::PAD_LOGICAL_PX),
            prefs::EDIT_WINDOW_PADDING_TOP => top = parsed(crate::PAD_TOP_LOGICAL_PX),
            _ => {}
        }
    }
    let base = if base.is_finite() {
        base.clamp(0.0, crate::app_config::MAX_WINDOW_PADDING_PX)
    } else {
        crate::PAD_LOGICAL_PX
    };
    if !top.is_finite() {
        return None;
    }
    let effective = top.clamp(0.0, base);
    (top > effective + f32::EPSILON).then_some((top, effective))
}

fn committed_settings_number(state: &SettingsViewState, key: &str, fallback: f32) -> f32 {
    state
        .field_by_key(key)
        .and_then(|field| field.seed.as_deref())
        .and_then(|value| value.split_whitespace().next())
        .and_then(|value| value.parse::<f32>().ok())
        .unwrap_or(fallback)
}

fn post_patch_minimum_contrast_constraint(
    state: &SettingsViewState,
    patch: &ConfigPatch,
) -> Option<(f32, f32)> {
    if !patch.edits.iter().any(|edit| {
        matches!(
            edit.key.as_str(),
            prefs::EDIT_MINIMUM_CONTRAST | prefs::EDIT_BACKGROUND_OPACITY
        )
    }) {
        return None;
    }
    let mut configured = committed_settings_number(state, prefs::EDIT_MINIMUM_CONTRAST, 1.0);
    let mut opacity = committed_settings_number(state, prefs::EDIT_BACKGROUND_OPACITY, 1.0);
    for edit in &patch.edits {
        let parsed = |fallback| {
            edit.value
                .as_deref()
                .and_then(|value| value.split_whitespace().next())
                .and_then(|value| value.parse::<f32>().ok())
                .unwrap_or(fallback)
        };
        match edit.key.as_str() {
            prefs::EDIT_MINIMUM_CONTRAST => configured = parsed(1.0),
            prefs::EDIT_BACKGROUND_OPACITY => opacity = parsed(1.0),
            _ => {}
        }
    }
    let configured = if configured.is_finite() {
        configured.clamp(1.0, 21.0)
    } else {
        1.0
    };
    let opacity = if opacity.is_finite() {
        opacity.clamp(0.0, 1.0)
    } else {
        1.0
    };
    let effective = aterm_render::vibrancy::effective_minimum_contrast(configured, opacity);
    (effective > configured + f32::EPSILON).then_some((configured, effective))
}

fn compact_number(value: f32) -> String {
    if value.fract().abs() <= f32::EPSILON {
        format!("{value:.0}")
    } else {
        value.to_string()
    }
}

fn field_color(state: &SettingsViewState, key: &str) -> Option<u32> {
    let value = field_text(state, key, "");
    aterm_types::scheme::parse_hex(&value)
        .map(|color| (u32::from(color.r) << 16) | (u32::from(color.g) << 8) | u32::from(color.b))
}

fn split_font_list(value: &str) -> Vec<String> {
    value
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect()
}

fn renderer_preview_path(state: &SettingsViewState) -> &'static str {
    if state.search.trim().is_empty() {
        state.route.path()
    } else {
        "/search"
    }
}

fn focused_preview_key(state: &SettingsViewState) -> Option<String> {
    let text = folded_search(state);
    let query = SearchQuery::of(state, &text);
    let previewable = |key: &str| {
        prefs::VISUAL_PREVIEW_KEYS.contains(&key)
            && (query.is_empty()
                || (settings_field_is_visible(state, key, false, true)
                    && state.field_by_key(key).is_some_and(|field| {
                        field_match_score(field, query, &state.assets.themes).is_some()
                    })))
    };
    let focused = state.common.last_focus.as_ref().map(UiKey::as_str);
    let preview_path = renderer_preview_path(state);
    let subject = |key: &str| {
        let key = prefs::VISUAL_PREVIEW_KEYS
            .iter()
            .copied()
            .find(|candidate| *candidate == key && previewable(candidate))?;
        state.preview_subject.set(Some((key, preview_path)));
        Some(key.to_string())
    };
    if (focused.is_some_and(|focus| focus.starts_with("settings/cursor-style/"))
        || cursor_style_trial_from(state).is_some())
        && let Some(key) = subject(prefs::EDIT_CURSOR_TRAIL_STYLE)
    {
        return Some(key);
    }
    if let Some(key) = focused
        .and_then(|focus| focus.strip_prefix("settings/control/"))
        .and_then(subject)
    {
        return Some(key);
    }
    if let Some(key) = focused
        .and_then(|focus| {
            focus
                .strip_prefix("settings/choice/")
                .or_else(|| focus.strip_prefix("settings/segment/"))
        })
        .and_then(|choice| choice.rsplit_once('/'))
        .and_then(|(key, _)| subject(key))
    {
        return Some(key);
    }
    if let Some(key) = state.editing_field.as_deref().and_then(subject) {
        return Some(key);
    }
    if focused.and_then(|focus| focus.strip_prefix("settings/preview")) == Some(preview_path)
        && let Some((key, shown_in)) = state.preview_subject.get()
        && shown_in == preview_path
    {
        return Some(key.to_string());
    }
    if !query.is_empty() {
        return state
            .legacy
            .fields
            .iter()
            .filter(|field| {
                prefs::VISUAL_PREVIEW_KEYS.contains(&field.key)
                    && settings_field_is_visible(state, field.key, false, true)
            })
            .filter_map(|field| {
                field_match_score(field, query, &state.assets.themes).map(|score| (score, field))
            })
            .min_by_key(|(score, field)| {
                (
                    *score,
                    prefs::section_of(field.key).order_index(),
                    prefs::group_of(field.key).1,
                )
            })
            .map(|(_, field)| field.key.to_string());
    }
    state.route.section().and_then(|section| {
        prefs::VISUAL_PREVIEW_KEYS
            .iter()
            .copied()
            .find(|key| prefs::section_of(key) == section)
            .map(str::to_string)
    })
}

fn preview_route_for_key(key: &str) -> Option<SettingsRoute> {
    match prefs::section_of(key) {
        Section::Appearance => Some(SettingsRoute::Appearance),
        Section::Typography => Some(SettingsRoute::TextFonts),
        Section::Cursor => Some(SettingsRoute::CursorMotion),
        Section::CursorStyles => Some(SettingsRoute::CursorStyles),
        _ => None,
    }
}

fn preview_font_candidate(state: &SettingsViewState) -> crate::widget::SemanticFontCandidate {
    let authored_value = |key: &str| {
        if let Some(active) = state.environment_override(key) {
            return (!active.effective.trim().is_empty())
                .then(|| active.effective.trim().to_string());
        }
        if let Some(value) = state.field_inputs.get(key) {
            return (!value.value().trim().is_empty()).then(|| value.value().trim().to_string());
        }
        if !state.raw_values.contains_key(key) {
            return None;
        }
        state
            .field_by_key(key)
            .and_then(|field| field.seed.as_deref())
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    };
    let highlighted = |key: &str| {
        picker_choice(state, key)
            .filter(|choice| font_picker_key(key) && !choice.free_text)
            .filter(|_| state.environment_override(key).is_none())
            .map(|choice| choice.value.clone())
    };
    let family = |key: &str| highlighted(key).unwrap_or_else(|| authored_value(key));
    let variation_text = authored_value(prefs::EDIT_FONT_VARIATION).unwrap_or_default();
    let mut variations = split_font_list(&variation_text)
        .into_iter()
        .filter_map(|value| aterm_render::variation::parse_variation_spec(&value))
        .map(|(tag, value)| crate::widget::SemanticVariation::new(tag, value))
        .collect::<Vec<_>>();
    let authored_weight = authored_value(prefs::EDIT_FONT_WEIGHT)
        .as_deref()
        .and_then(|value| value.split_whitespace().next())
        .and_then(|value| value.parse::<f32>().ok())
        .filter(|value| value.is_finite())
        .map(|value| value.clamp(1.0, 1_000.0));
    if let Some(weight) = authored_weight {
        variations.retain(|variation| variation.tag != aterm_render::variation::WGHT_TAG);
        variations.push(crate::widget::SemanticVariation::new(
            aterm_render::variation::WGHT_TAG,
            weight,
        ));
    }
    let named = family(prefs::EDIT_FONT_FAMILY);
    let layer_named = named
        .as_deref()
        .and_then(aterm_render::display_face_ids_for_family)
        .map(aterm_render::display_layer_ids);
    let display = match (
        layer_named.filter(|_| {
            state
                .environment_override(prefs::EDIT_FONT_FAMILY)
                .is_some()
        }),
        state.raw_value(prefs::EDIT_DISPLAY_FONT),
    ) {
        (Some(launch), _) => launch,
        (None, Some(raw)) => aterm_render::display_layer_ids(raw.split('+')),
        (None, None) => named
            .as_deref()
            .and_then(aterm_render::display_face_ids_for_family)
            .map(aterm_render::display_layer_ids)
            .unwrap_or_default(),
    };
    let regular =
        named.filter(|family| aterm_render::display_face_ids_for_family(family).is_none());
    crate::widget::SemanticFontCandidate {
        regular,
        display,
        bold: family(prefs::EDIT_FONT_FAMILY_BOLD),
        italic: family(prefs::EDIT_FONT_FAMILY_ITALIC),
        bold_italic: family(prefs::EDIT_FONT_FAMILY_BOLD_ITALIC),
        fallback: authored_value(prefs::EDIT_FALLBACK_FONTS)
            .as_deref()
            .map(split_font_list)
            .unwrap_or_default(),
        symbol: family(prefs::EDIT_SYMBOL_FONT),
        emoji: family(prefs::EDIT_EMOJI_FONT),
        variations,
        synthetic_styles: field_bool(state, prefs::EDIT_FONT_SYNTHETIC_STYLE, true),
    }
}

fn preview_resolved_colors(
    state: &SettingsViewState,
    system_dark: bool,
) -> crate::resolved_colors::ResolvedColors {
    let candidate = state
        .environment_override(prefs::EDIT_THEME)
        .map(|active| active.effective.clone())
        .or_else(|| {
            picker_choice(state, prefs::EDIT_THEME).map(|choice| {
                choice
                    .value
                    .clone()
                    .unwrap_or_else(|| "Default".to_string())
            })
        })
        .or_else(|| state.showcase_preview_id());
    preview_resolved_colors_with(state, system_dark, candidate.as_deref())
}

fn showcase_stage_theme(state: &SettingsViewState) -> Option<String> {
    if state.environment_override(prefs::EDIT_THEME).is_some()
        || picker_choice(state, prefs::EDIT_THEME).is_some()
    {
        return None;
    }
    state.showcase_stage_theme_id()
}

fn preview_resolved_colors_with(
    state: &SettingsViewState,
    system_dark: bool,
    candidate: Option<&str>,
) -> crate::resolved_colors::ResolvedColors {
    preview_resolved_colors_on(state, theme_visible_side(state, system_dark), candidate)
}

fn preview_resolved_colors_on(
    state: &SettingsViewState,
    appearance: aterm_types::Appearance,
    candidate: Option<&str>,
) -> crate::resolved_colors::ResolvedColors {
    let authored = |key: &str| {
        state
            .environment_override(key)
            .map(|active| active.effective.clone())
            .or_else(|| {
                (state.is_explicit(key) || state.field_has_unsaved_draft(key))
                    .then(|| field_text(state, key, ""))
            })
            .filter(|value| !value.trim().is_empty())
    };
    let mut config = Config {
        theme: authored(prefs::EDIT_THEME),
        foreground: authored(prefs::EDIT_FOREGROUND),
        background: authored(prefs::EDIT_BACKGROUND),
        cursor_color: authored(prefs::EDIT_CURSOR_COLOR),
        selection_color: authored(prefs::EDIT_SELECTION_COLOR),
        selection_foreground: authored(prefs::EDIT_SELECTION_FOREGROUND),
        ..Config::default()
    };
    config.palette = authored(prefs::EDIT_PALETTE).map(|value| {
        value
            .split(',')
            .map(str::trim)
            .filter(|entry| !entry.is_empty())
            .map(str::to_string)
            .collect()
    });
    config.palette_overrides = state.showcase_palette_overrides();
    config.resolved_colors_previewing(appearance, &state.assets.themes, candidate)
}

fn working_theme_is_light(state: &SettingsViewState, system_dark: bool) -> bool {
    !aterm_render::theme_is_dark(
        PreviewTerminalTheme::from_resolved(&preview_resolved_colors_with(
            state,
            system_dark,
            None,
        ))
        .bg,
    )
}

fn configured_cursor_is_block(state: &SettingsViewState) -> bool {
    !matches!(
        field_text(state, prefs::EDIT_CURSOR_STYLE, "block")
            .trim()
            .to_ascii_lowercase()
            .as_str(),
        "bar" | "beam"
    )
}

#[cfg(test)]
fn preview_terminal_theme(state: &SettingsViewState, system_dark: bool) -> PreviewTerminalTheme {
    PreviewTerminalTheme::from_resolved(&preview_resolved_colors(state, system_dark))
}

#[allow(clippy::too_many_arguments)] // Host paint inputs plus the exact paging budget.
fn renderer_preview(
    state: &SettingsViewState,
    phase_ms: u64,
    motion: crate::native_app::ViewMotionCx,
    terminal_font_px: f32,
    terminal_scale: f32,
    prepared_font: Option<&crate::tray_raster::PreparedSemanticFont>,
    width: SettingsWidth,
    maximum_height: f32,
    preview_width: f32,
) -> Option<UiNode> {
    let spec = renderer_preview_spec_with_font(
        state,
        phase_ms,
        motion,
        terminal_font_px,
        terminal_scale,
        prepared_font,
    )?
    .with_measure_width(preview_width);
    let preview_path = renderer_preview_path(state);
    let height = if spec.scene == PreviewScene::Typography {
        spec.preferred_height(renderer_preview_height(width))
            .min(2.0 * renderer_preview_height(width))
            .min(maximum_height.max(96.0))
    } else {
        renderer_preview_height(width)
            .min(maximum_height)
            .max(spec.minimum_height(48.0))
    };
    let key = format!("settings/preview{preview_path}");
    Some(crate::settings_preview::preview_node(key, spec, height))
}

fn renderer_preview_spec(
    state: &SettingsViewState,
    phase_ms: u64,
    motion: crate::native_app::ViewMotionCx,
    terminal_font_px: f32,
    terminal_scale: f32,
) -> Option<SettingsPreviewSpec> {
    renderer_preview_spec_with_font(
        state,
        phase_ms,
        motion,
        terminal_font_px,
        terminal_scale,
        None,
    )
}

fn renderer_preview_spec_with_font(
    state: &SettingsViewState,
    phase_ms: u64,
    motion: crate::native_app::ViewMotionCx,
    terminal_font_px: f32,
    terminal_scale: f32,
    prepared_font: Option<&crate::tray_raster::PreparedSemanticFont>,
) -> Option<SettingsPreviewSpec> {
    let focused_key = focused_preview_key(state)?;
    renderer_preview_spec_for_key_with_font(
        state,
        &focused_key,
        phase_ms,
        motion,
        terminal_font_px,
        terminal_scale,
        prepared_font,
    )
}

#[allow(clippy::too_many_arguments)] // One projection shared by paint, inspection and cadence.
fn renderer_preview_spec_for_key_with_font(
    state: &SettingsViewState,
    focused_key: &str,
    phase_ms: u64,
    motion: crate::native_app::ViewMotionCx,
    terminal_font_px: f32,
    terminal_scale: f32,
    prepared_font: Option<&crate::tray_raster::PreparedSemanticFont>,
) -> Option<SettingsPreviewSpec> {
    let route = preview_route_for_key(focused_key)?;
    let style_candidate = cursor_style_candidate(state);
    let previews_serious_mode_exit = motion.serious
        && focused_key == prefs::EDIT_CURSOR_TRAIL_STYLE
        && style_candidate
            .as_deref()
            .is_some_and(|style| !style.eq_ignore_ascii_case("off"));
    let serious_preview_suppression = motion.serious && !previews_serious_mode_exit;
    let font_px = preview_font_px(state, terminal_font_px / terminal_scale.max(f32::EPSILON));
    let font_candidate = preview_font_candidate(state);
    let resolved = preview_resolved_colors(state, motion.system_dark);
    let terminal_theme_candidate = PreviewTerminalTheme::from_resolved(&resolved);
    let terminal_theme_identity = crate::settings_preview::PreviewThemeIdentity::from_resolved(
        &resolved,
        &state.assets.themes,
    );
    let appearance = AppearancePreviewSpec {
        window_theme: preview_field_text(state, prefs::EDIT_WINDOW_THEME, "auto"),
        minimum_contrast: preview_effective_minimum_contrast(state),
        indexed_minimum_contrast: preview_indexed_minimum_contrast(state),
        selection_foreground: resolved
            .selection_fg()
            .map(crate::settings_preview::pack_rgb),
        selection_inactive: field_bool(state, prefs::EDIT_SELECTION_INACTIVE, false),
        bold_is_bright: field_bool(state, prefs::EDIT_BOLD_IS_BRIGHT, true),
        faint_opacity: field_number(state, prefs::EDIT_FAINT_OPACITY, 0.5_f32),
    };
    let typography = TypographyPreviewSpec {
        cursor_break_ligatures: field_bool(state, prefs::EDIT_CURSOR_BREAK_LIGATURES, false),
        underline_position: field_number(state, prefs::EDIT_ADJUST_UNDERLINE_POSITION, 0_i32),
        underline_thickness: field_number(state, prefs::EDIT_ADJUST_UNDERLINE_THICKNESS, 0_i32),
        underline_skip_descenders: field_bool(state, prefs::EDIT_UNDERLINE_SKIP_DESCENDERS, true),
        text_blending: if field_text(state, prefs::EDIT_TEXT_BLENDING, "linear-corrected")
            .eq_ignore_ascii_case("linear")
        {
            crate::widget::SpecimenTextBlending::Linear
        } else {
            crate::widget::SpecimenTextBlending::LinearCorrected
        },
        font_thicken: field_bool(state, prefs::EDIT_FONT_THICKEN, false),
        stem_gamma: preview_field_number(state, prefs::EDIT_STEM_GAMMA, 1.0_f32),
        variations: font_candidate.variations.clone(),
    };

    let motion_raw = field_text(state, prefs::EDIT_MOTION, "auto");
    let motion_mode = crate::motion::MotionMode::parse(&motion_raw);
    let adaptive_motion = field_bool(state, prefs::EDIT_LOAD_ADAPTIVE_MOTION, true);
    let focus_load_probe = focused_key == prefs::EDIT_LOAD_ADAPTIVE_MOTION;
    let effective_load_reduced = motion.performance_reduced || focus_load_probe;
    let load_shed =
        effective_load_reduced && adaptive_motion && motion_mode == crate::motion::MotionMode::Auto;
    let motion_policy = if load_shed {
        crate::motion::MotionPolicy::Reduced
    } else {
        crate::motion::MotionPolicy::resolve(motion_mode, motion.system_reduced, motion.focused)
    };
    let reduced_motion =
        serious_preview_suppression || motion_policy == crate::motion::MotionPolicy::Reduced;
    let pause = if serious_preview_suppression {
        PreviewPause::SeriousMode
    } else if load_shed {
        PreviewPause::Load
    } else if motion_mode == crate::motion::MotionMode::Reduced {
        PreviewPause::MotionSetting
    } else if motion_mode == crate::motion::MotionMode::Auto && motion.system_reduced {
        PreviewPause::SystemReduceMotion
    } else if !motion.focused {
        PreviewPause::Unfocused
    } else {
        PreviewPause::Unspecified
    };
    let motion_reason = if reduced_motion {
        pause.audit()
    } else if previews_serious_mode_exit {
        "the highlighted trail previews its post-commit state; other playful effects stay off"
    } else if focus_load_probe {
        "the bounded adaptive-motion demo is bypassing its representative load signal"
    } else if motion_mode == crate::motion::MotionMode::Full {
        "motion=full explicitly enables motion"
    } else {
        "motion=auto follows the active system policy"
    };

    let committed_kitty_sprite = state
        .raw_value(prefs::EDIT_CURSOR_NYAN_SPRITE)
        .unwrap_or_default();
    let kitty_sprite_value = state
        .field_inputs
        .get(prefs::EDIT_CURSOR_NYAN_SPRITE)
        .filter(|_| state.editing_field.as_deref() == Some(prefs::EDIT_CURSOR_NYAN_SPRITE))
        .map_or_else(
            || committed_kitty_sprite.clone(),
            |input| input.projection().text,
        );
    let kitty_asset = if kitty_sprite_value.trim().is_empty() {
        crate::app_config::KittySpriteAsset::BuiltIn
    } else if kitty_sprite_value.trim() == committed_kitty_sprite.trim() {
        state.config_assets().kitty_sprite.clone()
    } else {
        crate::app_config::KittySpriteAsset::Invalid {
            source_id: Arc::from(kitty_sprite_value.as_str()),
            bounded_reason: Arc::from(
                "uncommitted source is disabled until config validation admits its decoded pixels",
            ),
        }
    };
    let post_fx = CursorPostFxSpec {
        kitty_sprite: if kitty_sprite_value.is_empty() {
            "built-in CatBaker".to_string()
        } else {
            kitty_sprite_value
        },
        kitty_asset,
        bloom: !serious_preview_suppression
            && field_bool(state, prefs::EDIT_CURSOR_TRAIL_BLOOM, true),
        bloom_strength: field_number(state, prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH, 0.85_f32),
        bloom_radius: field_number(
            state,
            prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
            Config::bloom_radius_style_default(crate::app_config::resolve_trail_style(
                style_candidate.as_deref().unwrap_or(&field_text(
                    state,
                    prefs::EDIT_CURSOR_TRAIL_STYLE,
                    crate::app_config::default_cursor_trail_style(),
                )),
            )),
        ),
        fire_shimmer: !serious_preview_suppression
            && field_bool(state, prefs::EDIT_CURSOR_FIRE_SHIMMER, true),
        hdr_glow: !serious_preview_suppression && field_bool(state, prefs::EDIT_HDR_GLOW, true),
        sdr_boost: if serious_preview_suppression {
            0.0
        } else {
            field_number(state, prefs::EDIT_CURSOR_GLOW_SDR_BOOST, 0.25_f32)
        },
        display_edr: motion.display_edr,
        motion_raw,
        motion_effective: if reduced_motion { "reduced" } else { "full" }.to_string(),
        motion_reason: motion_reason.to_string(),
        adaptive_motion,
        performance_reduced: effective_load_reduced,
        companion_look: motion.companion_look,
    };

    let cursor_style = if configured_cursor_is_block(state) {
        PreviewCursorStyle::Block
    } else {
        PreviewCursorStyle::Bar
    };
    let spelled = spelled_trail_value(state);
    let canonical = |raw: &str| crate::app_config::resolve_trail_style(raw).canonical;
    let trail_style_value = style_candidate
        .clone()
        .filter(|candidate| canonical(candidate) != canonical(&spelled))
        .unwrap_or(spelled);
    let resolved_trail = crate::app_config::resolve_trail_style(&trail_style_value);
    let trail_color =
        prefs::trail_color_setting(Some(&field_text(state, prefs::EDIT_CURSOR_TRAIL_COLOR, "")));
    let default_intensity = aterm_effects::cursor_fx::default_trail_intensity(
        resolved_trail.style,
        trail_color.chosen()
            || aterm_effects::cursor_glow::GlowStyle::style_names_classic_mono(
                trail_style_value.trim(),
            ),
    );
    let mut cursor = CursorPreviewSpec {
        style: cursor_style,
        blink: field_bool(state, prefs::EDIT_CURSOR_BLINK, true),
        trail_enabled: !serious_preview_suppression,
        trail_style: PreviewTrailStyle::from_resolution(resolved_trail),
        trail_style_raw: Arc::from(trail_style_value),
        color: trail_color,
        accent: field_color(state, prefs::EDIT_CURSOR_TRAIL_ACCENT),
        duration_ms: field_number(state, prefs::EDIT_CURSOR_TRAIL_MS, 260_u64),
        length: field_number(state, prefs::EDIT_CURSOR_TRAIL_LENGTH, 24_usize),
        intensity: field_number(state, prefs::EDIT_CURSOR_TRAIL_INTENSITY, default_intensity),
        radius: field_number(state, prefs::EDIT_CURSOR_TRAIL_RADIUS, 0.6_f32),
        ring: field_bool(state, prefs::EDIT_CURSOR_TRAIL_RING, true),
        momentum_glow: field_bool(
            state,
            prefs::EDIT_CURSOR_MOMENTUM_GLOW,
            crate::app_config::DEFAULT_DECORATIVE_EFFECTS,
        ),
        cursor_color_pinned: field_color(state, prefs::EDIT_CURSOR_COLOR).is_some(),
    };
    if !serious_preview_suppression && focused_key == prefs::EDIT_CURSOR_FIRE_SHIMMER {
        cursor.trail_style = PreviewTrailStyle::Fire;
        cursor.trail_enabled = true;
    }
    let mut spec = match route {
        SettingsRoute::Appearance => SettingsPreviewSpec::appearance(font_px),
        SettingsRoute::TextFonts => SettingsPreviewSpec::typography(font_px),
        SettingsRoute::CursorMotion | SettingsRoute::CursorStyles => {
            SettingsPreviewSpec::cursor(cursor.clone())
        }
        _ => return None,
    };
    spec.terminal_scale = terminal_scale;
    spec.scene = match route {
        SettingsRoute::Appearance => PreviewScene::Appearance,
        SettingsRoute::TextFonts => PreviewScene::Typography,
        SettingsRoute::CursorMotion | SettingsRoute::CursorStyles => PreviewScene::CursorMotion,
        _ => return None,
    };
    if matches!(
        route,
        SettingsRoute::CursorMotion | SettingsRoute::CursorStyles
    ) {
        spec.cursor = cursor;
    }
    if route == SettingsRoute::Appearance {
        spec.wallpaper = preview_wallpaper(state);
    }
    let stage_theme = (focused_key == prefs::EDIT_THEME)
        .then(|| showcase_stage_theme(state))
        .flatten();
    let theme_sample = stage_theme.is_some() && state.showcase_preview_id().is_some();
    let focused_value = if let Some(theme) = stage_theme {
        theme
    } else if focused_key == prefs::EDIT_CURSOR_TRAIL_STYLE {
        style_candidate
            .clone()
            .unwrap_or_else(|| top_projected_trail_value(state))
    } else {
        let value = preview_field_text(state, focused_key, "");
        if font_picker_key(focused_key)
            && state.environment_override(focused_key).is_none()
            && state
                .field_by_key(focused_key)
                .is_some_and(|field| field.seed.is_none())
            && !state.field_has_unsaved_draft(focused_key)
        {
            font_automatic_label(state, focused_key)
        } else if value.is_empty() {
            effective_default_for_field(focused_key)
        } else if focused_key == prefs::EDIT_THEME
            && prefs::theme_mode(Some(&value)) == prefs::ThemeMode::FollowSystem
        {
            resolved.id.clone()
        } else if focused_key == prefs::EDIT_CURSOR_TRAIL_COLOR
            && value.trim().eq_ignore_ascii_case(prefs::TRAIL_COLOR_CURSOR)
        {
            prefs::TRAIL_COLOR_CURSOR_LABEL.to_string()
        } else if state
            .field_by_key(focused_key)
            .is_some_and(|field| field.kind == EditKind::Color)
            && !prefs::color_value_is_valid(focused_key, &value)
        {
            state
                .raw_value(focused_key)
                .filter(|saved| aterm_types::scheme::parse_hex(saved).is_some())
                .unwrap_or_else(|| effective_default_for_field(focused_key))
        } else {
            value
        }
    };
    let focused_value = if focused_key == prefs::EDIT_THEME
        && prefs::theme_mode(Some(&focused_value)) != prefs::ThemeMode::FollowSystem
        && let Some(meta) = state.assets.themes.meta(focused_value.trim())
    {
        meta.display_name
    } else {
        focused_value
    };
    let prepared_font = prepared_font
        .filter(|prepared| prepared.matches(&font_candidate))
        .cloned()
        .unwrap_or_else(|| {
            crate::tray_raster::PreparedSemanticFont::unavailable(font_candidate.clone())
        });
    Some(
        spec.with_terminal_theme(terminal_theme_candidate)
            .with_terminal_theme_identity(terminal_theme_identity)
            .with_authored_chrome(resolved.authored_chrome())
            .with_typography(
                field_number(
                    state,
                    prefs::EDIT_LINE_HEIGHT,
                    crate::app_config::DEFAULT_LINE_HEIGHT,
                ),
                field_number(state, prefs::EDIT_ADJUST_BASELINE, 0_i32),
                field_bool(state, prefs::EDIT_LIGATURES, true),
                field_bool(state, prefs::EDIT_MERGED_LIGATURES, false),
                field_bool(state, prefs::EDIT_FONT_SYNTHETIC_STYLE, true),
            )
            .with_font_candidate(font_candidate)
            .with_prepared_font(prepared_font)
            .with_refused_fonts(state.refused_font_slots())
            .with_appearance(appearance)
            .with_typography_candidate(typography)
            .with_post_fx(post_fx)
            .with_focus(focused_key, focused_value)
            .with_theme_sample(theme_sample)
            .with_style_trial(
                cursor_style_trial_from(state)
                    .filter(|_| focused_key == prefs::EDIT_CURSOR_TRAIL_STYLE)
                    .map(|(_, source)| source),
            )
            .with_focused_effect(focused_row_idle_note(state, focused_key, motion))
            .with_focus_label(
                state
                    .field_by_key(focused_key)
                    .map_or("", |field| field.label),
            )
            .with_reduced_motion(reduced_motion)
            .with_pause(pause)
            .with_paused(state.preview_paused)
            .map_phase(|spec| {
                state
                    .preview_clock
                    .phase(focused_key, spec.loop_identity(), phase_ms)
            }),
    )
}

#[derive(Debug, Default)]
struct PreviewClock {
    entries: std::cell::RefCell<Vec<(String, u64, u64, u64)>>,
}

impl PreviewClock {
    const ENTRIES: usize = 8;
    const RESUME_MS: u64 = 250;

    fn phase(&self, key: &str, identity: Option<u64>, phase_ms: u64) -> u64 {
        let Some(identity) = identity else {
            return phase_ms;
        };
        let mut entries = self.entries.borrow_mut();
        let known = entries
            .iter()
            .position(|(k, id, _, _)| k == key && *id == identity);
        let latest = entries.iter().position(|(k, ..)| k == key);
        let origin = match known {
            Some(at) => {
                let (_, _, origin, seen) = entries[at];
                let resumed =
                    latest == Some(at) || (phase_ms >= seen && phase_ms - seen <= Self::RESUME_MS);
                entries.remove(at);
                if resumed { origin } else { phase_ms }
            }
            None if entries.iter().all(|(k, ..)| k != key) => 0,
            None => phase_ms,
        };
        entries.insert(0, (key.to_string(), identity, origin, phase_ms));
        entries.truncate(Self::ENTRIES);
        phase_ms.saturating_sub(origin)
    }
}

fn focused_row_idle_note(
    state: &SettingsViewState,
    focused_key: &str,
    motion: crate::native_app::ViewMotionCx,
) -> Option<String> {
    if focused_key.is_empty()
        || matches!(
            focused_key,
            prefs::EDIT_CURSOR_TRAIL_STYLE | prefs::EDIT_CURSOR_FIRE_SHIMMER
        )
        || state.field_index_of(focused_key).is_none()
    {
        return None;
    }
    setting_effect_projection(
        state,
        None,
        focused_key,
        SettingsAvailability::for_state(state),
        motion,
    )
    .notes
    .into_iter()
    .find(|note| {
        matches!(
            note.kind,
            EffectNoteKind::Inactive | EffectNoteKind::Unavailable
        )
    })
    .map(|note| note.visual)
}

fn preview_wallpaper(state: &SettingsViewState) -> Option<crate::widget::SpecimenWallpaper> {
    let crate::app_config::WallpaperAsset::Ready { w, h, rgba, fp, .. } =
        &state.config_assets().wallpaper
    else {
        return None;
    };
    state.raw_value(prefs::EDIT_WALLPAPER)?;
    Some(crate::widget::SpecimenWallpaper {
        rgba: Arc::clone(rgba),
        w: *w as usize,
        h: *h as usize,
        fp: *fp,
        dim: field_number(state, prefs::EDIT_WALLPAPER_DIM, 0.3_f32).clamp(0.0, 1.0),
        tint: field_bool(state, prefs::EDIT_WALLPAPER_TEXT_TINT, true),
    })
}

fn wallpaper_preview(
    state: &SettingsViewState,
    cx: &ViewCx<'_>,
    width: SettingsWidth,
    room: f32,
    preview_width: f32,
) -> Option<(UiNode, f32)> {
    let wallpaper = preview_wallpaper(state)?;
    let mut spec = renderer_preview_spec_for_key_with_font(
        state,
        prefs::EDIT_WALLPAPER,
        cx.animation_phase_ms,
        cx.motion,
        cx.terminal_font_px,
        cx.terminal_scale,
        cx.semantic_font.as_ref(),
    )?
    .with_measure_width(preview_width);
    spec.scene = PreviewScene::Wallpaper;
    spec.wallpaper = Some(wallpaper);
    spec.focused_value = wallpaper_words(state)
        .map(|(visual, _)| visual)
        .unwrap_or_default();
    let least = spec.minimum_height(48.0);
    let height = renderer_preview_height(width)
        .max(least)
        .min(room.max(least));
    Some((
        crate::settings_preview::preview_node("settings/preview/wallpaper", spec, height),
        height.max(96.0),
    ))
}

const fn renderer_preview_height(width: SettingsWidth) -> f32 {
    match width {
        SettingsWidth::Compact => 108.0,
        SettingsWidth::Medium => 132.0,
        SettingsWidth::Wide => 156.0,
    }
}

/// The one action that goes to `route`.
pub(crate) fn route_action(route: SettingsRoute) -> ActionId {
    ActionId::new(format!("settings/route{}", route.path()))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SettingsWidth {
    Compact,
    Medium,
    Wide,
}

impl SettingsWidth {
    fn for_viewport(width: f32) -> Self {
        Self::for_viewport_at_scale(width, crate::native_appearance::text_scale())
    }

    fn for_viewport_at_scale(width: f32, text_scale: f32) -> Self {
        let effective_width = width / text_scale.clamp(0.85, 2.0);
        if effective_width >= 1_040.0 {
            Self::Wide
        } else if effective_width >= 760.0 {
            Self::Medium
        } else {
            Self::Compact
        }
    }

    fn row_height(self) -> f32 {
        self.row_height_at_scale(settings_text_scale())
    }

    fn row_height_at_scale(self, scale: f32) -> f32 {
        let scale = scale.clamp(0.85, 2.0);
        match self {
            Self::Compact => {
                let label_height = 22.0_f32.max(20.0 * scale);
                let control_height = scaled_control_height_at_scale(scale);
                72.0_f32.max(label_height + control_height + 4.0)
            }
            Self::Medium | Self::Wide => 44.0_f32.max(40.0 * scale),
        }
    }
}

fn settings_text_scale() -> f32 {
    crate::native_appearance::text_scale().clamp(0.85, 2.0)
}

pub(crate) fn scaled_control_height() -> f32 {
    scaled_control_height_at_scale(settings_text_scale())
}

fn scaled_control_height_at_scale(scale: f32) -> f32 {
    44.0_f32.max(32.0 * scale.clamp(0.85, 2.0))
}

fn compact_toolbar_height() -> f32 {
    compact_toolbar_height_at_scale(settings_text_scale())
}

fn compact_toolbar_height_at_scale(scale: f32) -> f32 {
    52.0_f32.max(40.0 * scale.clamp(0.85, 2.0))
}

fn page_heading_height() -> f32 {
    34.0 * settings_text_scale()
}

fn page_subtitle_height() -> f32 {
    24.0_f32.max(20.0 * settings_text_scale())
}

fn group_heading_label_height() -> f32 {
    22.0_f32.max(16.0 * settings_text_scale())
}

fn navigation_row_height(scale: f32) -> f32 {
    32.0_f32.max(24.0 * scale)
}

const NAVIGATION_GAP: f32 = 2.0;

fn status_scroll_target(key: &UiKey) -> bool {
    let key = key.as_str();
    [
        "settings/feedback",
        "settings/status",
        "settings/draft-recovery/status",
    ]
    .iter()
    .any(|bar| {
        key == *bar
            || key
                .strip_prefix(bar)
                .is_some_and(|rest| rest.starts_with('/'))
    })
}

fn navigation_scroll_target(key: &UiKey) -> bool {
    let key = key.as_str();
    key == "settings/navigation"
        || key == "settings/navigation-title"
        || [
            "settings/navigation/",
            "settings/nav/",
            "settings/nav-label/",
            "settings/nav-sub/",
        ]
        .iter()
        .any(|prefix| key.starts_with(prefix))
}

fn settings_tree(
    state: &SettingsViewState,
    update: &UpdateProjection,
    packages: &PackagesProjection,
    messages: &MessagesState,
    harness: &HarnessProjection,
    cx: &ViewCx<'_>,
) -> UiTree {
    state.page_window.set(None);
    state.observe_semantic_font(cx.semantic_font.as_ref());
    state.status_bar_most.set(None);
    #[cfg(test)]
    if STATUS_BAR_LEAST.with(Cell::get) {
        state.status_bar_most.set(Some(0.0));
    }
    state.record_runtime_presentation(cx.motion, packages, update);
    let width = SettingsWidth::for_viewport(cx.viewport.width);
    let watch_status_height = config_watch_status_bar_height(state);
    let available_height = (cx.viewport.height - watch_status_height).max(0.0);
    state.record_presented_width(width);
    let compact_status_docked =
        width == SettingsWidth::Compact && compact_status_dock_required(state, cx.viewport);
    let question_page = reset_all_question_takes_page(state, cx.viewport);
    state
        .presented_plain_dock
        .set(compact_status_docked && state.plain_status());
    let watch_status = (!compact_status_docked)
        .then(|| config_watch_status_bar(state, cx.viewport))
        .flatten();
    let page = if question_page {
        reset_all_question_page(state, cx.viewport)
    } else {
        page(state, update, packages, messages, harness, cx, width)
    };
    let feedback = (!compact_status_docked && !question_page)
        .then(|| feedback_bar(state, width, cx.viewport))
        .flatten();
    let (body, root_feedback) = match width {
        SettingsWidth::Compact => {
            let body = UiNode::new(
                "settings/body",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::column().height(Length::Fill).clipped())
            .children(vec![
                compact_toolbar(state, cx.viewport, compact_status_docked),
                page,
            ]);
            (body, feedback)
        }
        SettingsWidth::Medium | SettingsWidth::Wide => {
            let mut content_children = vec![page];
            if let Some(feedback) = feedback {
                content_children.push(feedback);
            }
            let content = UiNode::new(
                "settings/content",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fill)
                    .clipped(),
            )
            .children(content_children);
            let body = UiNode::new(
                "settings/body",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::row().height(Length::Fill).clipped())
            .children(vec![
                navigation(state, packages, width, available_height),
                content,
            ]);
            (body, None)
        }
    };

    let mut app_children = vec![body];
    if let Some(status) = watch_status {
        app_children.push(status);
    }
    if let Some(feedback) = root_feedback {
        app_children.push(feedback);
    }

    let surface = if cx.motion.serious {
        StyleRef::Plain
    } else {
        StyleRef::Hero
    };
    UiTree::new(
        UiNode::new(
            "settings/app",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Application).style(surface)),
        )
        .layout(Layout::column().clipped())
        .children(app_children),
    )
}

fn config_watch_status_bar(state: &SettingsViewState, viewport: LogicalRect) -> Option<UiNode> {
    let status = state.config_watch_status.as_ref()?;
    let visual_status =
        crate::native_ui::fit_native_status_label(status, (viewport.width - 32.0).max(0.0));
    Some(
        UiNode::new(
            "settings/config-watch-status",
            UiContent::Group(
                GroupSpec::new("Configuration reload warning").style(StyleRef::Danger),
            ),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(config_watch_status_bar_height(state)))
                .padding(Insets::symmetric(16.0, 5.0))
                .gap(2.0),
        )
        .children(vec![
            UiNode::new(
                "settings/config-watch-status/title",
                UiContent::Group(GroupSpec {
                    label: Some("Reload warning".to_string()),
                    role: SemanticRole::Heading,
                    style: StyleRef::Danger,
                }),
            )
            .layout(
                Layout::default()
                    .width(Length::Fill)
                    .height(Length::Fixed(scaled_control_height() * 0.75)),
            )
            .children(vec![
                UiNode::new(
                    "settings/config-watch-status/title/visual",
                    UiContent::Text(TextSpec {
                        text: "Reload warning".to_string(),
                        role: SemanticRole::Text,
                        style: StyleRef::Danger,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
                .paint_only(),
            ]),
            UiNode::new(
                "settings/config-watch-status/detail",
                UiContent::Group(GroupSpec {
                    label: Some(format!("Reload warning. {status}")),
                    role: SemanticRole::Status,
                    style: StyleRef::Plain,
                }),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill))
            .children(vec![
                UiNode::new(
                    "settings/config-watch-status/detail/visual",
                    UiContent::Text(TextSpec {
                        text: visual_status,
                        role: SemanticRole::Status,
                        style: StyleRef::Plain,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
                .paint_only(),
            ]),
        ]),
    )
}

fn settings_search(state: &SettingsViewState, placeholder: &str) -> UiNode {
    let (search_value, _) = state.search_input.display_projection();
    UiNode::new(
        "settings/search",
        UiContent::TextField(
            Control::new(
                TextFieldSpec {
                    label: "Search pages, settings and aterm.toml keys".to_string(),
                    placeholder: Some(placeholder.to_string()),
                    secret: false,
                    visual_value: None,
                    input: Some(state.search_input.projection()),
                    swatch: None,
                    swatch_line: false,
                    trailing_hint: None,
                    description: None,
                    end_button: false,
                },
                ActionId::new("settings/search"),
            )
            .value(SemanticValue::Text(search_value))
            .state(ControlState {
                focused: state
                    .common
                    .last_focus
                    .as_ref()
                    .is_some_and(|key| key.as_str() == "settings/search"),
                ..ControlState::default()
            })
            .style(StyleRef::Secondary),
        ),
    )
}

fn search_placeholder(field_width: f32) -> String {
    let fitted =
        |words: &str| crate::native_ui::fit_native_field_placeholder(words, field_width, false);
    if fitted("Search…") == "Search…" {
        "Search…".to_string()
    } else {
        fitted("Search")
    }
}

fn compact_search_is_a_button(field_width: f32) -> bool {
    crate::native_ui::fit_native_field_placeholder("Search", field_width, false) != "Search"
}

fn compact_search_shows_its_field(state: &SettingsViewState) -> bool {
    state.search_open
        || !state.search_input.value().is_empty()
        || !state.search.is_empty()
        || state.search_has_focus()
}

fn compact_search_open_button() -> UiNode {
    UiNode::new(
        SEARCH_OPEN,
        UiContent::Button(
            Control::new(
                ButtonSpec::new("Search Settings")
                    .visual_icon(ButtonIcon::Search)
                    .description("Opens the search field"),
                ActionId::new(SEARCH_OPEN),
            )
            .style(StyleRef::Navigation),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(56.0 * settings_text_scale().min(1.4)))
            .height(Length::Fill),
    )
}

fn compact_open_search(state: &SettingsViewState, width: f32, height: f32) -> UiNode {
    let end = crate::native_ui::TEXT_FIELD_END_BUTTON;
    let placeholder = search_placeholder(width - end - crate::native_ui::TEXT_FIELD_END_BUTTON_GAP);
    let mut field = settings_search(state, &placeholder)
        .layout(Layout::default().width(Length::Fill).height(Length::Fill));
    if let UiContent::TextField(spec) = &mut field.content {
        spec.spec.end_button = true;
    }
    let pad = ((height - end) / 2.0).max(0.0);
    let cancel = UiNode::new(
        SEARCH_CANCEL,
        UiContent::Button(
            Control::new(
                ButtonSpec::new("Cancel search")
                    .visual_label("")
                    .visual_icon(ButtonIcon::Clear),
                ActionId::new(SEARCH_CANCEL),
            )
            .style(StyleRef::Quiet),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(end))
            .height(Length::Fill),
    );
    let end_row = UiNode::new(
        "settings/search-bar/end",
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::row()
            .width(Length::Fill)
            .height(Length::Fill)
            .padding(Insets {
                top: pad,
                right: pad,
                bottom: pad,
                left: 0.0,
            }),
    )
    .children(vec![
        UiNode::new(
            "settings/search-bar/lead",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
        cancel,
    ]);
    UiNode::new(
        "settings/search-bar",
        UiContent::Group(GroupSpec::new("Settings search")),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill))
    .children(vec![field, end_row])
}

const SEARCH_OPEN: &str = "settings/search-open";
const SEARCH_CANCEL: &str = "settings/search-cancel";

fn settings_search_bar(state: &SettingsViewState, placeholder: &str, height: Length) -> UiNode {
    let mut children = vec![
        settings_search(state, placeholder)
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
    ];
    if !state.search_input.value().is_empty() || !state.search.is_empty() {
        let clear_width =
            (crate::tray_raster::ui_text_width("Clear", 13.0 * settings_text_scale()) + 24.0)
                .max(44.0);
        children.push(
            UiNode::new(
                "settings/search-clear",
                UiContent::Button(
                    Control::new(
                        ButtonSpec::new("Clear search").visual_label("Clear"),
                        ActionId::new("settings/search-clear"),
                    )
                    .style(StyleRef::Quiet),
                ),
            )
            .layout(
                Layout::default()
                    .width(Length::Fixed(clear_width))
                    .height(Length::Fill),
            ),
        );
    }
    UiNode::new(
        "settings/search-bar",
        UiContent::Group(GroupSpec::new("Settings search")),
    )
    .layout(Layout::row().width(Length::Fill).height(height).gap(4.0))
    .children(children)
}

const ALL_SETTINGS: &str = "All Settings";

fn compact_title_width(title: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Plain);
    crate::tray_raster::ui_text_width_for(face, title, px).ceil()
}

fn compact_search_least() -> f32 {
    160.0 * settings_text_scale()
}

fn compact_title_widest() -> f32 {
    SettingsRoute::ALL
        .iter()
        .map(|route| route.label())
        .chain([ALL_SETTINGS, "Search Results"])
        .map(compact_title_width)
        .fold(0.0, f32::max)
}

fn compact_titled_leading(viewport: LogicalRect) -> Option<(ButtonSpec, f32)> {
    let scale = settings_text_scale();
    let room = viewport.width - 20.0 - 16.0 - compact_title_widest() - compact_search_least();
    let least = 94.0 * scale.min(1.4);
    if least > room {
        return None;
    }
    let label = crate::native_ui::native_button_label_width(ALL_SETTINGS);
    let with_arrow = (40.0 + label + 12.0).ceil().max(96.0);
    let spec = ButtonSpec::new(ALL_SETTINGS).visual_icon(ButtonIcon::Back);
    Some(if with_arrow <= room {
        (spec.visual_label(ALL_SETTINGS), with_arrow)
    } else {
        (spec, 56.0 * scale.min(1.4))
    })
}

fn compact_toolbar_titles(width: SettingsWidth, viewport: LogicalRect) -> bool {
    width == SettingsWidth::Compact && compact_titled_leading(viewport).is_some()
}

fn page_named(width: SettingsWidth, viewport: LogicalRect) -> bool {
    compact_toolbar_titles(width, viewport) || window_page_chrome(width, viewport).0
}

fn compact_page_title(state: &SettingsViewState, slot: f32) -> &'static str {
    if !state.search.trim().is_empty() {
        "Search Results"
    } else if state.compact_navigation {
        ALL_SETTINGS
    } else if state.route == SettingsRoute::Harness
        && compact_title_width(harness_page::HARNESS_PAGE_TITLE) <= slot
    {
        harness_page::HARNESS_PAGE_TITLE
    } else {
        state.route.label()
    }
}

fn compact_toolbar_leading(
    state: &SettingsViewState,
    viewport: LogicalRect,
    status_docked: bool,
) -> (ButtonSpec, f32) {
    if state.compact_navigation {
        let spec = ButtonSpec::new("Done")
            .visual_label("Done")
            .description("Closes the settings categories");
        return (spec, 94.0 * settings_text_scale().min(1.4));
    }
    let spec = ButtonSpec::new(ALL_SETTINGS);
    if status_docked {
        return (spec.visual_icon(ButtonIcon::Back), 56.0);
    }
    if let Some(titled) = compact_titled_leading(viewport) {
        return titled;
    }
    let search = crate::native_ui::native_button_label_width("Search\u{2026}") + 40.0;
    let room = (viewport.width - 20.0 - 8.0 - search).max(0.0);
    let label = crate::native_ui::native_button_label_width(ALL_SETTINGS);
    let with_arrow = (40.0 + label + 12.0).ceil();
    let alone = (label + 24.0).ceil();
    if with_arrow <= room {
        (
            spec.visual_icon(ButtonIcon::Back)
                .visual_label(ALL_SETTINGS),
            with_arrow.max(96.0).min(room),
        )
    } else if alone <= room {
        (spec.visual_label(ALL_SETTINGS), alone)
    } else {
        (
            spec.visual_icon(ButtonIcon::Back),
            56.0 * settings_text_scale().min(1.4),
        )
    }
}

fn compact_toolbar(
    state: &SettingsViewState,
    viewport: LogicalRect,
    status_docked: bool,
) -> UiNode {
    let (spec, leading_width) = compact_toolbar_leading(state, viewport, status_docked);
    let leading_height = if status_docked {
        Length::Fixed(scaled_control_height())
    } else {
        Length::Fill
    };
    let key = if state.compact_navigation {
        "settings/compact-navigation-close"
    } else {
        "settings/compact-navigation"
    };
    let leading = UiNode::new(
        key,
        UiContent::Button(Control::new(spec, ActionId::new(key)).style(StyleRef::Navigation)),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(leading_width))
            .height(leading_height),
    );
    let mut children = vec![leading];
    let mut under = None;
    if status_docked {
        let dock = compact_status_dock(state, viewport)
            .expect("a docked compact status always has a watcher or feedback");
        children.push(dock.dock);
        under = dock.under;
    } else {
        let mut title_width = 0.0;
        if compact_toolbar_titles(SettingsWidth::Compact, viewport) {
            let slot = viewport.width - 20.0 - leading_width - 16.0 - compact_search_least();
            let title = compact_page_title(state, slot);
            title_width = compact_title_width(title);
            children.push(
                UiNode::new(
                    format!("settings/page-heading/{}", key_fragment(title)),
                    UiContent::Text(TextSpec {
                        text: title.to_string(),
                        role: SemanticRole::Heading,
                        style: StyleRef::Plain,
                    }),
                )
                .layout(
                    Layout::default()
                        .width(Length::Fixed(title_width))
                        .height(Length::Fill),
                ),
            );
        }
        let field_width = viewport.width
            - 2.0 * 10.0
            - 8.0
            - leading_width
            - if title_width > 0.0 {
                title_width + 8.0
            } else {
                0.0
            };
        if !compact_search_is_a_button(field_width) {
            children.push(settings_search_bar(
                state,
                &search_placeholder(field_width),
                Length::Fill,
            ));
        } else if !compact_search_shows_its_field(state) {
            children.push(compact_search_open_button());
        } else {
            children = vec![compact_open_search(
                state,
                viewport.width - 2.0 * 10.0,
                compact_header_height(state, viewport) - 2.0 * 8.0,
            )];
        }
    }
    let toolbar = UiNode::new(
        "settings/compact-toolbar",
        UiContent::Group(GroupSpec::new("Settings toolbar").style(StyleRef::Secondary)),
    );
    let header = compact_header_height(state, viewport);
    let Some(under) = under else {
        return toolbar
            .layout(
                Layout::row()
                    .height(Length::Fixed(header))
                    .padding(Insets::symmetric(10.0, 8.0))
                    .gap(8.0),
            )
            .children(children);
    };
    let top = (header - 16.0 - 8.0 - fixed_height(&under)).max(scaled_control_height());
    toolbar
        .layout(
            Layout::column()
                .height(Length::Fixed(header))
                .padding(Insets::symmetric(10.0, 8.0))
                .gap(8.0),
        )
        .children(vec![
            UiNode::new(
                "settings/compact-toolbar/top",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(top))
                    .gap(8.0),
            )
            .children(children),
            under,
        ])
}

fn reset_all_question_lines(
    state: &SettingsViewState,
    room: f32,
) -> (Vec<(String, String, StyleRef)>, f32, f32) {
    let line_height = 22.0_f32.max(16.0 * settings_text_scale());
    let count = reset_all_count(state);
    let wrapped = |key: &str, text: &str, style: StyleRef| {
        let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, style);
        let lines = wrapped_copy_lines(text, px, room);
        let one = lines.len() == 1;
        lines
            .into_iter()
            .enumerate()
            .map(|(index, line)| {
                let key = if one {
                    key.to_string()
                } else {
                    format!("{key}/line-{index}")
                };
                (key, line, style)
            })
            .collect::<Vec<_>>()
    };
    let mut lines = wrapped(
        "settings/status/visual",
        &format!(
            "Reset {}?",
            counted_value_label("setting", "settings", count)
        ),
        StyleRef::Plain,
    );
    if let Some(sentence) = reset_all_reach_sentence(state) {
        lines.extend(wrapped("settings/status/reach", &sentence, StyleRef::Plain));
    }
    lines.extend(wrapped(
        "settings/status/kept",
        "Keys only in aterm.toml stay.",
        StyleRef::Quiet,
    ));
    let height = line_height * lines.len() as f32 + 4.0 * lines.len().saturating_sub(1) as f32;
    (lines, height, line_height)
}

fn feedback_bar(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> Option<UiNode> {
    let navigation_width = settings_navigation_width(width);
    if state.has_unsaved_field_drafts() {
        let bar = DraftBar::of(state);
        let status = bar.status.clone();
        let room = (viewport.width - navigation_width - 16.0).max(0.0);
        let one_row = draft_bar_row_actions_width(&bar, room);
        let words = draft_bar_words(&bar, width, viewport);
        let mut actions = bar_actions(
            "settings/draft-recovery/actions",
            "Unsaved Settings draft recovery actions",
            &bar.buttons,
            one_row.unwrap_or(room),
        );
        let layout = if let Some(buttons) = one_row {
            actions.layout.width = Length::Fixed(buttons);
            actions.layout.height = Length::Fill;
            Layout::row()
                .height(Length::Fixed(feedback_bar_height(state, width, viewport)))
                .padding(Insets::symmetric(16.0, 5.0))
                .gap(8.0)
        } else {
            Layout::column()
                .height(Length::Fixed(feedback_bar_height(state, width, viewport)))
                .padding(Insets::all(8.0))
                .gap(4.0)
        };
        return Some(
            UiNode::new(
                "settings/feedback",
                UiContent::Group(
                    GroupSpec::new("Unsaved Settings drafts require recovery")
                        .style(StyleRef::Secondary),
                ),
            )
            .layout(layout)
            .children(vec![
                UiNode::new(
                    "settings/draft-recovery/status",
                    UiContent::Group(GroupSpec {
                        label: Some(status),
                        role: SemanticRole::Status,
                        style: StyleRef::Plain,
                    }),
                )
                .layout(
                    Layout::default()
                        .width(Length::Fill)
                        .height(if one_row.is_some() {
                            Length::Fill
                        } else {
                            Length::Fixed(words.height)
                        }),
                )
                .children(vec![if one_row.is_some() {
                    UiNode::new(
                        "settings/draft-recovery/status/visual",
                        UiContent::Text(TextSpec {
                            text: bar.visual.clone(),
                            role: SemanticRole::Status,
                            style: StyleRef::Plain,
                        }),
                    )
                    .layout(Layout::default().width(Length::Fill).height(Length::Fill))
                    .paint_only()
                } else {
                    status_words_node(
                        state,
                        "settings/draft-recovery/status/visual",
                        &bar.visual,
                        room,
                        words.most,
                    )
                }]),
                actions,
            ]),
        );
    }
    let feedback = state.bar_feedback()?;
    if messages_feedback_inline(state) {
        return None;
    }
    if state.reset_all_confirmation {
        let room = (viewport.width - navigation_width - 20.0).max(0.0);
        let (visual_lines, status_height, line_height) = reset_all_question_lines(state, room);
        let status = UiNode::new(
            "settings/status",
            UiContent::Group(GroupSpec {
                label: Some(reset_all_scope(state)),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(status_height))
                .gap(4.0),
        )
        .children(
            visual_lines
                .into_iter()
                .map(|(key, text, style)| {
                    UiNode::new(
                        key,
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Text,
                            style,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        );
        let children = vec![
            status,
            bar_actions(
                "settings/reset-all/actions",
                "Reset All confirmation actions",
                &reset_all_buttons(state),
                room,
            ),
        ];
        return Some(
            UiNode::new(
                "settings/feedback",
                UiContent::Group(GroupSpec::new("Reset All scope").style(StyleRef::Secondary)),
            )
            .layout(
                Layout::column()
                    .height(Length::Fixed(feedback_bar_height(state, width, viewport)))
                    .padding(Insets::all(10.0))
                    .gap(4.0),
            )
            .children(children),
        );
    }
    let bar = plain_bar_layout(state, feedback, width, viewport);
    let words_height = if bar.undo_under {
        Length::Fixed(bar.height - 4.0 - scaled_control_height())
    } else {
        Length::Fill
    };
    let mut children = vec![
        UiNode::new(
            "settings/status",
            UiContent::Group(GroupSpec {
                label: Some(feedback.clone()),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(words_height))
        .children(vec![status_words_node(
            state,
            "settings/status/visual",
            feedback,
            bar.words_width,
            bar.most_lines,
        )]),
    ];
    if state.undo_offer().is_some() {
        children.push(
            UiNode::new(
                "settings/undo",
                UiContent::Button(
                    Control::new(
                        ButtonSpec::new(undo_button_label(state)),
                        ActionId::new("settings/undo"),
                    )
                    .style(StyleRef::Quiet),
                ),
            )
            .layout(
                Layout::default()
                    .width(Length::Fixed(bar_undo_width()))
                    .height(Length::Fixed(scaled_control_height() - 10.0)),
            ),
        );
    }
    let flow = if bar.undo_under {
        Layout::column().gap(4.0)
    } else {
        Layout::row().gap(8.0)
    };
    Some(
        UiNode::new(
            "settings/feedback",
            UiContent::Group(GroupSpec::new("Settings status").style(StyleRef::Secondary)),
        )
        .layout(
            flow.height(Length::Fixed(bar.height))
                .padding(Insets::symmetric(16.0, 5.0)),
        )
        .children(children),
    )
}

struct BarButton {
    key: &'static str,
    label: String,
    visual: String,
    qualifier: Option<&'static str>,
    style: StyleRef,
}

impl BarButton {
    fn words(&self, qualified: bool) -> String {
        match self.qualifier {
            Some(qualifier) if qualified => format!("{}{qualifier}", self.visual),
            _ => self.visual.clone(),
        }
    }
}

struct DraftBar {
    status: String,
    visual: String,
    short: String,
    buttons: Vec<BarButton>,
}

impl DraftBar {
    fn of(state: &SettingsViewState) -> Self {
        let count = state.unsaved_field_draft_count();
        let one = count == 1;
        let name = state
            .field_inputs
            .keys()
            .find(|key| state.field_has_unsaved_draft(key))
            .and_then(|key| state.field_by_key(key))
            .map_or("Settings", |field| field.label);
        let on_modified = state.route == SettingsRoute::Modified && state.search.trim().is_empty();
        if state.draft_discard_confirmation {
            let (status, short, visual, label) = if one {
                (
                    format!("Discard your unsaved {name} draft? This cannot be undone."),
                    "Discard the draft?".to_string(),
                    "Discard Draft",
                    format!("Discard Draft: your unsaved {name} draft"),
                )
            } else {
                (
                    format!("Discard all {count} unsaved drafts? This cannot be undone."),
                    format!("Discard {count} drafts?"),
                    "Discard All",
                    format!("Discard All {count} unsaved Settings drafts"),
                )
            };
            return Self {
                visual: status.clone(),
                status,
                short,
                buttons: vec![
                    BarButton {
                        key: "settings/drafts/discard-cancel",
                        label: "Cancel, and keep unsaved Settings drafts".to_string(),
                        visual: "Cancel".to_string(),
                        qualifier: None,
                        style: StyleRef::Secondary,
                    },
                    BarButton {
                        key: "settings/drafts/discard-all",
                        label,
                        visual: visual.to_string(),
                        qualifier: None,
                        style: StyleRef::Danger,
                    },
                ],
            };
        }
        let noun = if one { "draft" } else { "drafts" };
        let refusal = state
            .field_inputs
            .keys()
            .filter(|key| state.field_has_unsaved_draft(key))
            .find_map(|key| state.field_errors.get(key.as_str()));
        let refused = refusal.filter(|_| one);
        let status = if let Some(reason) = refused {
            format!("{reason}. Correct it and press Return, or discard it.")
        } else if on_modified {
            format!(
                "{count} unsaved {noun}. Press Return in {} to save, or discard.",
                if one { "its field" } else { "each field" }
            )
        } else {
            format!("{count} unsaved Settings {noun}. Review and save, or discard before closing.")
        };
        let mut buttons = Vec::new();
        if !on_modified {
            buttons.push(BarButton {
                key: "settings/drafts/review",
                label: format!("Review in Modified: {count} unsaved Settings {noun}"),
                visual: "Review".to_string(),
                qualifier: Some(" in Modified"),
                style: StyleRef::Secondary,
            });
        }
        buttons.push(BarButton {
            key: "settings/drafts/discard-all",
            label: if one {
                format!("Discard: drop your unsaved {name} draft")
            } else {
                format!("Discard All {count} unsaved Settings drafts")
            },
            visual: if one { "Discard" } else { "Discard All" }.to_string(),
            qualifier: None,
            style: StyleRef::Secondary,
        });
        Self {
            visual: if refused.is_some() {
                format!("{name} was not saved. Correct it and press Return, or discard it.")
            } else {
                status.clone()
            },
            status,
            short: format!("{count} unsaved {noun}"),
            buttons,
        }
    }
}

fn reset_all_buttons(view: &SettingsViewState) -> Vec<BarButton> {
    let count = reset_all_count(view);
    let reach = reset_all_reach_sentence(view)
        .map(|sentence| format!(" {sentence}"))
        .unwrap_or_default();
    vec![
        BarButton {
            key: "settings/reset-all-cancel",
            label: "Cancel Reset All: keep every setting".to_string(),
            visual: "Cancel".to_string(),
            qualifier: None,
            style: StyleRef::Secondary,
        },
        BarButton {
            key: "settings/reset-all-confirm",
            label: format!(
                "Reset All: {}.{reach} Keys only in aterm.toml stay.",
                counted_value_label("setting", "settings", count)
            ),
            visual: "Reset All".to_string(),
            qualifier: None,
            style: StyleRef::Danger,
        },
    ]
}

#[derive(Clone, Debug, PartialEq)]
enum BarFit {
    Row { qualified: bool, widths: Vec<f32> },
    Shared,
    Stacked,
}

fn bar_button_fit(buttons: &[BarButton], room: f32) -> BarFit {
    let gaps = 8.0 * buttons.len() as f32;
    let qualifies = buttons.iter().any(|button| button.qualifier.is_some());
    for qualified in [true, false] {
        if !qualified && !qualifies {
            break;
        }
        let widths: Vec<f32> = buttons
            .iter()
            .map(|button| page_button_width(&button.words(qualified), f32::INFINITY))
            .collect();
        if widths.iter().sum::<f32>() + gaps <= room + 0.01 {
            return BarFit::Row { qualified, widths };
        }
    }
    let share = (room - gaps) / buttons.len().max(1) as f32;
    let fits_share = |button: &BarButton| {
        crate::native_ui::native_button_label_width(&button.words(false)) + 24.0 <= share + 0.01
    };
    if share >= scaled_control_height() && buttons.iter().all(fits_share) {
        BarFit::Shared
    } else {
        BarFit::Stacked
    }
}

fn bar_actions_height(buttons: &[BarButton], room: f32) -> f32 {
    match bar_button_fit(buttons, room) {
        BarFit::Stacked => {
            let rows = buttons.len().max(1) as f32;
            buttons
                .iter()
                .map(|button| stacked_bar_button(button, room).1)
                .sum::<f32>()
                .max(scaled_control_height())
                + 8.0 * (rows - 1.0)
        }
        BarFit::Row { .. } | BarFit::Shared => scaled_control_height(),
    }
}

fn stacked_bar_button(button: &BarButton, room: f32) -> (String, f32) {
    let words = button.words(false);
    let spec = ButtonSpec::new(button.label.clone()).visual_label(words.clone());
    let (words, lines) = button_words_in(&spec, &words, &[], room);
    let height = crate::native_ui::native_button_height_for_lines(lines, scaled_control_height());
    (words, height)
}

fn bar_actions(key: &str, label: &str, buttons: &[BarButton], room: f32) -> UiNode {
    let fit = bar_button_fit(buttons, room);
    let mut children = Vec::new();
    if matches!(fit, BarFit::Row { .. }) {
        children.push(
            UiNode::new(
                format!("{key}/spacer"),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill))
            .paint_only(),
        );
    }
    let qualified = matches!(
        fit,
        BarFit::Row {
            qualified: true,
            ..
        }
    );
    children.extend(buttons.iter().enumerate().map(|(index, button)| {
        let (width, height, words) = match &fit {
            BarFit::Row { widths, .. } => (
                Length::Fixed(widths[index]),
                Length::Fill,
                button.words(qualified),
            ),
            BarFit::Shared => (Length::Fill, Length::Fill, button.words(qualified)),
            BarFit::Stacked => {
                let (words, height) = stacked_bar_button(button, room);
                (Length::Fill, Length::Fixed(height), words)
            }
        };
        UiNode::new(
            button.key,
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(button.label.clone()).visual_label(words),
                    ActionId::new(button.key),
                )
                .style(button.style),
            ),
        )
        .layout(Layout::default().width(width).height(height))
    }));
    let layout = if fit == BarFit::Stacked {
        Layout::column()
    } else {
        Layout::row()
    };
    UiNode::new(key, UiContent::Group(GroupSpec::new(label)))
        .layout(
            layout
                .width(Length::Fill)
                .height(Length::Fixed(bar_actions_height(buttons, room)))
                .gap(8.0),
        )
        .children(children)
}

fn rail_row_words(
    route: SettingsRoute,
    width: SettingsWidth,
    text_scale: f32,
) -> Option<&'static str> {
    if text_scale > 1.25 {
        return Some(match route {
            SettingsRoute::Home => "Top",
            SettingsRoute::Modified => "Modified",
            SettingsRoute::Manual => "Manual",
            SettingsRoute::Appearance => "Colors",
            SettingsRoute::Themes => "Themes",
            SettingsRoute::TextFonts => "Fonts",
            SettingsRoute::CursorMotion => "Cursor",
            SettingsRoute::CursorStyles => "Styles",
            SettingsRoute::Sound => "Sound",
            SettingsRoute::WindowTabs => "Window",
            SettingsRoute::TabColor => "Tab Color",
            SettingsRoute::Wallpaper => "Wallpaper",
            SettingsRoute::KeyboardInput => "Keyboard",
            SettingsRoute::Terminal => "Terminal",
            SettingsRoute::Security => "Security",
            SettingsRoute::SoftwareUpdate => "Update",
            SettingsRoute::Packages => "Packages",
            SettingsRoute::Harness => "Harness",
            SettingsRoute::Ai => "AI CLIs",
            SettingsRoute::Tabs => "Tabs",
            SettingsRoute::Messages => "Messages",
            SettingsRoute::About => "About",
        });
    }
    (width == SettingsWidth::Medium && route == SettingsRoute::SoftwareUpdate).then_some("Update")
}

fn navigation_side_inset(width: SettingsWidth) -> f32 {
    if width == SettingsWidth::Wide {
        14.0
    } else {
        12.0
    }
}

type RailMeasure = (
    SettingsWidth,
    u32,
    Option<Arc<aterm_render::font::Font>>,
    f32,
);

thread_local! {
    static RAIL_MEASURES: RefCell<Vec<RailMeasure>> = const { RefCell::new(Vec::new()) };
}

fn settings_navigation_width(width: SettingsWidth) -> f32 {
    let authored = match width {
        SettingsWidth::Wide => 216.0,
        SettingsWidth::Medium => 196.0,
        SettingsWidth::Compact => return 0.0,
    };
    let scale = settings_text_scale();
    let face = crate::tray_raster::ui_font_of(crate::widget::TextFace::UiBold);
    let same = |measure: &RailMeasure| {
        measure.0 == width
            && measure.1 == scale.to_bits()
            && match (&measure.2, &face) {
                (Some(a), Some(b)) => Arc::ptr_eq(a, b),
                (None, None) => true,
                _ => false,
            }
    };
    if let Some(known) = RAIL_MEASURES.with(|measures| {
        measures
            .borrow()
            .iter()
            .find(|measure| same(measure))
            .map(|measure| measure.3)
    }) {
        return known;
    }
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let widest_row = SettingsRoute::ALL
        .into_iter()
        .map(|route| {
            let words = rail_row_words(route, width, scale).unwrap_or(route.label());
            let indent = if route.rail_parent().is_some() {
                SUB_ROW_INDENT
            } else {
                0.0
            };
            indent
                + crate::native_ui::NAVIGATION_LABEL_LEAD
                + crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, words, px)
                + crate::native_ui::NAVIGATION_LABEL_END
        })
        .fold(0.0_f32, f32::max);
    let measured = (widest_row + 2.0 * navigation_side_inset(width))
        .ceil()
        .max(authored);
    RAIL_MEASURES.with(|measures| {
        let mut measures = measures.borrow_mut();
        measures.retain(|measure| measure.0 != width);
        measures.push((width, scale.to_bits(), face, measured));
    });
    measured
}

fn draft_bar_row_actions_width(bar: &DraftBar, room: f32) -> Option<f32> {
    let qualifies = bar.buttons.iter().any(|button| button.qualifier.is_some());
    [true, false]
        .into_iter()
        .filter(|qualified| *qualified || qualifies)
        .map(|qualified| {
            bar.buttons
                .iter()
                .map(|button| page_button_width(&button.words(qualified), f32::INFINITY))
                .sum::<f32>()
                + 8.0 * bar.buttons.len() as f32
        })
        .find(|buttons| {
            let words = room - 16.0 - 8.0 - buttons;
            words > 0.0
                && crate::native_ui::fit_native_status_label(&bar.visual, words) == bar.visual
        })
}

struct DraftBarWords {
    most: usize,
    height: f32,
}

fn draft_bar_words(bar: &DraftBar, width: SettingsWidth, viewport: LogicalRect) -> DraftBarWords {
    let room = (viewport.width - settings_navigation_width(width) - 16.0).max(0.0);
    let over = if width == SettingsWidth::Compact {
        compact_toolbar_height()
    } else {
        0.0
    };
    let room_for_words =
        viewport.height - over - 16.0 - 4.0 - bar_actions_height(&bar.buttons, room);
    let most = (room_for_words / status_line_height()).floor().max(1.0) as usize;
    let lines = status_word_lines(&bar.visual, room).len().clamp(1, most);
    DraftBarWords {
        most,
        height: scaled_control_height().max(lines as f32 * status_line_height()),
    }
}

fn feedback_bar_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let viewport_width = viewport.width;
    if state.has_unsaved_field_drafts() {
        let bar = DraftBar::of(state);
        let room = (viewport_width - settings_navigation_width(width) - 16.0).max(0.0);
        if draft_bar_row_actions_width(&bar, room).is_some() {
            scaled_control_height()
        } else {
            draft_bar_words(&bar, width, viewport).height
                + 4.0
                + bar_actions_height(&bar.buttons, room)
                + 16.0
        }
    } else if state.reset_all_confirmation {
        let room = (viewport_width - settings_navigation_width(width) - 20.0).max(0.0);
        let (_, status_height, _) = reset_all_question_lines(state, room);
        20.0 + status_height + 4.0 + bar_actions_height(&reset_all_buttons(state), room)
    } else if let Some(feedback) = state
        .bar_feedback()
        .filter(|_| !messages_feedback_inline(state))
    {
        plain_bar_layout(state, feedback, width, viewport).height
    } else {
        0.0
    }
}

fn status_line_height() -> f32 {
    22.0_f32.max(16.0 * settings_text_scale())
}

thread_local! {
    /// The status's words as a page being built wrapped them ([`StatusWordsShared`]).
    static STATUS_WORDS: RefCell<Option<StatusWords>> = const { RefCell::new(None) };
}

/// What the status's words wrapped to, by text and width.
type WrappedBy<T> = aterm_hash::FxHashMap<(Box<str>, u32), T>;

/// The status's words wrapped, by text and width: their lines, and the words broken.
#[derive(Default)]
struct StatusWords {
    lines: WrappedBy<Vec<String>>,
    broken: WrappedBy<usize>,
}

/// THE PAGE'S SEATS SHARE THE STATUS'S WORDS: while open, each text is wrapped at each width once a render.
struct StatusWordsShared;

impl StatusWordsShared {
    fn open() -> Self {
        STATUS_WORDS.with(|words| words.replace(Some(StatusWords::default())));
        Self
    }

    fn once<T: Clone>(
        text: &str,
        width: f32,
        of: fn(&mut StatusWords) -> &mut WrappedBy<T>,
        wrap: impl FnOnce() -> T,
    ) -> T {
        let at = (Box::from(text), width.to_bits());
        let seen = STATUS_WORDS.with(|words| {
            words
                .borrow_mut()
                .as_mut()
                .and_then(|words| of(words).get(&at).cloned())
        });
        seen.unwrap_or_else(|| {
            let wrapped = wrap();
            STATUS_WORDS.with(|words| {
                if let Some(words) = words.borrow_mut().as_mut() {
                    of(words).insert(at, wrapped.clone());
                }
            });
            wrapped
        })
    }
}

impl Drop for StatusWordsShared {
    fn drop(&mut self) {
        STATUS_WORDS.with(|words| words.replace(None));
    }
}

fn status_word_lines(text: &str, width: f32) -> Vec<String> {
    StatusWordsShared::once(
        text,
        width,
        |words| &mut words.lines,
        || {
            wrap_to_box(text, width.max(1.0), &status_words_width)
                .into_iter()
                .map(|line| line.trim().to_string())
                .filter(|line| !line.is_empty())
                .collect()
        },
    )
}

fn status_words_width(text: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Plain);
    crate::tray_raster::ui_text_width_for(face, text, px)
}

fn broken_words(text: &str, width: f32) -> usize {
    StatusWordsShared::once(
        text,
        width,
        |words| &mut words.broken,
        || words_broken(text, width),
    )
}

fn words_broken(text: &str, width: f32) -> usize {
    let base = text.as_ptr() as usize;
    let starts: std::collections::BTreeSet<usize> = line_pieces(text)
        .into_iter()
        .map(|(_, piece)| piece.as_ptr() as usize - base)
        .collect();
    wrap_to_box_from(text, width.max(1.0), &status_words_width, "-")
        .into_iter()
        .skip(1)
        .filter(|(at, _)| !starts.contains(at))
        .count()
}

struct PlainBarLayout {
    words_width: f32,
    most_lines: usize,
    undo_under: bool,
    height: f32,
}

fn plain_bar_layout(
    state: &SettingsViewState,
    feedback: &str,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> PlainBarLayout {
    let full = (viewport.width - settings_navigation_width(width) - 32.0).max(0.0);
    let undo = state.undo_offer().is_some();
    let beside = if undo {
        (full - bar_undo_width() - 8.0).max(0.0)
    } else {
        full
    };
    let undo_under = undo && broken_words(feedback, beside) > broken_words(feedback, full);
    let words_width = if undo_under { full } else { beside };
    let over = if width == SettingsWidth::Compact {
        compact_toolbar_height()
    } else {
        0.0
    };
    let undo_row = if undo_under {
        4.0 + scaled_control_height() - 10.0
    } else {
        0.0
    };
    let most_lines = ((viewport.height - over - 10.0 - undo_row) / status_line_height())
        .floor()
        .max(1.0) as usize;
    let most_lines = state.status_bar_most.get().map_or(most_lines, |most| {
        let words = if undo_under {
            most - 4.0 - scaled_control_height()
        } else {
            most - 10.0
        };
        most_lines.min((words / status_line_height()).floor().max(1.0) as usize)
    });
    let words = status_word_lines(feedback, words_width)
        .len()
        .clamp(1, most_lines) as f32
        * status_line_height();
    let height = if undo_under {
        words + 4.0 + scaled_control_height()
    } else {
        scaled_control_height().max(words + 10.0)
    };
    PlainBarLayout {
        words_width,
        most_lines,
        undo_under,
        height,
    }
}

#[derive(Debug, Default)]
struct StatusScroll {
    text: String,
    offset: f32,
    limit: f32,
    line: f32,
}

const STATUS_THUMB_GUTTER: f32 = 10.0;

fn status_words_node(
    state: &SettingsViewState,
    key: &str,
    feedback: &str,
    width: f32,
    most: usize,
) -> UiNode {
    status_words_node_at(state, key, feedback, width, most, status_line_height())
}

fn status_words_node_at(
    state: &SettingsViewState,
    key: &str,
    feedback: &str,
    width: f32,
    most: usize,
    line_height: f32,
) -> UiNode {
    let most = most.max(1);
    let mut lines = status_word_lines(feedback, width);
    let scrolls = lines.len() > most;
    if scrolls {
        lines = status_word_lines(feedback, (width - STATUS_THUMB_GUTTER).max(1.0));
    }
    let words_key = format!("{key}/words");
    let keyboard_on = state
        .common
        .last_focus
        .as_ref()
        .is_some_and(|focus| focus.as_str() == words_key);
    let boxed = scrolls || (keyboard_on && lines.len() > 1);
    {
        let mut scroll = state.status_scroll.borrow_mut();
        if scroll.text != feedback || !scrolls {
            *scroll = StatusScroll {
                text: feedback.to_string(),
                ..StatusScroll::default()
            };
        }
    }
    if lines.len() <= 1 {
        return UiNode::new(
            key,
            UiContent::Text(TextSpec {
                text: lines.into_iter().next().unwrap_or_default(),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .paint_only();
    }
    let count = lines.len();
    let line_nodes = lines
        .into_iter()
        .enumerate()
        .map(|(index, text)| {
            UiNode::new(
                format!("{key}/line-{index}"),
                UiContent::Text(TextSpec {
                    text,
                    role: SemanticRole::Status,
                    style: StyleRef::Plain,
                }),
            )
            .layout(
                Layout::default()
                    .width(Length::Fill)
                    .height(Length::Fixed(line_height)),
            )
            .paint_only()
        })
        .collect();
    let column = UiNode::new(
        key,
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    );
    if !boxed {
        return column
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(count as f32 * line_height)),
            )
            .children(line_nodes)
            .paint_only();
    }
    let shown = most.min(count) as f32 * line_height;
    let content = count as f32 * line_height;
    let offset = if scrolls {
        let mut scroll = state.status_scroll.borrow_mut();
        scroll.limit = content - shown;
        scroll.line = line_height;
        scroll.offset =
            ((scroll.offset / line_height).round() * line_height).clamp(0.0, scroll.limit);
        scroll.offset
    } else {
        0.0
    };
    let list = column
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(shown))
                .scrolled(offset)
                .clipped(),
        )
        .room(shown, false)
        .children(line_nodes);
    #[allow(
        clippy::cast_possible_truncation,
        clippy::cast_sign_loss,
        reason = "points of a status a few lines tall, rounded"
    )]
    let share = format!(
        "{},{},{}",
        offset.round() as u32,
        shown.round() as u32,
        content.round() as u32
    );
    let thumb = UiNode::new(
        format!("{key}/thumb"),
        UiContent::Custom(crate::native_ui::AuditedCustomNode {
            audit_id: crate::native_ui::MESSAGES_SCROLL_AUDIT,
            role: SemanticRole::Group,
            label: String::new(),
            value: Some(share),
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(shown)),
    )
    .paint_only();
    let stop = UiNode::new(
        words_key,
        UiContent::Custom(crate::native_ui::AuditedCustomNode {
            audit_id: crate::native_ui::MESSAGES_SCROLL_AUDIT,
            role: SemanticRole::Status,
            label: feedback.to_string(),
            value: None,
            action: None,
            focusable: true,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(shown)),
    );
    UiNode::new(
        format!("{key}/scroll"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(shown)),
    )
    .children(vec![list, thumb, stop])
    .paint_only()
}

fn messages_feedback_inline(state: &SettingsViewState) -> bool {
    state.route == SettingsRoute::Messages
        && state.feedback.is_some()
        && state.search.trim().is_empty()
        && !state.compact_navigation
        && !state.has_unsaved_field_drafts()
        && !state.reset_all_confirmation
        && state.undo_offer().is_none()
}

fn config_watch_status_bar_height(state: &SettingsViewState) -> f32 {
    if state.config_watch_status.is_some() {
        scaled_control_height() * 1.75 + 12.0
    } else {
        0.0
    }
}

fn settings_status_bars_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if state.measuring_calm.get() {
        return 0.0;
    }
    feedback_bar_height(state, width, viewport) + config_watch_status_bar_height(state)
}

enum DockActions {
    None,
    Undo,
    Buttons(Vec<BarButton>),
}

impl DockActions {
    fn of(state: &SettingsViewState) -> Self {
        if state.has_unsaved_field_drafts() {
            Self::Buttons(DraftBar::of(state).buttons)
        } else if state.reset_all_confirmation {
            Self::Buttons(reset_all_buttons(state))
        } else if state.bar_feedback().is_some() && state.undo_offer().is_some() {
            Self::Undo
        } else {
            Self::None
        }
    }
}

fn dock_undo_width() -> f32 {
    (scaled_control_height() * 1.65).max(78.0)
}

const DOCK_WORDS_LEAST: f32 = 96.0;

const DOCK_WORDS_MIN: f32 = 40.0;

struct CompactDockLayout {
    dock_width: f32,
    watcher_share: f32,
    watcher_width: f32,
    words_width: f32,
    actions_width: f32,
    search_width: f32,
    under: Option<f32>,
}

fn compact_dock_layout(
    state: &SettingsViewState,
    viewport: LogicalRect,
    actions: &DockActions,
    watcher: bool,
    plain: bool,
    words: Option<&str>,
) -> CompactDockLayout {
    let (_, leading) = compact_toolbar_leading(state, viewport, true);
    let dock_width = (viewport.width - 20.0 - leading - 8.0).max(0.0);
    let scale = settings_text_scale();
    let watcher_share = if watcher {
        (80.0 * scale.min(1.25)).min(dock_width * 0.42)
    } else {
        0.0
    };
    let watcher_width = if watcher {
        watcher_share.min(
            compact_watch_words(state, watcher_share).map_or(watcher_share, |words| {
                status_words_width(&words).ceil() + 1.0
            }),
        )
    } else {
        0.0
    };
    let room = dock_width - if watcher { watcher_width + 8.0 } else { 0.0 };
    let beside = (room - 8.0 - DOCK_WORDS_MIN * scale).max(0.0);
    let breaks_more = |narrow: f32, wide: f32| {
        words.is_some_and(|words| {
            broken_words(words, (narrow - 10.0).max(0.0))
                > broken_words(words, (wide - 10.0).max(0.0))
        })
    };
    let inline_actions = match actions {
        DockActions::None => Some(0.0),
        DockActions::Undo => Some(dock_undo_width())
            .filter(|width| *width <= beside + 0.01 && !breaks_more(room - width - 8.0, room)),
        DockActions::Buttons(buttons) => match bar_button_fit(buttons, beside) {
            BarFit::Row { widths, .. } => {
                Some(widths.iter().sum::<f32>() + 8.0 * buttons.len() as f32)
            }
            BarFit::Shared | BarFit::Stacked => None,
        },
    };
    let toolbar_width = (viewport.width - 20.0).max(0.0);
    let Some(actions_width) = inline_actions else {
        let under = match actions {
            DockActions::Buttons(buttons) => bar_actions_height(buttons, toolbar_width),
            DockActions::Undo | DockActions::None => scaled_control_height(),
        };
        return CompactDockLayout {
            dock_width,
            watcher_share,
            watcher_width,
            words_width: room,
            actions_width: toolbar_width,
            search_width: 0.0,
            under: Some(under),
        };
    };
    let mut words_width = room
        - if actions_width > 0.0 {
            actions_width + 8.0
        } else {
            0.0
        };
    let search = dock_search_width() + 8.0;
    let search_width = if plain
        && words_width - search >= DOCK_WORDS_LEAST * scale - 0.01
        && !breaks_more(words_width - search, words_width)
    {
        words_width -= search;
        search
    } else {
        0.0
    };
    CompactDockLayout {
        dock_width,
        watcher_share,
        watcher_width,
        words_width,
        actions_width,
        search_width,
        under: None,
    }
}

fn dock_search_width() -> f32 {
    page_button_width("Search", f32::INFINITY)
}

fn dock_search_button() -> UiNode {
    UiNode::new(
        "settings/status-dock/search",
        UiContent::Button(
            Control::new(
                ButtonSpec::new("Search Settings").visual_label("Search"),
                ActionId::new("settings/status-dock/search"),
            )
            .style(StyleRef::Quiet),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(dock_search_width()))
            .height(Length::Fill),
    )
}

fn compact_status_dock_required(state: &SettingsViewState, viewport: LogicalRect) -> bool {
    compact_status_dock_wanted(state, viewport) && !reset_all_question_takes_page(state, viewport)
}

fn compact_status_dock_wanted(state: &SettingsViewState, viewport: LogicalRect) -> bool {
    let words = dock_plain_words(state);
    compact_status_dock_required_at(
        state,
        viewport,
        settings_status_bars_height(state, SettingsWidth::Compact, viewport),
        &DockActions::of(state),
        compact_dock_watcher(state),
        state.plain_status(),
        words,
    ) && words.is_none_or(|words| {
        let docked = compact_dock_layout(
            state,
            viewport,
            &DockActions::of(state),
            compact_dock_watcher(state),
            true,
            Some(words),
        );
        let bar = plain_bar_layout(state, words, SettingsWidth::Compact, viewport);
        broken_words(words, (docked.words_width - 10.0).max(0.0))
            <= broken_words(words, bar.words_width)
    })
}

fn dock_plain_words(state: &SettingsViewState) -> Option<&str> {
    state
        .bar_feedback()
        .filter(|_| state.plain_status())
        .map(String::as_str)
}

fn reset_all_question_takes_page(state: &SettingsViewState, viewport: LogicalRect) -> bool {
    if !state.reset_all_confirmation || state.has_unsaved_field_drafts() {
        return false;
    }
    let width = SettingsWidth::for_viewport(viewport.width);
    if width != SettingsWidth::Compact {
        return feedback_bar_height(state, width, viewport)
            > viewport.height - config_watch_status_bar_height(state) + 0.01;
    }
    if !compact_status_dock_wanted(state, viewport) {
        return false;
    }
    let layout = compact_dock_layout(
        state,
        viewport,
        &DockActions::of(state),
        compact_dock_watcher(state),
        state.plain_status(),
        dock_plain_words(state),
    );
    let words = reset_all_question_line(state);
    crate::native_ui::fit_native_status_label(&words, (layout.words_width - 10.0).max(0.0)) != words
}

fn reset_all_question_line(state: &SettingsViewState) -> String {
    let question = format!(
        "Reset {}?",
        counted_value_label("setting", "settings", reset_all_count(state))
    );
    match reset_all_reach_sentence(state) {
        Some(sentence) => format!("{question} {sentence}"),
        None => question,
    }
}

fn reset_all_question_page(state: &SettingsViewState, viewport: LogicalRect) -> UiNode {
    let width = SettingsWidth::for_viewport(viewport.width);
    let insets = page_frame_insets(
        state,
        viewport,
        width,
        PageLayout::shown(state).maximum(width),
    );
    let gap = settings_page_gap(state, width, viewport);
    let column = (viewport.width
        - if width == SettingsWidth::Compact {
            0.0
        } else {
            settings_navigation_width(width)
        }
        - insets.left
        - insets.right)
        .max(0.0);
    let buttons = reset_all_buttons(state);
    let actions_height = bar_actions_height(&buttons, column);
    let mut actions = bar_actions(
        "settings/reset-all/actions",
        "Reset All confirmation actions",
        &buttons,
        column,
    );
    actions.layout.height = Length::Fixed(actions_height);
    let body = viewport.height
        - if width == SettingsWidth::Compact {
            compact_header_height(state, viewport)
        } else {
            0.0
        }
        - config_watch_status_bar_height(state);
    let room = (body - insets.top - insets.bottom - gap - actions_height).max(0.0);
    const PADDING: f32 = 10.0;
    let (lines, status_height, line_height) =
        reset_all_question_lines(state, (column - 2.0 * PADDING).max(0.0));
    let words_height = status_height + 2.0 * PADDING;
    let words = UiNode::new(
        "settings/status",
        UiContent::Group(GroupSpec {
            label: Some(reset_all_scope(state)),
            role: SemanticRole::Status,
            style: StyleRef::Secondary,
        }),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(words_height))
            .padding(Insets::all(PADDING))
            .gap(4.0),
    )
    .children(
        lines
            .into_iter()
            .map(|(key, text, style)| {
                UiNode::new(
                    key,
                    UiContent::Text(TextSpec {
                        text,
                        role: SemanticRole::Text,
                        style,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(line_height)))
                .paint_only()
            })
            .collect(),
    );
    let mut children = vec![
        scroll::list_page(
            state,
            "settings/reset-all/question",
            "Reset All question",
            vec![ListItem::of(words, words_height)],
            room,
            4.0,
        ),
        actions,
    ];
    scroll::seat_page_scroller(&mut children, insets.right);
    UiNode::new(
        "settings/page/reset-all",
        UiContent::Group(GroupSpec::new("Reset All")),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fill)
            .padding(insets)
            .gap(gap)
            .clipped(),
    )
    .children(children)
}

fn compact_dock_watcher(state: &SettingsViewState) -> bool {
    let feedback = state.has_unsaved_field_drafts()
        || state.reset_all_confirmation
        || (state.bar_feedback().is_some() && !messages_feedback_inline(state));
    feedback && state.config_watch_status.is_some()
}

fn compact_status_dock_required_at(
    state: &SettingsViewState,
    viewport: LogicalRect,
    status_height: f32,
    actions: &DockActions,
    watcher: bool,
    plain: bool,
    words: Option<&str>,
) -> bool {
    if status_height <= 0.0 {
        return false;
    }
    let insets = responsive_page_insets(
        viewport.width,
        viewport.height,
        SettingsWidth::Compact,
        PageLayout::shown(state).maximum(SettingsWidth::Compact),
    );
    let stacked_content =
        (viewport.height - compact_toolbar_height() - status_height - insets.top - insets.bottom)
            .max(0.0)
            / settings_text_scale();
    let floor = if status_height <= scaled_control_height() + 0.01 || plain {
        compact_page_floor(state)
    } else if state.reset_all_confirmation && reset_all_reach_sentence(state).is_some() {
        page_heading_height() / settings_text_scale()
    } else {
        compact_page_floor(state).min(COMPACT_BODY_LEAST)
    };
    if stacked_content >= floor {
        return false;
    }
    let layout = compact_dock_layout(state, viewport, actions, watcher, plain, words);
    if plain && !watcher {
        return layout.under.is_none()
            && words.is_none_or(|_| {
                dock_words_height(state, layout.words_width)
                    <= compact_toolbar_height() - 16.0 + 0.01
            });
    }
    layout.under.is_none() || stacked_content < COMPACT_BODY_LEAST.min(floor)
}

const fn compact_page_floor(state: &SettingsViewState) -> f32 {
    if state.choice_picker.is_some() {
        420.0
    } else {
        COMPACT_BODY_FLOOR
    }
}

const COMPACT_BODY_LEAST: f32 = 220.0;

fn compact_header_height(state: &SettingsViewState, viewport: LogicalRect) -> f32 {
    if !compact_status_dock_required(state, viewport) {
        return compact_toolbar_height();
    }
    let layout = compact_dock_layout(
        state,
        viewport,
        &DockActions::of(state),
        compact_dock_watcher(state),
        state.plain_status(),
        dock_plain_words(state),
    );
    let words = dock_words_height(state, layout.words_width);
    match layout.under {
        Some(under) => scaled_control_height().max(words) + 8.0 + under + 16.0,
        None => compact_toolbar_height().max(words + 16.0),
    }
}

fn dock_words_height(state: &SettingsViewState, words_width: f32) -> f32 {
    let words = if state.has_unsaved_field_drafts() {
        DraftBar::of(state).short
    } else if let Some(feedback) = state.bar_feedback().filter(|_| state.plain_status()) {
        feedback.clone()
    } else {
        return 0.0;
    };
    let lines = status_word_lines(&words, (words_width - 10.0).max(0.0)).len();
    if lines <= 1 {
        0.0
    } else {
        lines as f32 * dock_line_height()
    }
}

fn dock_line_height() -> f32 {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Plain);
    status_line_height()
        .min((compact_toolbar_height() - 16.0) / 2.0)
        .max((px * 1.3).ceil())
}

struct CompactFeedbackParts {
    status: UiNode,
    actions: Option<UiNode>,
    group_label: &'static str,
}

fn compact_feedback_parts(
    state: &SettingsViewState,
    visual_width: f32,
    actions_room: f32,
) -> Option<CompactFeedbackParts> {
    let paint_status = |key: &str, full: String, preferred: String| {
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(full),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fill)
                .padding(Insets {
                    left: 10.0,
                    ..Insets::default()
                }),
        )
        .children(vec![status_words_node_at(
            state,
            &format!("{key}/visual"),
            &preferred,
            (visual_width - 10.0).max(0.0),
            usize::MAX,
            dock_line_height(),
        )])
    };

    if state.has_unsaved_field_drafts() {
        let bar = DraftBar::of(state);
        let mut actions = bar_actions(
            "settings/draft-recovery/actions",
            "Unsaved Settings draft recovery actions",
            &bar.buttons,
            actions_room,
        );
        actions.layout.height = Length::Fill;
        return Some(CompactFeedbackParts {
            status: paint_status("settings/draft-recovery/status", bar.status, bar.short),
            actions: Some(actions),
            group_label: "Unsaved Settings drafts require recovery",
        });
    }

    let feedback = state.bar_feedback()?;
    if messages_feedback_inline(state) {
        return None;
    }
    if state.reset_all_confirmation {
        let buttons = reset_all_buttons(state);
        let mut actions = bar_actions(
            "settings/reset-all/actions",
            "Reset All confirmation actions",
            &buttons,
            actions_room,
        );
        actions.layout.height = Length::Fill;
        let preferred = reset_all_question_line(state);
        return Some(CompactFeedbackParts {
            status: paint_status("settings/status", reset_all_scope(state), preferred),
            actions: Some(actions),
            group_label: "Reset All scope",
        });
    }

    let undo = state.undo_offer().is_some().then(|| {
        UiNode::new(
            "settings/status-dock/undo-action",
            UiContent::Group(GroupSpec::new("Settings status actions")),
        )
        .layout(Layout::row().width(Length::Fill).height(Length::Fill))
        .children(vec![
            UiNode::new(
                "settings/undo",
                UiContent::Button(
                    Control::new(
                        ButtonSpec::new(undo_button_label(state)),
                        ActionId::new("settings/undo"),
                    )
                    .style(StyleRef::Quiet),
                ),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
        ])
    });
    let status = UiNode::new(
        "settings/status",
        UiContent::Group(GroupSpec {
            label: Some(feedback.clone()),
            role: SemanticRole::Status,
            style: StyleRef::Plain,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fill)
            .padding(Insets {
                left: 10.0,
                ..Insets::default()
            }),
    )
    .children(vec![status_words_node_at(
        state,
        "settings/status/visual",
        feedback,
        (visual_width - 10.0).max(0.0),
        usize::MAX,
        dock_line_height(),
    )]);
    Some(CompactFeedbackParts {
        status,
        actions: undo,
        group_label: "Settings status",
    })
}

fn bar_undo_width() -> f32 {
    const WIDTH: f32 = 68.0;
    let edges = WIDTH - crate::native_ui::text_button_label_room(&ButtonSpec::new("Undo"), WIDTH);
    let words = ["Undo", "Redo"]
        .into_iter()
        .map(crate::native_ui::native_button_label_width)
        .fold(0.0_f32, f32::max);
    let need = words + edges;
    if need <= WIDTH {
        WIDTH
    } else {
        need.ceil() + 1.0
    }
}

fn undo_button_label(state: &SettingsViewState) -> &'static str {
    if state.undo_offer().is_some_and(|offer| offer.redo) {
        "Redo"
    } else {
        "Undo"
    }
}

fn compact_watch_words(state: &SettingsViewState, visual_width: f32) -> Option<String> {
    let status = state.config_watch_status.as_ref()?;
    Some(if visual_width < 110.0 {
        "Reload".to_string()
    } else if visual_width < 220.0 {
        "Reload warning".to_string()
    } else {
        format!("Reload warning: {status}")
    })
}

fn compact_watch_status(state: &SettingsViewState, visual_width: f32) -> Option<UiNode> {
    let status = state.config_watch_status.as_ref()?;
    let preferred = compact_watch_words(state, visual_width)?;
    Some(
        UiNode::new(
            "settings/config-watch-status",
            UiContent::Group(
                GroupSpec::new("Configuration reload warning").style(StyleRef::Danger),
            ),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .children(vec![
            UiNode::new(
                "settings/config-watch-status/detail",
                UiContent::Group(GroupSpec {
                    label: Some(format!("Reload warning. {status}")),
                    role: SemanticRole::Status,
                    style: StyleRef::Danger,
                }),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill))
            .children(vec![
                UiNode::new(
                    "settings/config-watch-status/detail/visual",
                    UiContent::Text(TextSpec {
                        text: crate::native_ui::fit_native_status_label(
                            &preferred,
                            visual_width.max(0.0),
                        ),
                        role: SemanticRole::Status,
                        style: StyleRef::Danger,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
                .paint_only(),
            ]),
        ]),
    )
}

struct CompactStatusDock {
    dock: UiNode,
    under: Option<UiNode>,
}

fn compact_status_dock(
    state: &SettingsViewState,
    viewport: LogicalRect,
) -> Option<CompactStatusDock> {
    let feedback_present = state.has_unsaved_field_drafts()
        || state.reset_all_confirmation
        || state.bar_feedback().is_some();
    let watcher_present = state.config_watch_status.is_some();
    if !feedback_present && !watcher_present {
        return None;
    }
    let actions = DockActions::of(state);
    let both = watcher_present && feedback_present;
    let layout = compact_dock_layout(
        state,
        viewport,
        &actions,
        both,
        state.plain_status(),
        dock_plain_words(state),
    );
    let (watcher_share, watcher_width) = if both {
        (layout.watcher_share, layout.watcher_width)
    } else {
        (layout.dock_width, layout.dock_width)
    };
    let watcher = compact_watch_status(state, watcher_share);
    let parts = compact_feedback_parts(state, layout.words_width, layout.actions_width);

    let mut under_actions = None;
    let content = match parts {
        None => watcher.expect("watcher-only dock"),
        Some(mut parts) => {
            let mut status_children = Vec::new();
            if let Some(mut watcher) = watcher {
                watcher.layout.width = Length::Fixed(watcher_width);
                status_children.push(watcher);
            }
            status_children.push(parts.status);
            let status_row = UiNode::new(
                "settings/status-dock/statuses",
                UiContent::Group(GroupSpec::new("Settings status summaries")),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fill)
                    .gap(8.0),
            )
            .children(status_children);
            let mut children = vec![status_row];
            let row = scaled_control_height().max(dock_words_height(state, layout.words_width));
            let layout_kind = if let Some(under) = layout.under {
                children[0].layout.height = Length::Fixed(row);
                if let Some(mut actions) = parts.actions.take() {
                    actions.layout.width = Length::Fill;
                    actions.layout.height = Length::Fixed(under);
                    under_actions = Some(actions);
                }
                Layout::column()
            } else {
                let beside = (compact_toolbar_height() - 16.0).min(row);
                if let Some(mut actions) = parts.actions.take() {
                    actions.layout.width = Length::Fixed(layout.actions_width);
                    actions.layout.height = Length::Fixed(beside);
                    children.push(actions);
                }
                if layout.search_width > 0.0 {
                    let mut search = dock_search_button();
                    search.layout.height = Length::Fixed(beside);
                    children.push(search);
                }
                Layout::row()
            };
            UiNode::new(
                "settings/feedback",
                UiContent::Group(GroupSpec::new(parts.group_label).style(StyleRef::Secondary)),
            )
            .layout(
                layout_kind
                    .width(Length::Fill)
                    .height(Length::Fill)
                    .gap(8.0),
            )
            .children(children)
        }
    };

    Some(CompactStatusDock {
        dock: UiNode::new(
            "settings/status-dock",
            UiContent::Group(GroupSpec::new("Settings alerts and status")),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .children(vec![content]),
        under: under_actions,
    })
}

fn route_control(
    route: SettingsRoute,
    button: ButtonSpec,
    packages: &PackagesProjection,
) -> Control<ButtonSpec> {
    let attention = packages_route_attention(route, packages);
    let control = Control::new(button.badge(attention.is_some()), route_action(route));
    match attention {
        Some(summary) => control.value(SemanticValue::Text(summary)),
        None => control,
    }
}

fn packages_route_attention(route: SettingsRoute, packages: &PackagesProjection) -> Option<String> {
    if route != SettingsRoute::Packages {
        return None;
    }
    crate::packages_screen::attention_headline(&packages.attention)
}

const NAVIGATION_GROUPS: [(&str, &[SettingsRoute]); 4] = [
    (
        "",
        &[
            SettingsRoute::Home,
            SettingsRoute::Modified,
            SettingsRoute::Manual,
        ],
    ),
    (
        "Look & Feel",
        &[
            SettingsRoute::Appearance,
            SettingsRoute::Wallpaper,
            SettingsRoute::TextFonts,
            SettingsRoute::CursorMotion,
            SettingsRoute::CursorStyles,
            SettingsRoute::Sound,
        ],
    ),
    (
        "Workspace",
        &[
            SettingsRoute::WindowTabs,
            SettingsRoute::TabColor,
            SettingsRoute::KeyboardInput,
            SettingsRoute::Terminal,
            SettingsRoute::Harness,
            SettingsRoute::Security,
        ],
    ),
    (
        "aterm",
        &[
            SettingsRoute::SoftwareUpdate,
            SettingsRoute::Packages,
            SettingsRoute::Messages,
            SettingsRoute::About,
        ],
    ),
];

fn navigation_heading(heading: &str) -> TextSpec {
    if cfg!(windows) {
        let mut text = String::with_capacity(heading.len());
        let mut seen_letter = false;
        for c in heading.chars() {
            if seen_letter {
                text.extend(c.to_lowercase());
            } else {
                text.push(c);
            }
            seen_letter |= c.is_alphabetic();
        }
        TextSpec {
            text,
            role: SemanticRole::Heading,
            style: StyleRef::Quiet,
        }
    } else {
        TextSpec {
            text: heading.to_uppercase(),
            role: SemanticRole::Heading,
            style: StyleRef::Accent,
        }
    }
}

fn navigation_groups(current: SettingsRoute) -> Vec<(&'static str, Vec<SettingsRoute>)> {
    NAVIGATION_GROUPS
        .iter()
        .map(|(heading, routes)| {
            let mut rows = Vec::with_capacity(routes.len() + 1);
            for &route in *routes {
                rows.push(route);
                if current.rail_parent() == Some(route) {
                    rows.push(current);
                }
            }
            (*heading, rows)
        })
        .collect()
}

const SUB_ROW_INDENT: f32 = 14.0;

fn navigation(
    state: &SettingsViewState,
    packages: &PackagesProjection,
    width: SettingsWidth,
    available_height: f32,
) -> UiNode {
    debug_assert_ne!(width, SettingsWidth::Compact);
    let text_scale = settings_text_scale();
    let vertical_padding = if width == SettingsWidth::Wide {
        12.0
    } else {
        10.0
    };
    let title_height = 36.0_f32.max(30.0 * text_scale);
    let search_height = 36.0_f32.max(40.0 * text_scale);
    let section_height = (if width == SettingsWidth::Wide {
        16.0_f32
    } else {
        12.0_f32
    })
    .max(14.0 * text_scale);
    let row_height = navigation_row_height(text_scale);
    let gap = NAVIGATION_GAP;
    let titled_list =
        (available_height - vertical_padding * 2.0 - title_height - search_height - gap * 2.0)
            .max(0.0);
    let titled = titled_list + 0.01 >= row_height;
    let list_height = if titled {
        titled_list
    } else {
        (available_height - vertical_padding * 2.0 - search_height - gap).max(0.0)
    };

    let mut items: Vec<(UiNode, f32, Option<UiKey>)> = Vec::new();
    for (section, routes) in navigation_groups(state.route) {
        if !section.is_empty() {
            items.push((
                UiNode::new(
                    format!("settings/nav-label/{}", key_fragment(section)),
                    UiContent::Text(navigation_heading(section)),
                )
                .layout(Layout::default().height(Length::Fixed(section_height))),
                section_height,
                None,
            ));
        }
        for route in &routes {
            let mut button = ButtonSpec::new(route.label()).visual_icon(route_icon(*route));
            if let Some(words) = rail_row_words(*route, width, text_scale) {
                if !crate::native_ui::visible_label_in_name(words, route.label()) {
                    button.label = format!("{} ({words})", route.label());
                }
                button = button.visual_label(words);
            }
            let key = UiKey::new(format!("settings/nav{}", route.path()));
            let row = UiNode::new(
                key.as_str(),
                UiContent::Button(
                    route_control(*route, button, packages)
                        .state(ControlState {
                            selected: state.search.trim().is_empty() && *route == state.route,
                            ..ControlState::default()
                        })
                        .style(StyleRef::Navigation),
                ),
            );
            let node = if route.rail_parent().is_some() {
                UiNode::new(
                    format!("settings/nav-sub{}", route.path()),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    Layout::row()
                        .height(Length::Fixed(row_height))
                        .width(Length::Fill)
                        .padding(Insets {
                            left: SUB_ROW_INDENT,
                            ..Insets::default()
                        }),
                )
                .children(vec![
                    row.layout(Layout::default().height(Length::Fill).width(Length::Fill)),
                ])
            } else {
                row.layout(
                    Layout::default()
                        .height(Length::Fixed(row_height))
                        .width(Length::Fill),
                )
            };
            items.push((node, row_height, Some(key)));
        }
    }

    let mut tops = Vec::with_capacity(items.len());
    let mut content = 0.0_f32;
    for (index, (_, height, _)) in items.iter().enumerate() {
        if index > 0 {
            content += gap;
        }
        tops.push(content);
        content += height;
    }
    let limit = (content - list_height).max(0.0);
    let mut offset = state.navigation_scroll.get().clamp(0.0, limit);
    let target = state
        .common
        .last_focus
        .as_ref()
        .filter(|focus| items.iter().any(|(_, _, key)| key.as_ref() == Some(*focus)))
        .cloned()
        .or_else(|| {
            state
                .search
                .trim()
                .is_empty()
                .then(|| UiKey::new(format!("settings/nav{}", state.route.path())))
        });
    if *state.navigation_revealed.borrow() != target {
        if let Some(index) = target.as_ref().and_then(|target| {
            items
                .iter()
                .position(|(_, _, key)| key.as_ref() == Some(target))
        }) {
            let top = tops[index];
            let bottom = top + items[index].1;
            if top < offset {
                offset = top;
            } else if bottom > offset + list_height {
                offset = (bottom - list_height).min(limit);
            }
        }
        *state.navigation_revealed.borrow_mut() = target;
    }
    state.navigation_scroll.set(offset);
    state.navigation_scroll_limit.set(limit);

    let children: Vec<UiNode> = items
        .into_iter()
        .zip(&tops)
        .map(|((node, height, _), top)| {
            let top = top - offset;
            let bottom = top + height;
            if bottom <= 0.01 || top >= list_height - 0.01 {
                node.offscreen()
            } else {
                node
            }
        })
        .collect();
    let list = UiNode::new(
        "settings/navigation/list",
        UiContent::Group(GroupSpec {
            label: Some("Settings pages".to_string()),
            role: SemanticRole::List,
            style: StyleRef::Plain,
        }),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(list_height))
            .gap(gap)
            .scrolled(offset)
            .clipped(),
    )
    .room(list_height, false)
    .children(children);
    let body = if limit > 0.0 {
        #[allow(
            clippy::cast_possible_truncation,
            clippy::cast_sign_loss,
            reason = "points of a list a few thousand tall, rounded"
        )]
        let share = format!(
            "{},{},{}",
            offset.round() as u32,
            list_height.round() as u32,
            content.round() as u32
        );
        let thumb = UiNode::new(
            "settings/navigation/thumb",
            UiContent::Custom(AuditedCustomNode {
                audit_id: crate::native_ui::MESSAGES_SCROLL_AUDIT,
                role: SemanticRole::Group,
                label: String::new(),
                value: Some(share),
                action: None,
                focusable: false,
                focused: false,
                focus_visible: false,
            }),
        )
        .layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fixed(list_height)),
        )
        .paint_only();
        UiNode::new(
            "settings/navigation/scroll",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fixed(list_height)),
        )
        .children(vec![list, thumb])
    } else {
        list
    };

    let title = titled.then(|| {
        UiNode::new(
            "settings/navigation-title",
            UiContent::Text(TextSpec::heading("Settings")),
        )
        .layout(Layout::default().height(Length::Fixed(title_height)))
    });
    let header = title.into_iter().chain(std::iter::once(settings_search_bar(
        state,
        if text_scale > 1.25 {
            "Search…"
        } else {
            "Search settings…"
        },
        Length::Fixed(search_height),
    )));
    UiNode::new(
        "settings/navigation",
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Navigation)),
    )
    .layout(
        Layout::column()
            .width(Length::Fixed(settings_navigation_width(width)))
            .height(Length::Fill)
            .padding(Insets::symmetric(
                navigation_side_inset(width),
                vertical_padding,
            ))
            .gap(gap)
            .clipped(),
    )
    .children(header.chain(std::iter::once(body)).collect())
}

const fn route_icon(route: SettingsRoute) -> ButtonIcon {
    match route {
        SettingsRoute::Home => ButtonIcon::Home,
        SettingsRoute::Modified => ButtonIcon::Modified,
        SettingsRoute::Manual => ButtonIcon::Document,
        SettingsRoute::Appearance => ButtonIcon::Appearance,
        SettingsRoute::Themes => ButtonIcon::Themes,
        SettingsRoute::TextFonts => ButtonIcon::Text,
        SettingsRoute::CursorMotion => ButtonIcon::Cursor,
        SettingsRoute::CursorStyles => ButtonIcon::Trail,
        SettingsRoute::Sound => ButtonIcon::Sound,
        SettingsRoute::WindowTabs => ButtonIcon::Window,
        SettingsRoute::TabColor => ButtonIcon::Swatch,
        SettingsRoute::Wallpaper => ButtonIcon::Image,
        SettingsRoute::KeyboardInput => ButtonIcon::Keyboard,
        SettingsRoute::Terminal => ButtonIcon::Terminal,
        SettingsRoute::Security => ButtonIcon::Security,
        SettingsRoute::SoftwareUpdate => ButtonIcon::Update,
        SettingsRoute::Packages => ButtonIcon::Packages,
        SettingsRoute::Harness => ButtonIcon::Agents,
        SettingsRoute::Ai => ButtonIcon::Spark,
        SettingsRoute::Tabs => ButtonIcon::Window,
        SettingsRoute::Messages => ButtonIcon::Diagnostics,
        SettingsRoute::About => ButtonIcon::Info,
    }
}

fn page(
    state: &SettingsViewState,
    update: &UpdateProjection,
    packages: &PackagesProjection,
    messages: &MessagesState,
    harness: &HarnessProjection,
    cx: &ViewCx<'_>,
    width: SettingsWidth,
) -> UiNode {
    let record = state.scroll_record.borrow().clone();
    let _shared = showcase_page::BlocksShared::open(state);
    let _words = scroll::KeyboardWords::watch(state.common.last_focus.clone());
    let _status = StatusWordsShared::open();
    let bars = settings_status_bars_height(state, width, cx.viewport) > 0.0;
    let seat = |chrome: PageChrome, calm: bool| {
        state.scroll_record.replace(record.clone());
        state.page_chrome.set(chrome);
        state.measuring_calm.set(true);
        let list = settings_list_body_height(state, width, cx.viewport);
        let _rows = RowsTooTallToStack::set(
            (width == SettingsWidth::Compact && SettingsWidth::Compact.row_height() > list + 0.01)
                .then_some(list),
        );
        let _fields = FieldListRoom::set(Some(
            (list - page_heading_height()).max(scaled_control_height()),
        ));
        state.measuring_calm.set(calm);
        state
            .status_extra
            .set(plain_status_extra(state, width, cx.viewport));
        state
            .status_slack
            .set(plain_status_slack(state, width, cx.viewport));
        let built = page_children(state, update, packages, messages, harness, cx, width);
        state.status_extra.set(0.0);
        state.status_slack.set(0.0);
        let (holds, cuts) = if state.route == SettingsRoute::Messages
            && state.search.trim().is_empty()
            && !state.compact_navigation
        {
            let visible = messages_visible(messages, &state.messages_filter);
            let holds = visible.is_empty()
                || !messages_plan_opening(
                    state,
                    messages,
                    &visible,
                    width,
                    cx.viewport,
                    None,
                    state.messages_tag_menu,
                )
                .view(0)
                .rows
                .is_empty();
            (holds, (0, 0))
        } else {
            state.scroll_plan().map_or((true, (0, 0)), |plan| {
                (
                    plan.first_screen_need() <= plan.room() + 0.01,
                    (plan.cut_stops(), plan.bare_captions()),
                )
            })
        };
        state.measuring_calm.set(false);
        (built, holds, cuts)
    };
    let seated_at = (cx.viewport, settings_text_scale());
    let decide = || {
        #[cfg(test)]
        if let Some(chrome) = PAGE_CHROME_HELD.with(Cell::get) {
            return (chrome, seat(chrome, bars).0);
        }
        let kept = record
            .as_ref()
            .filter(|record| {
                (record.top() > 0 || state.page_reveal.is_some()) && record.same_context(state)
            })
            .and_then(|_| state.page_chrome_at.get())
            .filter(|at| *at == seated_at)
            .map(|_| state.page_chrome.get());
        // The seat built last, while no other has been since: a seat starts
        // from the same record, so the same chrome seated again builds the
        // same page and leaves the same state, and is not built twice.
        let mut spare = None;
        if let Some(chrome) = kept {
            let seated = seat(chrome, bars);
            let scrolled = record.as_ref().is_some_and(|record| record.top() > 0);
            if scrolled || state.revealed_stop_fits() {
                return (chrome, seated.0);
            }
            spare = Some((chrome, seated));
        }
        let mut chosen = None;
        let mut full_cuts = None;
        for chrome in PageChrome::ladder(width, cx.viewport) {
            let (built, holds, cuts) = match spare.take() {
                Some((was, seated)) if was == chrome => seated,
                _ => seat(chrome, bars),
            };
            if chrome == PageChrome::FULL {
                full_cuts = Some(cuts);
            }
            if holds {
                chosen = Some((chrome, Some(built), cuts));
                break;
            }
            spare = Some((chrome, (built, holds, cuts)));
        }
        // No rung holds the page: FULL, its page built only where nothing
        // is cut, since the trials below seat another and FULL again.
        let (chrome, built, cuts) = chosen.unwrap_or_else(|| match (spare, full_cuts) {
            (Some((was, (built, _, cuts))), _) if was == PageChrome::FULL => {
                (PageChrome::FULL, Some(built), cuts)
            }
            (_, Some(cuts)) if cuts != (0, 0) => (PageChrome::FULL, None, cuts),
            _ => {
                let (built, _, cuts) = seat(PageChrome::FULL, bars);
                (PageChrome::FULL, Some(built), cuts)
            }
        });
        if let (Some(built), (0, 0)) = (built, cuts) {
            return (chrome, built);
        }
        let ladder = PageChrome::ladder(width, cx.viewport);
        let further = ladder
            .iter()
            .position(|rung| *rung == chrome)
            .map_or(ladder.len(), |at| at + 1);
        let mut best = (chrome, None, cuts);
        let mut last = chrome;
        let rungs = std::iter::once(chrome).chain(ladder[further..].iter().copied());
        let sheds = rungs.clone().map(PageChrome::giving_bar_room);
        let lists = lists_its_preview_when_starved(state.route)
            .then(|| {
                rungs.flat_map(|rung| {
                    [
                        rung.listing_preview(),
                        rung.giving_bar_room().listing_preview(),
                    ]
                })
            })
            .into_iter()
            .flatten();
        for trial in sheds.chain(lists) {
            let listing = trial.preview_listed && !chrome.preview_listed;
            if listing && best.2.0 == 0 {
                break;
            }
            let (trial_built, _, trial_cuts) = seat(trial, bars);
            last = trial;
            let better = if listing {
                trial_cuts.0 < best.2.0
            } else {
                trial_cuts < best.2
            };
            if better {
                best = (trial, Some(trial_built), trial_cuts);
            }
            if trial_cuts == (0, 0) || (better && listing && trial_cuts.0 == 0) {
                break;
            }
        }
        match best {
            (taken, Some(built), _) if taken == last => (taken, built),
            (taken, _, _) => (taken, seat(taken, bars).0),
        }
    };
    let inputs = ChromeInputs::of(state, cx);
    let remembered = state
        .page_chrome_memo
        .borrow()
        .as_ref()
        .filter(|(at, _)| *at == inputs)
        .map(|(_, chrome)| *chrome);
    #[cfg(test)]
    let remembered = remembered.filter(|_| PAGE_CHROME_HELD.with(Cell::get).is_none());
    let (chrome, built) = match remembered {
        Some(chrome) => {
            #[cfg(test)]
            {
                CHROME_REMEMBERED.with(|count| count.set(count.get() + 1));
                let (decided, _) = decide();
                assert_eq!(
                    decided, chrome,
                    "the chrome remembered for these inputs is the chrome the page chooses"
                );
            }
            (chrome, None)
        }
        None => {
            let (chrome, built) = decide();
            state.page_chrome_memo.replace(Some((inputs, chrome)));
            (chrome, Some(built))
        }
    };
    let (mut children, layout) = match built {
        Some(built) if !bars => built,
        _ => {
            state.status_overrun.set(0.0);
            let mut seated = seat(chrome, false).0;
            loop {
                let overrun = state.status_overrun.replace(0.0);
                if overrun <= 0.01 {
                    break seated;
                }
                let height = feedback_bar_height(state, width, cx.viewport);
                state.status_bar_most.set(Some((height - overrun).max(0.0)));
                if feedback_bar_height(state, width, cx.viewport) >= height - 0.01 {
                    break seated;
                }
                seated = seat(chrome, false).0;
            }
        }
    };
    state.page_chrome_at.set(Some(seated_at));
    let global_search = !state.search.trim().is_empty();
    let insets = page_frame_insets(state, cx.viewport, width, layout.maximum(width));
    scroll::seat_page_scroller(&mut children, insets.right);
    let (page_key, page_label) = if global_search {
        ("settings/page/search-results".to_string(), "Search Results")
    } else if width == SettingsWidth::Compact && state.compact_navigation {
        ("settings/categories/page".to_string(), "All Settings")
    } else {
        (
            format!("settings/page{}", state.route.path()),
            state.route.label(),
        )
    };
    UiNode::new(page_key, UiContent::Group(GroupSpec::new(page_label)))
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fill)
                .padding(insets)
                .gap(settings_page_gap(state, width, cx.viewport))
                .clipped(),
        )
        .children(children)
}

fn page_children(
    state: &SettingsViewState,
    update: &UpdateProjection,
    packages: &PackagesProjection,
    messages: &MessagesState,
    harness: &HarnessProjection,
    cx: &ViewCx<'_>,
    width: SettingsWidth,
) -> (Vec<UiNode>, PageLayout) {
    let global_search = !state.search.trim().is_empty();
    let shown = PageLayout::shown(state);
    if global_search {
        (
            settings_fields_page(state, false, cx, width, packages),
            shown,
        )
    } else if width == SettingsWidth::Compact && state.compact_navigation {
        (compact_navigation_page(state, packages, cx), shown)
    } else {
        match state.route {
            SettingsRoute::Home => top_settings_page(state, width, cx),
            SettingsRoute::SoftwareUpdate => update_page(
                state,
                update,
                SettingsAvailability::for_state(state),
                width,
                cx.viewport.width,
                cx.viewport.height,
            ),
            route => (
                match route {
                    SettingsRoute::Manual => manual_page(state, cx, width),
                    SettingsRoute::Modified => {
                        settings_fields_page(state, true, cx, width, packages)
                    }
                    SettingsRoute::Themes => showcase_page::themes_page(state, width, cx),
                    SettingsRoute::TabColor => tab_color_page(state, width, cx.viewport),
                    SettingsRoute::Wallpaper => wallpaper_page(state, width, cx),
                    SettingsRoute::CursorStyles => cursor_styles_page(state, width, cx),
                    SettingsRoute::Packages => packages_page(
                        state,
                        packages,
                        width,
                        cx.viewport.width,
                        cx.viewport.height,
                    ),
                    SettingsRoute::Harness => {
                        harness_page::harness_page(state, harness, update, width, cx)
                    }
                    SettingsRoute::Ai => ai_page::ai_page(state, &harness.ai, width, cx),
                    SettingsRoute::Tabs => tabs_page::tabs_page(state, &harness.tabs, width, cx),
                    SettingsRoute::Messages => messages_page(state, messages, width, cx.viewport),
                    SettingsRoute::About => about_page(state, messages, width, cx.viewport),
                    _ => settings_fields_page(state, false, cx, width, packages),
                },
                shown,
            ),
        }
    }
}

fn compact_navigation_page(
    state: &SettingsViewState,
    packages: &PackagesProjection,
    cx: &ViewCx<'_>,
) -> Vec<UiNode> {
    let scale = settings_text_scale();
    let row_height = 44.0_f32.max(36.0 * scale);
    let page_gap = settings_page_gap(state, SettingsWidth::Compact, cx.viewport);
    let body = settings_page_body_height(state, SettingsWidth::Compact, cx.viewport);
    let (mut out, used) = pinned_heading(
        state,
        SettingsWidth::Compact,
        cx.viewport,
        page_gap,
        "All Settings",
        "Choose a settings pane.",
    );
    let content_width = settings_page_content_width(
        cx.viewport.width,
        SettingsWidth::Compact,
        PageLayout::Form.maximum(SettingsWidth::Compact),
    );
    let columns = if content_width / scale >= 480.0 { 2 } else { 1 };
    let heading_height = 22.0_f32.max(16.0 * scale);
    let heading_gap = 6.0;
    let sheet: Vec<(Option<&'static str>, Vec<SettingsRoute>)> = navigation_groups(state.route)
        .into_iter()
        .flat_map(|(heading, routes)| {
            routes
                .chunks(columns)
                .enumerate()
                .map(|(row, chunk)| {
                    (
                        (row == 0 && !heading.is_empty()).then_some(heading),
                        chunk.to_vec(),
                    )
                })
                .collect::<Vec<_>>()
        })
        .collect();
    let stop_height =
        |heading: Option<&str>| row_height + heading.map_or(0.0, |_| heading_height + heading_gap);
    let mut plan = ScrollPlan::new(6.0);
    for (heading, chunk) in &sheet {
        plan.card(
            stop_height(*heading),
            chunk
                .iter()
                .map(|route| UiKey::new(format!("settings/categories{}", route.path())))
                .collect(),
        );
    }
    plan.set_room((body - used).max(row_height));
    let view = state.seat_scroll(&mut plan);
    let button = |route: SettingsRoute| {
        UiNode::new(
            format!("settings/categories{}", route.path()),
            UiContent::Button(
                route_control(
                    route,
                    ButtonSpec::new(route.label())
                        .visual_icon(route_icon(route))
                        .trailing_icon(ButtonIcon::Forward),
                    packages,
                )
                .state(ControlState {
                    selected: route == state.route,
                    ..ControlState::default()
                })
                .style(StyleRef::Navigation),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fixed(row_height)),
        )
    };
    let children = sheet
        .iter()
        .enumerate()
        .filter(|(index, _)| view.contains(index))
        .map(|(index, (heading, chunk))| {
            let row = if columns == 1 {
                button(chunk[0])
            } else {
                let mut cells: Vec<UiNode> = chunk.iter().copied().map(button).collect();
                if chunk.len() < columns {
                    cells.push(
                        UiNode::new(
                            format!("settings/categories/row/{index}/rest"),
                            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                        )
                        .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
                    );
                }
                UiNode::new(
                    format!("settings/categories/row/{index}"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(Layout::row().height(Length::Fixed(row_height)).gap(8.0))
                .children(cells)
            };
            let Some(heading) = heading else {
                return row;
            };
            UiNode::new(
                format!("settings/categories/group/{}", key_fragment(heading)),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .height(Length::Fixed(stop_height(Some(heading))))
                    .gap(heading_gap),
            )
            .children(vec![
                UiNode::new(
                    format!("settings/categories/label/{}", key_fragment(heading)),
                    UiContent::Text(navigation_heading(heading)),
                )
                .layout(Layout::default().height(Length::Fixed(heading_height))),
                row,
            ])
        })
        .collect();
    out.push(scroll::scroll_list_node(
        "settings/categories/routes",
        "Settings categories",
        &plan,
        view,
        children,
    ));
    out
}

const FORM_MEASURE: f32 = 720.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PageLayout {
    Form,
    Columns,
    Stage,
}

impl PageLayout {
    const fn maximum(self, width: SettingsWidth) -> f32 {
        match (self, width) {
            (Self::Stage, SettingsWidth::Wide) => 1_040.0,
            (Self::Stage, _) => 760.0,
            (Self::Columns, SettingsWidth::Wide) => 1_000.0,
            (Self::Columns, SettingsWidth::Medium) => 760.0,
            _ => FORM_MEASURE,
        }
    }

    fn shown(state: &SettingsViewState) -> Self {
        if state.compact_navigation {
            Self::Form
        } else if state.search.trim().is_empty() && state.route == SettingsRoute::Themes {
            Self::Stage
        } else if state.choice_picker.is_some() {
            Self::Columns
        } else {
            Self::Form
        }
    }
}

fn responsive_page_insets(
    viewport_width: f32,
    viewport_height: f32,
    width: SettingsWidth,
    maximum: f32,
) -> Insets {
    let mut insets = page_insets(viewport_width, width, maximum);
    if width == SettingsWidth::Compact {
        let vertical = compact_page_vertical_inset(viewport_height);
        insets.top = vertical;
        insets.bottom = vertical;
    }
    insets
}

fn responsive_page_gap(width: SettingsWidth, viewport_height: f32) -> f32 {
    if width == SettingsWidth::Compact {
        compact_page_gap(viewport_height)
    } else {
        12.0
    }
}

fn settings_page_gap(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if width == SettingsWidth::Compact
        && state.choice_picker.is_some()
        && compact_header_height(state, viewport) > compact_toolbar_height() + 0.01
    {
        6.0
    } else {
        responsive_page_gap(width, viewport.height)
    }
}

const fn widest_page_maximum(width: SettingsWidth) -> f32 {
    match width {
        SettingsWidth::Wide => 1_000.0,
        SettingsWidth::Medium => 760.0,
        SettingsWidth::Compact => 0.0,
    }
}

fn page_insets(viewport_width: f32, width: SettingsWidth, maximum: f32) -> Insets {
    let navigation = settings_navigation_width(width);
    let (minimum, vertical) = match width {
        SettingsWidth::Wide => (40.0, 32.0),
        SettingsWidth::Medium => (24.0, 24.0),
        SettingsWidth::Compact => (
            if viewport_width < 300.0 && settings_text_scale() > 1.25 {
                14.0
            } else {
                16.0
            },
            20.0,
        ),
    };
    let canvas = (viewport_width - navigation).max(0.0);
    if width == SettingsWidth::Compact {
        let horizontal = ((canvas - maximum) / 2.0).max(minimum);
        return Insets::symmetric(horizontal, vertical);
    }
    let left = ((canvas - widest_page_maximum(width)) / 2.0).max(minimum);
    let right = (canvas - left - maximum).max(minimum);
    Insets {
        left,
        right,
        top: vertical,
        bottom: vertical,
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct CompactPageBudget {
    content_height: f32,
    side_by_side_pager: bool,
}

fn compact_page_budget(state: &SettingsViewState, viewport: LogicalRect) -> CompactPageBudget {
    let content_height = settings_page_body_height(state, SettingsWidth::Compact, viewport);
    CompactPageBudget {
        content_height,
        side_by_side_pager: viewport.width >= 480.0 && content_height < 300.0,
    }
}

fn window_page_chrome(width: SettingsWidth, viewport: LogicalRect) -> (bool, bool) {
    let heading =
        !compact_page_omits_heading(viewport.height) && !compact_toolbar_titles(width, viewport);
    let subtitle = heading && width != SettingsWidth::Compact;
    (heading, subtitle)
}

fn page_chrome(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> (bool, bool) {
    let (heading, subtitle) = window_page_chrome(width, viewport);
    (heading, subtitle && !state.page_chrome.get().no_subtitle)
}

/// SHORT WINDOWS SHED CHROME BEFORE CONTENT.
#[derive(Clone, Copy, Debug, PartialEq)]
pub(crate) struct PageChrome {
    no_subtitle: bool,
    inset: Option<f32>,
    bar_room_given: bool,
    preview_listed: bool,
}

impl PageChrome {
    const FULL: Self = Self {
        no_subtitle: false,
        inset: None,
        bar_room_given: false,
        preview_listed: false,
    };

    const fn giving_bar_room(self) -> Self {
        Self {
            bar_room_given: true,
            ..self
        }
    }

    const fn listing_preview(self) -> Self {
        Self {
            preview_listed: true,
            ..self
        }
    }

    fn ladder(width: SettingsWidth, viewport: LogicalRect) -> Vec<Self> {
        let natural = responsive_page_insets(viewport.width, viewport.height, width, FORM_MEASURE);
        let mut ladder = vec![Self::FULL];
        if window_page_chrome(width, viewport).1 {
            ladder.push(Self {
                no_subtitle: true,
                ..Self::FULL
            });
        }
        for inset in [12.0, 4.0] {
            if natural.top.max(natural.bottom) > inset + 0.01 {
                ladder.push(Self {
                    no_subtitle: true,
                    inset: Some(inset),
                    ..Self::FULL
                });
            }
        }
        ladder
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct PinnedPlace {
    route: SettingsRoute,
    viewport: LogicalRect,
    scale: f32,
    chrome: PageChrome,
    summary_listed: bool,
    preview: Option<f32>,
}

impl PinnedPlace {
    fn same_place(&self, other: &Self) -> bool {
        self.route == other.route
            && self.viewport == other.viewport
            && (self.scale - other.scale).abs() < 0.001
            && self.chrome == other.chrome
    }
}

fn lists_its_preview_when_starved(route: SettingsRoute) -> bool {
    route == SettingsRoute::CursorStyles
}

#[cfg(test)]
thread_local! {
    /// How many renders took the chrome remembered for their inputs, on this thread.
    pub(crate) static CHROME_REMEMBERED: Cell<usize> = const { Cell::new(0) };
    /// Whether this thread's renders draw a plain status's bar at its least
    /// ([`SettingsViewState::status_bar_most`]).
    pub(crate) static STATUS_BAR_LEAST: Cell<bool> = const { Cell::new(false) };
    /// The chrome this thread's renders seat the page in, whatever the page
    /// would choose: the chrome a frame held, which a test measures the
    /// screens of.
    pub(crate) static PAGE_CHROME_HELD: Cell<Option<PageChrome>> = const { Cell::new(None) };
}

#[derive(Clone, Debug, PartialEq)]
struct ChromeInputs {
    content: u64,
    viewport: LogicalRect,
    appearance: crate::native_appearance::AppearancePreferences,
    terminal: (f32, f32),
    semantic_font: Option<crate::tray_raster::PreparedSemanticFont>,
    motion: crate::native_app::ViewMotionCx,
    faces: u64,
}

impl ChromeInputs {
    fn of(state: &SettingsViewState, cx: &ViewCx<'_>) -> Self {
        Self {
            content: state.common.content_epoch,
            viewport: cx.viewport,
            appearance: crate::native_appearance::current_preferences(),
            terminal: (cx.terminal_font_px, cx.terminal_scale),
            semantic_font: cx.semantic_font.clone(),
            motion: cx.motion,
            faces: crate::tray_raster::strip_band_font_epoch(),
        }
    }
}

fn page_frame_insets(
    state: &SettingsViewState,
    viewport: LogicalRect,
    width: SettingsWidth,
    maximum: f32,
) -> Insets {
    let mut insets = page_chrome_insets(state, viewport, width, maximum);
    insets.bottom -= status_bottom_inset_given(state, width, viewport);
    insets
}

fn page_chrome_insets(
    state: &SettingsViewState,
    viewport: LogicalRect,
    width: SettingsWidth,
    maximum: f32,
) -> Insets {
    let mut insets = responsive_page_insets(viewport.width, viewport.height, width, maximum);
    if let Some(inset) = state.page_chrome.get().inset {
        insets.top = insets.top.min(inset);
        insets.bottom = insets.bottom.min(inset);
    }
    insets
}

const LEANEST_PAGE_INSET: f32 = 4.0;

fn status_bottom_inset_given(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let over = plain_status_overflow(state, width, viewport);
    if over <= 0.01 {
        return 0.0;
    }
    let bottom = page_chrome_insets(state, viewport, width, FORM_MEASURE).bottom;
    over.min((bottom - LEANEST_PAGE_INSET).max(0.0))
}

fn pinned_heading(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
    gap: f32,
    title: &str,
    subtitle: &str,
) -> (Vec<UiNode>, f32) {
    let (heading, show_subtitle) = page_chrome(state, width, viewport);
    if !heading {
        return (Vec::new(), 0.0);
    }
    let subtitle = if show_subtitle { subtitle } else { "" };
    let mut nodes = page_heading(title, subtitle);
    let column = settings_page_content_width(viewport.width, width, FORM_MEASURE);
    let one_line = |style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, style);
        crate::tray_raster::ui_text_width_for(face, title, px)
            <= column + crate::native_ui::TEXT_FIT_SLACK
    };
    let large = width == SettingsWidth::Compact && settings_text_scale() > 1.25;
    let mut heading_height = page_heading_height();
    if let Some(heading) = nodes.first_mut()
        && let UiContent::Text(spec) = &mut heading.content
        && (large || !one_line(spec.style))
    {
        spec.style = StyleRef::Plain;
        if !one_line(StyleRef::Plain) {
            let (wrapped, height) = wrapped_words_node(
                heading.key.as_str(),
                title,
                (SemanticRole::Heading, StyleRef::Plain),
                column,
                page_heading_height() / 1.5,
            );
            heading_height = height.max(page_heading_height());
            *heading = wrapped;
            heading.layout.height = Length::Fixed(heading_height);
        }
    }
    let mut subtitle_height = 0.0;
    if !subtitle.is_empty()
        && let Some(line) = nodes.get_mut(1)
    {
        let (wrapped, height) = wrapped_words_node(
            line.key.as_str(),
            subtitle,
            (SemanticRole::Text, StyleRef::Quiet),
            column,
            page_subtitle_height(),
        );
        *line = wrapped;
        if !matches!(line.content, UiContent::Text(_)) {
            line.layout.width = Length::Fixed(column);
        }
        subtitle_height = height + gap;
    }
    (nodes, heading_height + gap + subtitle_height)
}

fn settings_list_body_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let body = settings_page_body_height(state, width, viewport);
    let taken = settings_status_bars_taken(state, width, viewport);
    let cost = settings_status_bar_kept(state, width, viewport);
    (body - (cost - taken).max(0.0)).max(0.0) + plain_status_extra(state, width, viewport)
}

fn plain_status_extra(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    (plain_status_overflow(state, width, viewport)
        - status_bottom_inset_given(state, width, viewport))
    .max(0.0)
}

/// THE BAR UNDER A RELOAD WARNING SHORTENS FOR WHAT THE PERSON IS ON TOO
/// ([`SettingsViewState::seat_scroll`], [`plain_status_extra`], [`status_words_node`]).
fn plain_status_slack(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if !state.plain_status()
        || state.config_watch_status.is_none()
        || state.measuring_calm.get()
        || (width == SettingsWidth::Compact && compact_status_dock_required(state, viewport))
    {
        return 0.0;
    }
    let height = feedback_bar_height(state, width, viewport);
    let most = state.status_bar_most.replace(Some(0.0));
    let least = feedback_bar_height(state, width, viewport);
    state.status_bar_most.set(most);
    (height - least).max(0.0)
}

fn plain_status_overflow(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if !state.plain_status() || state.config_watch_status.is_some() || state.measuring_calm.get() {
        return 0.0;
    }
    (settings_status_bars_taken(state, width, viewport)
        - settings_status_bar_kept(state, width, viewport))
    .max(0.0)
}

fn settings_status_bar_kept(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if state.page_chrome.get().bar_room_given {
        0.0
    } else {
        settings_status_bar_cost(state, width, viewport)
    }
}

fn settings_status_bar_cost(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let bar = scaled_control_height();
    let watcher = state.config_watch_status.is_some() && !state.measuring_calm.get();
    let docks = width == SettingsWidth::Compact
        && compact_status_dock_required_at(
            state,
            viewport,
            bar,
            &DockActions::Undo,
            watcher,
            true,
            None,
        );
    if !docks {
        return bar;
    }
    compact_dock_layout(state, viewport, &DockActions::Undo, watcher, true, None)
        .under
        .map_or(0.0, |under| {
            scaled_control_height() + 8.0 + under + 16.0 - compact_toolbar_height()
        })
        .max(0.0)
}

const COMPACT_BODY_FLOOR: f32 = 260.0;

fn settings_status_bars_taken(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    if width == SettingsWidth::Compact && compact_status_dock_required(state, viewport) {
        compact_header_height(state, viewport) - compact_toolbar_height()
    } else {
        settings_status_bars_height(state, width, viewport)
    }
}

fn settings_steady_body_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    (settings_page_body_height(state, width, viewport)
        + settings_status_bars_taken(state, width, viewport)
        - settings_status_bar_kept(state, width, viewport))
    .max(0.0)
}

fn settings_list_overhang(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> scroll::Overhang {
    scroll::Overhang {
        now: (settings_page_body_height(state, width, viewport)
            - settings_list_body_height(state, width, viewport))
        .max(0.0),
        kept: settings_status_bar_kept(state, width, viewport),
    }
}

fn compact_page_effective_height(viewport_height: f32) -> f32 {
    viewport_height / settings_text_scale()
}

fn compact_page_omits_heading(viewport_height: f32) -> bool {
    compact_page_effective_height(viewport_height) <= 240.0
}

fn compact_page_vertical_inset(viewport_height: f32) -> f32 {
    let effective = compact_page_effective_height(viewport_height);
    if effective <= 190.0 {
        0.0
    } else if effective <= 240.0 {
        4.0
    } else if effective <= 420.0 {
        12.0
    } else {
        20.0
    }
}

fn compact_page_gap(viewport_height: f32) -> f32 {
    if compact_page_omits_heading(viewport_height) {
        4.0
    } else if compact_page_effective_height(viewport_height) <= 420.0 {
        5.0
    } else {
        10.0
    }
}

fn noncompact_page_content_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport_width: f32,
    viewport_height: f32,
    maximum: f32,
) -> f32 {
    debug_assert_ne!(width, SettingsWidth::Compact);
    let insets = page_frame_insets(
        state,
        LogicalRect::new(0.0, 0.0, viewport_width, viewport_height),
        width,
        maximum,
    );
    (viewport_height
        - settings_status_bars_height(
            state,
            width,
            LogicalRect::new(0.0, 0.0, viewport_width, viewport_height),
        )
        - insets.top
        - insets.bottom)
        .max(0.0)
}

fn page_heading(title: &str, subtitle: &str) -> Vec<UiNode> {
    let mut out = vec![
        UiNode::new(
            format!("settings/page-heading/{}", key_fragment(title)),
            UiContent::Text(TextSpec {
                text: title.to_string(),
                role: SemanticRole::Heading,
                style: StyleRef::Hero,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(page_heading_height()))),
    ];
    if !subtitle.is_empty() {
        out.push(
            UiNode::new(
                format!("settings/page-subtitle/{}", key_fragment(title)),
                UiContent::Text(TextSpec {
                    text: subtitle.to_string(),
                    role: SemanticRole::Text,
                    style: StyleRef::Quiet,
                }),
            )
            .layout(Layout::default().height(Length::Fixed(page_subtitle_height()))),
        );
    }
    out
}

fn settings_page_content_width(viewport_width: f32, width: SettingsWidth, maximum: f32) -> f32 {
    let navigation = settings_navigation_width(width);
    let insets = page_insets(viewport_width, width, maximum);
    (viewport_width - navigation - insets.left - insets.right).max(0.0)
}

fn settings_page_body_height(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let insets = page_frame_insets(state, viewport, width, FORM_MEASURE);
    let chrome = if width == SettingsWidth::Compact {
        compact_header_height(state, viewport)
            + if compact_status_dock_required(state, viewport) {
                0.0
            } else {
                settings_status_bars_height(state, width, viewport)
            }
    } else {
        settings_status_bars_height(state, width, viewport)
    };
    (viewport.height - chrome - insets.top - insets.bottom).max(0.0)
}

fn settings_card_text_width(viewport: LogicalRect, width: SettingsWidth) -> f32 {
    (settings_page_content_width(viewport.width, width, FORM_MEASURE) - 24.0).max(48.0)
}

fn wrapped_copy_lines(text: &str, px: f32, available_width: f32) -> Vec<String> {
    let available_width = available_width.max(48.0);
    text.split('\n')
        .flat_map(|paragraph| copy_paragraph_lines(paragraph, px, available_width))
        .collect()
}

fn copy_paragraph_lines(paragraph: &str, px: f32, width: f32) -> Vec<String> {
    use crate::tray_raster::{LinesRule, kept_lines};
    use crate::widget::TextFace;
    kept_lines(LinesRule::Copy, TextFace::Ui, paragraph, px, width, || {
        let measure = |text: &str| crate::tray_raster::ui_text_width(text, px);
        let wider = paragraph.split_whitespace().any(|word| {
            !word.chars().any(crate::tray_raster::is_east_asian)
                && measure(word) > width + crate::native_ui::TEXT_FIT_SLACK
        });
        if wider {
            return wrap_to_box(paragraph, width, &measure);
        }
        let walked: Vec<String> = crate::tray_raster::ui_text_wrap_ranges(paragraph, px, width)
            .into_iter()
            .map(|range| paragraph[range].trim_end().to_string())
            .collect();
        let lone = walked
            .split_last()
            .is_some_and(|(_, before)| before.iter().any(|line| is_a_lone_letter(line)));
        if lone {
            return wrap_to_box(paragraph, width, &measure);
        }
        walked
    })
}

fn elide_wrapped_copy_tail(
    line: &str,
    px: f32,
    face: crate::widget::TextFace,
    max_width: f32,
) -> String {
    let mut graphemes = line.graphemes().collect::<Vec<_>>();
    loop {
        let candidate = format!("{}\u{2026}", graphemes.concat().trim_end());
        if crate::tray_raster::ui_text_width_for(face, &candidate, px) <= max_width
            || graphemes.is_empty()
        {
            return candidate;
        }
        graphemes.pop();
    }
}

fn wrapped_copy_node(
    key: &str,
    text: &str,
    role: SemanticRole,
    style: StyleRef,
    available_width: f32,
    line_height: f32,
    max_lines: Option<usize>,
) -> (UiNode, f32) {
    let (px, face) = crate::native_ui::text_paint_metrics(role, style);
    debug_assert!(
        face == crate::widget::TextFace::Ui,
        "wrapped settings copy must be UI-face copy"
    );
    let mut lines = wrapped_copy_lines(text, px, available_width);
    if let Some(max) = max_lines.filter(|max| *max >= 1 && lines.len() > *max) {
        lines.truncate(max);
        if let Some(last) = lines.pop() {
            lines.push(elide_wrapped_copy_tail(&last, px, face, available_width));
        }
    }
    let height = lines.len().max(1) as f32 * line_height;
    let children = lines
        .into_iter()
        .enumerate()
        .map(|(index, line)| {
            UiNode::new(
                format!("{key}/line-{index}"),
                UiContent::Text(TextSpec {
                    text: line,
                    role,
                    style,
                }),
            )
            .layout(Layout::default().height(Length::Fixed(line_height)))
            .paint_only()
        })
        .collect::<Vec<_>>();
    (
        UiNode::new(
            key.to_string(),
            UiContent::Group(GroupSpec {
                label: Some(text.to_string()),
                role,
                style: StyleRef::Plain,
            }),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(0.0),
        )
        .children(children),
        height,
    )
}

fn top_choice_short_title(key: &str, fallback: &str) -> String {
    match key {
        prefs::EDIT_THEME => "Theme".to_string(),
        prefs::EDIT_WINDOW_THEME => "Window".to_string(),
        _ => fallback.to_string(),
    }
}

fn choice_picker_title(label: &str) -> String {
    let mut words = label.split_whitespace();
    let first_word = words.next().unwrap_or_default();
    let mut chars = first_word.chars();
    let lowercase_rest = chars.next().is_some_and(char::is_uppercase)
        && chars.all(|character| !character.is_uppercase());
    let name = words
        .next()
        .and_then(|word| word.chars().next())
        .is_some_and(char::is_uppercase);
    if lowercase_rest && !name {
        let mut letters = label.chars();
        let first = letters.next().map(|first| first.to_lowercase().to_string());
        format!("Choose {}{}", first.unwrap_or_default(), letters.as_str())
    } else {
        format!("Choose {label}")
    }
}

fn choice_cancel_button_width() -> f32 {
    (crate::native_ui::native_button_label_width("Cancel") + 26.0).max(64.0)
}

fn choice_option_text_width(tile_width: f32, selected: bool) -> f32 {
    (tile_width - 10.0 - if selected { 38.0 } else { 10.0 }).max(0.0)
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ChoicePickerFit {
    width: f32,
    height: f32,
    padding: Insets,
    gap: f32,
    compact: bool,
}

fn picker_list_least(themed: bool) -> f32 {
    let gap = 6.0;
    (if themed {
        picker_heading_height() + gap
    } else {
        0.0
    }) + 2.0 * scaled_control_height()
        + gap
}

fn choice_picker_floor(themed: bool, width: SettingsWidth) -> f32 {
    let padding = if width == SettingsWidth::Compact {
        22.0
    } else {
        24.0
    };
    padding + scaled_control_height() + 6.0 + picker_list_least(themed)
}

const fn picker_host_preview_height(least: f32, natural: f32, room: f32) -> f32 {
    room.min(natural).max(least)
}

impl ChoicePickerFit {
    fn stacked(
        state: &SettingsViewState,
        width: SettingsWidth,
        viewport: LogicalRect,
        above: &[UiNode],
    ) -> Self {
        let gap = settings_page_gap(state, width, viewport);
        let used = above
            .iter()
            .map(|node| match node.layout.height {
                Length::Fixed(height) => height + gap,
                _ => gap,
            })
            .sum::<f32>();
        let padding = if width == SettingsWidth::Compact {
            Insets {
                top: 12.0,
                right: 12.0,
                bottom: 10.0,
                left: 12.0,
            }
        } else {
            Insets::all(12.0)
        };
        let height = (settings_list_body_height(state, width, viewport)
            - plain_status_extra(state, width, viewport)
            - used)
            .max(0.0);
        let tile_gap = 6.0;
        let row = scaled_control_height();
        let full_room =
            height - padding.top - padding.bottom - row - tile_gap - 2.0 * (row + tile_gap);
        let compact = width == SettingsWidth::Compact || full_room + 0.5 < picker_list_least(true);
        Self {
            width: settings_page_content_width(
                viewport.width,
                width,
                PageLayout::shown(state).maximum(width),
            ),
            height,
            padding,
            gap: tile_gap,
            compact,
        }
    }
}

fn choice_picker_card(
    state: &SettingsViewState,
    picker: &ChoicePicker,
    field: &EditField,
    fit: ChoicePickerFit,
) -> (UiNode, f32) {
    let row_height = scaled_control_height();
    let gap = fit.gap;
    let padding = fit.padding;
    let field_label = picker.title(field.label);
    let inner_width = (fit.width - padding.left - padding.right).max(0.0);
    picker
        .trailing
        .set(if fit.compact && picker.themes.is_some() {
            THEME_PICKER_ACTION_CELLS
        } else {
            0
        });
    let theme_rows = if picker.themes.is_some() && !fit.compact {
        2
    } else {
        0
    };
    let no_match = picker.themes.is_some() && picker.shown.is_empty();

    let widest = picker
        .options
        .iter()
        .filter(|option| {
            !(picker.headed()
                && option
                    .theme
                    .as_ref()
                    .is_some_and(|theme| theme.section.spans_row()))
        })
        .map(|option| crate::native_ui::native_button_label_width(&option.label))
        .fold(0.0_f32, f32::max);
    let tile_minimum = (widest + 58.0)
        .max(140.0 * settings_text_scale())
        .min(inner_width.max(1.0));
    let max_columns =
        (((inner_width - 10.0 + gap) / (tile_minimum + gap)).floor() as usize).clamp(1, 4);
    let room = (fit.height
        - padding.top
        - padding.bottom
        - row_height
        - gap
        - (theme_rows + usize::from(no_match)) as f32 * (row_height + gap))
        .max(0.0);
    let columns = (max_columns.min(2)..=max_columns)
        .find(|columns| picker_rows_height(&picker.unfiltered_rows(*columns), gap) <= room + 0.5)
        .unwrap_or(max_columns);
    let rows_height = picker_rows_height(&picker.unfiltered_rows(columns), gap).min(room);
    let anchor = state
        .common
        .last_focus
        .as_ref()
        .and_then(|focus| picker.focus_position(focus));
    picker.configure_window(columns, rows_height, gap, anchor);
    let rows = picker.rows();
    let window = picker.window(&rows);
    let scrolls = window.len() < rows.len();

    let rows_width = (inner_width - if scrolls { 10.0 } else { 0.0 }).max(0.0);
    let tile_width = (rows_width - gap * columns.saturating_sub(1) as f32) / columns as f32;
    let row_node = |row: usize, cells: &PickerRow| match cells {
        PickerRow::Heading(heading) => picker_heading_node(picker, heading),
        PickerRow::Cells(cells) => {
            let spans = cells.len() == 1 && picker.spans_row(cells.start);
            let width = if spans { rows_width } else { tile_width };
            let mut tiles = cells
                .clone()
                .map(|position| match picker.shown.get(position) {
                    Some(index) => PickerCell::Option(*index),
                    None => PickerCell::Action(position - picker.shown.len()),
                })
                .map(|cell| picker_cell_node(state, picker, cell, width))
                .collect::<Vec<_>>();
            for spacer in cells.len()..if spans { 1 } else { columns } {
                tiles.push(
                    UiNode::new(
                        format!("settings/choice-spacer/{}/{row}/{spacer}", picker.key),
                        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                    )
                    .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
                );
            }
            UiNode::new(
                format!("settings/choice-row/{}/{row}", picker.key),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::row().height(Length::Fixed(row_height)).gap(gap))
            .children(tiles)
        }
    };
    let carried = picker.carried_heading(&rows, window.start);
    let window_used = picker_rows_height(&rows[window.clone()], gap)
        + carried.map_or(0.0, |_| picker_heading_height() + gap);
    let last_screen =
        window.start > 0 && window.end == rows.len() && window_used + 0.5 < rows_height;
    let mut pinned = None;
    let mut scrolled = 0.0;
    let mut option_rows = Vec::new();
    let peeks = if last_screen {
        let caption_of = |first: usize| {
            let cells = (first..rows.len())
                .find(|row| matches!(rows[*row], PickerRow::Cells(_)))
                .unwrap_or(first);
            picker.carried_heading(&rows, cells)
        };
        let drawn_from = |first: usize| match rows[first] {
            PickerRow::Heading(_) if caption_of(first).is_some() => first + 1,
            _ => first,
        };
        let inner_of = |first: usize| {
            rows_height - caption_of(first).map_or(0.0, |_| picker_heading_height() + gap)
        };
        let mut first = window.start;
        while first > 0
            && picker_rows_height(&rows[drawn_from(first)..], gap) + 0.5 < inner_of(first)
        {
            first -= 1;
        }
        pinned = caption_of(first);
        let from = drawn_from(first);
        scrolled = (picker_rows_height(&rows[from..], gap) - inner_of(first)).max(0.0);
        option_rows.extend(
            rows.iter()
                .enumerate()
                .skip(from)
                .map(|(row, cells)| row_node(row - from, cells)),
        );
        true
    } else {
        option_rows.extend(carried.map(|heading| picker_heading_node(picker, heading)));
        option_rows.extend(
            rows[window.clone()]
                .iter()
                .enumerate()
                .map(|(row, cells)| row_node(row, cells)),
        );
        let mut used = window_used;
        for (row, cells) in rows.iter().enumerate().skip(window.end) {
            if used + gap >= rows_height - 4.0 {
                break;
            }
            if matches!(cells, PickerRow::Heading(_))
                && used + gap + picker_heading_height() + gap >= rows_height - 4.0
            {
                break;
            }
            option_rows.push(row_node(row - window.start, cells));
            used += gap + picker_row_height(cells);
        }
        used > rows_height + 0.5
    };
    if no_match {
        option_rows.insert(0, theme_no_match_node(picker));
    }
    let rows_height = rows_height + if no_match { row_height + gap } else { 0.0 };
    let list = UiNode::new(
        format!("settings/choice-list/{}", picker.key),
        UiContent::Group(GroupSpec {
            label: Some(theme_list_label(picker, field_label)),
            role: if scrolls {
                SemanticRole::List
            } else {
                SemanticRole::Group
            },
            style: StyleRef::Plain,
        }),
    )
    .layout({
        let layout = Layout::column()
            .width(Length::Fixed(rows_width))
            .height(Length::Fixed(rows_height))
            .gap(gap);
        match pinned {
            Some(_) => layout.clipped(),
            None if peeks => layout.scrolled(scrolled).clipped(),
            None => layout,
        }
    })
    .room(rows_height, false)
    .children(match pinned {
        Some(caption) => {
            let inner = (rows_height - picker_heading_height() - gap).max(0.0);
            vec![
                picker_heading_node(picker, caption),
                UiNode::new(
                    format!("settings/choice-list/{}/scrolled", picker.key),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    Layout::column()
                        .width(Length::Fill)
                        .height(Length::Fixed(inner))
                        .gap(gap)
                        .scrolled(scrolled)
                        .clipped(),
                )
                .under_caption(inner)
                .children(option_rows),
            ]
        }
        None => option_rows,
    });
    let list = if scrolls {
        let thumb = UiNode::new(
            format!("settings/choice-scroll/{}/thumb", picker.key),
            UiContent::Custom(crate::native_ui::AuditedCustomNode {
                audit_id: crate::native_ui::MESSAGES_SCROLL_AUDIT,
                role: SemanticRole::Group,
                label: String::new(),
                value: Some(format!("{},{},{}", window.start, window.len(), rows.len())),
                action: None,
                focusable: false,
                focused: false,
                focus_visible: false,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .paint_only();
        UiNode::new(
            format!("settings/choice-scroll/{}", picker.key),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fixed(rows_height)),
        )
        .children(vec![list, thumb])
    } else {
        list
    };

    let cancel_width = choice_cancel_button_width();
    let title_width = (inner_width - cancel_width - 8.0).max(0.0);
    let (full_title, short_title) = if picker.searchable() {
        let typed = if picker.filter.is_empty() {
            "type to search".to_string()
        } else {
            format!("\u{201c}{}\u{201d}", picker.filter)
        };
        (
            format!("{field_label} · {typed}"),
            if picker.filter.is_empty() {
                field_label.to_string()
            } else {
                typed
            },
        )
    } else {
        (
            choice_picker_title(field_label),
            top_choice_short_title(&picker.key, field_label),
        )
    };
    let fits = |title: &str, role: SemanticRole, style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(role, style);
        crate::tray_raster::ui_text_width_for(face, title, px) <= title_width
    };
    let heading = (SemanticRole::Heading, StyleRef::Primary);
    let quiet = (SemanticRole::Status, StyleRef::Quiet);
    let (title, (title_role, title_style)) = [
        (full_title.clone(), heading),
        (full_title.clone(), quiet),
        (field_label.to_string(), quiet),
        (short_title.clone(), quiet),
    ]
    .into_iter()
    .find(|(title, (role, style))| fits(title, *role, *style))
    .unwrap_or_else(|| {
        (
            crate::native_ui::fit_native_status_label(&short_title, title_width),
            quiet,
        )
    });
    let header = UiNode::new(
        format!("settings/choice-header/{}", picker.key),
        UiContent::Group(GroupSpec::new(full_title)),
    )
    .layout(Layout::row().height(Length::Fixed(row_height)).gap(8.0))
    .children(vec![
        theme_filter_node(state, picker, title_width)
            .filter(|_| fit.compact)
            .unwrap_or_else(|| {
                UiNode::new(
                    format!("settings/choice-title/{}", picker.key),
                    UiContent::Text(TextSpec {
                        text: title,
                        role: title_role,
                        style: title_style,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
            }),
        UiNode::new(
            "settings/choice-close",
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(format!("Cancel, keep {}", picker_saved_label(picker)))
                        .visual_label("Cancel"),
                    ActionId::new("settings/choice-close"),
                )
                .style(StyleRef::Quiet),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(cancel_width))
                .height(Length::Fill),
        ),
    ]);

    let mut children = vec![header];
    if !fit.compact
        && let Some(mut filter) = theme_filter_node(state, picker, inner_width)
    {
        filter.layout = Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(row_height));
        children.push(filter);
    }
    children.push(list);
    if !fit.compact {
        children.extend(theme_footer_node(picker, inner_width));
    }
    let height = padding.top
        + padding.bottom
        + row_height
        + gap
        + rows_height
        + theme_rows as f32 * (row_height + gap);
    (
        UiNode::new(
            format!("settings/choice-picker/{}", picker.key),
            UiContent::Group(
                GroupSpec::new(format!("{field_label} choices")).style(StyleRef::Secondary),
            ),
        )
        .layout(
            Layout::column()
                .width(Length::Fixed(fit.width))
                .height(Length::Fixed(height))
                .padding(padding)
                .gap(gap)
                .clipped(),
        )
        .children(children),
        height,
    )
}

fn theme_list_label(picker: &ChoicePicker, field_label: &str) -> String {
    let sections = picker.visible_sections();
    if sections.is_empty() {
        format!("{field_label} options")
    } else {
        let names: Vec<&str> = sections.iter().map(|section| section.label()).collect();
        format!("{field_label} options: {}", names.join(", "))
    }
}

fn picker_saved_label(picker: &ChoicePicker) -> String {
    let label = picker
        .options
        .get(picker.selected)
        .map_or("", |option| option.label.as_str());
    label
        .strip_suffix(" (default)")
        .or_else(|| label.strip_suffix(" (current)"))
        .or_else(|| {
            label
                .strip_prefix("Use default (")
                .and_then(|rest| rest.strip_suffix(')'))
        })
        .unwrap_or(label)
        .to_string()
}

fn choice_picker_node(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
    above: &[UiNode],
) -> Option<UiNode> {
    let picker = state.choice_picker.as_ref()?;
    let field = state.field_by_key(&picker.key)?;
    let fit = ChoicePickerFit::stacked(state, width, viewport, above);
    Some(choice_picker_card(state, picker, field, fit).0)
}

const COMPACT_LANDSCAPE_PREVIEW: f32 = 96.0;

fn page_preview_width(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    settings_page_content_width(
        viewport.width,
        width,
        PageLayout::shown(state).maximum(width),
    )
}

fn compact_landscape_choice_page(
    state: &SettingsViewState,
    mut preview: Option<UiNode>,
    budget: CompactPageBudget,
    viewport_width: f32,
) -> Option<Vec<UiNode>> {
    let picker = state.choice_picker.as_ref()?;
    let field = state.field_by_key(&picker.key)?;
    let page_width = settings_page_content_width(viewport_width, SettingsWidth::Compact, 720.0);
    let preview_width = if preview.is_some() {
        COMPACT_LANDSCAPE_PREVIEW + 8.0
    } else {
        0.0
    };
    let height = budget.content_height.max(0.0);
    let row_height = scaled_control_height();
    let padding = if height >= 2.0 * row_height + 4.0 + 12.0 {
        Insets::all(6.0)
    } else {
        Insets::default()
    };
    let (mut picker_node, picker_height) = choice_picker_card(
        state,
        picker,
        field,
        ChoicePickerFit {
            width: (page_width - preview_width).max(0.0),
            height,
            padding,
            gap: 4.0,
            compact: true,
        },
    );
    picker_node.layout.width = Length::Fill;
    let mut children = Vec::new();
    if let Some(preview) = preview.as_mut() {
        preview.layout.width = Length::Fixed(COMPACT_LANDSCAPE_PREVIEW);
        preview.layout.height = Length::Fixed(COMPACT_LANDSCAPE_PREVIEW.min(height));
    }
    children.extend(preview);
    children.push(picker_node);
    let choice = UiNode::new(
        "settings/choice-landscape",
        UiContent::Group(GroupSpec::new("Live choice preview and picker")),
    )
    .layout(
        Layout::row()
            .height(Length::Fixed(picker_height.max(96.0).min(height)))
            .gap(8.0)
            .clipped(),
    )
    .children(children);
    Some(vec![choice])
}

fn choice_option_button(option: &ChoiceOption, text_width: f32, fonts: bool) -> ButtonSpec {
    let visual = if option.value.is_none() && option.theme.is_none() && !option.free_text && !fonts
    {
        reset_row_visual(&option.label, text_width.max(0.0))
    } else {
        crate::native_ui::fit_native_button_label(&option.label, text_width.max(0.0))
    };
    let mut button = ButtonSpec::new(option.label.clone()).visual_label(visual);
    if let Some(theme) = option.theme.as_ref() {
        button = button.description(match &theme.description {
            Some(description) => format!("{}. {description}", theme.summary),
            None => theme.summary.clone(),
        });
        if let Some((background, cells)) = theme.swatches.split_first() {
            button = button.swatches(*background, cells);
        }
    }
    button
}

fn reset_row_visual(label: &str, text_width: f32) -> String {
    let width = crate::native_ui::native_button_label_width;
    if width(label) <= text_width {
        return label.to_string();
    }
    let Some(name) = label.strip_suffix(" (default)").or_else(|| {
        label
            .strip_prefix("Use default (")
            .and_then(|rest| rest.strip_suffix(')'))
    }) else {
        return crate::native_ui::fit_native_button_label(label, text_width);
    };
    let tail = " (default)";
    let shown = crate::native_ui::fit_native_button_label(name, text_width - width(tail));
    if shown.trim_end_matches('\u{2026}').is_empty() {
        // Not even a letter of the name fits beside the note.
        return crate::native_ui::fit_native_button_label(label, text_width);
    }
    format!("{shown}{tail}")
}

fn choice_option_node(
    state: &SettingsViewState,
    picker: &ChoicePicker,
    index: usize,
    tile_width: f32,
) -> UiNode {
    let option = &picker.options[index];
    let selected = index == picker.selected;
    let text_width = choice_option_text_width(tile_width, selected);
    let key = format!("settings/choice/{}/{index}", picker.key);
    let focused = state
        .common
        .last_focus
        .as_ref()
        .is_some_and(|focus| focus.as_str() == key);
    let disabled = option.disabled_reason().is_some();
    let open_width = native_button_width_for("Open file");
    let with_open = disabled && text_width - open_width - 6.0 >= 96.0;
    let button_text_width = if with_open {
        text_width - open_width - 6.0
    } else {
        text_width
    };
    let mut spec = choice_option_button(option, button_text_width, picker.fonts);
    if selected {
        spec = spec.trailing_icon(ButtonIcon::Check);
    }
    if let Some(reason) = option.disabled_reason() {
        let words = format!("{} \u{2014} {reason}", option.label);
        spec.visual_label = Some(crate::native_ui::fit_native_button_label(
            &words,
            button_text_width.max(0.0),
        ));
        spec.label = words;
    }
    let button = UiNode::new(
        key.clone(),
        UiContent::Button(
            Control::new(spec, ActionId::new(key))
                .state(ControlState {
                    focused,
                    selected,
                    enabled: !disabled,
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
        ),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill));
    if !with_open {
        return button;
    }
    let open_key = format!("settings/choice-open-file/{}/{index}", picker.key);
    UiNode::new(
        format!("settings/choice-attention/{}/{index}", picker.key),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::row()
            .width(Length::Fill)
            .height(Length::Fill)
            .gap(6.0),
    )
    .children(vec![
        button,
        UiNode::new(
            open_key.clone(),
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(format!("Open file: {}.conf", option.label))
                        .visual_label("Open file"),
                    ActionId::new(open_key),
                )
                .style(StyleRef::Quiet),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(open_width))
                .height(Length::Fill),
        ),
    ])
}

fn fitting_native_label<'a>(candidates: &[&'a str], available: f32) -> &'a str {
    candidates
        .iter()
        .copied()
        .find(|candidate| crate::native_ui::native_button_label_width(candidate) <= available)
        .unwrap_or("")
}

fn native_button_width_for(label: &str) -> f32 {
    crate::native_ui::native_button_label_width(label) + 24.0
}

