fn theme_footer_node(picker: &ChoicePicker, row_width: f32) -> Option<UiNode> {
    let extras = picker.themes.as_ref()?;
    let status = theme_files_status(picker)?;
    let import_label = "Import\u{2026}";
    let import_width = native_button_width_for(import_label);
    let browse_label = "All themes\u{2026}";
    let browse_width = native_button_width_for(browse_label);
    let long_folder = native_button_width_for("Open folder");
    let browse =
        row_width - import_width - browse_width - native_button_width_for("Folder") - 18.0 >= 96.0;
    let browse_room = if browse { browse_width + 6.0 } else { 0.0 };
    let folder_label = if row_width - import_width - long_folder - browse_room - 12.0 >= 96.0 {
        "Open folder"
    } else {
        "Folder"
    };
    let folder_width = native_button_width_for(folder_label);
    let status_width = (row_width - import_width - folder_width - browse_room - 12.0).max(0.0);
    let (long, short) = if extras.files == 0 {
        ("No theme files yet".to_string(), "None".to_string())
    } else {
        (
            format!("{} of {} loaded", extras.loaded, extras.files),
            format!("{}/{}", extras.loaded, extras.files),
        )
    };
    let visual = fitting_native_label(&[&long, &short], status_width).to_string();
    let import_enabled = crate::menu::local_file_picker_available();
    let mut children = vec![
        UiNode::new(
            format!("settings/themes/loaded/{}", picker.key),
            UiContent::Group(GroupSpec {
                label: Some(status),
                role: SemanticRole::Status,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .children(vec![
            UiNode::new(
                format!("settings/themes/loaded/{}/visual", picker.key),
                UiContent::Text(TextSpec {
                    text: visual,
                    role: SemanticRole::Status,
                    style: StyleRef::Quiet,
                }),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill))
            .paint_only(),
        ]),
    ];
    if browse {
        children.push(
            UiNode::new(
                THEMES_BROWSE_KEY,
                UiContent::Button(
                    Control::new(
                        ButtonSpec::new("Browse all themes")
                            .visual_label(browse_label)
                            .description("Opens Settings, Themes"),
                        route_action(SettingsRoute::Themes),
                    )
                    .style(StyleRef::Quiet),
                ),
            )
            .layout(
                Layout::default()
                    .width(Length::Fixed(browse_width))
                    .height(Length::Fill),
            ),
        );
    }
    children.push(
        UiNode::new(
            THEMES_FOLDER_ACTION,
            UiContent::Button(
                Control::new(
                    ButtonSpec::new("Open folder of themes").visual_label(folder_label),
                    ActionId::new(THEMES_FOLDER_ACTION),
                )
                .style(StyleRef::Quiet),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(folder_width))
                .height(Length::Fill),
        ),
    );
    children.push(
        UiNode::new(
            THEMES_IMPORT_ACTION,
            UiContent::Button(
                Control::new(
                    ButtonSpec::new("Import a theme from another terminal\u{2026}")
                        .visual_label(import_label),
                    ActionId::new(THEMES_IMPORT_ACTION),
                )
                .state(ControlState {
                    enabled: import_enabled,
                    ..ControlState::default()
                })
                .style(StyleRef::Quiet),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(import_width))
                .height(Length::Fill),
        ),
    );
    Some(
        UiNode::new(
            format!("settings/themes/footer/{}", picker.key),
            UiContent::Group(GroupSpec::new("Theme files")),
        )
        .layout(
            Layout::row()
                .height(Length::Fixed(scaled_control_height()))
                .gap(6.0),
        )
        .children(children),
    )
}

