#[derive(Clone, Copy)]
struct TopPreviews {
    theme: f32,
    text: f32,
    trail: f32,
}

fn top_preview_at(
    state: &SettingsViewState,
    key: &str,
    semantic_key: &str,
    height: f32,
    cx: &ViewCx<'_>,
    preview_width: f32,
) -> Option<(UiNode, f32)> {
    top_preview(state, key, semantic_key, height, cx, preview_width).map(|mut node| {
        let height = match &node.content {
            UiContent::SettingsPreview(spec) => spec.whole_rows_at_most(height),
            _ => height,
        };
        node.layout.height = Length::Fixed(height);
        (node, height)
    })
}

fn top_row_height(node: &UiNode, width: SettingsWidth) -> f32 {
    match node.layout.height {
        Length::Fixed(height) => height,
        _ => width.row_height(),
    }
}

fn top_cards(
    state: &SettingsViewState,
    width: SettingsWidth,
    cx: &ViewCx<'_>,
    text_width: f32,
    previews: TopPreviews,
) -> [SplitCard; 4] {
    let row = |key: &str, projected: Option<String>| {
        top_card_row(state, key, projected, width, text_width, true)
    };
    let preview = |key: &str, semantic_key: &str, height: f32| {
        top_preview_at(state, key, semantic_key, height, cx, text_width)
    };
    let compact = width == SettingsWidth::Compact;

    let mut color_rows: Vec<(UiNode, f32)> =
        theme_card_rows(state, ThemeRowsHost::Top, width, text_width, || {
            top_card_row(state, prefs::EDIT_THEME, None, width, text_width, true)
        });
    let sample_at = usize::from(!color_rows.is_empty());
    if let Some(sample) = preview(
        prefs::EDIT_THEME,
        "settings/top/theme/preview",
        previews.theme,
    ) {
        color_rows.insert(sample_at, sample);
    }
    color_rows.extend(row(prefs::EDIT_WINDOW_THEME, None));
    let colors = top_split_card(
        "theme",
        "Terminal colors & window appearance",
        Some("Colors & appearance"),
        Some((
            if cfg!(target_os = "macos") {
                "Choose colors; the window can match macOS, Light, or Dark."
            } else {
                "Choose colors; the window can match the terminal, Light, or Dark."
            },
            None,
        )),
        color_rows,
        width,
        text_width,
    );

    let mut text_rows: Vec<(UiNode, f32)> = Vec::new();
    text_rows.extend(preview(
        prefs::EDIT_FONT_FAMILY,
        "settings/top/text/preview",
        previews.text,
    ));
    text_rows.extend(row(prefs::EDIT_FONT_FAMILY, None));
    text_rows.extend(row(prefs::EDIT_FONT_PX, None));
    let text = top_split_card(
        "text",
        "Text",
        None,
        Some(("Your terminal font and its size.", None)),
        text_rows,
        width,
        text_width,
    );

    let mut trail_rows: Vec<(UiNode, f32)> = Vec::new();
    trail_rows.extend(preview(
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        "settings/top/cursor-trail/preview",
        previews.trail,
    ));
    trail_rows.push(cursor_style_link_row(state, text_width));
    let trail = top_split_card(
        "cursor-trail",
        "Cursor",
        None,
        Some((
            if compact {
                "A live preview of your cursor."
            } else {
                "A live preview of your cursor. More styles shows every style you can pick."
            },
            None,
        )),
        trail_rows,
        width,
        text_width,
    );

    let mut playful_rows = music_effects_rows(state, width, cx, text_width, true);
    playful_rows.extend(row(
        SPARKLE_WORDS_KEY,
        Some(top_projected_toy_value(state, SPARKLE_WORDS_KEY).to_string()),
    ));
    playful_rows.extend(row(
        KEYWORD_KITTIES_KEY,
        Some(top_projected_toy_value(state, KEYWORD_KITTIES_KEY).to_string()),
    ));
    if !field_bool(state, SPARKLE_MASTER_KEY, true) && !serious_mode_active(state, None, cx.motion)
    {
        playful_rows.push((top_word_effects_off_node(), page_subtitle_height()));
    }
    let playful = top_split_card(
        "playful-effects",
        PLAYFUL_EFFECTS_TITLE,
        None,
        Some((
            if compact {
                "Swear words sparkle; a cat peeks at cat words."
            } else {
                "Swear words in output sparkle; a cat peeks out at \u{201c}cat\u{201d}."
            },
            None,
        )),
        playful_rows,
        width,
        text_width,
    );
    [colors, text, trail, playful]
}

fn theme_browse_arrow_width() -> f32 {
    44.0 * settings_text_scale().min(1.5)
}

fn theme_browse_button(text_width: f32) -> UiNode {
    let spec = ButtonSpec::new("Browse themes")
        .description("Browse and customize themes in Settings, Themes");
    let visual = "Browse themes\u{2026}";
    let labelled = native_button_width_for(visual);
    let name_room = crate::native_ui::native_button_label_width(THEME_SHOWCASE_ROW_LABEL);
    let (spec, button_width) = if labelled + 12.0 + name_room + 8.0 <= text_width {
        (spec.visual_label(visual), labelled)
    } else {
        (
            spec.visual_icon(ButtonIcon::Forward),
            theme_browse_arrow_width(),
        )
    };
    UiNode::new(
        THEMES_BROWSE_ROW_KEY,
        UiContent::Button(
            Control::new(spec, route_action(SettingsRoute::Themes)).style(StyleRef::Quiet),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(button_width))
            .height(Length::Fill),
    )
}

