impl MacosAccess {
    /// The copies *Move to Trash* takes.
    pub(crate) fn retire_plan(&self) -> Vec<std::path::PathBuf> {
        let Some(census) = self.claimants.as_ref() else {
            return Vec::new();
        };
        census
            .offered_for_trash(self.trash_tool)
            .into_iter()
            .map(|copy| copy.path.clone())
            .collect()
    }

    /// `prompt_possible`.
    pub(crate) fn prompt_possible(&self) -> bool {
        aterm_containment::ConsentPosture::join(aterm_containment::PostureInputs {
            adoption: if self.sessions_adopted > 0 {
                aterm_containment::Attribution::Adopted
            } else {
                aterm_containment::Attribution::Live
            },
            fda: self.fda,
            responsible: aterm_containment::Responsible::Unknown,
            observed_eperm: self
                .warmup_rows
                .iter()
                .any(|(_, row)| *row == crate::consent_warmup::WarmupRow::Denied),
            evidence: self.evidence,
        })
        .prompt_possible
    }

    /// The folders the warm-up observed an `EPERM` for.
    pub(crate) fn denied_folders(&self) -> Vec<Folder> {
        self.warmup_rows
            .iter()
            .filter(|(_, row)| *row == crate::consent_warmup::WarmupRow::Denied)
            .map(|(folder, _)| *folder)
            .collect()
    }

    const fn reset_inputs(&self) -> ResetOfferInputs<'_> {
        ResetOfferInputs {
            dr: self.dr,
            tccutil: self.tccutil,
            bundle_id: self.bundle_id.as_ref(),
        }
    }

    /// Whether *Ask again* may be offered, and why not when it may not.
    pub(crate) fn reset_offer(&self) -> ResetOffer {
        aterm_containment::consent::reset_offer(self.reset_inputs())
    }

    /// The argv set the gesture would run, for exactly the denied folders.
    pub(crate) fn reset_plan(&self) -> Option<ResetPlan> {
        let denied = self.denied_folders();
        if !self.enabled || denied.is_empty() {
            return None;
        }
        ResetPlan::for_offer(self.reset_inputs(), &denied)
    }

    /// Whether the *Ask again* button is drawn at all.
    pub(crate) fn shows_reset_button(&self) -> bool {
        self.reset_offer().shows_button() && self.reset_plan().is_some()
    }
}

/// The fence for this panel's OS gestures.
#[derive(Clone, Copy)]
pub(crate) struct ConsentGestures {
    open_settings: fn(crate::menu::PrivacyPane) -> crate::menu::SettingsOpen,
    run_reset: fn(&ResetPlan) -> Vec<ResetAttempt>,
    confirm: fn(&str, &str, &str) -> Option<bool>,
    run_devtools: fn(crate::debugger_access::DevtoolsJob) -> crate::debugger_access::DevtoolsSpawn,
    asks_devtools_hand_over: fn() -> bool,
    live: bool,
}

impl ConsentGestures {
    /// The windowed instance's arms.
    pub(crate) const fn live() -> Self {
        Self {
            open_settings: crate::menu::open_privacy_settings,
            run_reset: run_tccutil_reset,
            confirm: live_confirm,
            run_devtools: crate::debugger_access::spawn_devtools_worker,
            asks_devtools_hand_over: gesture_yes,
            live: true,
        }
    }

    fn asks_devtools_hand_over(&self) -> bool {
        (self.asks_devtools_hand_over)()
    }

    /// Open a Privacy & Security pane through this instance's arm.
    pub(crate) fn open_settings(
        &self,
        pane: crate::menu::PrivacyPane,
    ) -> crate::menu::SettingsOpen {
        (self.open_settings)(pane)
    }

    /// The headless / unit-test arms.
    pub(crate) const fn inert() -> Self {
        Self {
            open_settings: inert_open_settings,
            run_reset: inert_run_reset,
            confirm: inert_confirm,
            run_devtools: crate::debugger_access::inert_run_devtools,
            asks_devtools_hand_over: gesture_no,
            live: false,
        }
    }

    /// The inert arms with an owner who says yes.
    #[cfg(test)]
    pub(crate) const fn confirming() -> Self {
        Self {
            confirm: test_confirm_yes,
            asks_devtools_hand_over: gesture_yes,
            ..Self::inert()
        }
    }

    /// Start the owner's debugger-access change through this instance's arm.
    pub(crate) fn run_devtools(
        &self,
        job: crate::debugger_access::DevtoolsJob,
    ) -> crate::debugger_access::DevtoolsSpawn {
        (self.run_devtools)(job)
    }

    /// The inert arms with a stand-in alert and a stand-in worker start.
    #[cfg(all(test, target_os = "macos"))]
    pub(crate) const fn for_test_with(
        confirm: fn(&str, &str, &str) -> Option<bool>,
        run_devtools: fn(
            crate::debugger_access::DevtoolsJob,
        ) -> crate::debugger_access::DevtoolsSpawn,
    ) -> Self {
        Self {
            confirm,
            run_devtools,
            ..Self::inert()
        }
    }

    fn confirm(&self, title: &str, body: &str, proceed: &str) -> Option<bool> {
        (self.confirm)(title, body, proceed)
    }

    /// `live()` for a windowed instance, `inert()` for a headless one.
    pub(crate) const fn for_instance(headless: bool) -> Self {
        if headless {
            Self::inert()
        } else {
            Self::live()
        }
    }

    /// Whether these are the live arms.
    #[cfg(test)]
    pub(crate) const fn is_live(self) -> bool {
        self.live
    }
}

/// What Show in Finder did with aterm.toml, as the file viewer reported it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ConfigFileShown {
    File,
    FolderOnly,
    Nothing,
}

/// Where aterm.toml lives, for the Manual page, and the arm that shows it in the file viewer.
#[derive(Clone, Copy)]
pub(crate) struct ConfigFileArm {
    reveal: fn(&std::path::Path) -> bool,
    open_folder: fn(&std::path::Path) -> bool,
    live: bool,
}

impl ConfigFileArm {
    /// Shows nothing; the page names the path instead.
    pub(crate) const fn inert() -> Self {
        Self {
            reveal: |_| false,
            open_folder: |_| false,
            live: false,
        }
    }

    /// A windowed instance's arm.
    pub(crate) const fn live() -> Self {
        Self {
            reveal: crate::menu::reveal_file_in_workspace,
            open_folder: crate::menu::open_file_in_workspace,
            live: true,
        }
    }

    pub(crate) const fn for_instance(headless: bool) -> Self {
        if headless {
            Self::inert()
        } else {
            Self::live()
        }
    }

    /// Show `path` in the file viewer, and say what was shown.
    pub(crate) fn show(self, path: &std::path::Path) -> ConfigFileShown {
        if path.is_file() {
            return if (self.reveal)(path) {
                ConfigFileShown::File
            } else {
                ConfigFileShown::Nothing
            };
        }
        match path.parent() {
            Some(folder) if !path.exists() && folder.is_dir() && (self.open_folder)(folder) => {
                ConfigFileShown::FolderOnly
            }
            _ => ConfigFileShown::Nothing,
        }
    }

    /// An arm whose OS seams are `reveal` and `open_folder`, for tests.
    #[cfg(test)]
    pub(crate) const fn with_seams(
        reveal: fn(&std::path::Path) -> bool,
        open_folder: fn(&std::path::Path) -> bool,
    ) -> Self {
        Self {
            reveal,
            open_folder,
            live: false,
        }
    }

    /// Whether this arm's seams are the live OS calls.
    #[cfg(test)]
    pub(crate) fn seams_are_live(self) -> bool {
        let reveal: fn(&std::path::Path) -> bool = crate::menu::reveal_file_in_workspace;
        let open_folder: fn(&std::path::Path) -> bool = crate::menu::open_file_in_workspace;
        std::ptr::fn_addr_eq(self.reveal, reveal)
            && std::ptr::fn_addr_eq(self.open_folder, open_folder)
    }
}

impl std::fmt::Debug for ConfigFileArm {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ConfigFileArm")
            .field("live", &self.live)
            .finish()
    }
}

