fn macos_access_folder_label(folder: Folder) -> String {
    folder.label().to_string()
}

fn macos_access_service_label(service: &str) -> String {
    match Folder::parse(service) {
        Some(folder) => macos_access_folder_label(folder),
        None => match service {
            "network-volumes" => "Network drives".to_string(),
            "removable-volumes" => "Removable drives".to_string(),
            "file-provider-domains" => "Cloud-storage folders (File Provider)".to_string(),
            "media-library" => "Music and media library".to_string(),
            "photos" => "Photos library".to_string(),
            "app-bundles" => "Other apps' bundles (App Management)".to_string(),
            "contacts" => "Contacts".to_string(),
            other => other.to_string(),
        },
    }
}

fn macos_access_row_label(folder: Folder, row: crate::consent_warmup::WarmupRow) -> String {
    match row {
        crate::consent_warmup::WarmupRow::Unknown => "not asked by this aterm process".to_string(),
        crate::consent_warmup::WarmupRow::Asking => "asking\u{2026}".to_string(),
        #[cfg(any(target_os = "macos", test))]
        crate::consent_warmup::WarmupRow::Allowed => "allowed".to_string(),
        crate::consent_warmup::WarmupRow::Denied => format!(
            "denied \u{2014} macOS is not asking again for this {}",
            folder.noun()
        ),
        #[cfg(any(target_os = "macos", test))]
        crate::consent_warmup::WarmupRow::Error => "could not be read".to_string(),
    }
}

/// The whole string table, as a total function of the published facts.
pub(crate) fn macos_access_copy(access: &MacosAccess) -> MacosAccessCopy {
    let headline = if !access.enabled {
        "File access \u{2014} not checked. aterm's privacy checks are switched off in aterm.toml."
    } else {
        match access.fda {
            FdaState::Granted => "Full disk access \u{2014} granted to aterm.",
            FdaState::Denied => {
                "File access \u{2014} not confirmed. Full Disk Access may already be enabled."
            }
            FdaState::Unknown if access.probe == ProbeLabel::Pending => {
                "File access \u{2014} checking\u{2026}"
            }
            FdaState::Unknown => "Full disk access \u{2014} unknown.",
        }
    };
    let probe_detail = match access.probe {
        ProbeLabel::Pending => "aterm is checking access in the background.".to_string(),
        ProbeLabel::OpenOk => "aterm's own check succeeded.".to_string(),
        ProbeLabel::OpenEperm => "aterm's own check was refused by macOS.".to_string(),
        ProbeLabel::OpenErrno(errno) => {
            format!("aterm's own check failed with error {errno}, which is not a privacy verdict.")
        }
        ProbeLabel::RefusedOutOfBundle => {
            "aterm did not check: this build is not running from an application bundle.".to_string()
        }
        ProbeLabel::RefusedNoExe => {
            "aterm did not check: the running program could not be resolved.".to_string()
        }
        ProbeLabel::RefusedDisabled => {
            "aterm did not check: the privacy check is switched off in aterm.toml.".to_string()
        }
        ProbeLabel::RefusedNoHome => {
            "aterm did not check: this account has no home directory set.".to_string()
        }
        ProbeLabel::RefusedBadPath => {
            "aterm did not check: the store path could not be used.".to_string()
        }
        ProbeLabel::UnsupportedPlatform => {
            "There is no macOS privacy database on this system.".to_string()
        }
    };
    let coverage = if access.evidence.fda_coverage_measured {
        "Full Disk Access stops macOS's \"access data from other applications\" request; the \
         rows below list what else it reaches on this Mac."
    } else {
        "Full Disk Access stops macOS's \"access data from other applications\" request."
    };
    let identity = {
        let posture = match access.install {
            "installed" => "installed in Applications",
            "mounted-image" => "on a mounted disk image",
            "translocated" => "in a quarantined copy macOS made",
            "not-a-bundle" => "outside an application bundle",
            _ => "at a location aterm could not read",
        };
        let consequence = match access.install {
            "installed" => "check the Full Disk Access entry for this installed app.",
            _ => {
                "a grant made for the copy in Applications does not reach this one; move it \
                  there and open that copy."
            }
        };
        match access.running.as_deref() {
            Some(path) => format!("Running from {path} ({posture}) \u{2014} {consequence}"),
            None => format!("Running {posture} \u{2014} {consequence}"),
        }
    };
    let anchor_fault = access.anchor.grant_unverifiable().then(|| {
        "This aterm's bundle has moved or been deleted: macOS asks again for everything and \
         clears every copy's access."
            .to_string()
    });
    let responsible = {
        let mut text = String::from(
            "Programs run in aterm ask macOS as aterm, so a dialog about a tool you ran here \
             names aterm.",
        );
        if access.sessions_adopted > 0 {
            text.push_str(&format!(
                " {} of {} sessions kept running across an update. This check does not establish \
                 their access. A new tab starts a fresh session under the running copy; existing \
                 work can keep running.",
                access.sessions_adopted, access.sessions_total
            ));
        }
        text
    };
    let services = {
        let mut rows = Vec::new();
        for service in access.covers.iter() {
            if *service == "app-data" && !access.evidence.fda_coverage_measured {
                rows.push(
                    "Other applications' data \u{2014} stopped by Full Disk Access".to_string(),
                );
                continue;
            }
            rows.push(format!(
                "{} \u{2014} measured: Full Disk Access applies",
                macos_access_service_label(service)
            ));
        }
        for service in access.unmeasured.iter() {
            rows.push(if *service == "app-data" {
                "Other applications' data \u{2014} stopped once Full Disk Access is granted"
                    .to_string()
            } else {
                format!(
                    "{} \u{2014} not measured",
                    macos_access_service_label(service)
                )
            });
        }
        for service in access.uncovered.iter() {
            rows.push(format!(
                "{} \u{2014} Full Disk Access does not apply",
                macos_access_service_label(service)
            ));
        }
        rows
    };
    let trade = "Full disk access on a terminal is broad: everything you run in aterm could then \
                 read everything this account can read.";
    let grants = "Who grants: Only you, in System Settings. aterm opens the page; macOS has no \
                  dialog for this.";
    let lasts = "Lasts: While this aterm keeps its signature. Applies to programs run in aterm.";
    let prompt = if access.prompt_possible() && access.fda == FdaState::Granted {
        "Granted. A row below marked not measured, or one Full Disk Access does not apply to, can still interrupt a program."
    } else if access.prompt_possible() {
        "A program running in aterm can still be interrupted by a macOS file-access request."
    } else {
        "For the services measured as covered, macOS is not expected to interrupt a program run in \
         aterm."
    };
    let mut route =
        crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::FullDiskAccess)
            .to_string();
    if access.install == "installed"
        && let Some(bundle) = access.running.as_deref().and_then(|path| {
            aterm_containment::consent::app_bundle_root(std::path::Path::new(path))
        })
    {
        route.push_str(&format!(
            " \u{2014} enable {}; use + to add it if absent. App Management is a different setting.",
            bundle.display()
        ));
    }
    let observation =
        "This shows what aterm's own check found, never the switch in System Settings.";
    let rebuild = (access.reset_offer() == ResetOffer::ExplainRebuild).then(|| {
        "This build's saved answers were invalidated by a rebuild, not by you. macOS binds every \
         answer to the exact code identity that asked, and this build's identity changes each time \
         it is built \u{2014} so clearing the saved answers here would not hold. A build signed \
         with a stable Developer ID identity keeps one identity across builds, which is what \
         shipped aterm releases carry."
            .to_string()
    });
    let folders = access
        .warmup_rows
        .iter()
        .map(|(folder, row)| {
            format!(
                "{} \u{2014} {}",
                macos_access_folder_label(*folder),
                macos_access_row_label(*folder, *row)
            )
        })
        .collect::<Vec<_>>();
    let mut repair = Vec::new();
    let denied = access.denied_folders();
    if !denied.is_empty() {
        repair.push(
            if access.shows_reset_button() {
                "macOS is not asking again for the folders above. Both ways out of that are \
                 yours to start, and neither happens on its own."
            } else {
                "macOS is not asking again for the folders above. The way out is yours to take \
                 in Files & Folders, and it does not happen on its own."
            }
            .to_string(),
        );
    }
    if let Some(report) = access.reset.as_ref() {
        repair.extend(macos_access_reset_lines(report, access.warmup_offered));
    }
    MacosAccessCopy {
        headline: headline.to_string(),
        probe_detail,
        coverage: coverage.to_string(),
        trade: trade.to_string(),
        grants: grants.to_string(),
        lasts: lasts.to_string(),
        prompt: prompt.to_string(),
        route,
        observation: observation.to_string(),
        identity,
        anchor_fault,
        responsible,
        services,
        rebuild,
        folders,
        repair,
        claimants: macos_access_claimant_lines(access),
        retired: access
            .retired
            .iter()
            .flatten()
            .map(|(path, outcome)| macos_access_retired_line(path, outcome))
            .collect(),
        retire_status: access.retire_status.clone(),
        debugger: debugger_row_copy(access),
    }
}

fn debugger_stamp_words(secs: u64) -> String {
    aterm_messages::words::stamp_words(secs.saturating_mul(1000))
}

fn debugger_date_words(secs: u64) -> String {
    let mut stamp = debugger_stamp_words(secs);
    stamp.truncate(10);
    stamp
}

const fn debugger_mode_words(mode: aterm_containment::consent::DebuggerMode) -> &'static str {
    use aterm_containment::consent::DebuggerMode;
    match mode {
        DebuggerMode::Enabled => "allowed",
        DebuggerMode::Disabled => "off",
        DebuggerMode::Unrecognized => "in a shape aterm does not recognise",
        DebuggerMode::Unknown => "not readable",
    }
}

const fn debugger_not_hardened_sentence(
    hardening: aterm_containment::consent::SelfHardening,
) -> Option<&'static str> {
    use aterm_containment::consent::SelfHardening;
    match hardening {
        SelfHardening::Hardened => None,
        SelfHardening::NotHardened => Some(
            "This aterm is not hardened (a development build), so after this any program you \
             run could take control of this aterm and drive it past aterm's alert.",
        ),
        SelfHardening::Unknown => Some(
            "aterm could not read whether this aterm is hardened. If it is not (a development \
             build), after this any program you run could take control of this aterm and drive \
             it past aterm's alert.",
        ),
    }
}

/// The rule the debugger row's headline states.
pub(crate) fn debugger_row_states(
    facts: &crate::debugger_access::DebuggerFacts,
) -> Option<aterm_containment::consent::DebuggerMode> {
    (facts.enabled && facts.probe.label != aterm_containment::consent::DebuggerProbeLabel::Pending)
        .then_some(facts.probe.mode)
}

/// The debugger row's string table (debugger design §3.3).
pub(crate) fn debugger_row_copy(access: &MacosAccess) -> DebuggerRowCopy {
    use crate::debugger_access::{Origin, Outcome};
    use aterm_containment::consent::{
        DEBUGGER_ACCESS_REVERT, DebuggerChange, DebuggerMember, DebuggerMode, DebuggerProbeLabel,
        SelfHardening,
    };
    let facts = &access.debugger;
    let probe = facts.probe;
    let headline = if !facts.enabled {
        "Debugger access \u{2014} not checked. aterm's privacy checks are switched off in \
         aterm.toml."
    } else {
        match debugger_row_states(facts) {
            None => "Debugger access \u{2014} checking\u{2026}",
            Some(DebuggerMode::Enabled) => "Debugger access \u{2014} allowed.",
            Some(DebuggerMode::Disabled) => "Debugger access \u{2014} not allowed.",
            Some(DebuggerMode::Unrecognized) => "Debugger access \u{2014} not recognised.",
            Some(DebuggerMode::Unknown) => "Debugger access \u{2014} not observed.",
        }
    }
    .to_string();
    let kind = "macOS developer mode. Not the Privacy & Security \u{25B8} Developer Tools list. \
                That list governs running software that fails the security policy, and does not \
                help with this dialog."
        .to_string();
    let not_hardened = debugger_not_hardened_sentence(facts.self_hardened);
    let with_not_hardened = |text: &str| match not_hardened {
        Some(extra) => format!("{text} {extra}"),
        None => text.to_string(),
    };
    let asks = "macOS asks for a password when a debugger attaches: under Apple's original rule \
                once, then quiet for up to 10 hours, during which the same access is open without \
                asking; once developer mode has been turned off with DevToolsSecurity, at every \
                new debugger. An unanswered dialog has waited 12 hours.";
    let member_unread = if probe.member == DebuggerMember::Unknown {
        " aterm could not read whether this account is an administrator or developer, and the \
         switch helps only those accounts."
    } else {
        ""
    };
    let measured = access.evidence.devtools_enable_measured;
    let state = if let Some(flight) = facts.in_flight {
        // The change's own child, or a predecessor's read from its marker:
        // either way a second press cannot start a second child.
        if measured {
            format!(
                "Waiting for macOS's administrator dialog (since {}).",
                debugger_stamp_words(flight.since)
            )
        } else {
            format!(
                "Waiting for DevToolsSecurity to finish; macOS should be asking for an \
                 administrator in its own dialog (since {}).",
                debugger_stamp_words(flight.since)
            )
        }
    } else if !facts.enabled {
        "aterm did not read the debugger rule.".to_string()
    } else {
        match (probe.mode, probe.label) {
            (_, DebuggerProbeLabel::Pending) => "Not read yet.".to_string(),
            (DebuggerMode::Disabled, _) if probe.member == DebuggerMember::NotMember => {
                "Allowing it would not change this for your account: macOS still asks accounts \
                 outside admin and _developer."
                    .to_string()
            }
            (DebuggerMode::Disabled, _) => {
                let lead = match facts.drift_since {
                    Some(since) => format!(
                        "Was allowed ({}); it is off now. {asks}",
                        debugger_date_words(since)
                    ),
                    None => asks.to_string(),
                };
                with_not_hardened(&format!("{lead}{member_unread}"))
            }
            (DebuggerMode::Enabled, _) => {
                let origin = match facts.recorded {
                    Some(marker) if marker.mode == DebuggerMode::Enabled => match marker.origin {
                        Origin::Aterm => format!(
                            ", turned on from aterm on {}",
                            debugger_date_words(marker.since)
                        ),
                        Origin::Outside => ", set outside aterm".to_string(),
                        Origin::Unknown => String::new(),
                    },
                    _ => String::new(),
                };
                match facts.self_hardened {
                    SelfHardening::Hardened => format!("Allowed for this Mac{origin}."),
                    SelfHardening::NotHardened => format!(
                        "Allowed for this Mac{origin}, and this aterm is not hardened: any \
                         program you run can take control of this aterm."
                    ),
                    SelfHardening::Unknown => format!(
                        "Allowed for this Mac{origin}, and aterm could not read whether this aterm \
                         is hardened: if it is not, any program you run can take control of it."
                    ),
                }
            }
            (DebuggerMode::Unrecognized, _) => {
                "macOS reports this rule in a shape aterm does not recognise; aterm leaves it \
                 alone."
                    .to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::ToolAbsent) => {
                "DevToolsSecurity is not on this Mac.".to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::RefusedOutOfBundle) => {
                "aterm did not read it: this build is not running from an application bundle."
                    .to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::UnsupportedPlatform) => {
                "There is no macOS debugger rule on this system.".to_string()
            }
            (DebuggerMode::Unknown, _) => "Not read yet.".to_string(),
        }
    };
    let status = if let Some(why) = facts.refusal {
        Some(format!("Nothing was changed: {}.", why.words()))
    } else {
        facts.last_outcome.map(|outcome| match outcome {
            Outcome::Changed(change) => format!(
                "aterm read the rule again after DevToolsSecurity finished: {} now.",
                debugger_mode_words(change.target())
            ),
            Outcome::NotChanged(_) => {
                "aterm read the rule again after DevToolsSecurity finished: unchanged. aterm does \
                 not try again on its own."
                    .to_string()
            }
            Outcome::Unrecognized(_) => {
                "aterm read the rule again after DevToolsSecurity finished: macOS reports it in a \
                 shape aterm does not recognise."
                    .to_string()
            }
            Outcome::Unobserved(_) => {
                "aterm could not read the rule again after DevToolsSecurity finished.".to_string()
            }
            Outcome::NotDue(_, DebuggerMode::Unknown) => {
                "Nothing was changed: aterm could not read the rule again before starting."
                    .to_string()
            }
            Outcome::NotDue(_, mode) => format!(
                "Nothing was changed: when aterm checked again, the rule already read {}.",
                debugger_mode_words(mode)
            ),
            Outcome::NotStarted(_) => {
                "Nothing was changed: aterm could not start DevToolsSecurity.".to_string()
            }
            Outcome::PeerInFlight(_) => {
                "Nothing was changed: another aterm on this Mac is already changing debugger \
                 access."
                    .to_string()
            }
        })
    };
    let stops = if access.evidence.devtools_silences_lldb {
        "Stops: The \"Developer Tools Access\" password dialog when lldb or Xcode attaches to your \
         programs. Does not stop \"take control\" dialogs from other debuggers, or attaching to \
         hardened apps."
    } else {
        "Stops: Should stop the \"Developer Tools Access\" password dialog when lldb or Xcode \
         attaches to your programs. Does not stop \"take control\" dialogs from other debuggers, \
         or attaching to hardened apps."
    }
    .to_string();
    let grants = if measured {
        "Who grants: An administrator, once, in macOS's own password dialog. aterm starts it \
         and never sees the password."
    } else {
        "Who grants: An administrator, once; macOS should ask in its own password dialog. aterm \
         starts DevToolsSecurity and never sees the password."
    }
    .to_string();
    let lasts = "Lasts: Until turned off. Applies to the whole Mac: every app, and every admin or \
                 developer account. aterm re-checks it."
        .to_string();
    let undo = format!("Undo: Turn Off Debugger Access\u{2026}, or run {DEBUGGER_ACCESS_REVERT}.");
    let mut trade = String::from(
        "Trade: Any program run by an admin or developer account, in any app, could use Apple's \
         debugger on that account's other unhardened programs without asking, and read or change \
         their memory: Homebrew tools, node, gpg-agent, anything built with cargo, development \
         builds of aterm. Hardened apps and macOS itself stay protected.",
    );
    match facts.self_hardened {
        SelfHardening::Hardened => {}
        SelfHardening::NotHardened => trade.push_str(" This aterm is not hardened, so it is one of them."),
        SelfHardening::Unknown => trade.push_str(
            " aterm could not read whether this aterm is hardened; if it is not, it is one of them.",
        ),
    }
    let cross_link =
        "Machine-wide, like THIS MAC below, but changed only when you say yes.".to_string();
    let button = (facts.enabled)
        .then(|| match probe.mode {
            DebuggerMode::Disabled if probe.member != DebuggerMember::NotMember => {
                Some(DebuggerChange::On)
            }
            DebuggerMode::Enabled => Some(DebuggerChange::Off),
            _ => None,
        })
        .flatten()
        .or_else(|| facts.in_flight.map(|flight| flight.change))
        .map(|change| DebuggerButton {
            change,
            enabled: facts.offers(change),
            busy: facts.in_flight.is_some(),
        });
    DebuggerRowCopy {
        headline,
        kind,
        state,
        status,
        stops,
        grants,
        lasts,
        undo,
        trade,
        cross_link,
        button,
    }
}

fn devtools_age_words(minutes: u64) -> String {
    match minutes {
        0 => "under a minute ago".to_string(),
        1 => "1 minute ago".to_string(),
        n => format!("{n} minutes ago"),
    }
}

fn devtools_opened_words(minutes: u64) -> String {
    match minutes {
        0..=59 => devtools_age_words(minutes),
        60..=119 => "1 hour ago".to_string(),
        120..=2_879 => format!("{} hours ago", minutes / 60),
        _ => format!("{} days ago", minutes / 1_440),
    }
}

/// The Developer Tools card's string table (debugger design §9.1).
pub(crate) fn devtools_card_copy(access: &MacosAccess) -> DevToolsCardCopy {
    use aterm_containment::consent::{DevToolListLabel as LL, DevToolListing as Li};
    use aterm_containment::{DevToolGrant as G, DevToolProbeLabel as L, DevToolState as S};
    let facts = &access.devtools;
    let probe = facts.probe;
    let list = facts.list;
    let shapes = access.evidence.devtool_answer_shapes_measured;
    let skips = access.evidence.devtool_skips_first_run_check;
    let observed = facts.enabled && probe.label == L::Observed;
    let list_read = facts.enabled && list.label == LL::Read && list.listing != Li::Unknown;
    let granted = facts.enabled && facts.grant == G::Granted;
    let latest = || match facts.answer_minutes {
        Some(minutes) => format!("macOS's latest answer, {}", devtools_age_words(minutes)),
        None => "macOS's latest answer".to_string(),
    };
    let stale = facts.grant == G::NotGranted
        && facts
            .answer_minutes
            .zip(facts.opened_minutes)
            .is_some_and(|(answer, opened)| answer > opened);
    let state_short = if !facts.enabled {
        "not checked"
    } else if list_read {
        match (list.listing, facts.grant) {
            (Li::On, G::Granted) => "on",
            (Li::On, _) => "still checks",
            (Li::Off, G::Granted) => "off, allowed",
            (Li::Off, _) => "off",
            (Li::Absent | Li::Unknown, _) => "not listed",
        }
    } else {
        match facts.grant {
            G::Granted => "allowed",
            G::NotGranted if stale => "unconfirmed",
            G::NotGranted => match probe.state {
                S::Unlisted => "not listed",
                S::Denied if shapes => "off",
                S::Denied | S::Allowed | S::Unknown => "not allowed",
            },
            G::Unknown if probe.label == L::Pending || list.label == LL::Pending => {
                "checking\u{2026}"
            }
            G::Unknown => "can't tell",
        }
    };
    let state = if !facts.enabled {
        "Not checked: aterm's privacy checks are switched off in aterm.toml.".to_string()
    } else if list_read {
        match (list.listing, facts.grant) {
            (Li::On, G::Granted) => {
                let mut text = "aterm is on the list and switched on.".to_string();
                if let Some(at) = list.modified_at_s.and_then(|s| u64::try_from(s).ok()) {
                    text.push_str(&format!(" Since {}.", debugger_date_words(at)));
                }
                text
            }
            (Li::On, _) => {
                "aterm is switched on, but macOS still checks its new programs.".to_string()
            }
            (Li::Off, G::Granted) => "aterm is on the list, switched off, though macOS's newest \
                                      answer allowed it."
                .to_string(),
            (Li::Off, _) => "aterm is on the list, switched off.".to_string(),
            (Li::Absent | Li::Unknown, _) => "aterm is not on the list.".to_string(),
        }
    } else {
        match facts.grant {
            G::Granted => format!("{}: aterm is allowed.", latest()),
            G::NotGranted if stale => {
                "Can't confirm yet: macOS answers again when aterm next starts a new program."
                    .to_string()
            }
            G::NotGranted => match probe.state {
                S::Unlisted => format!("{}: aterm is not on the list.", latest()),
                S::Denied if shapes => format!("{}: aterm is on the list, switched off.", latest()),
                S::Denied | S::Allowed | S::Unknown => match facts.answer_minutes {
                    Some(minutes) => format!(
                        "macOS checked a new program aterm started {} and did not allow it.",
                        devtools_age_words(minutes)
                    ),
                    None => "macOS checked a new program aterm started and did not allow it."
                        .to_string(),
                },
            },
            G::Unknown if probe.label == L::Pending || list.label == LL::Pending => {
                "Checking\u{2026}".to_string()
            }
            G::Unknown => {
                let list_why = if list.label == LL::Read {
                    "the list answered in a shape aterm does not recognise"
                } else {
                    atpkg::devtools::list_reason(list.label)
                };
                let log_why = if probe.label == L::Observed {
                    "macOS's answer was not recognised"
                } else {
                    atpkg::devtools::log_reason(probe.label)
                };
                if list_why == log_why {
                    format!("aterm can't tell: {list_why}.")
                } else {
                    format!("aterm can't tell: {list_why}, and {log_why}.")
                }
            }
        }
    };
    let state_style = if granted {
        StyleRef::Success
    } else if !facts.enabled || facts.grant == G::Unknown {
        StyleRef::Quiet
    } else {
        StyleRef::Primary
    };
    let unread = (facts.enabled && !granted && list.label == LL::NoFullDiskAccess)
        .then(|| "Full Disk Access (below) lets aterm read this list.".to_string());
    let kind = "macOS's Privacy & Security \u{25B8} Developer Tools list: in Apple's words, apps \
                allowed to \"run software locally that does not meet the system's security \
                policy\". Not debugger access: it does not stop the \"Developer Tools Access\" \
                password dialog."
        .to_string();
    let how = if list_read && !granted {
        atpkg::devtools::Step::of(&list).how()
    } else {
        atpkg::devtools::HELPER_HOW
    }
    .to_string();
    let mut route =
        crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::DeveloperTools)
            .to_string();
    if access.install == "installed"
        && let Some(bundle) = access.running.as_deref().and_then(|path| {
            aterm_containment::consent::app_bundle_root(std::path::Path::new(path))
        })
    {
        route.push_str(&format!(" \u{2014} this aterm is {}.", bundle.display()));
    }
    DevToolsCardCopy {
        state,
        state_short,
        state_style,
        granted,
        unread,
        kind,
        why: atpkg::devtools::why(skips).to_string(),
        checked: if observed {
            crate::devtools_helper::checked_words(probe.not_allowed)
        } else {
            None
        },
        how,
        route,
        trade: atpkg::devtools::trade(skips).to_string(),
        only: atpkg::devtools::only_aterm(false).to_string(),
        opened: facts.opened_minutes.map(|minutes| {
            format!(
                "aterm last opened this list in System Settings for you {}.",
                devtools_opened_words(minutes)
            )
        }),
        declined: facts.declined.filter(|_| !granted).map(|(at, until)| {
            format!(
                "You said Not now on {}: aterm won't open System Settings at this list by \
                 itself until {}. Open Developer Tools\u{2026} still opens it.",
                debugger_date_words(at),
                debugger_date_words(until)
            )
        }),
    }
}

fn debugger_press_refusal(
    facts: &crate::debugger_access::DebuggerFacts,
    change: aterm_containment::consent::DebuggerChange,
) -> Option<&'static str> {
    use crate::debugger_access::Refusal;
    use aterm_containment::consent::{DebuggerChange, DebuggerMember};
    if facts.offers(change) {
        return None;
    }
    Some(if !facts.enabled {
        Refusal::PrivacyOff.words()
    } else if facts.in_flight.is_some() {
        Refusal::InFlight.words()
    } else if facts.busy {
        "aterm is still reading debugger access, or the result of the last change"
    } else if facts.probe.mode != change.precondition() {
        Refusal::State(change, facts.probe.mode).words()
    } else if change == DebuggerChange::On && facts.probe.member == DebuggerMember::NotMember {
        "allowing it would not change this for your account, since macOS still asks accounts \
         outside admin and _developer"
    } else {
        "debugger access cannot be changed from here right now"
    })
}

/// Who raises [`debugger_access_alert`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum DebuggerAlertFrom {
    Press,
    Launch,
}

const fn debugger_alert_not_hardened_bullet(
    hardening: aterm_containment::consent::SelfHardening,
) -> Option<&'static str> {
    use aterm_containment::consent::SelfHardening;
    match hardening {
        SelfHardening::Hardened => None,
        SelfHardening::NotHardened => Some(
            "\u{2022} Not protected: this aterm (a development build). Any program you run could \
             take control of it and get past this alert.",
        ),
        SelfHardening::Unknown => Some(
            "\u{2022} Maybe not protected: this aterm, if it is a development build. Any program \
             you run could then take control of it and get past this alert.",
        ),
    }
}

/// aterm's own alert before a debugger-access change (debugger design §3.4 step 1).
pub(crate) fn debugger_access_alert(
    change: aterm_containment::consent::DebuggerChange,
    facts: &crate::debugger_access::DebuggerFacts,
    evidence: SpikeEvidence,
    from: DebuggerAlertFrom,
) -> (String, String, &'static str) {
    use aterm_containment::consent::{
        DEBUGGER_ACCESS_REVERT, DebuggerChange, DebuggerMember, SelfHardening,
    };
    let password_of = if facts.probe.member == DebuggerMember::Admin {
        "your admin password"
    } else {
        "an admin's password"
    };
    let dialog = match (change, evidence.devtools_enable_measured) {
        (DebuggerChange::On, true) => {
            format!("asks for {password_of} in a dialog named \"SamplingTools\", Apple's tool")
        }
        (DebuggerChange::On, false) => format!(
            "should ask for {password_of} in its own dialog, named \"SamplingTools\", Apple's tool"
        ),
        (DebuggerChange::Off, true) => {
            format!("asks for {password_of} in a dialog named \"SamplingTools\"")
        }
        (DebuggerChange::Off, false) => format!("should ask for {password_of} in its own dialog"),
    };
    let password = format!("Next, macOS {dialog}. aterm never sees it.");
    match change {
        DebuggerChange::On => {
            let mut bullets = vec![
                "\u{2022} Whole Mac: every admin and developer account, not just aterm",
                "\u{2022} Exposed: Homebrew tools, node, gpg-agent, cargo builds",
                if facts.self_hardened == SelfHardening::Hardened {
                    "\u{2022} Still protected: hardened apps (this aterm too) and macOS"
                } else {
                    "\u{2022} Still protected: hardened apps and macOS"
                },
            ];
            bullets.extend(debugger_alert_not_hardened_bullet(facts.self_hardened));
            bullets.push("\u{2022} Apple advises administrators not to change this rule");
            let undo = match from {
                DebuggerAlertFrom::Press => "press Turn Off Debugger Access\u{2026} here",
                DebuggerAlertFrom::Launch => {
                    "aterm's Settings \u{25b8} Security \u{25b8} Turn Off Debugger Access\u{2026}"
                }
            };
            let mut paragraphs = Vec::new();
            if from == DebuggerAlertFrom::Launch {
                paragraphs.push("aterm asks you this once on this Mac.".to_owned());
            }
            paragraphs.extend([
                "Afterwards, programs you run can debug your other programs without a password, \
                 and read or change their memory."
                    .to_owned(),
                bullets.join("\n"),
                password,
                format!("To undo: {undo}, or run {DEBUGGER_ACCESS_REVERT}."),
            ]);
            (
                "Allow debugger access on this Mac?".to_owned(),
                paragraphs.join("\n\n"),
                "Allow\u{2026}",
            )
        }
        DebuggerChange::Off => (
            "Turn off debugger access on this Mac?".to_owned(),
            format!(
                "Debuggers will need a password again each time one attaches. Apple's original \
                 10 hours without asking, after an answer, does not come back.\n\n{password}"
            ),
            "Turn Off\u{2026}",
        ),
    }
}

fn macos_access_claimant_lines(access: &MacosAccess) -> Vec<String> {
    use aterm_containment::consent::{MAX_CLAIMANT_ROWS, TrashOffer};
    let Some(census) = access.claimants.as_ref() else {
        return Vec::new();
    };
    let conflicting = census.conflicting();
    if conflicting.is_empty() {
        return Vec::new();
    }
    let mut lines = vec![
        "Other copies of aterm on this Mac are signed differently. macOS keeps one record of \
         aterm's code and replaces it with whichever copy asks last, which clears this access \
         for every copy."
            .to_string(),
    ];
    let listed = census.listed(access.trash_tool);
    for (copy, offer) in &listed {
        let signed = match (copy.signing, copy.team.as_deref()) {
            ("adhoc", _) => "signed ad hoc".to_string(),
            ("unsigned", _) => "not signed".to_string(),
            (_, Some(team)) => format!("signed by team {}", owner_text(team)),
            _ => "signature unreadable".to_string(),
        };
        let links = match copy.links.as_slice() {
            [] => None,
            [link] => Some(format!("{} leads to it", owner_path(link))),
            [link, more @ ..] => Some(format!(
                "{} and {} more {} lead to it",
                owner_path(link),
                more.len(),
                if more.len() == 1 { "link" } else { "links" }
            )),
        };
        let stays = ", so it stays where it is";
        let why = match offer {
            TrashOffer::Signature => stays.to_string(),
            TrashOffer::Requirement => {
                format!("; aterm cannot read its code identity as one build's{stays}")
            }
            TrashOffer::Linked
            | TrashOffer::Offered
            | TrashOffer::RunningUnstable
            | TrashOffer::NoTool => String::new(),
        };
        let row = match (offer, links) {
            (TrashOffer::Linked, Some(links)) => format!("{signed}; {links}{stays}"),
            (_, Some(links)) => format!("{signed}{why}; {links}"),
            (_, None) => format!("{signed}{why}"),
        };
        lines.push(format!("{} \u{2014} {row}", owner_path(&copy.path)));
    }
    if conflicting.len() > MAX_CLAIMANT_ROWS {
        lines.push(format!(
            "\u{2026}and {} more.",
            conflicting.len() - MAX_CLAIMANT_ROWS
        ));
    }
    let any = |reason: TrashOffer| listed.iter().any(|(_, offer)| *offer == reason);
    if any(TrashOffer::RunningUnstable) {
        lines.push(
            "The copy running here does not keep its access across updates, so aterm offers \
             none of these for the Trash: one of them may be the release."
                .to_string(),
        );
    }
    if any(TrashOffer::NoTool) {
        lines.push(
            "This macOS has no trash tool aterm can use, so these stay where they are.".to_string(),
        );
    }
    lines
}

fn macos_access_retired_line(
    path: &std::path::Path,
    outcome: &aterm_containment::consent::Retired,
) -> String {
    use aterm_containment::consent::Retired;
    let path = owner_path(path);
    match outcome {
        Retired::Moved => format!("Moved to the Trash: {path}."),
        Retired::NotOffered => {
            format!("Left in place: {path} \u{2014} a fresh check no longer offers it.")
        }
        Retired::InUse => {
            format!("Left in place: {path} \u{2014} aterm could not rule out that it is in use.")
        }
        Retired::Failed(reason) => format!("Not moved: {path} \u{2014} {}", owner_text(reason)),
    }
}

fn macos_access_reset_lines(report: &MacosAccessReset, warmup_offered: bool) -> Vec<String> {
    let (again, again_those) = if warmup_offered {
        (
            "Ask for folder access now to let it ask again.",
            "Ask for folder access now to let it ask again about those.",
        )
    } else {
        (
            "macOS asks again the next time aterm opens one.",
            "macOS asks again about those the next time aterm opens one.",
        )
    };
    let names = |folders: &[Folder]| {
        folders
            .iter()
            .map(|folder| macos_access_folder_label(*folder))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let mut out = Vec::new();
    match report.outcome {
        ResetOutcome::AllReset => out.push(format!(
            "macOS cleared its saved answer for every folder asked: {}. {again}",
            names(&report.reset)
        )),
        ResetOutcome::Partial => out.push(format!(
            "macOS cleared its saved answer for {} only. {again_those}",
            names(&report.reset)
        )),
        ResetOutcome::NoneReset => {
            out.push("macOS cleared no saved answer.".to_string());
        }
        ResetOutcome::ToolAbsent => {
            out.push(
                "Nothing was changed: the macOS tool that clears a saved answer could not be run."
                    .to_string(),
            );
        }
        ResetOutcome::NotAttempted => {}
    }
    for (folder, code) in &report.declined {
        out.push(match code {
            Some(code) => format!(
                "macOS declined to clear {} (exit status {code}).",
                macos_access_folder_label(*folder)
            ),
            None => format!(
                "macOS declined to clear {} (the command was ended by a signal).",
                macos_access_folder_label(*folder)
            ),
        });
    }
    out
}

/// The action ids this block owns.
pub(crate) const MACOS_ACCESS_GESTURE_PREFIX: &str = "settings/macos-access/";
pub(crate) const MACOS_ACCESS_OPEN_FDA: &str = "settings/macos-access/full-disk-access";
pub(crate) const MACOS_ACCESS_OPEN_FILES: &str = "settings/macos-access/files-and-folders";
pub(crate) const MACOS_ACCESS_WARM_UP: &str = "settings/macos-access/warm-up";
pub(crate) const MACOS_ACCESS_ASK_AGAIN: &str = "settings/macos-access/ask-again";
pub(crate) const MACOS_ACCESS_TRASH: &str = "settings/macos-access/trash-copies";
/// *Allow Debugger Access…*.
pub(crate) const MACOS_ACCESS_DEBUGGER_ON: &str = "settings/macos-access/debugger-on";
/// *Turn Off Debugger Access…*.
pub(crate) const MACOS_ACCESS_DEBUGGER_OFF: &str = "settings/macos-access/debugger-off";
/// The owner's `sudo` askpass relay off switch.
pub(crate) const MACOS_ACCESS_ASKPASS_OFF: &str = "settings/macos-access/askpass-off";
/// *Allow sudo Password Prompts*.
pub(crate) const MACOS_ACCESS_ASKPASS_ON: &str = "settings/macos-access/askpass-on";
/// *Open Developer Tools…*, the Developer Tools card's one button.
pub(crate) const MACOS_ACCESS_OPEN_DEVTOOLS: &str = "settings/macos-access/developer-tools";

const OWNER_QUIET_FIRST: std::time::Duration = std::time::Duration::from_secs(10);
const OWNER_QUIET_MAX: std::time::Duration = std::time::Duration::from_secs(5 * 60);
const OWNER_QUIET_FORGET: std::time::Duration = std::time::Duration::from_secs(10 * 60);

/// The owner's recent answers to the block's alerts, one record for every view.
#[derive(Debug, Default)]
pub(crate) struct OwnerQuiet {
    until: Option<QuietStamp>,
    declines: u32,
    warmup_confirmed: bool,
    retire_confirmed: bool,
    debugger_confirmed: bool,
    askpass_confirmed: bool,
    debugger_answered: bool,
}

#[derive(Clone, Copy, Debug)]
struct QuietStamp {
    awake: std::time::Instant,
    wall: std::time::SystemTime,
}

impl QuietStamp {
    fn now() -> Self {
        Self {
            awake: std::time::Instant::now(),
            wall: std::time::SystemTime::now(),
        }
    }

    fn after(self, span: std::time::Duration) -> Self {
        Self {
            awake: self.awake + span,
            wall: self.wall + span,
        }
    }

    fn before(self, other: Self) -> bool {
        self.awake < other.awake && self.wall < other.wall
    }

    fn since(self, earlier: Self) -> std::time::Duration {
        let wall = self.wall.duration_since(earlier.wall).unwrap_or_default();
        self.awake
            .saturating_duration_since(earlier.awake)
            .max(wall)
    }
}

/// One [`OwnerQuiet`] for the whole process, armed into every Settings view.
pub(crate) type SharedOwnerQuiet = std::sync::Arc<std::sync::Mutex<OwnerQuiet>>;

impl OwnerQuiet {
    fn quiet_at(&self, now: QuietStamp) -> bool {
        self.until.is_some_and(|until| now.before(until))
    }

    fn declined(&mut self, now: QuietStamp) {
        if self
            .until
            .is_some_and(|until| now.since(until) > OWNER_QUIET_FORGET)
        {
            self.declines = 0;
        }
        self.declines = self.declines.saturating_add(1);
        let doubled = OWNER_QUIET_FIRST
            .checked_mul(1 << self.declines.saturating_sub(1).min(16))
            .unwrap_or(OWNER_QUIET_MAX);
        self.until = Some(now.after(doubled.min(OWNER_QUIET_MAX)));
    }

    const fn accepted(&mut self) {
        self.until = None;
        self.declines = 0;
    }

    /// Count a decline the owner gave outside aterm's alert.
    pub(crate) fn note_decline(&mut self) {
        self.declined(QuietStamp::now());
    }

    /// Whether a gesture asked now would be quieted (a recent decline).
    pub(crate) fn quiet_now(&self) -> bool {
        self.quiet_at(QuietStamp::now())
    }

    /// The owner answered a debugger-access alert, yes or no.
    pub(crate) const fn note_debugger_answered(&mut self) {
        self.debugger_answered = true;
    }

    /// Whether the owner answered a debugger-access alert in this process.
    pub(crate) const fn debugger_answered(&self) -> bool {
        self.debugger_answered
    }

    /// The App's launch ask took the owner's yes to a debugger-access change.
    pub(crate) const fn note_debugger_confirmed(&mut self) {
        self.debugger_answered = true;
        self.debugger_confirmed = true;
    }

    /// The park has taken up every confirmed gesture (started it, or said why not).
    pub(crate) const fn settle_confirmed(&mut self) {
        self.warmup_confirmed = false;
        self.retire_confirmed = false;
        self.debugger_confirmed = false;
        self.askpass_confirmed = false;
    }

    #[cfg(test)]
    pub(crate) fn confirm_both_for_test(&mut self) {
        self.warmup_confirmed = true;
        self.retire_confirmed = true;
        self.debugger_confirmed = true;
        self.askpass_confirmed = true;
    }

    /// Whether a press right now would be quieted.
    #[cfg(test)]
    pub(crate) fn is_quiet_now_for_test(&self) -> bool {
        self.quiet_at(QuietStamp::now())
    }

    #[cfg(test)]
    pub(crate) const fn has_confirmed_for_test(&self) -> bool {
        self.warmup_confirmed
            || self.retire_confirmed
            || self.debugger_confirmed
            || self.askpass_confirmed
    }
}

/// The owner's yes in one of aterm's own alerts.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct OwnerYes(());

impl OwnerYes {
    /// A yes minted outside an alert, for tests only.
    #[cfg(test)]
    pub(crate) const fn for_test() -> Self {
        Self(())
    }
}

/// Ask the owner in aterm's alert.
pub(crate) fn owner_confirms_with(
    quiet: &SharedOwnerQuiet,
    gestures: &ConsentGestures,
    title: &str,
    body: &str,
    proceed: &str,
) -> OwnerAnswer {
    if quiet
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .quiet_at(QuietStamp::now())
    {
        return OwnerAnswer::Quiet;
    }
    let answer = gestures.confirm(title, body, proceed);
    let mut quiet = quiet.lock().unwrap_or_else(|p| p.into_inner());
    match answer {
        Some(true) => {
            quiet.accepted();
            OwnerAnswer::Yes(OwnerYes(()))
        }
        Some(false) => {
            quiet.declined(QuietStamp::now());
            OwnerAnswer::No
        }
        None => OwnerAnswer::NotAsked,
    }
}

/// How [`owner_confirms_with`] came out.
#[derive(Debug, PartialEq, Eq)]
pub(crate) enum OwnerAnswer {
    Yes(OwnerYes),
    No,
    Quiet,
    NotAsked,
}

impl OwnerAnswer {
    /// A yes minted outside an alert, for tests only.
    #[cfg(test)]
    pub(crate) const fn yes_for_test() -> Self {
        Self::Yes(OwnerYes::for_test())
    }

    const fn is_yes(&self) -> bool {
        matches!(self, Self::Yes(_))
    }

    const fn refusal(&self, declined: &'static str) -> &'static str {
        match self {
            Self::Yes(_) | Self::No => declined,
            Self::Quiet => {
                "You declined one of these a moment ago, so aterm did not ask again yet."
            }
            Self::NotAsked => "Nothing was changed: aterm could not show its question.",
        }
    }
}

fn owner_path(path: &std::path::Path) -> String {
    owner_text(&path.to_string_lossy())
}

fn owner_text(text: &str) -> String {
    let mut out = String::new();
    for c in text.chars() {
        if c.is_control()
            || matches!(
                c,
                '\u{00AD}'
                    | '\u{034F}'
                    | '\u{061C}'
                    | '\u{115F}'..='\u{1160}'
                    | '\u{17B4}'..='\u{17B5}'
                    | '\u{180B}'..='\u{180F}'
                    | '\u{200B}'..='\u{200F}'
                    | '\u{202A}'..='\u{202E}'
                    | '\u{2060}'..='\u{206F}'
                    | '\u{3164}'
                    | '\u{FE00}'..='\u{FE0F}'
                    | '\u{FEFF}'
                    | '\u{FFA0}'
                    | '\u{FFF0}'..='\u{FFF8}'
                    | '\u{1BCA0}'..='\u{1BCA3}'
                    | '\u{1D173}'..='\u{1D17A}'
                    | '\u{E0000}'..='\u{E0FFF}'
                    | '\u{13430}'..='\u{1343F}'
                    | '\u{2028}'..='\u{2029}'
                    | '\u{FFF9}'..='\u{FFFB}'
            )
        {
            out.push_str(&format!("\\u{{{:04X}}}", u32::from(c)));
        } else {
            out.push(c);
        }
    }
    out
}

fn prefers_macos_access(state: &SettingsViewState) -> bool {
    state.route == SettingsRoute::Security
        && state.search.trim().is_empty()
        && state.macos_access.is_some()
}

fn macos_access_height(access: &MacosAccess, lead: AccessLead, text_width: f32) -> f32 {
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let heading_height = access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).1;
    let copy = macos_access_copy(access);
    let (above, below) = macos_access_rows(&copy, access, lead);
    let lines = macos_access_visual_lines(&above, text_width)
        + macos_access_visual_lines(&below, text_width)
        + macos_access_visual_lines(&debugger_row_lines(&copy.debugger), text_width);
    let debugger_actions = debugger_access_actions(&copy, text_width).map_or(0.0, |(_, h)| h);
    heading_height
        + lines as f32 * line_height
        + macos_access_actions_height(access, text_width)
        + debugger_actions
        + 12.0
        + 24.0
}

type MacosAccessLine = (String, String, SemanticRole, StyleRef);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AccessLead {
    Whole,
    NoTrade,
    State,
}

impl AccessLead {
    const ALL: [Self; 3] = [Self::Whole, Self::NoTrade, Self::State];
}

fn macos_access_rows(
    copy: &MacosAccessCopy,
    access: &MacosAccess,
    lead: AccessLead,
) -> (Vec<MacosAccessLine>, Vec<MacosAccessLine>) {
    let line = |key: &str, text: &str, role: SemanticRole, style: StyleRef| {
        (
            format!("settings/macos-access/{key}"),
            text.to_string(),
            role,
            style,
        )
    };
    let headline_style = match (access.enabled, access.fda) {
        (false, _) => StyleRef::Quiet,
        (true, FdaState::Granted) => StyleRef::Success,
        (true, FdaState::Denied) => StyleRef::Primary,
        (true, FdaState::Unknown) => StyleRef::Quiet,
    };
    let mut above = vec![line(
        "state",
        &copy.headline,
        SemanticRole::Status,
        headline_style,
    )];
    if let Some(fault) = &copy.anchor_fault {
        above.push(line(
            "anchor-fault",
            fault,
            SemanticRole::Status,
            StyleRef::Danger,
        ));
    }
    let coverage = line(
        "coverage",
        &copy.coverage,
        SemanticRole::Status,
        StyleRef::Primary,
    );
    let trade = line("trade", &copy.trade, SemanticRole::Text, StyleRef::Primary);
    let mut below = Vec::new();
    match lead {
        AccessLead::Whole => above.extend([coverage, trade]),
        AccessLead::NoTrade => {
            above.push(coverage);
            below.push(trade);
        }
        AccessLead::State => below.extend([coverage, trade]),
    }
    if let Some(rebuild) = &copy.rebuild {
        below.push(line(
            "rebuild",
            rebuild,
            SemanticRole::Status,
            StyleRef::Danger,
        ));
    }
    if let Some(status) = &copy.retire_status {
        below.push(line(
            "retire-status",
            status,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    below.extend([
        line("grants", &copy.grants, SemanticRole::Text, StyleRef::Quiet),
        line("lasts", &copy.lasts, SemanticRole::Text, StyleRef::Quiet),
        line(
            "probe",
            &copy.probe_detail,
            SemanticRole::Status,
            StyleRef::Quiet,
        ),
        line(
            "prompt",
            &copy.prompt,
            SemanticRole::Status,
            StyleRef::Primary,
        ),
        line(
            "observation",
            &copy.observation,
            SemanticRole::Text,
            StyleRef::Quiet,
        ),
        line("route", &copy.route, SemanticRole::Text, StyleRef::Quiet),
        line(
            "identity",
            &copy.identity,
            SemanticRole::Status,
            if access.install == "installed" {
                StyleRef::Quiet
            } else {
                StyleRef::Danger
            },
        ),
        line(
            "responsible",
            &copy.responsible,
            SemanticRole::Text,
            StyleRef::Quiet,
        ),
    ]);
    for (index, service) in copy.services.iter().enumerate() {
        below.push(line(
            &format!("service/{index}"),
            service,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (index, folder) in copy.folders.iter().enumerate() {
        below.push(line(
            &format!("folder/{index}"),
            folder,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (index, repair) in copy.repair.iter().enumerate() {
        below.push(line(
            &format!("repair/{index}"),
            repair,
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    for (index, claimant) in copy.claimants.iter().enumerate() {
        below.push(line(
            &format!("claimant/{index}"),
            claimant,
            SemanticRole::Status,
            if index == 0 {
                StyleRef::Danger
            } else {
                StyleRef::Quiet
            },
        ));
    }
    for (index, retired) in copy.retired.iter().enumerate() {
        below.push(line(
            &format!("retired/{index}"),
            retired,
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    (above, below)
}

fn macos_access_kept_in_view(access: &MacosAccess, lead: AccessLead, text_width: f32) -> f32 {
    macos_access_reach(access, lead, text_width, None)
}

fn macos_access_reach(
    access: &MacosAccess,
    lead: AccessLead,
    text_width: f32,
    rows: Option<usize>,
) -> f32 {
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let heading_height = access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).1;
    let (above, _) = macos_access_rows(&macos_access_copy(access), access, lead);
    let lines = macos_access_action_rows(access, text_width);
    let all = lines.len().max(1);
    let rows = rows.map_or(all, |rows| rows.clamp(1, all));
    12.0 + heading_height
        + macos_access_visual_lines(&above, text_width) as f32 * line_height
        + button_line_set_height(&lines[..rows.min(lines.len())], MACOS_ACCESS_BUTTON_GAP)
}

fn macos_access_line_count(line: &MacosAccessLine, text_width: f32) -> usize {
    let (px, _) = crate::native_ui::text_paint_metrics(line.2, line.3);
    wrapped_copy_lines(&line.1, px, text_width).len().max(1)
}

fn macos_access_visual_lines(lines: &[MacosAccessLine], text_width: f32) -> usize {
    lines
        .iter()
        .map(|line| macos_access_line_count(line, text_width))
        .sum()
}

fn macos_access_line_node(line: MacosAccessLine, text_width: f32, line_height: f32) -> UiNode {
    let count = macos_access_line_count(&line, text_width);
    let (key, text, role, style) = line;
    if count == 1 {
        return UiNode::new(key, UiContent::Text(TextSpec { text, role, style }))
            .layout(Layout::default().height(Length::Fixed(line_height)));
    }
    let (mut node, _) = wrapped_copy_node(&key, &text, role, style, text_width, line_height, None);
    node.layout.height = Length::Fixed(count as f32 * line_height);
    node
}

fn macos_access_buttons(access: &MacosAccess) -> Vec<UiNode> {
    let mut buttons = vec![macos_access_button(
        MACOS_ACCESS_OPEN_FDA,
        "Open Privacy & Security\u{2026}",
        true,
        false,
    )];
    if access.warmup_offered {
        buttons.push(macos_access_button(
            MACOS_ACCESS_WARM_UP,
            "Ask for Folder Access Now",
            !access.warmup_live,
            access.warmup_live,
        ));
    }
    if !access.denied_folders().is_empty() {
        buttons.push(macos_access_button(
            MACOS_ACCESS_OPEN_FILES,
            "Open Files & Folders\u{2026}",
            true,
            false,
        ));
        if access.shows_reset_button() {
            buttons.push(macos_access_button(
                MACOS_ACCESS_ASK_AGAIN,
                "Ask Again",
                !access.warmup_live,
                false,
            ));
        }
    }
    if !access.retire_plan().is_empty() {
        buttons.push(macos_access_button(
            MACOS_ACCESS_TRASH,
            "Move Other Copies to the Trash",
            !access.retire_live,
            access.retire_live,
        ));
    }
    let (action, label) = if access.askpass_relay_off {
        (MACOS_ACCESS_ASKPASS_ON, "Allow sudo Password Prompts")
    } else {
        (MACOS_ACCESS_ASKPASS_OFF, "Turn Off sudo Password Prompts")
    };
    buttons.push(macos_access_button(action, label, true, false));
    buttons
}

fn macos_access_action_rows(access: &MacosAccess, text_width: f32) -> Vec<(Vec<UiNode>, f32)> {
    button_line_set(
        macos_access_buttons(access),
        text_width,
        macos_access_button_lines(),
    )
}

fn macos_access_button_lines() -> ButtonLines {
    ButtonLines {
        single: scaled_control_height(),
        least: 72.0,
        slack: 8.0,
        gap: MACOS_ACCESS_BUTTON_GAP,
    }
}

const MACOS_ACCESS_BUTTON_GAP: f32 = 8.0;

const MACOS_ACCESS_HEADING: &str = "settings/macos-access/heading";

fn macos_access_actions_height(access: &MacosAccess, text_width: f32) -> f32 {
    button_line_set_height(
        &macos_access_action_rows(access, text_width),
        MACOS_ACCESS_BUTTON_GAP,
    )
    .max(scaled_control_height())
}

fn access_card_heading(key: &str, caption: &str, text_width: f32) -> (UiNode, f32) {
    let slot = 28.0_f32.max(22.0 * settings_text_scale());
    let (mut node, lines) = caption_node(key, caption, text_width);
    let height = lines + (slot - caption_line_height()).max(0.0);
    node.layout.height = Length::Fixed(height);
    (node, height)
}

fn debugger_access_actions(copy: &MacosAccessCopy, text_width: f32) -> Option<(UiNode, f32)> {
    let button = copy.debugger.button.as_ref()?;
    let mut lines = button_line_set(
        vec![macos_access_button(
            button.action(),
            button.label(),
            button.enabled,
            button.busy,
        )],
        text_width,
        macos_access_button_lines(),
    );
    let (buttons, height) = lines.pop()?;
    Some((
        UiNode::new(
            "settings/macos-access/debugger/actions",
            UiContent::Group(GroupSpec::new("Debugger access actions")),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(MACOS_ACCESS_BUTTON_GAP),
        )
        .children(buttons),
        height,
    ))
}

fn debugger_row_lines(copy: &DebuggerRowCopy) -> Vec<(String, String, SemanticRole, StyleRef)> {
    let mut lines = vec![(
        "settings/macos-access/debugger/state".to_string(),
        copy.headline.clone(),
        SemanticRole::Status,
        StyleRef::Primary,
    )];
    lines.push((
        "settings/macos-access/debugger/kind".to_string(),
        copy.kind.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "settings/macos-access/debugger/observed".to_string(),
        copy.state.clone(),
        SemanticRole::Status,
        StyleRef::Primary,
    ));
    if let Some(status) = copy.status.clone() {
        lines.push((
            "settings/macos-access/debugger/status".to_string(),
            status,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (key, text) in [
        ("stops", &copy.stops),
        ("grants", &copy.grants),
        ("lasts", &copy.lasts),
        ("undo", &copy.undo),
        ("trade", &copy.trade),
        ("machine", &copy.cross_link),
    ] {
        lines.push((
            format!("settings/macos-access/debugger/{key}"),
            text.clone(),
            SemanticRole::Text,
            StyleRef::Quiet,
        ));
    }
    lines
}

fn macos_access_button(action: &str, label: &str, enabled: bool, busy: bool) -> UiNode {
    UiNode::new(
        action.to_string(),
        UiContent::Button(
            Control::new(ButtonSpec::new(label), ActionId::new(action.to_string()))
                .state(ControlState {
                    enabled,
                    busy,
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(scaled_control_height())),
    )
}

fn macos_access_card(access: &MacosAccess, lead: AccessLead, text_width: f32) -> UiNode {
    let line_height = 24.0_f32.max(20.0 * settings_text_scale());
    let copy = macos_access_copy(access);
    let line = |line: MacosAccessLine| macos_access_line_node(line, text_width, line_height);
    let (above, below) = macos_access_rows(&copy, access, lead);
    let mut children =
        vec![access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).0];
    children.extend(above.into_iter().map(line));
    let rows = macos_access_action_rows(access, text_width);
    let actions_height = macos_access_actions_height(access, text_width);
    children.push(
        UiNode::new(
            "settings/macos-access/actions",
            UiContent::Group(GroupSpec::new("macOS access actions")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(actions_height))
                .gap(MACOS_ACCESS_BUTTON_GAP),
        )
        .children(
            rows.into_iter()
                .enumerate()
                .map(|(index, (row, height))| {
                    UiNode::new(
                        format!("settings/macos-access/actions/row-{index}"),
                        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                    )
                    .layout(
                        Layout::row()
                            .width(Length::Fill)
                            .height(Length::Fixed(height))
                            .gap(MACOS_ACCESS_BUTTON_GAP),
                    )
                    .children(row)
                })
                .collect(),
        ),
    );
    children.extend(below.into_iter().map(line));
    children.extend(debugger_row_lines(&copy.debugger).into_iter().map(line));
    if let Some((actions, _)) = debugger_access_actions(&copy, text_width) {
        children.push(actions);
    }
    UiNode::new(
        "settings/macos-access",
        UiContent::Group(GroupSpec::new("macOS access").style(StyleRef::Secondary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(macos_access_height(access, lead, text_width)))
            .padding(Insets::all(12.0))
            .gap(0.0)
            .clipped(),
    )
    .children(children)
}

/// The Security page's "This Mac" Apply Now action id.
pub(crate) const MACHINE_APPLY: &str = "machine/apply";

fn shows_machine_status(state: &SettingsViewState, machine: &MachineProjection) -> bool {
    state.route == SettingsRoute::Security
        && state.search.trim().is_empty()
        && machine.supported
        && (machine.observed || machine.tool_missing)
}

const MACHINE_TOOL_MISSING: &str =
    "This copy of aterm has no package tool, so it can\u{2019}t change Universal Control.";

fn machine_status_node(
    packages: &PackagesProjection,
    text_width: f32,
    compact: bool,
    debugger_row: bool,
) -> (UiNode, f32) {
    let machine = &packages.machine;
    let line_height = 20.0_f32.max(18.0 * settings_text_scale());
    let gap = 4.0;
    let line = |key: &str, text: &str, role: SemanticRole, style: StyleRef, width: f32| {
        wrapped_copy_node(key, text, role, style, width, line_height, None)
    };
    let mut items = vec![if machine.tool_missing {
        line(
            "settings/machine/universal-control",
            MACHINE_TOOL_MISSING,
            SemanticRole::Status,
            StyleRef::Quiet,
            text_width,
        )
    } else {
        line(
            "settings/machine/universal-control",
            &machine.universal_control,
            SemanticRole::Status,
            StyleRef::Primary,
            text_width,
        )
    }];
    if let Some(rosetta) = machine.rosetta.as_deref().filter(|_| !machine.tool_missing) {
        items.push(line(
            "settings/machine/rosetta",
            rosetta,
            SemanticRole::Status,
            StyleRef::Primary,
            text_width,
        ));
    }
    let applying = packages.busy == Some(PackagesBusy::MachineApply);
    let live = !machine.tool_missing;
    if live && machine.refreshing {
        items.push(line(
            "settings/machine/refreshing",
            "Reading this Mac\u{2019}s settings\u{2026}",
            SemanticRole::Status,
            StyleRef::Quiet,
            text_width,
        ));
    } else if live && (applying || (!machine.next.is_empty() && !machine.nothing_to_apply)) {
        let button_width = page_button_width("Apply Now", text_width);
        let control_height = scaled_control_height();
        let mut button = UiNode::new(
            MACHINE_APPLY,
            UiContent::Button(
                Control::new(ButtonSpec::new("Apply Now"), ActionId::new(MACHINE_APPLY))
                    .state(ControlState {
                        enabled: machine.apply_enabled && !applying,
                        busy: applying,
                        ..ControlState::default()
                    })
                    .style(StyleRef::Secondary),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(button_width))
                .height(Length::Fixed(control_height)),
        );
        let beside = text_width - button_width - 8.0 >= 160.0;
        let (next, next_height) = line(
            "settings/machine/next",
            &machine.next,
            SemanticRole::Text,
            StyleRef::Quiet,
            if beside {
                text_width - button_width - 8.0
            } else {
                text_width
            },
        );
        let (layout, children, height) = if beside {
            let height = next_height.max(control_height);
            let mut next = next;
            next.layout.width = Length::Fill;
            (
                Layout::row().height(Length::Fixed(height)).gap(8.0),
                vec![next, button],
                height,
            )
        } else {
            button.layout.height = Length::Fixed(control_height);
            let height = next_height + gap + control_height;
            (
                Layout::column().height(Length::Fixed(height)).gap(gap),
                vec![next, button],
                height,
            )
        };
        items.push((
            UiNode::new(
                "settings/machine/actions",
                UiContent::Group(GroupSpec::new("This Mac actions")),
            )
            .layout(layout)
            .children(children),
            height,
        ));
    }
    if let Some(reason) = machine.reason.as_deref().filter(|_| live) {
        items.push(line(
            "settings/machine/home",
            reason,
            SemanticRole::Text,
            StyleRef::Danger,
            text_width,
        ));
    }
    if let Some(saved) = machine.saved.as_deref().filter(|_| live) {
        items.push(line(
            "settings/machine/saved",
            saved,
            SemanticRole::Text,
            StyleRef::Quiet,
            text_width,
        ));
    }
    if live && !compact {
        if let Some(change) = machine.last_change.as_deref() {
            items.push(line(
                "settings/machine/last-applied",
                change,
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
        if let Some(verdict) = machine.last_verdict.as_deref() {
            items.push(line(
                "settings/machine/verdict",
                &format!("Last apply: {verdict}"),
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
        if debugger_row {
            items.push(line(
                "settings/machine/debugger",
                "Machine-wide, like Debugger access above, but applied automatically; \
                 Debugger access changes only when you say yes.",
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
    }
    let height = items.iter().map(|(_, height)| height).sum::<f32>()
        + items.len().saturating_sub(1) as f32 * gap;
    (
        UiNode::new(
            "settings/machine",
            UiContent::Group(GroupSpec::new("This Mac status")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(gap),
        )
        .children(items.into_iter().map(|(node, _)| node).collect()),
        height,
    )
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct SegmentOption {
    value: String,
    label: String,
}

const COMPACT_INLINE_CHOICE_MIN: f32 = 250.0;

fn segmented_choices(field: &EditField, value: &str) -> Option<(Vec<SegmentOption>, usize)> {
    if !matches!(field.kind, EditKind::Enum { .. })
        || matches!(
            field.key,
            prefs::EDIT_CURSOR_TRAIL_STYLE
                | prefs::EDIT_TRAIL_SOUND_STYLE
                | prefs::EDIT_DISPLAY_FONT
        )
    {
        return None;
    }
    let options = choices_for_field(field, &crate::app_config::ThemeCatalog::default())?;
    if !(2..=3).contains(&options.len()) {
        return None;
    }
    let segments = options
        .into_iter()
        .map(|value| SegmentOption {
            label: segment_label(field.key, &value),
            value,
        })
        .collect::<Vec<_>>();
    let value = if field.seed.is_some() {
        value.trim()
    } else {
        unset_choice_value(field, value)
    };
    let selected = segments
        .iter()
        .position(|segment| segment.value.eq_ignore_ascii_case(value))?;
    Some((segments, selected))
}

fn segment_label(key: &str, value: &str) -> String {
    match (key, value) {
        (prefs::EDIT_MOTION, "full") => "Animate".to_string(),
        (prefs::EDIT_MOTION, "reduced") => "Reduce".to_string(),
        (prefs::EDIT_WINDOW_THEME, "auto") => "Auto".to_string(),
        (prefs::EDIT_WINDOW_THEME, _) => setting_choice_label(key, value),
        _ => choice_label(value),
    }
}

fn segmented_natural_width(segments: &[SegmentOption]) -> f32 {
    let widest = segments
        .iter()
        .map(|segment| crate::native_ui::native_button_label_width(&segment.label) + 24.0)
        .fold(0.0_f32, f32::max);
    widest * segments.len() as f32 + 2.0 * segments.len().saturating_sub(1) as f32
}

fn segments_hold_their_labels(field: &EditField, text_width: f32) -> bool {
    let Some((segments, _)) = segmented_choices(field, SettingsState::display_value(field)) else {
        return true;
    };
    let count = segments.len() as f32;
    let share = (text_width - 2.0 * (count - 1.0)) / count;
    segments.iter().all(|segment| {
        let spec = ButtonSpec::new(segment.label.as_str());
        crate::native_ui::native_button_label_width(&segment.label)
            <= crate::native_ui::text_button_label_room(&spec, share)
    })
}

fn segmented_width_need(field: &EditField) -> Option<f32> {
    segmented_choices(field, SettingsState::display_value(field))
        .map(|(segments, _)| segmented_natural_width(&segments))
}

fn segments_line_room(row: &UiNode, key: &str, text_width: f32) -> f32 {
    let segments_key = format!("settings/segments/{key}");
    row.children
        .iter()
        .find(|line| {
            line.children
                .iter()
                .any(|child| child.key.as_str() == segments_key)
        })
        .map_or(text_width, |line| {
            let others = line
                .children
                .iter()
                .filter(|child| child.key.as_str() != segments_key)
                .map(|child| match child.layout.width {
                    Length::Fixed(width) => width + line.layout.gap,
                    _ => 0.0,
                })
                .sum::<f32>();
            (text_width - others).max(0.0)
        })
}

fn wrap_segments(row: &mut UiNode, key: &str, text_width: f32) {
    let segments_key = format!("settings/segments/{key}");
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let segment_height = 44.0_f32.max((px * 1.25 + 12.0).ceil());
    let text_width = segments_line_room(row, key, text_width);
    let Some(group) = find(row, &segments_key) else {
        return;
    };
    let count = group.children.len();
    if count < 2 {
        return;
    }
    let widest = group
        .children
        .iter()
        .filter_map(|segment| match &segment.content {
            UiContent::Button(button) => button.spec.visual_label.as_deref(),
            _ => None,
        })
        .map(|label| crate::native_ui::native_button_label_width(label) + 24.0)
        .fold(0.0_f32, f32::max);
    let per_line = (((text_width + 2.0) / (widest + 2.0)).floor() as usize).clamp(1, count);
    let width = ((text_width - 2.0 * (per_line - 1) as f32) / per_line as f32)
        .max(widest)
        .min(text_width);
    let segments = std::mem::take(&mut group.children);
    let mut lines = Vec::new();
    let mut column = 0.0;
    let mut segments = segments.into_iter().peekable();
    while segments.peek().is_some() {
        let mut line_height = segment_height;
        let line: Vec<UiNode> = segments
            .by_ref()
            .take(per_line)
            .map(|mut segment| {
                segment.layout.width = Length::Fixed(width);
                segment.layout.height = Length::Fill;
                if width < widest
                    && let UiContent::Button(button) = &mut segment.content
                    && let Some(label) = button.spec.visual_label.clone()
                {
                    let (words, count) = button_words_in(&button.spec, &label, &[], width);
                    button.spec.visual_label = Some(words);
                    line_height = line_height.max(
                        crate::native_ui::native_button_height_for_lines(count, segment_height),
                    );
                }
                segment
            })
            .collect();
        column += line_height + if lines.is_empty() { 0.0 } else { 2.0 };
        lines.push(
            UiNode::new(
                format!("{segments_key}/line-{}", lines.len()),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(line_height))
                    .gap(2.0),
            )
            .children(line),
        );
    }
    group.layout = Layout::column()
        .width(Length::Fill)
        .height(Length::Fill)
        .gap(2.0);
    group.children = lines;
    let label = row.children.first().map_or(0.0, fixed_height);
    row.layout.height = Length::Fixed(label + 4.0 + column);
}

fn segment_focus_key(key: &str, index: usize, selected: usize) -> UiKey {
    UiKey::new(if index == selected {
        format!("settings/control/{key}")
    } else {
        format!("settings/segment/{key}/{index}")
    })
}

fn segmented_choice_node(
    field: &EditField,
    segments: &[SegmentOption],
    selected: usize,
    value: &str,
    segment_facts: &[String],
    description: &str,
    state: ControlState,
) -> UiNode {
    let children = segments
        .iter()
        .enumerate()
        .map(|(index, segment)| {
            let semantic_facts = segment_facts.get(index).map_or("", String::as_str);
            let saved = index == selected;
            let (key, action) = if saved {
                (
                    format!("settings/control/{}", field.key),
                    format!("settings/set/{}", field.key),
                )
            } else {
                let key = format!("settings/segment/{}/{index}", field.key);
                (key.clone(), key)
            };
            let mut control = Control::new(
                ButtonSpec {
                    label: format!("{}: {}{semantic_facts}", field.label, segment.label),
                    visual_label: Some(segment.label.clone()),
                    visual_icon: None,
                    trailing_icon: None,
                    description: Some(description.to_string()),
                    badge: false,
                    swatches: Vec::new(),
                    chip: None,
                    chevron_row: None,
                },
                ActionId::new(action),
            )
            .state(ControlState {
                selected: saved,
                ..state
            })
            .style(StyleRef::Navigation);
            if saved {
                let words = if value.trim().ends_with(" (default)") {
                    format!("{} (default)", segment.label)
                } else {
                    segment.label.clone()
                };
                control = control.value(SemanticValue::Text(words));
            }
            UiNode::new(key, UiContent::Button(control))
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        })
        .collect();
    UiNode::new(
        format!("settings/segments/{}", field.key),
        UiContent::Group(GroupSpec {
            label: Some(field.label.to_string()),
            role: SemanticRole::Group,
            style: StyleRef::Secondary,
        }),
    )
    .layout(Layout::row().gap(2.0))
    .children(children)
    .segmented()
}

fn row_footnote(state: &SettingsViewState, key: &str) -> Option<std::borrow::Cow<'static, str>> {
    if matches!(
        key,
        prefs::EDIT_CURSOR_TRAIL_COLOR | prefs::EDIT_CURSOR_TRAIL_ACCENT
    ) {
        return Some(std::borrow::Cow::Owned(prefs::trail_color_note(
            &spelled_trail_value(state),
            configured_cursor_is_block(state),
            state.is_explicit(prefs::EDIT_CURSOR_COLOR),
        )));
    }
    prefs::footnote_of(key).map(std::borrow::Cow::Borrowed)
}

fn modified_default_words(state: &SettingsViewState, key: &str) -> Option<String> {
    let style = || crate::app_config::resolve_trail_style(&top_authored_trail_value(state));
    match key {
        prefs::EDIT_CURSOR_TRAIL_COLOR | prefs::EDIT_CURSOR_TRAIL_ACCENT => {
            Some(prefs::trail_color_default_words(
                key,
                &spelled_trail_value(state),
                prefs::trail_color_setting(
                    state.raw_value(prefs::EDIT_CURSOR_TRAIL_COLOR).as_deref(),
                ),
                state.is_explicit(prefs::EDIT_CURSOR_COLOR),
            ))
        }
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS => {
            let value = crate::app_config::Config::bloom_radius_style_default(style());
            let shown = value.to_string();
            Some(prefs::numeric_reading(key, f64::from(value), &shown).unwrap_or(shown))
        }
        _ => default_value_label(key).map(str::to_string),
    }
}

fn default_value_label(key: &str) -> Option<&'static str> {
    static DEFAULTS: std::sync::OnceLock<Vec<(&'static str, String)>> = std::sync::OnceLock::new();
    DEFAULTS
        .get_or_init(|| {
            prefs::editable_fields(&crate::app_config::Config::default())
                .into_iter()
                .filter_map(|field| {
                    let shown = SettingsState::display_value(&field);
                    let shown = shown.strip_suffix(" (default)").unwrap_or(shown).trim();
                    let label = match field.kind {
                        EditKind::Bool => match shown {
                            "true" => "On".to_string(),
                            "false" => "Off".to_string(),
                            _ => return None,
                        },
                        EditKind::Enum { .. } | EditKind::Theme => {
                            if segmented_choices(&field, shown).is_some() {
                                segment_label(field.key, shown)
                            } else {
                                setting_choice_label(field.key, shown)
                            }
                        }
                        EditKind::Float | EditKind::Integer => {
                            let number = shown.split_whitespace().next().unwrap_or_default();
                            number
                                .parse::<f64>()
                                .ok()
                                .filter(|value| value.is_finite())
                                .and_then(|value| prefs::numeric_reading(field.key, value, number))
                                .unwrap_or_else(|| shown.to_string())
                        }
                        _ => shown.to_string(),
                    };
                    (!label.is_empty()).then_some((field.key, label))
                })
                .collect()
        })
        .iter()
        .find(|(candidate, _)| *candidate == key)
        .map(|(_, label)| label.as_str())
}

#[allow(clippy::too_many_arguments)]
fn finish_setting_row_sharing(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
    text_width: f32,
    note: Option<&str>,
    shared_reason: Option<&str>,
) -> UiNode {
    finished_setting_row(
        state,
        index,
        field,
        modified_only,
        width,
        text_width,
        note.map(prefs::RowNote::Own),
        shared_reason,
        None,
    )
    .whole()
}

fn finish_setting_row_narrowed(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    width: SettingsWidth,
    text_width: f32,
    note: Option<&str>,
    control_width: f32,
) -> UiNode {
    finished_setting_row(
        state,
        index,
        field,
        false,
        width,
        text_width,
        note.map(prefs::RowNote::Own),
        None,
        Some(control_width),
    )
    .whole()
}

#[allow(clippy::too_many_arguments)]
fn finished_setting_row(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
    text_width: f32,
    note: Option<prefs::RowNote<'_>>,
    shared_reason: Option<&str>,
    control_width: Option<f32>,
) -> FinishedRow {
    let finished = finished_setting_row_as(
        state,
        index,
        field,
        modified_only,
        (width, text_width),
        note,
        shared_reason,
        control_width,
        false,
    );
    match rows_too_tall_to_stack() {
        Some(room) if !finished.stacked && fixed_height(&finished.split(room).0) > room + 0.01 => {
            finished_setting_row_as(
                state,
                index,
                field,
                modified_only,
                (width, text_width),
                note,
                shared_reason,
                control_width,
                true,
            )
        }
        _ => finished,
    }
}

#[allow(clippy::too_many_arguments)]
fn finished_setting_row_as(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    (width, text_width): (SettingsWidth, f32),
    note: Option<prefs::RowNote<'_>>,
    shared_reason: Option<&str>,
    control_width: Option<f32>,
    stack: bool,
) -> FinishedRow {
    let display_face = modified_only && field.key == prefs::EDIT_DISPLAY_FONT;
    let segment_need = segmented_width_need(field);
    let build = |inline_control: Option<f32>, stack: bool| -> (SettingRowParts, bool) {
        let inline = inline_control.is_some();
        let row_width = if display_face || stack {
            SettingsWidth::Compact
        } else if inline {
            SettingsWidth::Medium
        } else {
            width
        };
        let mut parts = setting_row_parts(state, index, field, modified_only, row_width);
        if let Some(reason) = shared_reason {
            parts.tags.facts.retain(|tag| tag != reason);
            parts.worst.facts.retain(|tag| tag != reason);
        }
        let mut row = parts.row;
        let stacked = row_width == SettingsWidth::Compact;
        if let Some(control_width) = inline_control {
            row.layout.height = Length::Fixed(compact_inline_row_height());
            if let Some(control) = row.children.get_mut(1) {
                control.layout.width = Length::Fixed(control_width);
            }
        }
        if let Some(narrow) = control_width.filter(|_| !stacked && !inline)
            && let Some(control) = row.children.get_mut(1)
            && let Length::Fixed(current) = control.layout.width
        {
            control.layout.width =
                Length::Fixed(current.min(narrow).max(segment_need.unwrap_or_default()));
        }
        if stacked
            && segment_need
                .is_some_and(|need| need > segments_line_room(&row, field.key, text_width) + 0.01)
        {
            wrap_segments(&mut row, field.key, text_width);
        }
        if display_face && row.children.len() > 1 {
            let faces = display_face_rows(state, width, text_width);
            let faces_height: f32 = faces.iter().map(|(_, height)| height).sum();
            let label_height = row.children.first().map_or(0.0, fixed_height);
            row.children[1] = UiNode::new(
                format!("settings/control/{}", field.key),
                UiContent::Group(GroupSpec {
                    label: Some("Display faces".to_string()),
                    role: SemanticRole::Group,
                    style: StyleRef::Plain,
                }),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(faces_height)),
            )
            .children(faces.into_iter().map(|(node, _)| node).collect());
            row.layout.height = Length::Fixed(label_height + 4.0 + faces_height);
        }
        page_owned_control_form(
            state,
            field,
            modified_only,
            (width, inline, text_width),
            &mut row,
        );
        (SettingRowParts { row, ..parts }, stacked)
    };
    let mut inline_control = (width == SettingsWidth::Compact && !display_face && !stack)
        .then(|| compact_inline_choice_width(field, segment_need, text_width))
        .flatten();
    let (mut parts, mut stacked) = build(inline_control, stack);
    let floor = |parts: &SettingRowParts| one_line_name_floor(&parts.name);
    if inline_control.is_some() {
        if one_line_row_extras(&parts.row) > 0.0
            && one_line_label_room(&parts.row, text_width) + 0.01 < floor(&parts)
        {
            let beside = one_line_row_extras(&parts.row);
            inline_control = compact_inline_choice_width(field, segment_need, text_width - beside);
            (parts, stacked) = build(inline_control, false);
        }
        if inline_control.is_some()
            && one_line_label_room(&parts.row, text_width) + 0.01 < floor(&parts)
        {
            (parts, stacked) = build(None, false);
        }
    } else if !stacked {
        let short = floor(&parts) - one_line_label_room(&parts.row, text_width);
        if short > 0.01 {
            let least = match field.kind {
                EditKind::Bool => f32::INFINITY,
                EditKind::Enum { .. } | EditKind::Theme => {
                    COMPACT_INLINE_CHOICE_MIN.max(segment_need.unwrap_or_default())
                }
                _ => 200.0,
            };
            match parts
                .row
                .children
                .get_mut(1)
                .map(|control| (control.layout.width, control))
            {
                Some((Length::Fixed(current), control)) if current - short + 0.01 >= least => {
                    control.layout.width = Length::Fixed(current - short);
                }
                _ => (parts, stacked) = build(None, true),
            }
        }
    }
    let SettingRowParts {
        mut row,
        name,
        tags,
        worst,
        timing,
    } = parts;
    if stacked {
        seat_stacked_reset(&mut row, &name, text_width);
    }
    fit_row_button_words(&mut row, &name, text_width, stacked);
    let unset = matches!(
        field.kind,
        EditKind::Text | EditKind::Color | EditKind::Float | EditKind::Integer
    )
    .then(|| unset_field_words(state, field))
    .flatten();
    fit_row_field_placeholder(
        &mut row,
        (&name, text_width, stacked),
        unset
            .as_deref()
            .map(|words| (words, field.kind == EditKind::Color)),
        field.seed.as_deref(),
    );
    let label_width = row_label_room(&row, stacked, text_width);
    FinishedRow {
        row,
        key: field.key,
        name,
        tags,
        worst,
        timing,
        note: prefs::RowNote::own(note).map(str::to_string),
        shared_note: prefs::RowNote::shared(note).map(str::to_string),
        error: state.field_errors.get(field.key).cloned(),
        label_width,
        stacked,
        text_width,
        facts_below: None,
        default_chip: modified_only
            .then(|| color_picker::default_color_chip(state, field))
            .flatten(),
    }
}

fn switch_tail(width: SettingsWidth, text_width: f32) -> Option<f32> {
    if width != SettingsWidth::Compact || compact_row_inline(&EditKind::Bool, text_width, true) {
        return Some(12.0);
    }
    stacked_switch_line_holds(
        switch_control_width(text_width).min(crate::native_ui::switch_least_width()),
        reset_slot_width(),
        text_width,
    )
    .then_some(STACKED_CONTROL_GAP)
}

fn switch_control_width(text_width: f32) -> f32 {
    (104.0 * settings_text_scale().min(1.4)).min(text_width.max(0.0))
}

fn stacked_switch_line_holds(switch_width: f32, reset_width: f32, text_width: f32) -> bool {
    switch_width + reset_width + 2.0 * STACKED_CONTROL_GAP <= text_width + 0.01
}

const STACKED_CONTROL_GAP: f32 = 6.0;

fn seat_stacked_reset(row: &mut UiNode, name: &str, text_width: f32) {
    seat_stacked_switch_reset(row, text_width);
    let Some(line) = row
        .children
        .first()
        .filter(|line| line.key.as_str().starts_with("settings/label-line/"))
    else {
        return;
    };
    let room = one_line_label_room(line, text_width);
    if pieces_fit(name, room, &row_label_width) {
        let beside = row_name_lines(name, room).len();
        let alone = row_name_lines(name, text_width).len();
        let cost = beside.saturating_sub(alone) as f32 * row_detail_line_height();
        if cost <= fixed_height(line) + row.layout.gap + 0.01 {
            return;
        }
    }
    let mut line = row.children.remove(0);
    let key = line
        .key
        .as_str()
        .trim_start_matches("settings/label-line/")
        .to_string();
    let label = line.children.remove(0);
    let height = fixed_height(&line);
    let spacer = UiNode::new(
        format!("settings/reset-line/{key}/spacer"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill));
    let mut trailing = vec![spacer];
    trailing.extend(line.children.into_iter().map(|mut reset| {
        if let Length::Fixed(width) = reset.layout.width {
            reset.layout.width = Length::Fixed(width.min(text_width));
        }
        reset
    }));
    let resets: f32 = trailing.iter().skip(1).map(fixed_width).sum();
    if resets + STACKED_CONTROL_GAP * (trailing.len() - 1) as f32 > text_width + 0.01 {
        trailing.remove(0);
    }
    row.children.insert(0, label);
    row.children.push(
        UiNode::new(
            format!("settings/reset-line/{key}"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(STACKED_CONTROL_GAP),
        )
        .children(trailing),
    );
    row.layout.height = Length::Fixed(fixed_height(row) + row.layout.gap + height);
}

fn seat_stacked_switch_reset(row: &mut UiNode, text_width: f32) {
    let Some(controls) = row
        .children
        .get_mut(1)
        .filter(|controls| controls.key.as_str().contains("/controls/"))
    else {
        return;
    };
    let line_width = |controls: &UiNode| -> f32 {
        let fixed: f32 = controls
            .children
            .iter()
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width,
                _ => 0.0,
            })
            .sum();
        fixed + controls.layout.gap * controls.children.len().saturating_sub(1) as f32
    };
    let reset_at = controls
        .children
        .iter()
        .position(|child| is_reset_place(child.key.as_str()));
    let least = crate::native_ui::switch_least_width();
    let least_line = line_width(controls)
        - controls
            .children
            .iter()
            .filter(|child| matches!(child.content, UiContent::Switch(_)))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => (width - least).max(0.0),
                _ => 0.0,
            })
            .sum::<f32>();
    let moved = match reset_at {
        Some(at) if least_line > text_width + 0.01 => Some(controls.children.remove(at)),
        _ => None,
    };
    let others = line_width(controls)
        - controls
            .children
            .iter()
            .filter(|child| matches!(child.content, UiContent::Switch(_)))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width,
                _ => 0.0,
            })
            .sum::<f32>();
    for control in &mut controls.children {
        if let (UiContent::Switch(_), Length::Fixed(width)) =
            (&control.content, control.layout.width)
        {
            control.layout.width = Length::Fixed(
                width
                    .min(switch_control_width(text_width - others))
                    .max(0.0),
            );
        }
    }
    let Some(reset) = moved else {
        return;
    };
    let label = row.children.remove(0);
    let height = fixed_height(&label);
    let key = label
        .key
        .as_str()
        .trim_start_matches("settings/label/")
        .to_string();
    row.children.insert(
        0,
        UiNode::new(
            format!("settings/label-line/{key}"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(6.0),
        )
        .children(vec![label, reset]),
    );
}

fn is_reset_place(key: &str) -> bool {
    key.starts_with("settings/reset/")
        || key.starts_with("settings/reset-slot/")
        || key.starts_with("settings/draft-discard/")
}

fn one_line_row_extras(row: &UiNode) -> f32 {
    row.children
        .iter()
        .skip(2)
        .filter(|child| !is_reset_place(child.key.as_str()))
        .map(|child| match child.layout.width {
            Length::Fixed(width) => width + row.layout.gap,
            _ => 0.0,
        })
        .sum()
}

fn row_label_room(row: &UiNode, stacked: bool, text_width: f32) -> f32 {
    if stacked {
        row.children
            .first()
            .filter(|line| line.key.as_str().starts_with("settings/label-line/"))
            .map_or(text_width, |line| one_line_label_room(line, text_width))
    } else {
        one_line_label_room(row, text_width)
    }
}

struct FinishedRow {
    row: UiNode,
    key: &'static str,
    name: String,
    tags: RowTags,
    worst: RowTags,
    timing: Option<&'static str>,
    note: Option<String>,
    shared_note: Option<String>,
    error: Option<String>,
    label_width: f32,
    stacked: bool,
    text_width: f32,
    facts_below: Option<bool>,
    default_chip: Option<[u8; 3]>,
}

impl FinishedRow {
    fn facts_fit_inline(&self) -> bool {
        row_tag_fit(&self.name, &self.worst, self.label_room()).facts
    }

    fn label_room(&self) -> f32 {
        self.label_width
            - self.default_chip.map_or(0.0, |_| {
                crate::native_ui::TEXT_FIELD_SWATCH_SIZE + crate::native_ui::TEXT_FIELD_SWATCH_GAP
            })
    }

    fn placed(&self) -> (UiNode, Vec<String>, Option<String>) {
        let below = self.facts_below.unwrap_or_else(|| !self.facts_fit_inline());
        let mut row = self.row.clone();
        let placement = lay_out_row_label(
            &mut row,
            &self.name,
            &self.tags,
            &self.worst,
            self.label_room(),
            self.stacked,
            below,
        );
        let mut chip_words = None;
        if let Some(color) = self.default_chip {
            if placement.below.is_empty() {
                set_row_label_chip(&mut row, self.key, color, self.label_width);
            } else if self.timing.is_none() {
                chip_words = placement.below.last().cloned();
            }
        }
        let detail = row_second_line(
            &placement,
            self.timing,
            self.note.as_deref(),
            self.text_width,
        );
        (row, detail, chip_words)
    }

    fn whole(&self) -> UiNode {
        let (row, detail, chip_words) = self.placed();
        let mut row = with_row_detail(row, self.key, &detail, self.stacked);
        if let (Some(color), Some(words)) = (self.default_chip, chip_words) {
            set_detail_chip(&mut row, self.key, &words, color, self.text_width);
        }
        self.with_error(row)
    }

    fn split(&self, most: f32) -> (UiNode, Vec<(UiNode, f32)>) {
        let (row, detail, _) = self.placed();
        let blocks = if detail.is_empty() {
            Vec::new()
        } else {
            row_note_blocks(self.key, &detail, most)
        };
        (self.with_error(row), blocks)
    }

    fn with_error(&self, row: UiNode) -> UiNode {
        match self.error.as_deref() {
            Some(message) => with_row_error(row, self.key, message, self.text_width),
            None => row,
        }
    }

    fn shared_note_stops(&self, most: Option<f32>) -> Vec<(UiNode, f32)> {
        self.shared_note
            .as_deref()
            .map(|note| shared_note_blocks(self.key, note, self.text_width, most))
            .unwrap_or_default()
    }
}

const SHARED_NOTE_GAP: f32 = 4.0;

fn shared_note_blocks(
    key: &str,
    note: &str,
    text_width: f32,
    most: Option<f32>,
) -> Vec<(UiNode, f32)> {
    let line_height = group_footnote_line_height();
    let lines = group_footnote_lines(note, text_width);
    let pitch = line_height + 2.0;
    let per_block = most.map_or(lines.len(), |most| {
        (((most - SHARED_NOTE_GAP + 2.0) / pitch).floor() as usize).max(1)
    });
    lines
        .chunks(per_block.max(1))
        .enumerate()
        .map(|(part, chunk)| {
            let height = SHARED_NOTE_GAP + chunk.len() as f32 * pitch - 2.0;
            let node = UiNode::new(
                if part == 0 {
                    format!("settings/shared-note/{key}")
                } else {
                    format!("settings/shared-note/{key}/part-{part}")
                },
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .padding(Insets {
                        top: SHARED_NOTE_GAP,
                        right: 0.0,
                        bottom: 0.0,
                        left: 0.0,
                    })
                    .gap(2.0),
            )
            .children(
                chunk
                    .iter()
                    .enumerate()
                    .map(|(offset, line)| {
                        UiNode::new(
                            format!(
                                "settings/shared-note/{key}/line-{}",
                                part * per_block + offset
                            ),
                            UiContent::Text(TextSpec {
                                text: line.clone(),
                                role: SemanticRole::Status,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(line_height)))
                        .paint_only()
                    })
                    .collect(),
            );
            (node, height)
        })
        .collect()
}

fn place_box_facts(rows: &mut [FinishedRow]) {
    let below = !rows.iter().all(FinishedRow::facts_fit_inline);
    for row in rows {
        row.facts_below = Some(below);
    }
}

fn agree_box_default_marks(rows: &mut [FinishedRow]) {
    let dropped = rows
        .iter()
        .any(|row| row_default_marks(&row.row).contains(&false));
    if dropped {
        for row in rows {
            drop_row_default_marks(&mut row.row);
        }
    }
}

fn row_default_marks(node: &UiNode) -> Vec<bool> {
    let mut marks = Vec::new();
    if let UiContent::TextField(field) = &node.content
        && let SemanticValue::Text(value) = &field.value
        && value.ends_with(" (default)")
        && field.spec.input.is_none()
    {
        marks.push(
            field
                .spec
                .placeholder
                .as_deref()
                .is_some_and(|painted| painted.ends_with(" (default)")),
        );
    }
    for child in &node.children {
        marks.extend(row_default_marks(child));
    }
    marks
}

fn drop_row_default_marks(node: &mut UiNode) {
    if let UiContent::TextField(field) = &mut node.content
        && let Some(painted) = field.spec.placeholder.as_mut()
        && let Some(plain) = painted.strip_suffix(" (default)")
    {
        *painted = plain.to_string();
    }
    for child in &mut node.children {
        drop_row_default_marks(child);
    }
}

fn row_second_line(
    placement: &RowTagPlacement,
    timing: Option<&str>,
    note: Option<&str>,
    text_width: f32,
) -> Vec<String> {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    let with_timing = |tags: &[String]| -> Vec<String> {
        tags.iter()
            .cloned()
            .chain(timing.map(str::to_string))
            .collect()
    };
    let mut lines = fact_lines(&with_timing(&placement.below), px, text_width);
    let reserved = fact_lines(&with_timing(&placement.worst_below), px, text_width).len();
    if lines.len() < reserved {
        lines.resize(reserved, String::new());
    }
    if let Some(note) = note {
        lines.extend(wrapped_copy_lines(note, px, text_width));
    }
    lines
}

const COMPACT_INLINE_LABEL_MIN: f32 = 170.0;

fn one_line_name_floor(name: &str) -> f32 {
    COMPACT_INLINE_LABEL_MIN.min(row_label_width(name).ceil())
}

fn compact_inline_choice_width(
    field: &EditField,
    segment_need: Option<f32>,
    text_width: f32,
) -> Option<f32> {
    let Some(need) = segment_need else {
        return compact_inline_control_width(&field.kind, text_width);
    };
    let scale = settings_text_scale();
    if large_text_rows_stack() {
        return None;
    }
    let spare = one_line_label_measure(0.0, text_width, true) - COMPACT_INLINE_LABEL_MIN;
    let most = need.max(270.0 * scale.min(1.25));
    (spare >= need).then(|| spare.min(most))
}

fn compact_inline_control_width(kind: &EditKind, text_width: f32) -> Option<f32> {
    let scale = settings_text_scale();
    if large_text_rows_stack() {
        return None;
    }
    let (least, most) = match kind {
        EditKind::Bool => (104.0 * scale.min(1.4), 104.0 * scale.min(1.4)),
        EditKind::Enum { .. } | EditKind::Theme => {
            (COMPACT_INLINE_CHOICE_MIN, 270.0 * scale.min(1.25))
        }
        _ => (200.0, 300.0 * scale.min(1.25)),
    };
    let spare = one_line_label_measure(0.0, text_width, true) - COMPACT_INLINE_LABEL_MIN;
    (spare >= least).then(|| spare.min(most))
}

fn one_line_label_room(row: &UiNode, text_width: f32) -> f32 {
    let fixed: f32 = row
        .children
        .iter()
        .skip(1)
        .map(|child| match child.layout.width {
            Length::Fixed(width) => width,
            _ => 0.0,
        })
        .sum();
    (text_width - fixed - row.layout.gap * row.children.len().saturating_sub(1) as f32).max(0.0)
}

fn shared_inactive_reason(state: &SettingsViewState, keys: &[&str]) -> Option<(String, String)> {
    if keys.len() < 2 {
        return None;
    }
    let reasons: Vec<Option<(String, String)>> = keys
        .iter()
        .map(|key| {
            setting_effect_projection(
                state,
                None,
                key,
                SettingsAvailability::for_state(state),
                state.presented_motion.get(),
            )
            .notes
            .into_iter()
            .find(|note| note.kind == EffectNoteKind::Inactive)
            .map(|note| {
                let words = note.visual.clone();
                let reason = note
                    .feedback
                    .strip_prefix("Currently inactive: ")
                    .map_or_else(|| words.clone(), str::to_string);
                (words, reason)
            })
        })
        .collect();
    let (words, reason) = reasons.first()?.clone()?;
    reasons
        .iter()
        .all(|other| other.as_ref().is_some_and(|other| other.0 == words))
        .then(|| {
            let sentence = match reason.strip_suffix(" does not use it") {
                Some(name) => format!("{name} does not use these."),
                None => format!("These are inactive for now: {reason}."),
            };
            (words, sentence)
        })
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RowTags {
    state: Vec<String>,
    facts: Vec<String>,
}

impl RowTags {
    fn iter(&self) -> impl Iterator<Item = &String> {
        self.state.iter().chain(&self.facts)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RowTagFit {
    state: bool,
    facts: bool,
}

fn row_name_lines(name: &str, label_width: f32) -> Vec<String> {
    use crate::tray_raster::{LinesRule, kept_lines};
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    kept_lines(LinesRule::RowName, face, name, px, label_width, || {
        wrap_to_box(name, label_width, &row_label_width)
    })
}

fn with_tags<'a>(base: &str, tags: impl IntoIterator<Item = &'a String>) -> String {
    let mut line = base.to_string();
    for tag in tags {
        line.push_str(FACT_SEPARATOR);
        line.push_str(tag);
    }
    line
}

fn row_label_fits(text: &str, label_width: f32) -> bool {
    row_label_width(text) <= label_width
}

fn row_label_width(text: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    crate::tray_raster::ui_text_width_for(face, text, px)
}

fn row_tag_fit(name: &str, worst: &RowTags, label_width: f32) -> RowTagFit {
    let lines = row_name_lines(name, label_width);
    let last = lines.last().map_or(name, String::as_str);
    let state =
        worst.state.is_empty() || row_label_fits(&with_tags(last, &worst.state), label_width);
    let facts = worst.facts.is_empty()
        || (state && row_label_fits(&with_tags(last, worst.iter()), label_width));
    RowTagFit { state, facts }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RowTagPlacement {
    lines: Vec<String>,
    below: Vec<String>,
    worst_below: Vec<String>,
}

fn place_row_tags(
    name: &str,
    tags: &RowTags,
    worst: &RowTags,
    label_width: f32,
    facts_below: bool,
) -> RowTagPlacement {
    let fit = row_tag_fit(name, worst, label_width);
    let facts_inline = fit.facts && !facts_below;
    let mut lines = row_name_lines(name, label_width);
    let pick = |tags: &RowTags, inline: bool| -> Vec<String> {
        let mut picked = Vec::new();
        if fit.state == inline {
            picked.extend(tags.state.iter().cloned());
        }
        if facts_inline == inline {
            picked.extend(tags.facts.iter().cloned());
        }
        picked
    };
    if let Some(last) = lines.last_mut() {
        *last = with_tags(last, &pick(tags, true));
    }
    RowTagPlacement {
        lines,
        below: pick(tags, false),
        worst_below: pick(worst, false),
    }
}

fn lay_out_row_label(
    row: &mut UiNode,
    name: &str,
    tags: &RowTags,
    worst: &RowTags,
    label_width: f32,
    stacked: bool,
    facts_below: bool,
) -> RowTagPlacement {
    let placement = place_row_tags(name, tags, worst, label_width, facts_below);
    set_row_label_lines(row, placement.lines.clone(), stacked);
    placement
}

fn chip_after_line(
    line: &mut UiNode,
    chip_key: String,
    color: [u8; 3],
    style: StyleRef,
    room: f32,
) {
    let UiContent::Text(text) = &line.content else {
        return;
    };
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, style);
    let chip = crate::native_ui::TEXT_FIELD_SWATCH_SIZE + crate::native_ui::TEXT_FIELD_SWATCH_GAP;
    let words = crate::tray_raster::ui_text_width_for(face, &text.text, px).ceil() + 1.0;
    if words + chip > room + 0.01 {
        return;
    }
    let height = line.layout.height;
    let mut words_node = line.clone();
    words_node.layout.width = Length::Fixed(words);
    *line = UiNode::new(
        format!("{}/row", line.key.as_str()),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::row().width(Length::Fill).height(height))
    .children(vec![
        words_node,
        UiNode::new(
            chip_key,
            UiContent::Custom(AuditedCustomNode {
                audit_id: crate::native_ui::COLOR_CHIP_AUDIT,
                role: SemanticRole::Group,
                label: String::new(),
                value: Some(format!("#{:02X}{:02X}{:02X}", color[0], color[1], color[2])),
                action: None,
                focusable: false,
                focused: false,
                focus_visible: false,
            }),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(chip))
                .height(Length::Fill),
        )
        .paint_only(),
    ])
    .paint_only();
}

fn set_row_label_chip(row: &mut UiNode, key: &str, color: [u8; 3], label_width: f32) {
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let Some(line) = find(row, &format!("settings/label/{key}/visual"))
        .and_then(|visual| visual.children.last_mut())
    else {
        return;
    };
    chip_after_line(
        line,
        format!("settings/label/{key}/chip"),
        color,
        StyleRef::Primary,
        label_width,
    );
}

fn set_detail_chip(row: &mut UiNode, key: &str, tag: &str, color: [u8; 3], text_width: f32) {
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let Some(detail) = find(row, &format!("settings/detail/{key}")) else {
        return;
    };
    let last_word = tag.split_whitespace().last().unwrap_or(tag);
    let Some(line) = detail.children.iter_mut().find(|line| {
        matches!(&line.content, UiContent::Text(text) if text.text.trim_end().ends_with(last_word))
    }) else {
        return;
    };
    chip_after_line(
        line,
        format!("settings/detail/{key}/chip"),
        color,
        StyleRef::Quiet,
        text_width,
    );
}

fn row_label_visual(label_key: &str, lines: Vec<String>) -> UiNode {
    let single = lines.len() <= 1;
    let line_height = row_detail_line_height();
    let height = |count: usize| {
        if single {
            Length::Fill
        } else {
            Length::Fixed(count as f32 * line_height)
        }
    };
    let count = lines.len();
    UiNode::new(
        format!("{label_key}/visual"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().width(Length::Fill).height(height(count)))
    .children(
        lines
            .into_iter()
            .enumerate()
            .map(|(index, text)| {
                UiNode::new(
                    format!("{label_key}/visual/line-{index}"),
                    UiContent::Text(TextSpec {
                        text,
                        role: SemanticRole::Text,
                        style: StyleRef::Primary,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(height(1)))
                .paint_only()
            })
            .collect(),
    )
    .paint_only()
}

fn set_row_label_lines(row: &mut UiNode, lines: Vec<String>, stacked: bool) {
    let line_height = row_detail_line_height();
    let block = lines.len().max(1) as f32 * line_height;
    let wrapped = row
        .children
        .first()
        .is_some_and(|line| line.key.as_str().starts_with("settings/label-line/"));
    let row_height = fixed_height(row);
    let padding = row.layout.padding.top + row.layout.padding.bottom;
    let Some(label) = (if wrapped {
        row.children
            .first_mut()
            .and_then(|line| line.children.first_mut())
    } else {
        row.children.first_mut()
    }) else {
        return;
    };
    let multi = lines.len() > 1;
    let visual = row_label_visual(label.key.as_str(), lines);
    label.children = vec![visual];
    if !multi {
        return;
    }
    let band = if stacked {
        fixed_height(label)
    } else {
        row_height - padding
    };
    if block <= band {
        label.layout.padding = Insets {
            top: ((band - block) / 2.0).max(0.0),
            ..Insets::default()
        };
        return;
    }
    let grow = block - band;
    if stacked {
        label.layout.height = Length::Fixed(block);
        if wrapped && let Some(line) = row.children.first_mut() {
            line.layout.height = Length::Fixed(block);
            for trailing in line.children.iter_mut().skip(1) {
                trailing.layout.height = Length::Fixed(band);
            }
        }
    } else {
        for control in row.children.iter_mut().skip(1) {
            control.layout.height = Length::Fixed(band);
        }
    }
    row.layout.height = Length::Fixed(row_height + grow);
}

fn with_row_detail(mut row: UiNode, key: &str, lines: &[String], stacked: bool) -> UiNode {
    if lines.is_empty() {
        return row;
    }
    let lines = lines.to_vec();
    let line_height = row_detail_line_height();
    let detail_height = lines.len() as f32 * line_height;
    let detail_node = UiNode::new(
        format!("settings/detail/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(detail_height)),
    )
    .children(
        lines
            .into_iter()
            .enumerate()
            .map(|(line, text)| {
                reserved_or_detail_line(
                    format!("settings/detail/{key}/line-{line}"),
                    text,
                    line_height,
                )
            })
            .collect(),
    );
    let row_height = fixed_height(&row);
    if stacked {
        row.children.insert(1, detail_node);
        row.layout.height = Length::Fixed(row_height + detail_height + 4.0);
        return row;
    }
    UiNode::new(
        format!("settings/row-detail/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().height(Length::Fixed(row_height + detail_height)))
    .children(vec![row, detail_node])
}

fn row_note_blocks(key: &str, lines: &[String], most: f32) -> Vec<(UiNode, f32)> {
    let line_height = row_detail_line_height();
    let per_block = ((most / line_height).floor() as usize).max(1);
    lines
        .chunks(per_block)
        .enumerate()
        .map(|(part, chunk)| {
            let height = chunk.len() as f32 * line_height;
            let node = UiNode::new(
                if part == 0 {
                    format!("settings/note/{key}")
                } else {
                    format!("settings/note/{key}/part-{part}")
                },
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height)),
            )
            .children(
                chunk
                    .iter()
                    .enumerate()
                    .map(|(offset, text)| {
                        reserved_or_detail_line(
                            format!("settings/note/{key}/line-{}", part * per_block + offset),
                            text.clone(),
                            line_height,
                        )
                    })
                    .collect(),
            );
            (node, height)
        })
        .collect()
}

fn reserved_or_detail_line(key: String, text: String, line_height: f32) -> UiNode {
    let content = if text.is_empty() {
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group))
    } else {
        UiContent::Text(TextSpec {
            text,
            role: SemanticRole::Text,
            style: StyleRef::Quiet,
        })
    };
    UiNode::new(key, content)
        .layout(Layout::default().height(Length::Fixed(line_height)))
        .paint_only()
}

fn fact_lines(facts: &[String], px: f32, width: f32) -> Vec<String> {
    let width = width.max(48.0);
    let fits = |text: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, text, px) <= width
    };
    let mut lines: Vec<String> = Vec::new();
    let mut open = false;
    for fact in facts.iter().filter(|fact| !fact.trim().is_empty()) {
        if open && let Some(last) = lines.last_mut() {
            let joined = format!("{last}{FACT_SEPARATOR}{fact}");
            if fits(&joined) {
                *last = joined;
                continue;
            }
        }
        let wrapped = wrapped_copy_lines(fact, px, width);
        open = wrapped.len() == 1;
        lines.extend(wrapped);
    }
    lines
}

fn row_detail_line_height() -> f32 {
    18.0_f32.max(16.0 * settings_text_scale())
}

fn with_row_error(row: UiNode, key: &str, message: &str, text_width: f32) -> UiNode {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Danger);
    let line_height = 18.0_f32.max(16.0 * settings_text_scale());
    let lines = wrapped_copy_lines(message, px, text_width);
    let error_height = lines.len() as f32 * line_height;
    let row_height = fixed_height(&row);
    UiNode::new(
        format!("settings/row-with-error/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().height(Length::Fixed(row_height + error_height)))
    .children(vec![
        row,
        UiNode::new(
            format!("settings/error/{key}"),
            UiContent::Group(GroupSpec {
                label: Some(message.to_string()),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(error_height)))
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(line, text)| {
                    UiNode::new(
                        format!("settings/error/{key}/line-{line}"),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Text,
                            style: StyleRef::Danger,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
    ])
}

fn devtools_card_line_height() -> f32 {
    24.0_f32.max(20.0 * settings_text_scale())
}

fn devtools_card_heading(text_width: f32) -> (UiNode, f32) {
    access_card_heading(
        "settings/macos-access/devtools/heading",
        "DEVELOPER TOOLS",
        text_width,
    )
}

fn devtools_open_button(text_width: f32) -> (UiNode, f32) {
    let button = || {
        macos_access_button(
            MACOS_ACCESS_OPEN_DEVTOOLS,
            "Open Developer Tools\u{2026}",
            true,
            false,
        )
    };
    button_line_set(vec![button()], text_width, macos_access_button_lines())
        .pop()
        .and_then(|(mut line, height)| line.pop().map(|button| (button, height)))
        .unwrap_or_else(|| (button(), scaled_control_height()))
}

fn devtools_floor(copy: &DevToolsCardCopy, text_width: f32) -> (UiNode, f32) {
    let (button, button_height) = devtools_open_button(text_width);
    let button_width = match button.layout.width {
        Length::Fixed(width) => width,
        _ => text_width,
    };
    let room = text_width - button_width - 8.0;
    let state = devtools_floor_state(copy.state_short, room);
    let beside = room > 0.0
        && crate::native_ui::fit_native_text_label(&state, room) == state
        && !state.is_empty();
    let group = UiNode::new(
        "settings/macos-access/devtools/actions",
        UiContent::Group(GroupSpec::new(format!("Developer Tools: {}", copy.state))),
    );
    if beside {
        return (
            group
                .layout(
                    Layout::row()
                        .width(Length::Fill)
                        .height(Length::Fixed(button_height))
                        .gap(8.0),
                )
                .children(vec![
                    UiNode::new(
                        "settings/macos-access/devtools/state",
                        UiContent::Text(TextSpec {
                            text: state,
                            role: SemanticRole::Status,
                            style: copy.state_style,
                        }),
                    )
                    .layout(
                        Layout::default()
                            .width(Length::Fill)
                            .height(Length::Fixed(button_height)),
                    ),
                    button,
                ]),
            button_height,
        );
    }
    let (words, words_height) = wrapped_words_node(
        "settings/macos-access/devtools/state",
        &format!("Developer Tools \u{2014} {}", copy.state_short),
        (SemanticRole::Status, copy.state_style),
        text_width,
        devtools_card_line_height(),
    );
    let height = words_height + 8.0 + button_height;
    (
        group
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .gap(8.0),
            )
            .children(vec![words, button]),
        height,
    )
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct DevToolsCardFit {
    text_width: f32,
    line_budget: usize,
}

impl DevToolsCardFit {
    fn stacked(
        state: &SettingsViewState,
        width: SettingsWidth,
        viewport: LogicalRect,
        access: &MacosAccess,
        lead: AccessLead,
    ) -> Self {
        let gap = settings_page_gap(state, width, viewport);
        let text_width = settings_card_text_width(viewport, width);
        Self::within(
            text_width,
            fields_page_list_room(state, width, viewport)
                - gap
                - macos_access_kept_in_view(access, lead, text_width),
        )
    }

    fn within(text_width: f32, height: f32) -> Self {
        let spare = height
            - devtools_card_heading(text_width).1
            - devtools_open_button(text_width).1
            - 2.0 * 12.0;
        Self {
            text_width,
            line_budget: (spare / devtools_card_line_height()).floor().max(0.0) as usize,
        }
    }
}

fn fields_page_list_room(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let gap = settings_page_gap(state, width, viewport);
    let (_, pinned) = pinned_heading(
        state,
        width,
        viewport,
        gap,
        state.route.label(),
        settings_fields_subtitle(state.route, false, false),
    );
    (settings_list_body_height(state, width, viewport) - pinned).max(0.0)
}

fn macos_access_lead(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
    access: &MacosAccess,
) -> AccessLead {
    let gap = settings_page_gap(state, width, viewport);
    let text_width = settings_card_text_width(viewport, width);
    let room = fields_page_list_room(state, width, viewport);
    let devtools_least = devtools_floor(&devtools_card_copy(access), text_width).1 + 2.0 * 12.0;
    AccessLead::ALL
        .into_iter()
        .find(|lead| {
            devtools_least + gap + macos_access_kept_in_view(access, *lead, text_width)
                <= room + 0.01
        })
        .unwrap_or(AccessLead::State)
}

fn devtools_card_priority(key: &str) -> u8 {
    match key {
        "state" => 0,
        "how" => 1,
        "trade" => 2,
        "kind" => 3,
        "why" => 4,
        "route" => 5,
        "only" => 6,
        "unread" => 7,
        "checked" => 8,
        "declined" => 9,
        "opened" => 10,
        _ => 11,
    }
}

fn devtools_card_lines(
    copy: &DevToolsCardCopy,
) -> Vec<(&'static str, String, SemanticRole, StyleRef)> {
    let mut lines = vec![(
        "state",
        copy.state.clone(),
        SemanticRole::Status,
        copy.state_style,
    )];
    if copy.granted {
        lines.push((
            "trade",
            copy.trade.clone(),
            SemanticRole::Text,
            StyleRef::Quiet,
        ));
        return lines;
    }
    if let Some(unread) = &copy.unread {
        lines.push((
            "unread",
            unread.clone(),
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    lines.push((
        "kind",
        copy.kind.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "why",
        copy.why.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    if let Some(checked) = &copy.checked {
        lines.push((
            "checked",
            checked.clone(),
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    lines.push((
        "how",
        copy.how.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    lines.push((
        "only",
        copy.only.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    lines.push((
        "route",
        copy.route.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "trade",
        copy.trade.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    if let Some(opened) = &copy.opened {
        lines.push((
            "opened",
            opened.clone(),
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    if let Some(declined) = &copy.declined {
        lines.push((
            "declined",
            declined.clone(),
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    lines
}

fn devtools_floor_state(short: &str, room: f32) -> String {
    let named = format!("Developer Tools \u{2014} {short}");
    if crate::native_ui::fit_native_text_label(&named, room.max(0.0)) == named {
        return named;
    }
    let mut chars = short.chars();
    chars.next().map_or_else(String::new, |first| {
        first.to_uppercase().chain(chars).collect()
    })
}

fn devtools_state_short_node(
    copy: &DevToolsCardCopy,
    text_width: f32,
    line_height: f32,
) -> (UiNode, f32) {
    let key = "settings/macos-access/devtools/state";
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, copy.state_style);
    let lines = wrap_to_box(
        &devtools_floor_state(copy.state_short, text_width),
        text_width,
        &|line| crate::tray_raster::ui_text_width_for(face, line, px),
    );
    let height = lines.len().max(1) as f32 * line_height;
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(copy.state.clone()),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(0.0),
        )
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| {
                    UiNode::new(
                        format!("{key}/line-{index}"),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Status,
                            style: copy.state_style,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        height,
    )
}

fn devtools_card(access: &MacosAccess, fit: DevToolsCardFit) -> (UiNode, f32) {
    let line_height = devtools_card_line_height();
    let copy = devtools_card_copy(access);
    let card = |children: Vec<UiNode>, height: f32| {
        (
            UiNode::new(
                "settings/developer-tools",
                UiContent::Group(GroupSpec::new("Developer Tools").style(StyleRef::Secondary)),
            )
            .layout(
                Layout::column()
                    .height(Length::Fixed(height))
                    .padding(Insets::all(12.0))
                    .gap(0.0)
                    .clipped(),
            )
            .children(children),
            height,
        )
    };
    if fit.line_budget == 0 {
        let (floor, height) = devtools_floor(&copy, fit.text_width);
        return card(vec![floor], height + 2.0 * 12.0);
    }
    let (open, open_height) = devtools_open_button(fit.text_width);
    let (heading, heading_height) = devtools_card_heading(fit.text_width);
    let mut height = heading_height + open_height + 2.0 * 12.0;
    let mut children = vec![heading];
    let mut wrapped = devtools_card_lines(&copy)
        .into_iter()
        .map(|(key, text, role, style)| {
            let (node, lines_height) = wrapped_copy_node(
                &format!("settings/macos-access/devtools/{key}"),
                &text,
                role,
                style,
                fit.text_width,
                line_height,
                None,
            );
            let lines = (lines_height / line_height).round() as usize;
            if key == "state" && lines > fit.line_budget {
                let (node, height) = devtools_state_short_node(&copy, fit.text_width, line_height);
                let lines = (height / line_height).round() as usize;
                return (key, node, height, lines, false);
            }
            (key, node, lines_height, lines, false)
        })
        .collect::<Vec<_>>();
    let mut order = (0..wrapped.len()).collect::<Vec<_>>();
    order.sort_by_key(|&index| devtools_card_priority(wrapped[index].0));
    let mut left = fit.line_budget;
    for index in order {
        let (key, _, _, lines, keep) = &mut wrapped[index];
        if *key != "state" && *lines > left {
            break;
        }
        left = left.saturating_sub(*lines);
        *keep = true;
    }
    for (_, node, lines_height, _, keep) in wrapped {
        if keep {
            height += lines_height;
            children.push(node);
        }
    }
    children.push(
        UiNode::new(
            "settings/macos-access/devtools/actions",
            UiContent::Group(GroupSpec::new("Developer Tools actions")),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(open_height))
                .gap(8.0),
        )
        .children(vec![open]),
    );
    card(children, height)
}

const OVERRIDES_THEME_WORD: &str = "Overrides theme";

fn setting_reset_button(field: &EditField) -> UiNode {
    setting_reset_button_to(field, None)
}

fn setting_reset_button_to(field: &EditField, theme: Option<&(String, String)>) -> UiNode {
    let spec = match theme {
        Some((value, label)) => {
            ButtonSpec::new(format!("Use theme's {} ({label}: {value})", field.label))
                .visual_label("Use theme's")
        }
        None => ButtonSpec::new(format!("Reset {}", field.label)).visual_label("Reset"),
    };
    row_trailing_button(
        format!("settings/reset/{}", field.key),
        spec,
        format!("settings/reset/{}", field.key),
    )
}

fn reserve_reset_slot(row: &mut UiNode, key: &str) {
    let reset = format!("settings/reset/{key}");
    let slot_key = format!("settings/reset-slot/{key}");
    if ui_node_holds(row, &reset) || ui_node_holds(row, &slot_key) {
        return;
    }
    let slot = UiNode::new(
        slot_key,
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(72.0 * settings_text_scale().min(1.5)))
            .height(Length::Fill),
    );
    let controls_key = format!("settings/controls/{key}");
    match row
        .children
        .iter_mut()
        .find(|child| child.key.as_str() == controls_key)
    {
        Some(controls) => controls.children.push(slot),
        None => row.children.push(slot),
    }
}

fn row_trailing_button(key: String, spec: ButtonSpec, action: String) -> UiNode {
    UiNode::new(
        key,
        UiContent::Button(
            Control::new(spec, ActionId::new(action))
                .state(ControlState::default())
                .style(StyleRef::Quiet),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(reset_slot_width()))
            .height(Length::Fill),
    )
}

fn reset_slot(key: &str) -> UiNode {
    UiNode::new(
        format!("settings/reset-slot/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(reset_slot_width()))
            .height(Length::Fill),
    )
    .paint_only()
}

fn reset_slot_width() -> f32 {
    72.0 * settings_text_scale().min(1.5)
}

fn switch_default(key: &str) -> Option<bool> {
    static DEFAULTS: std::sync::OnceLock<Vec<(&'static str, bool)>> = std::sync::OnceLock::new();
    DEFAULTS
        .get_or_init(|| {
            prefs::editable_fields(&crate::app_config::Config::default())
                .into_iter()
                .filter(|field| matches!(field.kind, EditKind::Bool))
                .filter_map(|field| Some((field.key, field.seed?.trim().parse().ok()?)))
                .collect()
        })
        .iter()
        .find(|(candidate, _)| *candidate == key)
        .map(|(_, default)| *default)
}

fn setting_row(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
) -> UiNode {
    setting_row_parts(state, index, field, modified_only, width).row
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RowForm {
    List { modified_only: bool },
    Direct,
}

struct SettingRowParts {
    row: UiNode,
    name: String,
    tags: RowTags,
    worst: RowTags,
    timing: Option<&'static str>,
}

const CHANGED_WORD: &str = "Changed";

const UNSAVED_HINT: &str = "Unsaved";

fn row_shown_value(state: &SettingsViewState, field: &EditField, modified_only: bool) -> String {
    if field.key == prefs::EDIT_CURSOR_TRAIL_STYLE {
        if modified_only {
            top_authored_trail_value(state)
        } else {
            let projected = top_projected_trail_value(state);
            if !state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE)
                && projected.eq_ignore_ascii_case(crate::app_config::default_cursor_trail_style())
            {
                format!("{projected} (default)")
            } else {
                projected
            }
        }
    } else if field.key == SPARKLE_WORDS_KEY || field.key == KEYWORD_KITTIES_KEY {
        if modified_only {
            top_authored_toy_value(state, field.key).to_string()
        } else {
            top_projected_toy_value(state, field.key).to_string()
        }
    } else if field.key == prefs::EDIT_TRAIL_SOUNDS {
        if modified_only {
            top_authored_music_value(state).to_string()
        } else {
            top_projected_music_value(state).to_string()
        }
    } else {
        SettingsState::display_value(field).to_string()
    }
}

/// WHAT A SETTING READS AS NOW.
pub(crate) fn effective_value_words(
    snapshot: &crate::native_config_service::ConfigSnapshot,
    key: &str,
    system_dark: bool,
    font_families: Option<Arc<aterm_render::font_catalog::MonospaceFamilies>>,
) -> Option<String> {
    let mut state = SettingsViewState::from_snapshot(snapshot).ok()?;
    if let Some(families) = font_families {
        state.replace_font_families(families);
    }
    state.presented_motion.set(crate::native_app::ViewMotionCx {
        system_dark,
        ..state.presented_motion.get()
    });
    let fields = state.theme_seeded_fields(&snapshot.config, &Arc::clone(&state.assets.themes));
    state.set_fields(fields);
    state.row_value_words(key)
}

impl SettingsViewState {
    fn row_value_words(&self, key: &str) -> Option<String> {
        let field = self.field_by_key(key)?;
        let held = top_effect_held_off_reason(self, None, key);
        let shown = match held {
            Some(_) if key == prefs::EDIT_CURSOR_TRAIL_STYLE => top_authored_trail_value(self),
            Some(_) => SettingsState::display_value(field).to_string(),
            None => row_shown_value(self, field, false),
        };
        let shown = shown.trim();
        let theme = (!self.is_explicit(key))
            .then(|| self.theme_fallback_for(key))
            .flatten()
            .map(|(_, label)| label);
        let bare = theme
            .as_ref()
            .and_then(|label| shown.strip_suffix(&format!(" (from theme {label})")))
            .or_else(|| shown.strip_suffix(" (default)"))
            .unwrap_or(shown)
            .trim();
        let automatic = bare.ends_with(" (automatic)");
        let bare = bare.strip_suffix(" (automatic)").unwrap_or(bare).trim();
        let words = match field.kind {
            EditKind::Bool => if bare.parse::<bool>().unwrap_or(false) {
                "On"
            } else {
                "Off"
            }
            .to_string(),
            _ if font_picker_key(key) && field.seed.is_none() => {
                let label = font_automatic_label(self, key);
                theme
                    .as_ref()
                    .and_then(|theme| label.strip_suffix(&format!(" (from theme {theme})")))
                    .map_or_else(|| label.clone(), str::to_string)
            }
            EditKind::Enum { .. } => {
                let token = unset_choice_value(field, bare);
                if segmented_choices(field, shown).is_some() {
                    segment_label(key, token)
                } else {
                    setting_choice_label(key, token)
                }
            }
            EditKind::Theme => theme_value_words(&self.assets.themes, field.seed.as_deref()),
            EditKind::Float | EditKind::Integer
                if let Some((numeric, readout)) = numeric_slider_value_for_state(self, field) =>
            {
                slider_readout(key, numeric, readout)
            }
            _ => match field_placeholder(self, field) {
                (_, Some(path)) if field.seed.is_none() => path,
                _ => bare
                    .split_once(" \u{2014} ")
                    .map_or(bare, |(value, _hint)| value)
                    .trim()
                    .to_string(),
            },
        };
        let words = if words.trim().is_empty() {
            "none".to_string()
        } else {
            words
        };
        let sourced = font_picker_key(key) && words.starts_with("Automatic (");
        let value = if self.is_explicit(key) || sourced {
            words
        } else if let Some(label) = theme {
            format!("{words} (from theme {label})")
        } else if automatic {
            format!("{words} (automatic)")
        } else if words.to_ascii_lowercase().ends_with("default") {
            words
        } else {
            format!("{words} (default)")
        };
        Some(match held {
            Some(reason) => format!("{value}; Off while {reason}"),
            None => value,
        })
    }
}

fn setting_row_parts(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
) -> SettingRowParts {
    setting_row_parts_in(state, index, field, RowForm::List { modified_only }, width)
}

fn setting_row_parts_in(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    form: RowForm,
    width: SettingsWidth,
) -> SettingRowParts {
    let direct = form == RowForm::Direct;
    let modified_only = form
        == RowForm::List {
            modified_only: true,
        };
    let offers_reset = !direct && (modified_only || state.is_explicit(field.key));
    let reserve_reset_slot = !direct;
    let setting_effect = setting_effect_projection(
        state,
        None,
        field.key,
        SettingsAvailability::for_state(state),
        state.presented_motion.get(),
    );
    let value = row_shown_value(state, field, modified_only);
    let first_token_is = |key: &str, word: &str| {
        field.key == key
            && value
                .split_whitespace()
                .next()
                .is_some_and(|token| token.eq_ignore_ascii_case(word))
    };
    let unlimited_scrollback = first_token_is(prefs::EDIT_SCROLLBACK, "0");
    let screen_only_search = first_token_is(prefs::EDIT_SEARCH_HISTORY_LINES, "0");
    let echo_always = first_token_is(prefs::EDIT_PREDICTIVE_ECHO, "always");
    let retained_input = state.field_inputs.get(field.key);
    let has_draft = retained_input.is_some_and(|input| {
        input.value() != field.seed.as_deref().unwrap_or_default() || input.preedit().is_some()
    });
    let environment_override = state.environment_override(field.key);
    let bounded_numeric_disclosure =
        bounded_numeric_disclosure(state, field, environment_override.is_some());
    let timing_of = |timing: Option<prefs::ApplicationTiming>| {
        timing
            .filter(|_| !setting_effect.unavailable())
            .map(prefs::ApplicationTiming::words)
    };
    let timing = timing_of(application_timing_in(state, None, field.key));
    let mut facts: Vec<(String, String)> = Vec::new();
    let mut own_value_facts: Vec<Option<String>> = Vec::new();
    let mut fact = |visual: String, semantic: String, own: Option<&str>| {
        facts.push((visual, semantic));
        own_value_facts.push(own.map(str::to_string));
    };
    if let Some(disclosure) = bounded_numeric_disclosure.as_ref() {
        fact(disclosure.visual.clone(), disclosure.semantic.clone(), None);
    }
    if let Some(active) = environment_override {
        fact(
            format!("{} active → {}", active.variable, active.effective),
            format!(
                "overridden by {}; effective {}",
                active.variable, active.effective
            ),
            None,
        );
    }
    if unlimited_scrollback {
        fact(String::new(), "Unlimited (0)".to_string(), None);
    }
    if field.key == prefs::EDIT_FONT_PX && environment_override.is_none() {
        let (visual, semantic) = if field.seed.is_none() {
            ("Automatic", "automatic")
        } else {
            ("", "")
        };
        fact(visual.to_string(), semantic.to_string(), Some("Automatic"));
    }
    if !has_draft
        && environment_override.is_none()
        && let Some(modifier) = font_style_modifier(state, field.key)
    {
        fact(modifier.to_string(), modifier.to_lowercase(), None);
    }
    if screen_only_search {
        fact(String::new(), "Screen only (0)".to_string(), None);
    }
    if field.key == prefs::EDIT_PREDICTIVE_ECHO {
        let (visual, semantic) = if echo_always {
            (
                "Can show a password",
                "Always, set in Manual, can show what you type at a password prompt",
            )
        } else {
            ("", "")
        };
        fact(
            visual.to_string(),
            semantic.to_string(),
            Some("Can show a password"),
        );
    }
    for note in &setting_effect.notes {
        fact(note.visual.clone(), note.semantic.clone(), None);
    }
    let facts_after = |timing: Option<&str>| -> String {
        timing
            .into_iter()
            .chain(facts.iter().map(|(_, semantic)| semantic.as_str()))
            .filter(|fact| !fact.is_empty())
            .map(|fact| format!(" · {fact}"))
            .collect()
    };
    let semantic_facts = facts_after(timing);
    let visual_facts: Vec<(String, Option<String>)> = facts
        .iter()
        .map(|(visual, _)| visual.clone())
        .zip(own_value_facts)
        .collect();
    let semantic_field_label = format!("{}{semantic_facts}", field.label);
    let field_error = state.field_errors.get(field.key);
    let takes_typing = matches!(
        field.kind,
        EditKind::Text | EditKind::Integer | EditKind::Float | EditKind::Color
    ) && numeric_slider_value(field).is_none();
    let setting_description = field_error
        .map(|error| {
            if takes_typing {
                format!("{error}; correct it and press Return, or use Discard Draft in Modified")
            } else {
                error.clone()
            }
        })
        .into_iter()
        .chain(row_footnote(state, field.key).map(std::borrow::Cow::into_owned))
        .chain((has_draft && field_error.is_none()).then(|| {
            "Unsaved draft; focus and press Return to save, or use Discard Draft in Modified"
                .to_string()
        }))
        .collect::<Vec<_>>()
        .join(FACT_SEPARATOR);
    let editing_input = (state.editing_field.as_deref() == Some(field.key))
        .then_some(retained_input)
        .flatten();
    let action = ActionId::new(format!("settings/set/{}", field.key));
    let focused = state
        .common
        .last_focus
        .as_ref()
        .is_some_and(|key| key.as_str() == format!("settings/control/{}", field.key));
    let invalid = field.kind == EditKind::Color
        && retained_input.is_some_and(|input| {
            let draft = input.value().trim();
            !draft.is_empty() && !prefs::color_value_is_valid(field.key, draft)
        });
    let control_state = ControlState {
        focused,
        invalid: invalid
            || field_error.is_some()
            || state.font_refusal(field.key).is_some_and(|refusal| {
                refusal.reason == crate::native_font_catalog::FontRefusalReason::NotFound
            }),
        muted: setting_effect.idle(),
        ..ControlState::default()
    };
    let segment_need =
        segmented_choices(field, &value).map(|(segments, _)| segmented_natural_width(&segments));
    let segmented = segmented_choices(field, &value).map(|(segments, selected)| {
        let segment_facts: Vec<String> = segments
            .iter()
            .map(|segment| facts_after(timing_of(segment_timing(state, field.key, &segment.value))))
            .collect();
        segmented_choice_node(
            field,
            &segments,
            selected,
            &value,
            &segment_facts,
            &setting_description,
            control_state,
        )
    });
    let font_list = font_picker_key(field.key) && !state.font_row_takes_text(field.key);
    let choice_words = if field.key == prefs::EDIT_THEME && field.seed.is_some() {
        theme_value_words(&state.assets.themes, Some(&value))
    } else {
        setting_choice_label(field.key, &value)
    };
    let control = match field.kind {
        _ if font_list => {
            let shown = field
                .seed
                .as_deref()
                .map(str::trim)
                .filter(|family| !family.is_empty())
                .map_or_else(|| font_automatic_label(state, field.key), str::to_string);
            UiContent::Button(
                Control::new(
                    ButtonSpec {
                        label: format!("{}: {shown}{semantic_facts}", field.label),
                        visual_label: Some(shown.clone()),
                        visual_icon: None,
                        trailing_icon: Some(ButtonIcon::ChevronDown),
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        badge: false,
                        swatches: Vec::new(),
                        chip: None,
                        chevron_row: None,
                    },
                    ActionId::new(format!("settings/font-picker/{}", field.key)),
                )
                .value(SemanticValue::Text(shown))
                .state(ControlState {
                    selected: state
                        .choice_picker
                        .as_ref()
                        .is_some_and(|picker| picker.key == field.key),
                    ..control_state
                })
                .style(StyleRef::Setting),
            )
        }
        EditKind::Bool => UiContent::Switch(
            Control::new(
                SwitchSpec {
                    label: semantic_field_label.clone(),
                    description: (!setting_description.is_empty())
                        .then(|| setting_description.clone()),
                },
                action,
            )
            .value(SemanticValue::Bool(value.parse().unwrap_or(false)))
            .state(control_state)
            .style(StyleRef::Setting),
        ),
        EditKind::Enum { .. } | EditKind::Theme => UiContent::Button(
            Control::new(
                ButtonSpec {
                    label: format!("{}: {choice_words}{semantic_facts}", field.label),
                    visual_label: Some(theme_pair_fitted(field.key, &value, &choice_words)),
                    visual_icon: None,
                    trailing_icon: Some(if field.key == prefs::EDIT_CURSOR_TRAIL_STYLE {
                        ButtonIcon::Forward
                    } else {
                        ButtonIcon::ChevronDown
                    }),
                    description: (!setting_description.is_empty())
                        .then(|| setting_description.clone()),
                    badge: false,
                    swatches: Vec::new(),
                    chip: None,
                    chevron_row: None,
                },
                action,
            )
            .value(SemanticValue::Text(choice_words.clone()))
            .state(ControlState {
                selected: state
                    .choice_picker
                    .as_ref()
                    .is_some_and(|picker| picker.key == field.key),
                ..control_state
            })
            .style(StyleRef::Setting),
        ),
        EditKind::Float | EditKind::Integer
            if numeric_slider_value_for_state(state, field).is_some() =>
        {
            let (numeric, display_value) = numeric_slider_value_for_state(state, field)
                .expect("guard checked numeric slider value");
            let range = slider_domain(state, field.key).expect("numeric slider has a range");
            let display_value = slider_readout(field.key, numeric, display_value);
            UiContent::Slider(
                Control::new(
                    SliderSpec {
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        track: slider_track(field.key, range, numeric),
                        label: semantic_field_label.clone(),
                        step: range.step,
                        display_value,
                    },
                    action,
                )
                .value(SemanticValue::Number {
                    value: numeric,
                    minimum: range.min,
                    maximum: range.max,
                })
                .state(control_state)
                .style(StyleRef::Setting),
            )
        }
        EditKind::Float | EditKind::Integer | EditKind::Text | EditKind::Color => {
            let field_text = retained_input.map_or_else(
                || field.seed.clone().unwrap_or_default(),
                |input| input.projection().text,
            );
            let semantic_text = if field_text.trim().is_empty() {
                value.clone()
            } else {
                field_text.clone()
            };
            let swatch = matches!(field.kind, EditKind::Color)
                .then(|| {
                    let candidate = if field_text.trim().is_empty() {
                        value.as_str()
                    } else {
                        field_text.as_str()
                    };
                    aterm_types::scheme::parse_hex(candidate)
                        .map(|color| [color.r, color.g, color.b])
                        .or_else(|| {
                            (field_text.trim().is_empty())
                                .then(|| unset_color_swatch(state, field.key))
                                .flatten()
                        })
                })
                .flatten();
            let (placeholder, default_path) = field_placeholder(state, field);
            let semantic_text = match default_path {
                Some(path) if field_text.trim().is_empty() => path,
                _ => semantic_text,
            };
            UiContent::TextField(
                Control::new(
                    TextFieldSpec {
                        label: semantic_field_label.clone(),
                        placeholder: Some(placeholder),
                        secret: false,
                        visual_value: Some(field_text),
                        input: editing_input
                            .map(crate::native_text_input::TextInputState::projection),
                        swatch,
                        swatch_line: false,
                        trailing_hint: has_draft.then(|| UNSAVED_HINT.to_string()),
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        end_button: false,
                    },
                    action,
                )
                .value(SemanticValue::Text(semantic_text))
                .state(control_state)
                .style(StyleRef::Setting),
            )
        }
    };
    let mut tags = RowTags::default();
    let mut worst = RowTags::default();
    if !modified_only && !direct {
        if state.is_explicit(field.key) {
            tags.state.push(CHANGED_WORD.to_string());
        }
        worst.state.push(CHANGED_WORD.to_string());
    }
    let theme_fallback = state.theme_fallback_for(field.key);
    if theme_fallback.is_some() && !direct {
        if state.is_explicit(field.key) {
            tags.state.push(OVERRIDES_THEME_WORD.to_string());
        }
        worst.state.push(OVERRIDES_THEME_WORD.to_string());
    }
    for (fact, own_value) in visual_facts.iter().filter(|_| !direct) {
        if !fact.is_empty() {
            tags.facts.push(fact.clone());
        }
        if let Some(fact) = own_value.as_ref().or((!fact.is_empty()).then_some(fact)) {
            worst.facts.push(fact.clone());
        }
    }
    if modified_only && let Some(default) = modified_default_words(state, field.key) {
        let tag = if field.key == prefs::EDIT_THEME {
            "Default theme"
        } else {
            "Default"
        };
        let default = format!("{tag}: {default}");
        tags.facts.push(default.clone());
        worst.facts.push(default);
    }
    let visual_label = with_tags(field.label, tags.iter());
    let mut label = visual_label.clone();
    if modified_only && let Some([r, g, b]) = color_picker::default_color_chip(state, field) {
        label.push_str(&format!(", #{r:02X}{g:02X}{b:02X}"));
    }
    if let Some(timing) = timing.filter(|_| !direct) {
        label.push_str(FACT_SEPARATOR);
        label.push_str(timing);
    }
    let label_node = UiNode::new(
        format!("settings/label/{}", field.key),
        UiContent::Group(GroupSpec {
            label: Some(label),
            role: SemanticRole::Text,
            style: StyleRef::Plain,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(if width == SettingsWidth::Compact {
                Length::Fixed(22.0_f32.max(20.0 * settings_text_scale()))
            } else {
                Length::Fill
            }),
    )
    .children(vec![row_label_visual(
        &format!("settings/label/{}", field.key),
        vec![visual_label],
    )]);
    let mut control_node = segmented
        .unwrap_or_else(|| UiNode::new(format!("settings/control/{}", field.key), control));
    control_node.layout.width = if width == SettingsWidth::Compact {
        if matches!(field.kind, EditKind::Bool) {
            Length::Fixed(104.0 * settings_text_scale().min(1.4))
        } else {
            Length::Fill
        }
    } else {
        match field.kind {
            EditKind::Bool => Length::Fixed(104.0 * settings_text_scale().min(1.4)),
            EditKind::Enum { .. } | EditKind::Theme => {
                Length::Fixed(regular_choice_control_width().max(segment_need.unwrap_or_default()))
            }
            _ => Length::Fixed(300.0 * settings_text_scale().min(1.25)),
        }
    };
    control_node.layout.height = Length::Fill;
    let mut control_children = vec![control_node];
    let reset = if offers_reset {
        Some(if modified_only && has_draft {
            row_trailing_button(
                format!("settings/draft-discard/{}", field.key),
                ButtonSpec::new("Discard Draft").visual_label("Discard"),
                format!("settings/drafts/discard/{}", field.key),
            )
        } else {
            setting_reset_button_to(field, theme_fallback.as_ref())
        })
    } else if reserve_reset_slot {
        Some(reset_slot(field.key))
    } else {
        None
    };
    let label_node = match reset {
        Some(reset) if width == SettingsWidth::Compact && !matches!(field.kind, EditKind::Bool) => {
            let height = 22.0_f32.max(20.0 * settings_text_scale());
            UiNode::new(
                format!("settings/label-line/{}", field.key),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .gap(6.0),
            )
            .children(vec![label_node, reset])
        }
        Some(reset) => {
            control_children.push(reset);
            label_node
        }
        None => label_node,
    };
    if width == SettingsWidth::Compact && matches!(field.kind, EditKind::Bool) {
        control_children.insert(
            0,
            UiNode::new(
                format!("settings/control-spacer/{}", field.key),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
        );
    }
    let (layout, children) = if width == SettingsWidth::Compact {
        let controls = UiNode::new(
            format!("settings/controls/{}", field.key),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fill)
                .gap(STACKED_CONTROL_GAP),
        )
        .children(control_children);
        (
            Layout::column()
                .height(Length::Fixed(width.row_height()))
                .gap(4.0),
            vec![label_node, controls],
        )
    } else {
        let mut children = vec![label_node];
        children.extend(control_children);
        (
            Layout::row()
                .height(Length::Fixed(width.row_height()))
                .padding(Insets::symmetric(0.0, 4.0))
                .gap(12.0),
            children,
        )
    };
    SettingRowParts {
        row: UiNode::new(
            format!("settings/row/{index}/{}", field.key),
            UiContent::Group(GroupSpec::new(field.label)),
        )
        .layout(layout)
        .children(children),
        name: field.label.to_string(),
        tags,
        worst,
        timing,
    }
}

fn field_placeholder(state: &SettingsViewState, field: &EditField) -> (String, Option<String>) {
    if field.key == prefs::EDIT_AI_FLEET
        && let Some((path, shown)) = state.config_file.as_ref()
        && let Some(dir) = path.parent()
    {
        let folder = &shown[..crate::native_ui::path_name_start(shown)];
        let painted = format!("{folder}{}", aterm_agent::ai::config::FLEET_FILE);
        let spoken = dir
            .join(aterm_agent::ai::config::FLEET_FILE)
            .display()
            .to_string();
        return (painted, Some(spoken));
    }
    (field.placeholder.clone(), None)
}

fn fit_row_button_words(row: &mut UiNode, name: &str, text_width: f32, stacked: bool) {
    if stacked {
        fit_row_choice_label(row, text_width);
        return;
    }
    let spare = (one_line_label_room(row, text_width) - one_line_name_floor(name)).max(0.0);
    let band = fixed_height(row) - row.layout.padding.top - row.layout.padding.bottom;
    let Some(control) = row
        .children
        .get_mut(1)
        .filter(|node| node.key.as_str().starts_with("settings/control/"))
    else {
        return;
    };
    let Length::Fixed(current) = control.layout.width else {
        return;
    };
    let UiContent::Button(button) = &mut control.content else {
        return;
    };
    let complete = button
        .spec
        .visual_label
        .clone()
        .unwrap_or_else(|| button.spec.label.clone());
    let edges = current - crate::native_ui::text_button_label_room(&button.spec, current);
    let need = crate::native_ui::native_button_label_width(&complete) + edges;
    let width = current + (need - current).clamp(0.0, spare);
    let lines = choice_words(&mut button.spec, &complete, width);
    control.layout.width = Length::Fixed(width);
    let grow = crate::native_ui::native_button_height_for_lines(lines, band) - band;
    if grow > 0.01 {
        grow_row(row, grow);
    }
}

fn fit_row_choice_label(row: &mut UiNode, max_width: f32) {
    let Some(controls) = row.children.get_mut(1) else {
        return;
    };
    let siblings: f32 = controls
        .children
        .iter()
        .filter(|node| !node.key.as_str().starts_with("settings/control/"))
        .map(|node| match node.layout.width {
            Length::Fixed(width) => width + 6.0,
            _ => 0.0,
        })
        .sum();
    let max_width = max_width - siblings;
    let Some(control) = controls
        .children
        .iter_mut()
        .find(|node| node.key.as_str().starts_with("settings/control/"))
    else {
        return;
    };
    let UiContent::Button(button) = &mut control.content else {
        return;
    };
    let complete = button
        .spec
        .visual_label
        .clone()
        .unwrap_or_else(|| button.spec.label.clone());
    let lines = choice_words(&mut button.spec, &complete, max_width);
    let single = scaled_control_height();
    let grow = crate::native_ui::native_button_height_for_lines(lines, single) - single;
    if grow > 0.0 {
        grow_row(row, grow);
    }
}

fn choice_words(spec: &mut ButtonSpec, complete: &str, max_width: f32) -> usize {
    let fits = |spec: &ButtonSpec, words: &str| {
        crate::native_ui::native_button_label_width(words)
            <= crate::native_ui::text_button_label_room(spec, max_width)
                + crate::native_ui::TEXT_FIT_SLACK
    };
    let bare = complete
        .strip_suffix(" (default)")
        .filter(|bare| !bare.is_empty())
        .map(str::to_string);
    let named = bare
        .as_deref()
        .unwrap_or(complete)
        .split_once(FACT_SEPARATOR)
        .map(|(name, _)| name.to_string())
        .filter(|name| !name.is_empty());
    let forms: Vec<String> = std::iter::once(complete.to_string())
        .chain(bare)
        .chain(named)
        .collect();
    if let Some(words) = forms.iter().find(|words| fits(spec, words)) {
        spec.visual_label = Some(words.clone());
        return 1;
    }
    if spec.trailing_icon.is_some() {
        let mut bare_spec = spec.clone();
        bare_spec.trailing_icon = None;
        if let Some(words) = forms.iter().find(|words| fits(&bare_spec, words)) {
            spec.trailing_icon = None;
            spec.visual_label = Some(words.clone());
            return 1;
        }
    }
    if spec.chip.is_some() {
        spec.visual_label = Some(String::new());
        return 1;
    }
    let short = forms[1..].iter().map(String::as_str).collect::<Vec<_>>();
    if let Some((words, lines)) = whole_button_words_in(spec, complete, &short, max_width) {
        spec.visual_label = Some(words);
        return lines;
    }
    spec.trailing_icon = None;
    let (words, lines) = button_words_in(spec, complete, &short, max_width);
    spec.visual_label = Some(words);
    lines
}

fn grow_row(row: &mut UiNode, grow: f32) {
    if let Length::Fixed(height) = row.layout.height {
        row.layout.height = Length::Fixed(height + grow);
    }
    if let Some(controls) = row.children.get_mut(1)
        && let Length::Fixed(height) = controls.layout.height
    {
        controls.layout.height = Length::Fixed(height + grow);
    }
}

fn fit_row_field_placeholder(
    row: &mut UiNode,
    (name, text_width, stacked): (&str, f32, bool),
    unset: Option<(&str, bool)>,
    held: Option<&str>,
) {
    // A ONE-LINE ROW'S FIELD TAKES THE WIDTH ITS UNSET WORDS NEED from the
    // name's column, down to the name's floor ([`one_line_name_floor`]), as a
    // row's button does ([`fit_row_button_words`]): measured on the words
    // the field shows unset (`unset`), so a value written or typed into it
    // never moves it.
    if !stacked && let Some((unset, chip)) = unset {
        let spare = (one_line_label_room(row, text_width) - one_line_name_floor(name)).max(0.0);
        if let Some(control) = row
            .children
            .get_mut(1)
            .filter(|node| node.key.as_str().starts_with("settings/control/"))
            && let Length::Fixed(current) = control.layout.width
            && matches!(control.content, UiContent::TextField(_))
        {
            let need = crate::native_ui::text_field_width_for(
                &crate::native_ui::plain_placeholder(unset),
                chip,
            );
            control.layout.width = Length::Fixed(current + (need - current).clamp(0.0, spare));
        }
    }
    fn fit(
        node: &mut UiNode,
        room: f32,
        unset: Option<(&str, bool)>,
        held: Option<&str>,
    ) -> Option<usize> {
        let siblings: f32 = node
            .children
            .iter()
            .filter(|child| !child.key.as_str().starts_with("settings/control/"))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width + node.layout.gap,
                _ => 0.0,
            })
            .sum();
        for child in &mut node.children {
            if child.key.as_str().starts_with("settings/control/")
                && let UiContent::TextField(field) = &mut child.content
            {
                let width = match child.layout.width {
                    Length::Fixed(width) => width,
                    _ => room - siblings,
                };
                let chip_line = field.spec.swatch_line;
                let swatch = field.spec.swatch.is_some() && !chip_line;
                let empty = field
                    .spec
                    .visual_value
                    .as_deref()
                    .unwrap_or_default()
                    .is_empty()
                    && field
                        .spec
                        .input
                        .as_ref()
                        .is_none_or(|input| input.text.is_empty());
                let placeholder = field.spec.placeholder.clone();
                let painted = placeholder
                    .as_deref()
                    .map(|placeholder| field_placeholder_lines(placeholder, width, swatch));
                let kept = unset
                    .map(|(unset, chip)| {
                        [false, chip && !chip_line]
                            .into_iter()
                            .map(|swatch| field_placeholder_lines(unset, width, swatch).1)
                            .max()
                            .unwrap_or(1)
                    })
                    .unwrap_or(1);
                let words_room = crate::native_ui::text_field_words_room(field, width);
                let kept = held
                    .filter(|held| !held.is_empty())
                    .map_or(kept, |held| kept.max(field_value_lines(held, words_room).1));
                let mut lines = kept;
                if let (Some((words, count)), Some(slot)) =
                    (painted, field.spec.placeholder.as_mut())
                {
                    if empty {
                        lines = lines.max(count);
                    }
                    *slot = words;
                }
                if field.spec.input.is_none()
                    && let Some(value) = field
                        .spec
                        .visual_value
                        .as_mut()
                        .filter(|value| !value.is_empty())
                {
                    let (shown, count) = field_value_lines(value, words_room);
                    lines = lines.max(count);
                    *value = shown;
                }
                return Some(lines.saturating_sub(1) + usize::from(chip_line));
            }
            if let Some(extra) = fit(child, room, unset, held) {
                return Some(extra);
            }
        }
        None
    }
    if let Some(extra) = fit(row, text_width, unset, held).filter(|extra| *extra > 0) {
        grow_row(
            row,
            extra as f32 * crate::native_ui::native_button_line_height(),
        );
    }
}

fn field_placeholder_lines(placeholder: &str, width: f32, swatch: bool) -> (String, usize) {
    let fitted = crate::native_ui::fit_native_field_placeholder(placeholder, width, swatch);
    let plain = crate::native_ui::plain_placeholder(placeholder);
    let path = crate::native_ui::reads_as_path(placeholder);
    let drops_words = if path {
        fitted.ends_with('\u{2026}')
    } else {
        fitted != placeholder
            && fitted != plain
            && placeholder.strip_suffix(" (default)") != Some(fitted.as_str())
    };
    if !drops_words {
        return (fitted, 1);
    }
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let room = crate::native_ui::field_placeholder_room(width, swatch);
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    let words_beside_chip = plain
        .split_whitespace()
        .all(|word| measure(word) <= room + crate::native_ui::TEXT_FIT_SLACK);
    if swatch && !path && !words_beside_chip {
        return (String::new(), 1);
    }
    let lines = if path {
        path_placeholder_lines(placeholder, room, &measure)
    } else {
        word_placeholder_lines(&plain, room, &measure, field_lines_most())
    };
    let count = lines.len().max(1);
    (lines.join("\n"), count)
}

fn field_value_lines(value: &str, room: f32) -> (String, usize) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    if value.contains('\n') {
        return (value.to_string(), value.split('\n').count());
    }
    if measure(value) <= room + crate::native_ui::TEXT_FIT_SLACK {
        return (value.to_string(), 1);
    }
    let lines = if crate::native_ui::reads_as_path(value) {
        path_placeholder_lines(value, room, &measure)
    } else {
        word_placeholder_lines(value, room, &measure, field_lines_most())
    };
    let count = lines.len().max(1);
    (lines.join("\n"), count)
}

fn unset_field_words(state: &SettingsViewState, field: &EditField) -> Option<String> {
    if field.seed.is_none() {
        return Some(field_placeholder(state, field).0);
    }
    let words = modified_default_words(state, field.key)?;
    let placeholder = if words.contains("(default)") {
        words
    } else {
        format!("{words} (default)")
    };
    let unset = EditField {
        label: field.label,
        key: field.key,
        kind: field.kind,
        seed: None,
        placeholder,
    };
    Some(field_placeholder(state, &unset).0)
}

fn path_placeholder_lines(path: &str, room: f32, measure: &dyn Fn(&str) -> f32) -> Vec<String> {
    let start = crate::native_ui::path_name_start(path);
    let tail = format!(
        "{}{}",
        crate::native_ui::TEXT_FIELD_ELLIPSIS,
        &path[start.saturating_sub(1)..]
    );
    std::iter::once(path.to_string())
        .chain(
            crate::native_ui::path_forms(path)
                .into_iter()
                .map(|(form, _, _)| form),
        )
        .map(|form| wrap_to_box(&form, room, measure))
        .find(|lines| lines.len() <= 2)
        .unwrap_or_else(|| wrap_to_box(&tail, room, measure))
}

fn word_placeholder_lines(
    plain: &str,
    room: f32,
    measure: &dyn Fn(&str) -> f32,
    most: usize,
) -> Vec<String> {
    let most = most.max(1);
    let whole = wrap_to_box(plain, room, measure);
    if whole.len() <= most {
        return whole;
    }
    let words: Vec<&str> = plain.split_whitespace().collect();
    (1..words.len())
        .rev()
        .find_map(|n| {
            let lines = wrap_to_box(
                &format!(
                    "{}{}",
                    words[..n].join(" "),
                    crate::native_ui::TEXT_FIELD_ELLIPSIS
                ),
                room,
                measure,
            );
            (lines.len() <= most).then_some(lines)
        })
        .unwrap_or(whole)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BoundedNumericDisclosure {
    semantic: String,
    visual: String,
}

fn numeric_slider_value(field: &EditField) -> Option<(f64, String)> {
    let range = prefs::range_of(field.key)?;
    let raw = SettingsState::display_value(field);
    let token = raw.split_whitespace().next().unwrap_or(raw);
    let configured = token.parse::<f64>().ok()?;
    if !configured.is_finite() {
        let (effective, _) = bounded_numeric_nonfinite_effective(field.key)?;
        return Some((effective, compact_f64(effective)));
    }
    if (range.min..=range.max).contains(&configured) {
        return Some((configured, compact_f64(configured)));
    }

    let effective = if field.key == prefs::EDIT_FONT_PX {
        f64::from(crate::FONT_PX)
    } else {
        configured.clamp(range.min, range.max)
    };
    Some((effective, compact_f64(effective)))
}

fn bounded_numeric_nonfinite_effective(key: &str) -> Option<(f64, &'static str)> {
    Some(match key {
        prefs::EDIT_FONT_PX => (f64::from(crate::FONT_PX), "default"),
        prefs::EDIT_LINE_HEIGHT => (
            f32_as_shown(crate::app_config::DEFAULT_LINE_HEIGHT),
            "default",
        ),
        prefs::EDIT_FONT_SIZE_SCALE => (1.0, "default"),
        prefs::EDIT_MINIMUM_CONTRAST => (1.0, "default"),
        prefs::EDIT_FAINT_OPACITY => (f64::from(aterm_types::DIM_FACTOR), "default"),
        prefs::EDIT_STEM_GAMMA => (1.0, "identity default"),
        prefs::EDIT_CURSOR_TRAIL_INTENSITY
        | prefs::EDIT_CURSOR_TRAIL_RADIUS
        | prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH
        | prefs::EDIT_CURSOR_GLOW_SDR_BOOST
        | prefs::EDIT_FONT_WEIGHT_DARK_NUDGE
        | "sparkle_words.profanity.intensity"
        | "sparkle_words.feline.intensity"
        | "sparkle_words.ink.strength" => (0.0, "off"),
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS => (
            f32_as_shown(Config::CURSOR_TRAIL_BLOOM_RADIUS_DEFAULT),
            "style default",
        ),
        prefs::EDIT_TRAIL_SOUND_VOLUME => (0.0, "muted"),
        prefs::EDIT_BACKGROUND_OPACITY => (1.0, "solid default"),
        prefs::EDIT_WALLPAPER_DIM => (0.3, "default"),
        prefs::EDIT_WINDOW_PADDING => (f64::from(crate::PAD_LOGICAL_PX), "default"),
        prefs::EDIT_WINDOW_PADDING_TOP => (f64::from(crate::PAD_TOP_LOGICAL_PX), "default"),
        _ => return None,
    })
}

fn f32_as_shown(value: f32) -> f64 {
    value.to_string().parse().unwrap_or(f64::from(value))
}

fn preview_bloom_radius_style_default(state: &SettingsViewState) -> f32 {
    let style = field_text(
        state,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        crate::app_config::default_cursor_trail_style(),
    );
    Config::bloom_radius_style_default(crate::app_config::resolve_trail_style(&style))
}

fn numeric_slider_value_for_state(
    state: &SettingsViewState,
    field: &EditField,
) -> Option<(f64, String)> {
    let projected = numeric_slider_value(field)?;
    let configured = field
        .seed
        .as_deref()
        .and_then(|seed| seed.parse::<f64>().ok());
    if field.key == prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS {
        if configured.is_some_and(f64::is_finite) {
            return Some(projected);
        }
        let effective = f32_as_shown(preview_bloom_radius_style_default(state));
        return Some((effective, compact_f64(effective)));
    }
    if field.key != prefs::EDIT_WINDOW_PADDING_TOP {
        return Some(projected);
    }
    let base = f64::from(window_padding_sides(state));
    let effective = configured
        .filter(|value| value.is_finite())
        .unwrap_or(f64::from(crate::PAD_TOP_LOGICAL_PX))
        .min(base);
    Some((effective, compact_f64(effective)))
}

fn bounded_numeric_disclosure(
    state: &SettingsViewState,
    field: &EditField,
    environment_override: bool,
) -> Option<BoundedNumericDisclosure> {
    let range = prefs::range_of(field.key)?;
    let raw = field.seed.as_deref()?;
    let token = raw.split_whitespace().next().unwrap_or(raw);
    let configured = token.parse::<f64>().ok()?;
    if !configured.is_finite() {
        let (mut effective, outcome) = bounded_numeric_nonfinite_effective(field.key)?;
        if field.key == prefs::EDIT_WINDOW_PADDING_TOP
            || field.key == prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS
        {
            effective = numeric_slider_value_for_state(state, field)?.0;
        }
        let effective = compact_f64(effective);
        let qualifier = if environment_override {
            "; a higher-priority environment value remains active"
        } else {
            ""
        };
        return Some(BoundedNumericDisclosure {
            semantic: format!(
                "configured {token} is non-finite; runtime uses {effective} ({outcome}){qualifier}"
            ),
            visual: format!("Configured {token} → Effective {effective} ({outcome})"),
        });
    }
    if (range.min..=range.max).contains(&configured) {
        return None;
    }

    let read = |value: f64| slider_readout(field.key, value, compact_f64(value));
    let configured = read(configured);
    let bounds = format!("{}–{}", read(range.min), read(range.max));
    if field.key == prefs::EDIT_FONT_PX {
        let fallback = read(f64::from(crate::FONT_PX));
        let qualifier = if environment_override {
            "; a higher-priority environment value remains active"
        } else {
            ""
        };
        return Some(BoundedNumericDisclosure {
            semantic: format!(
                "configured {configured} is outside {bounds} and is ignored; config resolution falls through to the {fallback} default{qualifier}"
            ),
            visual: format!("Configured {configured} → Default {fallback}"),
        });
    }

    let effective = read(
        token
            .parse::<f64>()
            .expect("finite numeric token was parsed above")
            .clamp(range.min, range.max),
    );
    let runtime = if environment_override {
        "the config source clamps"
    } else {
        "runtime clamps"
    };
    Some(BoundedNumericDisclosure {
        semantic: format!(
            "configured {configured}; {runtime} it to {effective} (allowed {bounds})"
        ),
        visual: format!("Configured {configured} → Effective {effective}"),
    })
}

fn slider_readout(key: &str, numeric: f64, shown: String) -> String {
    prefs::numeric_reading(key, numeric, &shown).unwrap_or(shown)
}

fn slider_domain(state: &SettingsViewState, key: &str) -> Option<prefs::Range> {
    let range = prefs::range_of(key)?;
    if key == prefs::EDIT_WINDOW_PADDING_TOP {
        return Some(prefs::Range {
            max: f64::from(window_padding_sides(state)).max(range.min),
            ..range
        });
    }
    Some(range)
}

fn slider_track(key: &str, domain: prefs::Range, value: f64) -> Option<(f64, f64)> {
    if key != prefs::EDIT_FONT_PX {
        return None;
    }
    let value = if value.is_finite() {
        value
    } else {
        f64::from(crate::FONT_PX)
    };
    Some((
        FONT_SIZE_SLIDER_SPAN.0.min(value.floor()).max(domain.min),
        FONT_SIZE_SLIDER_SPAN.1.max(value.ceil()).min(domain.max),
    ))
}

const FONT_SIZE_SLIDER_SPAN: (f64, f64) = (8.0, 36.0);

fn bounded_numeric_submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    let range = prefs::range_of(field.key)?;
    let raw = raw?.trim();
    if raw.is_empty() {
        return None;
    }
    let read = |value: f64| slider_readout(field.key, value, compact_f64(value));
    let (min, max) = (read(range.min), read(range.max));
    let Some(value) = raw.parse::<f64>().ok().filter(|value| value.is_finite()) else {
        return Some(format!(
            "{} must be a number from {min} to {max}; {raw:?} was not saved",
            field.label
        ));
    };
    (!(range.min..=range.max).contains(&value)).then(|| {
        format!(
            "{} must be between {min} and {max}; {} was not saved",
            field.label,
            read(value)
        )
    })
}

fn window_top_submission_error(
    view: &SettingsViewState,
    field: &EditField,
    raw: Option<&str>,
) -> Option<String> {
    if field.key != prefs::EDIT_WINDOW_PADDING_TOP {
        return None;
    }
    let value = raw?.trim().parse::<f32>().ok()?;
    let sides = window_padding_sides(view);
    let read = |px: f32| slider_readout(field.key, f64::from(px), compact_number(px));
    (value > sides + f32::EPSILON).then(|| {
        format!(
            "{} can't be more than Sides and bottom ({}); {} was not saved",
            field.label,
            read(sides),
            read(value)
        )
    })
}

fn color_submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    let raw = raw?.trim();
    (field.kind == EditKind::Color
        && !raw.is_empty()
        && !prefs::color_value_is_valid(field.key, raw))
    .then(|| {
        let takes = if field.key == prefs::EDIT_CURSOR_TRAIL_COLOR {
            format!(
                "a hex color like #D0D0D0, or {} for the cursor's color",
                prefs::TRAIL_COLOR_CURSOR
            )
        } else {
            "a hex color like #D0D0D0".to_string()
        };
        format!("{} needs {takes}; {raw:?} was not saved", field.label)
    })
}

fn submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    if let Some(message) =
        bounded_numeric_submission_error(field, raw).or_else(|| color_submission_error(field, raw))
    {
        return Some(message);
    }
    let raw = raw?.trim();
    if raw.is_empty() {
        return None;
    }
    let error = prefs::check_edit_value(field.key, raw).err()?;
    let label = field.label;
    Some(match (field.kind, error) {
        (EditKind::Integer, _) => format!(
            "{label} must be {}; {raw:?} was not saved",
            prefs::integer_requirement(field.key, raw)
        ),
        (EditKind::Float, prefs::PrefsEditError::OutOfRange { range, .. }) => {
            let range = range.replace("..=", " to ");
            format!("{label} must be from {range}; {raw:?} was not saved")
        }
        (EditKind::Float, _) => format!("{label} must be a number; {raw:?} was not saved"),
        (EditKind::Color, _) => {
            format!("{label} must be a color such as #1e1e2e; {raw:?} was not saved")
        }
        _ => format!("{label} can't be {raw:?}; it was not saved"),
    })
}

fn compact_f64(value: f64) -> String {
    if value.fract().abs() <= f64::EPSILON {
        format!("{value:.0}")
    } else {
        value.to_string()
    }
}

fn slider_edits(view: &SettingsViewState, key: &str, value: String) -> Vec<ConfigEdit> {
    let value = Some(value);
    let mut edits = vec![ConfigEdit {
        key: key.to_string(),
        expected: ExpectedConfigValue::Exact(view.raw_value(key)),
        value: value.clone(),
    }];
    edits.extend(window_top_follows_sides(view, key, value.as_deref()));
    edits
}

fn normalize_slider_value(value: f64, range: prefs::Range) -> Option<String> {
    if !value.is_finite() || !range.step.is_finite() || range.step <= 0.0 {
        return None;
    }
    Some(compact_f64(crate::native_ui::snap_slider_value(
        value, range.min, range.max, range.step,
    )))
}

fn about_page(
    state: &SettingsViewState,
    messages: &MessagesState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> Vec<UiNode> {
    let (viewport_width, viewport_height) = (viewport.width, viewport.height);
    let about = &state.about;
    let text_scale = settings_text_scale();
    let viewport = LogicalRect::new(0.0, 0.0, viewport_width, viewport_height);
    let gap = settings_page_gap(state, width, viewport);
    let (heading, heading_height) = pinned_heading(state, width, viewport, gap, "About", "");
    let room = (settings_list_body_height(state, width, viewport) - heading_height)
        .max(scaled_control_height());
    let value = |wanted: &str, fallback: &str| {
        about
            .semantic_rows()
            .iter()
            .find(|(key, _)| *key == wanted)
            .map_or_else(|| fallback.to_string(), |(_, value)| value.clone())
    };
    let content =
        settings_page_content_width(viewport_width, width, PageLayout::Form.maximum(width));
    let hero_inner = (content - 48.0).max(0.0);
    let short_wordmark_width = {
        let (px, face) = crate::native_ui::wordmark_typography("aterm", f32::INFINITY);
        (crate::tray_raster::ui_text_width_for(face, "aterm", px.get()) + 8.0).ceil()
    };
    let (copy_visual, copy_lines) =
        button_words("Copy Build Information", &["Copy Build"], hero_inner);
    let (site_visual, site_lines) = button_words("Open Project Site", &["Open Site"], hero_inner);
    let site_label = if painted_words(&site_visual) == "Open Site" {
        "Open Site"
    } else {
        "Open Project Site"
    };
    let button_width = |visual: &str, lines: usize| {
        if lines > 1 {
            hero_inner
        } else {
            page_button_width(visual, hero_inner)
        }
    };
    let copy_width = button_width(&copy_visual, copy_lines);
    let site_width = button_width(&site_visual, site_lines);
    let actions_in_row =
        copy_lines == 1 && site_lines == 1 && copy_width + 8.0 + site_width <= hero_inner;
    let row_actions_height = 40.0_f32.max(32.0 * text_scale);
    let copy_height =
        crate::native_ui::native_button_height_for_lines(copy_lines, scaled_control_height());
    let site_height =
        crate::native_ui::native_button_height_for_lines(site_lines, scaled_control_height());
    let compact_actions_height = if actions_in_row {
        row_actions_height
    } else {
        copy_height + site_height + 8.0
    };
    let hero_actions = UiNode::new(
        "about/actions",
        UiContent::Group(GroupSpec::new("About actions")),
    )
    .layout(if actions_in_row {
        Layout::row()
            .height(Length::Fixed(row_actions_height))
            .gap(8.0)
    } else {
        Layout::column()
            .height(Length::Fixed(compact_actions_height))
            .gap(8.0)
    })
    .children(vec![
        UiNode::new(
            "about/copy-build-info",
            UiContent::Button(
                Control::new(
                    ButtonSpec::new("Copy Build Information").visual_label(copy_visual),
                    ActionId::new("about/copy-build-info"),
                )
                .style(StyleRef::Primary),
            ),
        )
        .layout(Layout::default().width(Length::Fixed(copy_width)).height(
            if actions_in_row {
                Length::Fill
            } else {
                Length::Fixed(copy_height)
            },
        )),
        UiNode::new(
            "about/open-site",
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(site_label).visual_label(site_visual),
                    ActionId::new("about/open-site"),
                )
                .state(ControlState {
                    enabled: crate::about::site_url(about).is_some(),
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
            ),
        )
        .layout(Layout::default().width(Length::Fixed(site_width)).height(
            if actions_in_row {
                Length::Fill
            } else {
                Length::Fixed(site_height)
            },
        )),
    ]);
    let wordmark_base_height = 38.0_f32.max(30.0 * text_scale);
    let wordmark_fit = {
        let natural = crate::native_ui::wordmark_typography("aterm", f32::INFINITY).0;
        crate::native_ui::wordmark_typography("aterm", hero_inner)
            .0
            .get()
            / natural.get()
    };
    let wordmark_height = (wordmark_base_height * wordmark_fit).ceil();
    let status_height = 20.0_f32.max(18.0 * text_scale);
    let capability_height = 22.0_f32.max(18.0 * text_scale);
    let wordmark = UiNode::new(
        "about/wordmark",
        UiContent::Custom(AuditedCustomNode {
            audit_id: crate::native_ui::WORDMARK_AUDIT,
            role: SemanticRole::Heading,
            label: "aterm".to_string(),
            value: None,
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(Layout::default().height(Length::Fixed(wordmark_height)));
    let tagline_text = value("tagline", crate::build_info::TAGLINE);
    let tagline_in = |column: f32| {
        let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Plain);
        tagline_text
            .split_whitespace()
            .all(|word| crate::tray_raster::ui_text_width(word, px) <= column)
            .then(|| {
                wrapped_copy_node(
                    "about/tagline",
                    &tagline_text,
                    SemanticRole::Text,
                    StyleRef::Plain,
                    column,
                    26.0_f32.max(20.0 * text_scale),
                    None,
                )
            })
    };
    let version_text = format!("Version {}", value("version", "development"));
    let version_in = |column: f32| {
        wrapped_words_node(
            "about/version-summary",
            &version_text,
            (SemanticRole::Status, StyleRef::Quiet),
            column,
            status_height,
        )
    };
    let site = value("site", "");
    let byline_in = |column: f32| {
        let px = 13.0 * text_scale;
        let fits = |line: &str| crate::tray_raster::ui_text_width(line, px) <= column;
        let author_company = crate::build_info::AUTHOR_COMPANY_BYLINE;
        let full = (!site.is_empty()).then(|| format!("{author_company} \u{00b7} {site}"));
        let ladder = [
            full.as_deref().unwrap_or_default(),
            author_company,
            aterm_types::identity::AUTHOR,
            crate::build_info::AUTHOR_SHORT,
        ];
        ladder
            .iter()
            .position(|form| !form.is_empty() && fits(form))
            .map(|rung| (rung, ladder[rung].to_string()))
    };
    let hero_vertical_padding = if width == SettingsWidth::Compact {
        12.0
    } else {
        20.0
    };
    let full_hero_height = {
        let tagline = tagline_in(hero_inner).map_or(0.0, |(_, height)| height);
        let byline = byline_in(hero_inner).map_or(0.0, |_| capability_height);
        let children = 2 + usize::from(tagline > 0.0) + usize::from(byline > 0.0);
        wordmark_height
            + tagline
            + version_in(hero_inner).1
            + byline
            + hero_vertical_padding * 2.0
            + (children - 1) as f32 * 6.0
            + 6.0
            + compact_actions_height
    };
    let short_column = (content - 24.0 - short_wordmark_width - 8.0).max(0.0);
    let version_fits_short = {
        let (px, face) =
            crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Quiet);
        crate::tray_raster::ui_text_width_for(
            face,
            &format!("Version {}", value("version", "development")),
            px,
        ) <= short_column
    };
    let short_fits = {
        let tagline = tagline_in(short_column).map_or(0.0, |(_, height)| height);
        let byline = byline_in(short_column).map_or(0.0, |_| capability_height);
        let lines = usize::from(tagline > 0.0) + 1 + usize::from(byline > 0.0);
        let words =
            tagline + version_in(short_column).1 + byline + lines.saturating_sub(1) as f32 * 4.0;
        wordmark_base_height.max(words) + hero_vertical_padding * 2.0 <= room + 0.01
    };
    let short_compact = width == SettingsWidth::Compact
        && full_hero_height > room + 0.01
        && version_fits_short
        && short_fits;
    let text_column = if short_compact {
        short_column
    } else {
        hero_inner
    };
    let (version_summary, status_height) = version_in(text_column);
    let tagline = tagline_in(text_column);
    let tagline_height = tagline.as_ref().map_or(0.0, |(_, height)| *height);
    let tagline = tagline.map(|(node, _)| node);
    let byline = byline_in(text_column);
    let byline_names: &[&str] = match byline.as_ref().map(|(rung, _)| *rung) {
        Some(0) => &["author", "company", "site"],
        Some(1) => &["author", "company"],
        Some(_) => &["author"],
        None => &[],
    };
    let byline = byline.map(|(_, text)| text);
    let capability_height = if byline.is_some() {
        capability_height
    } else {
        0.0
    };
    let capabilities = byline.map(|text| {
        UiNode::new(
            "about/byline",
            UiContent::Text(TextSpec {
                text,
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(capability_height)))
    });
    let (mut hero_children, identity_height) = if short_compact {
        let wordmark_height = wordmark_base_height;
        let mut wordmark = wordmark;
        wordmark.layout.width = Length::Fixed(short_wordmark_width);
        wordmark.layout.height = Length::Fixed(wordmark_height);
        let lines = usize::from(tagline.is_some()) + 1 + usize::from(capabilities.is_some());
        let detail_height = tagline_height
            + status_height
            + capability_height
            + lines.saturating_sub(1) as f32 * 4.0;
        let details = UiNode::new(
            "about/compact-identity",
            UiContent::Group(GroupSpec::new("About summary")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(detail_height))
                .gap(4.0),
        )
        .children(
            tagline
                .into_iter()
                .chain([version_summary])
                .chain(capabilities)
                .collect(),
        );
        let height = wordmark_height.max(detail_height);
        (
            vec![
                UiNode::new(
                    "about/identity-row",
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(Layout::row().height(Length::Fixed(height)).gap(8.0))
                .children(vec![wordmark, details]),
            ],
            height,
        )
    } else {
        (
            [Some(wordmark), tagline, Some(version_summary)]
                .into_iter()
                .flatten()
                .chain(capabilities)
                .collect::<Vec<_>>(),
            wordmark_height + tagline_height + status_height + capability_height,
        )
    };
    let identity_block = identity_height
        + hero_vertical_padding * 2.0
        + hero_children.len().saturating_sub(1) as f32 * 6.0;
    let split_compact_actions =
        width == SettingsWidth::Compact && identity_block + 6.0 + compact_actions_height > room;
    let hero_height = if split_compact_actions {
        identity_block
    } else {
        hero_children.push(hero_actions.clone());
        identity_block + 6.0 + compact_actions_height
    };
    let hero = UiNode::new(
        "about/hero",
        UiContent::Group(GroupSpec::new("About aterm").style(StyleRef::Primary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(hero_height))
            .padding(Insets::symmetric(
                if short_compact { 12.0 } else { 24.0 },
                hero_vertical_padding,
            ))
            .gap(6.0),
    )
    .children(hero_children);

    let tagline_painted = tagline_height > 0.0;
    let build_rows = about
        .semantic_rows()
        .iter()
        .filter(|(key, _)| !((*key == "tagline" && tagline_painted) || byline_names.contains(key)))
        .map(|(key, value)| ((*key).to_string(), about_fact_value(key, value, messages)))
        .collect::<Vec<_>>();
    let (build, card_height) = metadata_card(
        "about/provenance",
        caption_words("BUILD INFORMATION", "BUILD INFO", card_text_width(content)),
        &build_rows,
        content,
        about_metadata_label_width(),
    );
    let mut sections = vec![ListItem::of(hero, hero_height)];
    if split_compact_actions {
        sections.push(ListItem::of(hero_actions, compact_actions_height));
    }
    sections.push(ListItem::of(build, card_height));
    let credit_rows = aterm_render::DISPLAY_FACES
        .iter()
        .map(|face| (face.label.to_string(), face.face.to_string()))
        .collect::<Vec<_>>();
    let (credits, credits_height) = metadata_card(
        "about/font-credits",
        "FONT CREDITS",
        &credit_rows,
        content,
        about_metadata_label_width(),
    );
    sections.push(ListItem::of(credits, credits_height));
    let mut out = heading;
    out.push(scroll::list_page_peeking(
        state,
        "about/list",
        "About aterm",
        sections,
        room,
        gap,
        settings_list_overhang(state, width, viewport),
    ));
    out
}

const ABOUT_METADATA_CARD_PADDING: f32 = 18.0;

fn card_side_padding(card_width: f32) -> f32 {
    let em = 13.0 * settings_text_scale();
    if card_width - 2.0 * ABOUT_METADATA_CARD_PADDING >= 16.0 * em {
        ABOUT_METADATA_CARD_PADDING
    } else {
        NARROW_CARD_PADDING
    }
}

const NARROW_CARD_PADDING: f32 = 12.0;

fn card_text_width(card_width: f32) -> f32 {
    (card_width - 2.0 * card_side_padding(card_width)).max(0.0)
}

const ABOUT_METADATA_LABEL_WIDTH: f32 = 104.0;
const ABOUT_METADATA_ROW_GAP: f32 = 10.0;
const ABOUT_METADATA_TEXT_SAFETY: f32 = 4.0;

fn about_metadata_label_width() -> f32 {
    ABOUT_METADATA_LABEL_WIDTH * settings_text_scale().min(1.2)
}

fn fact_label_width(rows: &[(String, String)], inner: f32) -> f32 {
    let px = 13.0 * crate::native_appearance::text_scale();
    let label = rows
        .iter()
        .map(|(label, _)| metadata_value_text_width(about_fact_label(label), px, false))
        .fold(0.0_f32, f32::max)
        + ABOUT_METADATA_TEXT_SAFETY;
    let word = rows
        .iter()
        .filter(|(label, _)| !metadata_value_is_code(label))
        .flat_map(|(_, value)| value_words(value))
        .map(|word| metadata_value_text_width(word, px, false))
        .fold(0.0_f32, f32::max)
        + ABOUT_METADATA_TEXT_SAFETY;
    about_metadata_label_width().max(label.min(inner - ABOUT_METADATA_ROW_GAP - word))
}

fn value_words(value: &str) -> impl Iterator<Item = &str> {
    value
        .split(FACT_SEPARATOR)
        .flat_map(|segment| segment.split(' '))
        .flat_map(|word| word.split_inclusive('/'))
}

fn caption_words<'a>(full: &'a str, short: &'a str, width: f32) -> &'a str {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let one_line = |text: &str| {
        crate::tray_raster::ui_text_width_for(face, text, px)
            <= width + crate::native_ui::TEXT_FIT_SLACK
    };
    if one_line(full) || !one_line(short) {
        full
    } else {
        short
    }
}

fn about_fact_label(key: &str) -> &str {
    match key {
        "version" => "Version",
        "build" => "Build",
        "commit" => "Commit",
        "built" => "Built",
        "arch" => "Architecture",
        "compiler" => "Compiler",
        "signature" => "Signature",
        "running" => "Running from",
        "another copy" => "Other copy",
        "tagline" => "About",
        "author" => "Author",
        "company" => "Company",
        "site" => "Website",
        other => other,
    }
}

fn about_fact_value(key: &str, value: &str, clock: &MessagesState) -> String {
    if key != "built" {
        return value.to_string();
    }
    let Some(built) = aterm_types::rfc3339::parse_utc(value.trim()) else {
        return value.to_string();
    };
    let built_ms = u64::try_from(built).unwrap_or(0).saturating_mul(1000);
    if clock.now_unix_ms == 0 {
        let (date, time) = value
            .trim()
            .trim_end_matches('Z')
            .split_once('T')
            .unwrap_or_default();
        return format!("{date} {} UTC", time.get(..5).unwrap_or(time));
    }
    aterm_messages::words::local_words(clock.now_unix_ms, built_ms, clock.utc_offset_s)
}

const fn metadata_value_is_code(label: &str) -> bool {
    label.eq_ignore_ascii_case("commit") || label.eq_ignore_ascii_case("build")
}

fn metadata_value_text_width(text: &str, px: f32, code: bool) -> f32 {
    if code {
        crate::tray_raster::measure_text(text, px, crate::widget::TextWeight::Regular)
    } else {
        crate::tray_raster::ui_text_width(text, px)
    }
}

const MAX_METADATA_VALUE_LINES: usize = 64;

/// A text's line pieces as byte ranges, each marked whether a space comes before it.
type PieceCut = Arc<[(bool, std::ops::Range<usize>)]>;

fn line_pieces(text: &str) -> Vec<(&str, &str)> {
    thread_local! {
        /// Each text's pieces as byte ranges: the cut is a pure function of
        /// the text, and every render lays out the same rows again.
        static CUTS: RefCell<aterm_hash::FxHashMap<Box<str>, PieceCut>> =
            RefCell::new(aterm_hash::FxHashMap::default());
    }
    let cut = CUTS.with_borrow(|cuts| cuts.get(text).cloned());
    let cut = cut.unwrap_or_else(|| {
        let cut: PieceCut = line_piece_ranges(text).into();
        CUTS.with_borrow_mut(|cuts| {
            if cuts.len() >= 4_096 {
                cuts.clear();
            }
            cuts.insert(text.into(), cut.clone());
        });
        cut
    });
    cut.iter()
        .map(|(spaced, range)| (if *spaced { " " } else { "" }, &text[range.clone()]))
        .collect()
}

fn line_piece_ranges(text: &str) -> Vec<(bool, std::ops::Range<usize>)> {
    let separator = FACT_SEPARATOR.trim();
    let mut pieces: Vec<(bool, std::ops::Range<usize>)> = Vec::new();
    for piece in aterm_grapheme::pieces(text, |_| true) {
        let end = piece.at + piece.text.len();
        if piece.text == separator
            && let Some(joined) = pieces.last_mut()
        {
            joined.1.end = end;
            continue;
        }
        pieces.push((piece.spaced, piece.at..end));
    }
    pieces
}

/// `text`'s lines in a box `width` wide.
pub(crate) fn wrap_to_box(text: &str, width: f32, measure: &dyn Fn(&str) -> f32) -> Vec<String> {
    wrap_to_box_marked(text, width, measure, "-")
}

fn wrap_to_box_marked(
    text: &str,
    width: f32,
    measure: &dyn Fn(&str) -> f32,
    mark: &str,
) -> Vec<String> {
    wrap_to_box_from(text, width, measure, mark)
        .into_iter()
        .map(|(_, line)| line)
        .collect()
}

fn wrap_to_box_from(
    text: &str,
    width: f32,
    measure: &dyn Fn(&str) -> f32,
    mark: &str,
) -> Vec<(usize, String)> {
    let fits = |line: &str| measure(line) <= width + crate::native_ui::TEXT_FIT_SLACK;
    let at = |piece: &str| piece.as_ptr() as usize - text.as_ptr() as usize;
    let mut lines: Vec<(usize, String)> = Vec::new();
    let mut line = String::new();
    let mut line_at = 0;
    for (joiner, piece) in line_pieces(text) {
        let candidate = if line.is_empty() {
            piece.to_string()
        } else {
            format!("{line}{joiner}{piece}")
        };
        if fits(&candidate) {
            if line.is_empty() {
                line_at = at(piece);
            }
            line = candidate;
            continue;
        }
        let mut start = at(piece);
        let end = start + piece.len();
        if !line.is_empty() {
            let after_a_lone_letter = is_a_lone_letter(&line)
                && aterm_grapheme::token_kind(piece.split_whitespace().next().unwrap_or(piece))
                    == aterm_grapheme::TokenKind::Word;
            if (!fits(piece) || after_a_lone_letter)
                && let Some((rest, part)) = aterm_grapheme::break_into_line(
                    text,
                    start..end,
                    mark,
                    &|part| fits(&format!("{line}{joiner}{part}")),
                    &fits,
                )
            {
                line.push_str(joiner);
                line.push_str(&part);
                start = rest;
            }
            lines.push((line_at, std::mem::take(&mut line)));
        }
        if fits(&text[start..end]) {
            line = text[start..end].to_string();
            line_at = start;
            continue;
        }
        let mut broken = aterm_grapheme::break_inside(text, start..end, mark, &fits);
        let (tail_at, tail) = broken.pop().unwrap_or((start, String::new()));
        lines.extend(broken);
        line_at = tail_at;
        line = tail;
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push((line_at, line));
    }
    lines
}

fn is_a_lone_letter(line: &str) -> bool {
    let mut graphemes = line.trim().graphemes();
    matches!(
        (graphemes.next(), graphemes.next()),
        (Some(one), None) if one.chars().all(|c| {
            c.is_alphabetic() && !crate::tray_raster::is_east_asian(c)
        })
    )
}

fn pieces_fit(text: &str, width: f32, measure: &dyn Fn(&str) -> f32) -> bool {
    line_pieces(text)
        .iter()
        .all(|(_, piece)| measure(piece) <= width + crate::native_ui::TEXT_FIT_SLACK)
}

fn fact_name_width(text: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    crate::tray_raster::ui_text_width_for(face, text, px)
}

/// FACTS SIT BESIDE THEIR NAMES until a word cannot, or until that takes
/// more lines than a name over its fact: the column a long name leaves its
/// fact wraps the fact into a column of words (Packages' Background service
/// at 444pt with 2× text in Windows' face: six lines beside, a 256pt row in
/// the list's 212pt room, never whole on any screen).
#[derive(Clone, Copy, Debug, PartialEq)]
struct FactColumns {
    label: f32,
    value: f32,
    stacked: bool,
}

impl FactColumns {
    fn measure(rows: &[(String, String)], inner: f32, label_width: f32) -> Self {
        let inner = inner.max(0.0);
        let widest = rows
            .iter()
            .flat_map(|(name, _)| line_pieces(about_fact_label(name)))
            .map(|(_, piece)| fact_name_width(piece))
            .fold(0.0_f32, f32::max);
        let label = label_width.max(widest.min(inner * 0.4)).min(inner);
        let value = (inner - label - ABOUT_METADATA_ROW_GAP).max(0.0);
        let px = 13.0 * crate::native_appearance::text_scale();
        let fits = rows.iter().all(|(name, text)| {
            let code = metadata_value_is_code(name);
            pieces_fit(about_fact_label(name), label, &fact_name_width)
                && if code {
                    metadata_value_text_width(text, px, true)
                        <= value + crate::native_ui::TEXT_FIT_SLACK
                } else {
                    pieces_fit(text, value, &|piece| {
                        metadata_value_text_width(piece, px, false)
                    })
                }
        });
        let beside = Self {
            label,
            value,
            stacked: false,
        };
        let stacked = Self {
            label: inner,
            value: inner,
            stacked: true,
        };
        if fits && beside.lines(rows) <= stacked.lines(rows) {
            beside
        } else {
            stacked
        }
    }

    /// The lines `rows` take in these columns: a name and its fact side by
    /// side take the taller of the two, stacked they take both.
    fn lines(self, rows: &[(String, String)]) -> usize {
        rows.iter()
            .map(|(name, text)| {
                let (names, facts) = fact_card_lines(name, text, self);
                let (names, facts) = (names.len().max(1), facts.len().max(1));
                if self.stacked {
                    names + facts
                } else {
                    names.max(facts)
                }
            })
            .sum()
    }
}

fn metadata_value_lines(label: &str, value: &str, value_width: f32) -> Vec<String> {
    let budget = value_width.max(0.0);
    let code = metadata_value_is_code(label);
    let px = 13.0 * crate::native_appearance::text_scale();
    let measure = |line: &str| metadata_value_text_width(line, px, code);
    let fits = |line: &str| measure(line) <= budget + crate::native_ui::TEXT_FIT_SLACK;
    if fits(value) {
        return vec![value.to_string()];
    }
    if code {
        return wrap_to_box_marked(value, budget, &measure, "");
    }
    let mut lines: Vec<String> = Vec::new();
    let mut after_wrap = false;
    for part in value.split(FACT_SEPARATOR) {
        if !fits(part) {
            lines.extend(wrap_to_box(part, budget, &measure));
            after_wrap = true;
            continue;
        }
        match lines.last_mut() {
            Some(line) if !after_wrap && fits(&format!("{line}{FACT_SEPARATOR}{part}")) => {
                line.push_str(FACT_SEPARATOR);
                line.push_str(part);
            }
            _ => lines.push(part.to_string()),
        }
        after_wrap = false;
    }
    if lines.len() > MAX_METADATA_VALUE_LINES {
        lines.truncate(MAX_METADATA_VALUE_LINES);
        if let Some(last) = lines.pop() {
            lines.push(elide_wrapped_copy_tail(
                &last,
                px,
                crate::widget::TextFace::Ui,
                budget,
            ));
        }
    }
    lines
}

fn fact_card_lines(label: &str, value: &str, columns: FactColumns) -> (Vec<String>, Vec<String>) {
    (
        wrap_to_box(about_fact_label(label), columns.label, &fact_name_width),
        metadata_value_lines(label, value, columns.value),
    )
}

fn caption_line_height() -> f32 {
    22.0_f32.max(16.0 * settings_text_scale())
}

fn caption_node(key: &str, text: &str, width: f32) -> (UiNode, f32) {
    wrapped_words_node(
        key,
        text,
        (SemanticRole::Heading, StyleRef::Quiet),
        width,
        caption_line_height(),
    )
}

fn wrapped_words_node(
    key: &str,
    text: &str,
    (role, style): (SemanticRole, StyleRef),
    width: f32,
    line_height: f32,
) -> (UiNode, f32) {
    let (px, face) = crate::native_ui::text_paint_metrics(role, style);
    let lines = wrap_to_box(text, width, &|line| {
        if face == crate::widget::TextFace::Mono {
            crate::tray_raster::measure_text(line, px, crate::widget::TextWeight::Regular)
        } else {
            crate::tray_raster::ui_text_width_for(face, line, px)
        }
    });
    let height = lines.len().max(1) as f32 * line_height;
    let line_node = |key: String, text: String| {
        UiNode::new(key, UiContent::Text(TextSpec { text, role, style }))
            .layout(Layout::default().height(Length::Fixed(line_height)))
    };
    if lines.len() <= 1 {
        return (line_node(key.to_string(), text.to_string()), height);
    }
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(text.to_string()),
                role,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(height)))
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(index, line)| line_node(format!("{key}/line-{index}"), line).paint_only())
                .collect(),
        ),
        height,
    )
}

fn metadata_card(
    key: &str,
    caption: &str,
    rows: &[(String, String)],
    card_width: f32,
    label_width: f32,
) -> (UiNode, f32) {
    let inner = card_text_width(card_width);
    let side = card_side_padding(card_width);
    let columns = FactColumns::measure(rows, inner, label_width);
    let row_height = 28.0_f32.max(18.0 * settings_text_scale());
    let (heading, heading_height) = caption_node(&format!("{key}/heading"), caption, inner);
    let mut children = vec![heading];
    let mut height = 2.0 * ABOUT_METADATA_CARD_PADDING + heading_height;
    children.extend(rows.iter().map(|(label, value)| {
        let fragment = key_fragment(label);
        let code = metadata_value_is_code(label);
        let shown_label = about_fact_label(label);
        let value_style = if code {
            StyleRef::Code
        } else {
            StyleRef::Primary
        };
        let cell = |key: String, text: String, style: StyleRef, width: Length| {
            UiNode::new(
                key,
                UiContent::Text(TextSpec {
                    text,
                    role: SemanticRole::Text,
                    style,
                }),
            )
            .layout(Layout::default().width(width).height(Length::Fill))
            .paint_only()
        };
        let suffix = |index: usize| {
            if index == 0 {
                String::new()
            } else {
                format!("/line-{index}")
            }
        };
        let label_cell = |index: usize, text: String, width: Length| {
            cell(
                format!("{key}/label/{fragment}{}", suffix(index)),
                text,
                StyleRef::Quiet,
                width,
            )
        };
        let value_cell = |index: usize, text: String| {
            cell(
                format!("{key}/value/{fragment}{}", suffix(index)),
                text,
                value_style,
                Length::Fill,
            )
        };
        let (names, values) = fact_card_lines(label, value, columns);
        let lines: Vec<Vec<UiNode>> = if columns.stacked {
            let name_lines = names
                .into_iter()
                .enumerate()
                .map(|(index, text)| vec![label_cell(index, text, Length::Fill)]);
            let value_lines = values
                .into_iter()
                .enumerate()
                .map(|(index, text)| vec![value_cell(index, text)]);
            name_lines.chain(value_lines).collect()
        } else {
            let count = names.len().max(values.len());
            (0..count)
                .map(|index| {
                    vec![
                        label_cell(
                            index,
                            names.get(index).cloned().unwrap_or_default(),
                            Length::Fixed(columns.label),
                        ),
                        value_cell(index, values.get(index).cloned().unwrap_or_default()),
                    ]
                })
                .collect()
        };
        let count = lines.len();
        let block_height = count as f32 * row_height + count.saturating_sub(1) as f32 * 4.0;
        height += block_height + 4.0;
        let line_rows = lines
            .into_iter()
            .enumerate()
            .map(|(index, cells)| {
                UiNode::new(
                    format!("{key}/row/{fragment}/line-{index}"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    Layout::row()
                        .height(Length::Fixed(row_height))
                        .gap(ABOUT_METADATA_ROW_GAP),
                )
                .children(cells)
                .paint_only()
            })
            .collect::<Vec<_>>();
        UiNode::new(
            format!("{key}/row/{fragment}"),
            UiContent::Group(GroupSpec::new(format!("{shown_label}: {value}"))),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(block_height))
                .gap(4.0),
        )
        .children(line_rows)
    }));
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec::new(caption).style(StyleRef::Secondary)),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .padding(Insets::symmetric(side, ABOUT_METADATA_CARD_PADDING))
                .gap(4.0)
                .clipped(),
        )
        .children(children),
        height,
    )
}

fn update_release_notes_padding() -> f32 {
    if settings_text_scale() > 1.25 {
        14.0
    } else {
        16.0
    }
}

fn update_release_notes_line_height() -> f32 {
    (13.0 * crate::native_appearance::text_scale() * 1.45).max(16.0)
}

fn wrap_native_lines(lines: &[String], max_width: f32, px: f32) -> Vec<String> {
    let max_width = max_width.max(48.0);
    let mut wrapped = Vec::new();
    for source in lines {
        if source.is_empty() {
            wrapped.push(String::new());
            continue;
        }
        wrapped.extend(copy_paragraph_lines(source, px, max_width));
    }
    wrapped
}

fn wrap_release_note_lines(lines: &[String], max_width: f32) -> Vec<String> {
    wrap_native_lines(
        lines,
        max_width,
        13.0 * crate::native_appearance::text_scale(),
    )
}

fn update_release_notes_card(update: &UpdateProjection, room: f32, text_width: f32) -> UiNode {
    let line_height = update_release_notes_line_height();
    let (heading, heading_height) =
        caption_node("updates/release-notes-heading", "RELEASE NOTES", text_width);
    let padding = update_release_notes_padding();
    let gap = 8.0;
    let capacity =
        (((room - padding * 2.0 - heading_height - gap) / line_height).floor() as usize).max(1);
    let mut rows: Vec<(UiNode, f32)> = Vec::new();
    for source in update_notes_lines(update)
        .iter()
        .filter(|line| !line.trim().is_empty())
    {
        let lines = wrap_release_note_lines(std::slice::from_ref(source), text_width);
        let whole = lines.len() <= capacity;
        for chunk in lines.chunks(capacity) {
            let index = rows.len();
            let key = if index == 0 {
                "updates/release-notes".to_string()
            } else {
                format!("updates/release-notes/{index}")
            };
            let height = (chunk.len() as f32 * line_height).ceil();
            rows.push((
                UiNode::new(
                    key,
                    UiContent::RichText(RichTextSpec {
                        semantic_text: if whole {
                            source.clone()
                        } else {
                            chunk.join(" ")
                        },
                        text: chunk.join("\n"),
                        selectable: true,
                    }),
                )
                .layout(
                    Layout::default()
                        .height(Length::Fixed(height))
                        .width(Length::Fill),
                ),
                height,
            ));
        }
    }
    let height =
        padding * 2.0 + heading_height + rows.iter().map(|(_, height)| height + gap).sum::<f32>();
    let mut children = vec![heading];
    children.extend(rows.into_iter().map(|(node, _)| node));
    UiNode::new(
        "updates/release-notes-card",
        UiContent::Group(GroupSpec::new("Release notes").style(StyleRef::Secondary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(height))
            .padding(Insets::all(padding))
            .gap(gap)
            .clipped(),
    )
    .children(children)
}

const fn not_applying(update: &UpdateProjection) -> bool {
    update.apply_trouble.is_some() || (update.staged.is_some() && update.apply_is_failing)
}

pub(crate) fn compact_update_headline(update: &UpdateProjection) -> String {
    if update.checking || update.installable == UpdateInstallability::Unobserved {
        "Checking".to_string()
    } else if update.linux_host {
        if update.installable.cannot_install() {
            "Unavailable"
        } else if !update.enabled {
            "Off"
        } else if update.linux_attention {
            "Needs attention"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.staged_build.is_some())
        {
            "Downloaded"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.trial_phase.is_some() && !status.trial_healthy)
        {
            "Awaiting startup"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.installed_build > update.current_build)
        {
            "Installed"
        } else if !update.automatic_checks {
            "Checks off"
        } else {
            "None staged"
        }
        .to_string()
    } else if update.staged_on_hold {
        "On hold".to_string()
    } else if not_applying(update) {
        "Not installing".to_string()
    } else if update.staged.is_some() {
        "Ready".to_string()
    } else if update.failing_persistent {
        "Failing".to_string()
    } else if update.dev_build {
        "Dev build".to_string()
    } else if update.installable.cannot_install() {
        "Can\u{2019}t update".to_string()
    } else if update.channel_unreadable {
        "Can\u{2019}t check".to_string()
    } else if !update.enabled {
        "No updater".to_string()
    } else if !update.automatic_checks {
        "Checks off".to_string()
    } else {
        "Current".to_string()
    }
}

pub(crate) fn compact_update_detail(update: &UpdateProjection) -> String {
    if update.checking {
        "Contacting service…".to_string()
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading this copy\u{2026}".to_string()
    } else if update.linux_host {
        update
            .detail
            .clone()
            .unwrap_or_else(|| "Run `aterm update status`.".to_string())
    } else if let Some(trouble) = update.apply_trouble.as_ref() {
        trouble.compact()
    } else if update.staged_on_hold {
        format!(
            "On hold \u{b7} {}.",
            crate::update_words::NEWER_RELEASE_REPLACES
        )
    } else if not_applying(update) {
        "Downloaded, but it keeps failing to install.".to_string()
    } else if update.staged.is_some() && update.failing_persistent {
        "Ready to install; update checks are failing.".to_string()
    } else if update.staged.is_some() {
        "Ready to install.".to_string()
    } else if update.failing_persistent {
        "Updates are failing.".to_string()
    } else if update.dev_build {
        "A dev build is left alone.".to_string()
    } else if update.installable.cannot_install() {
        "Install aterm to get updates.".to_string()
    } else if update.channel_unreadable {
        "The release channel can\u{2019}t be read.".to_string()
    } else if update.enabled {
        update_checked_sentence(update)
    } else {
        "Checks unavailable.".to_string()
    }
}

/// The tersest truthful rung for each [`compact_update_detail`] state.
pub(crate) fn compact_update_detail_minimum(update: &UpdateProjection) -> String {
    if update.linux_host && !update.checking {
        let downloaded = update
            .linux
            .as_ref()
            .is_some_and(|status| status.staged_build.is_some());
        return if update.installable.is_installable() && downloaded {
            "aterm update apply"
        } else {
            ""
        }
        .to_string();
    }
    if let Some(trouble) = update.apply_trouble.as_ref().filter(|_| !update.checking) {
        return trouble.micro();
    }
    if update.checking {
        "Contacting…"
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading\u{2026}"
    } else if update.staged_on_hold {
        "On hold."
    } else if not_applying(update) {
        "Install failing."
    } else if update.staged.is_some() && update.failing_persistent {
        "Checks failing."
    } else if update.staged.is_some() {
        "Ready."
    } else if update.failing_persistent {
        "Checks failing."
    } else if update.dev_build {
        "Dev build."
    } else if update.installable.cannot_install() {
        "Needs install."
    } else if update.channel_unreadable {
        "Channel unread."
    } else if !update.enabled {
        "Unavailable."
    } else if !update.automatic_checks {
        "Manual checks."
    } else {
        "Up to date."
    }
    .to_string()
}

fn fit_native_bold_label(value: &str, max_width: f32, px: f32) -> String {
    let fits = |candidate: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, candidate, px)
            <= max_width.max(0.0) + 0.5
    };
    if fits(value) {
        return value.to_string();
    }

    let graphemes = value.graphemes().collect::<Vec<_>>();
    for retained in (0..graphemes.len()).rev() {
        let candidate = format!("{}…", graphemes[..retained].concat());
        if fits(&candidate) {
            return candidate;
        }
    }
    String::new()
}

fn compact_update_summary_detail(update: &UpdateProjection) -> &'static str {
    if update.checking {
        "Checking…"
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading this copy\u{2026}"
    } else if update.linux_host {
        "See terminal status"
    } else if update.staged_on_hold {
        "On hold"
    } else if not_applying(update) {
        "Not installing"
    } else if update.staged.is_some() && update.failing_persistent {
        "Ready · checks failing"
    } else if update.staged.is_some() {
        "Ready"
    } else if update.failing_persistent {
        "Checks failing"
    } else if update.dev_build {
        "Not auto-updated"
    } else if update.installable.cannot_install() {
        "Needs an installed copy"
    } else if update.channel_unreadable {
        "Channel unreadable"
    } else if !update.enabled {
        "Unavailable"
    } else if !update.automatic_checks {
        "Manual checks"
    } else {
        "Up to date"
    }
}

fn compact_update_summary(
    update: &UpdateProjection,
    available_width: f32,
    titled: bool,
) -> (UiNode, f32, bool) {
    let scale = settings_text_scale();
    let title_height = 20.0_f32.max(16.0 * scale);
    let headline_height = 42.0_f32.max(30.0 * scale);
    let current_height = 22.0_f32.max(18.0 * scale);
    let detail_height = 24.0_f32.max(20.0 * scale);
    let inner_width = (available_width - 8.0 * 2.0 - 8.0).max(0.0);
    let identity_width = inner_width * 0.42;
    let detail_width = (inner_width - identity_width).max(0.0);
    let caption_px = 11.0 * crate::native_appearance::text_scale();
    let caption_fits = |text: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, text, caption_px)
            <= identity_width + 0.5
    };
    let title_words = if caption_fits("SOFTWARE UPDATE") {
        "SOFTWARE UPDATE"
    } else {
        "UPDATE"
    };
    let title = titled.then(|| fit_native_bold_label(title_words, identity_width, caption_px));
    let headline_words = compact_update_headline(update);
    let headline_px =
        |style: StyleRef| crate::native_ui::text_paint_metrics(SemanticRole::Heading, style).0;
    let preferred_style = update_headline_style(update);
    let headline_style = if crate::tray_raster::ui_text_width_for(
        crate::widget::TextFace::UiBold,
        &headline_words,
        headline_px(preferred_style),
    ) <= identity_width + 0.5
    {
        preferred_style
    } else {
        compact_heading_style(preferred_style)
    };
    let headline =
        fit_native_bold_label(&headline_words, identity_width, headline_px(headline_style));
    let current_semantic = format!("aterm {}", update.current_version);
    let current_preferred =
        if crate::native_ui::fit_native_status_label(&current_semantic, detail_width)
            == current_semantic
        {
            current_semantic.clone()
        } else {
            format!("v{}", update.current_version)
        };
    let current = crate::native_ui::fit_native_status_label(&current_preferred, detail_width);
    let detail = crate::native_ui::fit_native_text_label(
        compact_update_summary_detail(update),
        detail_width,
    );
    let whole = title.as_deref().is_none_or(|title| title == title_words)
        && headline == headline_words
        && current == current_preferred
        && detail == compact_update_summary_detail(update);
    let summary_semantic = format!("Software Update\n{}\n{}", update.headline, current_semantic);
    let left_height = if title.is_some() {
        title_height + 4.0
    } else {
        0.0
    } + headline_height;
    let right_height = current_height + detail_height + 4.0;
    let height = left_height.max(right_height) + 16.0;
    (
        UiNode::new(
            "updates/hero",
            UiContent::Group(GroupSpec {
                label: Some(summary_semantic),
                role: SemanticRole::Status,
                style: StyleRef::Primary,
            }),
        )
        .layout(
            Layout::row()
                .height(Length::Fixed(height))
                .padding(Insets::all(8.0))
                .gap(8.0)
                .clipped(),
        )
        .children(vec![
            UiNode::new(
                "updates/summary/identity",
                UiContent::Group(GroupSpec::new("Software Update")),
            )
            .layout(
                Layout::column()
                    .width(Length::Fraction(0.42))
                    .height(Length::Fixed(left_height))
                    .gap(4.0),
            )
            .children(
                title
                    .map(|title| {
                        UiNode::new(
                            "updates/title",
                            UiContent::Text(TextSpec {
                                text: title,
                                role: SemanticRole::Heading,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(title_height)))
                        .paint_only()
                    })
                    .into_iter()
                    .chain([UiNode::new(
                        "updates/headline",
                        UiContent::Text(TextSpec {
                            text: headline,
                            role: SemanticRole::Heading,
                            style: headline_style,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(headline_height)))
                    .paint_only()])
                    .collect(),
            )
            .paint_only(),
            UiNode::new(
                "updates/summary/detail",
                UiContent::Group(GroupSpec::new("Current update state")),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(right_height))
                    .gap(4.0),
            )
            .children(vec![
                UiNode::new(
                    "updates/current",
                    UiContent::Text(TextSpec {
                        text: current,
                        role: SemanticRole::Status,
                        style: StyleRef::Quiet,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(current_height)))
                .paint_only(),
                UiNode::new(
                    "updates/summary/state",
                    UiContent::Text(TextSpec {
                        text: detail,
                        role: SemanticRole::Text,
                        style: StyleRef::Quiet,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(detail_height)))
                .paint_only(),
            ])
            .paint_only(),
        ]),
        height,
        whole,
    )
}

fn compact_update_summary_card(
    mut summary: UiNode,
    summary_height: f32,
    detail: Option<(UiNode, f32)>,
    actions: Option<(UiNode, f32)>,
) -> (UiNode, f32) {
    let spec = match &summary.content {
        UiContent::Group(spec) => spec.clone(),
        _ => GroupSpec::new("Software Update").style(StyleRef::Primary),
    };
    let inner_height = summary_height - 16.0;
    summary.key = UiKey::new("updates/summary");
    summary.content = UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group));
    summary.layout.padding = Insets::default();
    summary.layout.height = Length::Fixed(inner_height);
    let mut height = summary_height;
    let mut children = vec![summary];
    for (node, node_height) in detail.into_iter().chain(actions) {
        height += 8.0 + node_height;
        children.push(node);
    }
    (
        UiNode::new("updates/hero", UiContent::Group(spec))
            .layout(
                Layout::column()
                    .height(Length::Fixed(height))
                    .padding(Insets::all(8.0))
                    .gap(8.0)
                    .clipped(),
            )
            .children(children),
        height,
    )
}

fn compact_update_full_items(
    status: UiNode,
    split_action: Option<UiNode>,
    automatic: Vec<(UiNode, f32)>,
    notes: Vec<UiNode>,
    notes_width: f32,
    action_height: f32,
) -> Vec<(UiNode, f32)> {
    let split = split_action.is_some();
    let mut sections = vec![status];
    if let Some(action) = split_action {
        let action_width = match action.layout.width {
            Length::Fixed(width) => width,
            _ => notes_width,
        };
        let row_height = fixed_height(&action).max(action_height);
        let mut row = vec![action];
        if action_width + 8.0 + messages_link_width() <= notes_width {
            row.push(messages_link_button(
                "updates/messages",
                messages_link_width(),
                action_height,
            ));
        }
        sections.push(
            UiNode::new(
                "updates/actions",
                UiContent::Group(GroupSpec::new("Update actions")),
            )
            .layout(Layout::row().height(Length::Fixed(row_height)).gap(8.0))
            .children(row),
        );
    }
    sections.extend(automatic.into_iter().map(|(node, _)| node));
    if !sections
        .iter()
        .take(1 + usize::from(split))
        .any(|section| ui_node_holds(section, "updates/messages"))
    {
        sections.insert(
            1 + usize::from(split),
            messages_link_button(
                "updates/messages",
                messages_link_width().min(notes_width),
                action_height,
            ),
        );
    }
    sections.extend(notes);
    with_heights(sections)
}

struct SummaryPlace {
    notes_width: f32,
    card_titled: bool,
    room: f32,
    action_height: f32,
}

fn compact_update_summary_items(
    update: &UpdateProjection,
    mut action: UiNode,
    automatic: Vec<(UiNode, f32)>,
    notes: Vec<UiNode>,
    place: SummaryPlace,
) -> Option<Vec<(UiNode, f32)>> {
    let SummaryPlace {
        notes_width,
        card_titled,
        room,
        action_height,
    } = place;
    let (summary, summary_height, whole) = compact_update_summary(update, notes_width, card_titled);
    if !whole {
        return None;
    }
    action.layout.height = Length::Fixed(fixed_height(&action).max(action_height));
    let link = messages_link_button(
        "updates/messages",
        messages_link_width().min(notes_width),
        action_height,
    );
    let action_width = match action.layout.width {
        Length::Fixed(width) => width,
        _ => notes_width,
    };
    let detail = compact_update_detail_line(update, (notes_width - 16.0).max(0.0));
    let detail_height = detail.as_ref().map_or(0.0, |(_, height)| 8.0 + height);
    let side_by_side = action_width + 8.0 + messages_link_width() <= notes_width - 16.0;
    let with_actions = summary_height + detail_height + 8.0 + action_height;
    let mut items = Vec::new();
    if side_by_side && with_actions <= room {
        items.push(compact_update_summary_card(
            summary,
            summary_height,
            detail,
            Some((
                UiNode::new(
                    "updates/actions",
                    UiContent::Group(GroupSpec::new("Update actions")),
                )
                .layout(Layout::row().height(Length::Fixed(action_height)).gap(8.0))
                .children(vec![action, link]),
                action_height,
            )),
        ));
    } else {
        items.push(compact_update_summary_card(
            summary,
            summary_height,
            detail,
            None,
        ));
        let height = fixed_height(&action);
        items.push((action, height));
        items.push((link, action_height));
    }
    items.extend(automatic);
    items.extend(compact_update_outcome(update, notes_width));
    items.extend(with_heights(notes));
    Some(items)
}

fn compact_update_detail_line(update: &UpdateProjection, width: f32) -> Option<(UiNode, f32)> {
    let sentence = update_status_detail(update, SettingsWidth::Compact);
    (!sentence.trim().is_empty()).then(|| {
        wrapped_copy_node(
            "updates/detail",
            &sentence,
            SemanticRole::Text,
            StyleRef::Quiet,
            width,
            24.0_f32.max(20.0 * settings_text_scale()),
            None,
        )
    })
}

const MAX_UPDATE_OUTCOME_LINES: usize = 3;

fn bound_outcome_lines(lines: &mut Vec<String>, max_width: f32) {
    bound_update_lines(lines, max_width, MAX_UPDATE_OUTCOME_LINES);
}

fn bound_update_lines(lines: &mut Vec<String>, max_width: f32, max_lines: usize) {
    if lines.len() <= max_lines {
        return;
    }
    lines.truncate(max_lines);
    let Some(last) = lines.pop() else {
        return;
    };
    let px = 13.0 * crate::native_appearance::text_scale();
    let measure = |candidate: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, candidate, px)
    };
    let mut graphemes = last.graphemes().collect::<Vec<_>>();
    loop {
        let retained = graphemes.concat();
        let candidate = format!("{}\u{2026}", retained.trim_end());
        if measure(&candidate) <= max_width || graphemes.is_empty() {
            lines.push(candidate);
            return;
        }
        graphemes.pop();
    }
}

const COMPACT_UPDATE_OUTCOME_PADDING: f32 = 16.0;

fn compact_update_outcome_text_width(card_width: f32) -> f32 {
    (card_width - COMPACT_UPDATE_OUTCOME_PADDING * 2.0).max(0.0)
}

fn compact_update_outcome(update: &UpdateProjection, card_width: f32) -> Option<(UiNode, f32)> {
    let display = update_outcome_line(update)?;
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let text_width = compact_update_outcome_text_width(card_width);
    let mut lines = wrap_native_lines(
        std::slice::from_ref(&display),
        text_width,
        13.0 * crate::native_appearance::text_scale(),
    );
    bound_outcome_lines(&mut lines, text_width);
    let height = 32.0 + lines.len() as f32 * line_height;
    Some((
        UiNode::new(
            "updates/outcome",
            UiContent::Group(GroupSpec {
                label: Some(update.outcome.clone()),
                role: SemanticRole::Status,
                style: StyleRef::Secondary,
            }),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .padding(Insets::all(COMPACT_UPDATE_OUTCOME_PADDING))
                .clipped(),
        )
        .children(
            lines
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/outcome/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        height,
    ))
}

fn update_action_label(room: f32) -> &'static str {
    const WHOLE: &str = "Update to Latest Now";
    if crate::native_ui::native_button_label_width(WHOLE) + 28.0 <= room + 0.01 {
        WHOLE
    } else {
        "Update"
    }
}

fn update_action_words(update: &UpdateProjection, room: f32) -> Option<String> {
    let (full, short): (&str, &[&str]) = if update.linux_host {
        ("Install in a terminal", &[])
    } else {
        (update_action_label(room), &["Update"])
    };
    whole_button_words(full, short, room).map(|(words, _)| words)
}

const UPDATE_CANT_INSTALL: &str = "This copy of aterm can\u{2019}t install updates.";

const UPDATE_UNOBSERVED_FEEDBACK: &str =
    "Still checking whether this copy of aterm can update itself.";

fn update_action_node(update: &UpdateProjection, height: f32, room: f32) -> UiNode {
    let installable = update.installable.is_installable() || update.linux_host;
    let semantic_label = if update.linux_host {
        "Install in a terminal: run aterm update apply"
    } else {
        "Update to Latest Now"
    };
    let (visual_label, lines) = if update.linux_host {
        button_words("Install in a terminal", &[], room)
    } else {
        button_words(update_action_label(room), &["Update"], room)
    };
    let visual_label = visual_label.as_str();
    let unobserved = update.installable == UpdateInstallability::Unobserved && !update.linux_host;
    let mut spec = ButtonSpec::new(semantic_label).visual_label(visual_label);
    if unobserved {
        spec.description = Some(UPDATE_UNOBSERVED_FEEDBACK.to_string());
    } else if !installable {
        spec.description = Some(UPDATE_CANT_INSTALL.to_string());
    }
    UiNode::new(
        "updates/install-now",
        UiContent::Button(
            Control::new(spec, ActionId::new("updates/install-now"))
                .state(ControlState {
                    enabled: update.enabled
                        && installable
                        && !update.checking
                        && !update.linux_host,
                    busy: update.checking || unobserved,
                    ..ControlState::default()
                })
                .style(if installable || unobserved {
                    StyleRef::Primary
                } else {
                    StyleRef::Secondary
                }),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(if lines > 1 {
                room
            } else {
                page_button_width(visual_label, room)
            }))
            .height(Length::Fixed(
                crate::native_ui::native_button_height_for_lines(lines, height),
            )),
    )
}

fn button_words(full: &str, short: &[&str], width: f32) -> (String, usize) {
    button_words_in(&ButtonSpec::new(full), full, short, width)
}

fn painted_words(visual: &str) -> String {
    visual
        .replace("-\n", "")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn button_words_in(spec: &ButtonSpec, full: &str, short: &[&str], width: f32) -> (String, usize) {
    fn bare(form: &str) -> Option<&str> {
        form.strip_suffix('\u{2026}')
            .map(str::trim_end)
            .filter(|bare| !bare.is_empty())
    }
    let bare_short: Vec<&str> = short.iter().filter_map(|form| bare(form)).collect();
    let without_ellipsis = || {
        let (full, short) = match bare(full) {
            Some(full) => (full, &bare_short[..]),
            None => bare_short
                .split_first()
                .map(|(first, rest)| (*first, rest))?,
        };
        whole_button_words_in(spec, full, short, width)
    };
    whole_button_words_in(spec, full, short, width)
        .or_else(without_ellipsis)
        .unwrap_or_else(|| {
            let shortest = short.last().copied().unwrap_or(full);
            let room = crate::native_ui::text_button_label_room(spec, width);
            let lines = wrap_to_box(shortest, room, &crate::native_ui::native_button_label_width);
            (lines.join("\n"), lines.len())
        })
}

fn whole_button_words(full: &str, short: &[&str], width: f32) -> Option<(String, usize)> {
    whole_button_words_in(&ButtonSpec::new(full), full, short, width)
}

fn whole_button_words_in(
    spec: &ButtonSpec,
    full: &str,
    short: &[&str],
    width: f32,
) -> Option<(String, usize)> {
    let room = crate::native_ui::text_button_label_room(spec, width);
    let one_line = |label: &str| {
        crate::native_ui::native_button_label_width(label)
            <= room + crate::native_ui::TEXT_FIT_SLACK
    };
    let forms = std::iter::once(full).chain(short.iter().copied());
    if let Some(form) = forms.clone().find(|form| one_line(form)) {
        return Some((form.to_string(), 1));
    }
    forms
        .clone()
        .find_map(|form| crate::native_ui::native_button_label_lines(form, room))
        .map(|lines| (lines.join("\n"), lines.len()))
}

fn page_button_width(label: &str, room: f32) -> f32 {
    (crate::native_ui::native_button_label_width(label) + 28.0)
        .max(72.0)
        .min(room.max(0.0))
}

fn update_notes_lines(update: &UpdateProjection) -> Vec<String> {
    if update.linux_host {
        return vec!["No release notes on Linux.".to_string()];
    }
    if !update.changelog.is_empty() {
        return update.changelog.clone();
    }
    vec![if update.checking {
        "Checking for a newer version\u{2026}".to_string()
    } else if let Some((_, version)) = update.staged.as_ref() {
        let state = if update.staged_on_hold {
            "is on hold"
        } else {
            "is ready to install"
        };
        format!("Version {version} {state}; its release notes aren\u{2019}t available here.")
    } else if update.failing_persistent || update.dev_build || !update.installable.is_installable()
    {
        // Never "the newest version" where this copy does not update; the status card says why.
        "Release notes appear here when an update is ready.".to_string()
    } else if update.enabled && (update.channel_unreadable || update.checked_at.is_none()) {
        // Channel unreadable or first check still pending.
        "Release notes appear here when an update is ready.".to_string()
    } else if update.enabled {
        format!(
            "aterm {} is the newest version. Notes for the next one appear here when it\u{2019}s ready.",
            update.current_version
        )
    } else {
        "Update checks are unavailable for this installation, so no release notes can be shown."
            .to_string()
    }]
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct StatusLineBudget {
    detail: usize,
    outcome: usize,
}

impl StatusLineBudget {
    const FULL: Self = Self {
        detail: MAX_UPDATE_OUTCOME_LINES,
        outcome: MAX_UPDATE_OUTCOME_LINES,
    };

    fn desktop_ladder() -> impl Iterator<Item = Self> {
        let outcome = (1..=MAX_UPDATE_OUTCOME_LINES).rev().map(|outcome| Self {
            detail: MAX_UPDATE_OUTCOME_LINES,
            outcome,
        });
        let detail = (1..MAX_UPDATE_OUTCOME_LINES)
            .rev()
            .map(|detail| Self { detail, outcome: 1 });
        outcome.chain(detail)
    }
}

#[derive(Clone, Copy, Debug)]
struct StatusCardShape {
    titled: bool,
}

fn update_headline_style(update: &UpdateProjection) -> StyleRef {
    if update.failing_persistent || update.linux_attention || not_applying(update) {
        StyleRef::Danger
    } else {
        StyleRef::Hero
    }
}

fn update_headline_fit(update: &UpdateProjection, text_width: f32) -> (String, StyleRef) {
    let style = update_headline_style(update);
    let width = |text: &str, style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, style);
        crate::tray_raster::ui_text_width_for(face, text, px)
    };
    let compact = compact_update_headline(update);
    if width(&update.headline, style) <= text_width + 0.01 {
        (update.headline.clone(), style)
    } else if width(&compact, style) <= text_width + 0.01 {
        (compact, style)
    } else {
        (compact, compact_heading_style(style))
    }
}

const fn compact_heading_style(style: StyleRef) -> StyleRef {
    if matches!(style, StyleRef::Danger | StyleRef::DangerCompact) {
        StyleRef::DangerCompact
    } else {
        StyleRef::Plain
    }
}

fn fitted_headline_node(
    key: &str,
    text: &str,
    style: StyleRef,
    width: f32,
    height: f32,
) -> (UiNode, f32) {
    let one_line = |style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, style);
        crate::tray_raster::ui_text_width_for(face, text, px)
            <= width + crate::native_ui::TEXT_FIT_SLACK
    };
    let style = if one_line(style) {
        style
    } else {
        compact_heading_style(style)
    };
    let (mut node, lines_height) = wrapped_words_node(
        key,
        text,
        (SemanticRole::Heading, style),
        width,
        26.0_f32.max(22.0 * settings_text_scale()),
    );
    let height = if matches!(node.content, UiContent::Text(_)) {
        height
    } else {
        lines_height
    };
    node.layout.height = Length::Fixed(height);
    (node, height)
}

fn update_detail_fit(
    update: &UpdateProjection,
    full: &str,
    text_width: f32,
    max_lines: usize,
) -> String {
    let px = 13.0 * crate::native_appearance::text_scale();
    let whole = |text: &str| {
        !text.trim().is_empty()
            && text
                .split_whitespace()
                .all(|word| crate::tray_raster::ui_text_width(word, px) <= text_width + 0.01)
            && wrap_to_box(text, text_width, &|line| {
                crate::tray_raster::ui_text_width(line, px)
            })
            .len()
                <= max_lines.max(1)
    };
    let forms = [
        full.to_string(),
        compact_update_detail(update),
        compact_update_detail_minimum(update),
    ];
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    forms
        .iter()
        .find(|text| whole(text))
        .or_else(|| {
            forms.iter().find(|text| {
                !text.trim().is_empty()
                    && wrap_to_box(text, text_width, &measure).len() <= max_lines.max(1)
            })
        })
        .cloned()
        .unwrap_or_else(|| full.to_string())
}

fn update_status_card(
    update: &UpdateProjection,
    width: SettingsWidth,
    shape: StatusCardShape,
    text_width: f32,
    action: Option<UiNode>,
    action_height: f32,
    lines: StatusLineBudget,
) -> (UiNode, f32) {
    let StatusCardShape { titled } = shape;
    let text_scale = settings_text_scale();
    let headline_height = 42.0_f32.max(30.0 * text_scale);
    let current_height = 22.0_f32.max(18.0 * text_scale);
    let detail_height = 24.0_f32.max(20.0 * text_scale);
    let full_detail = update_status_detail(update, width);
    let (visual_headline, headline_style) = update_headline_fit(update, text_width);
    let visual_detail = update_detail_fit(update, &full_detail, text_width, lines.detail);
    let detail_lines = {
        let px = 13.0 * crate::native_appearance::text_scale();
        let mut wrapped = wrap_to_box(&visual_detail, text_width, &|line| {
            crate::tray_raster::ui_text_width(line, px)
        });
        bound_update_lines(&mut wrapped, text_width, lines.detail.max(1));
        if wrapped.is_empty() {
            wrapped.push(visual_detail.clone());
        }
        wrapped
    };
    let outcome = update_outcome_line(update).filter(|_| !update.linux_host);
    let outcome_lines = outcome
        .as_ref()
        .map(|outcome| {
            let mut wrapped = wrap_native_lines(
                std::slice::from_ref(outcome),
                text_width,
                13.0 * crate::native_appearance::text_scale(),
            );
            bound_update_lines(&mut wrapped, text_width, lines.outcome.max(1));
            wrapped
        })
        .unwrap_or_default();
    let mut children = Vec::new();
    let (title_node, title_height) = caption_node(
        "updates/title",
        caption_words("SOFTWARE UPDATE", "UPDATE", text_width),
        text_width,
    );
    let title_height = if titled { title_height } else { 0.0 };
    if titled {
        children.push(title_node);
    }
    let (mut headline, wrapped_headline_height) = wrapped_words_node(
        "updates/headline",
        &visual_headline,
        (SemanticRole::Heading, headline_style),
        text_width,
        26.0_f32.max(22.0 * text_scale),
    );
    let headline_height = if matches!(headline.content, UiContent::Text(_)) {
        headline_height
    } else {
        wrapped_headline_height
    };
    headline.layout.height = Length::Fixed(headline_height);
    let (current, current_height) = wrapped_words_node(
        "updates/current",
        &format!("aterm {}", update.current_version),
        (SemanticRole::Status, StyleRef::Quiet),
        text_width,
        current_height,
    );
    children.extend([
        headline,
        current,
        UiNode::new(
            "updates/detail",
            UiContent::Group(GroupSpec {
                label: Some(full_detail.clone()),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(detail_lines.len() as f32 * detail_height)))
        .children(
            detail_lines
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/detail/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(detail_height)))
                    .paint_only()
                })
                .collect(),
        ),
    ]);
    if outcome.is_some() {
        children.push(
            UiNode::new(
                "updates/outcome",
                UiContent::Group(GroupSpec {
                    label: Some(update.outcome.clone()),
                    role: SemanticRole::Status,
                    style: StyleRef::Quiet,
                }),
            )
            .layout(
                Layout::column().height(Length::Fixed(outcome_lines.len() as f32 * detail_height)),
            )
            .children(
                outcome_lines
                    .iter()
                    .enumerate()
                    .map(|(index, line)| {
                        UiNode::new(
                            format!("updates/outcome/line-{index}"),
                            UiContent::Text(TextSpec {
                                text: line.clone(),
                                role: SemanticRole::Text,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(detail_height)))
                        .paint_only()
                    })
                    .collect(),
            ),
        );
    }
    let has_action = action.is_some();
    let compact = width == SettingsWidth::Compact;
    let link = messages_link_button("updates/messages", messages_link_width(), action_height);
    let action_width = action
        .as_ref()
        .map_or(0.0, |action| match action.layout.width {
            Length::Fixed(width) => width,
            _ => text_width,
        });
    let link_inline = has_action && action_width + 8.0 + messages_link_width() <= text_width;
    if let Some(action) = action {
        let mut row = vec![action];
        if link_inline {
            row.push(link.clone());
        }
        children.push(
            UiNode::new(
                "updates/actions",
                UiContent::Group(GroupSpec::new("Update actions")),
            )
            .layout(Layout::row().height(Length::Fixed(action_height)).gap(8.0))
            .children(row),
        );
    }
    let link_row = !compact && !link_inline;
    if link_row {
        children.push(link);
    }
    let height = if titled { title_height } else { 0.0 }
        + headline_height
        + current_height
        + detail_lines.len() as f32 * detail_height
        + outcome_lines.len() as f32 * detail_height
        + if has_action { action_height } else { 0.0 }
        + if link_row { action_height } else { 0.0 }
        + 40.0
        + children.len().saturating_sub(1) as f32 * 8.0;
    (
        UiNode::new(
            "updates/hero",
            UiContent::Group(
                GroupSpec::new(format!(
                    "Software Update status: {}. {full_detail}{}",
                    update
                        .headline
                        .trim_end_matches(['.', '\u{2026}', '?', '!']),
                    outcome.map_or_else(String::new, |outcome| format!(" {outcome}"))
                ))
                .style(StyleRef::Primary),
            ),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(height))
                .padding(Insets::symmetric(22.0, 20.0))
                .gap(8.0),
        )
        .children(children),
        height,
    )
}

fn update_status_detail(update: &UpdateProjection, width: SettingsWidth) -> String {
    if let Some(detail) = &update.detail {
        return detail.clone();
    }
    let status = if update.checking {
        "Contacting the update service\u{2026}".to_string()
    } else if update.enabled {
        update_checked_sentence(update)
    } else if width == SettingsWidth::Compact {
        "Update checks are unavailable.".to_string()
    } else {
        "Update checks are unavailable for this installation.".to_string()
    };
    match &update.automatic_checks_note {
        Some(note) => format!("{status} {note}"),
        None => status,
    }
}

fn update_checked_sentence(update: &UpdateProjection) -> String {
    let now = aterm_time::unix_secs().map_or(0, |s| i64::try_from(s).unwrap_or(i64::MAX));
    update
        .checked_line(now)
        .map_or_else(|| "Not checked yet.".to_string(), |line| format!("{line}."))
}

fn update_outcome_line(update: &UpdateProjection) -> Option<String> {
    let outcome = update.outcome.trim();
    let routine = outcome.is_empty()
        || outcome.eq_ignore_ascii_case("ok")
        || outcome.eq_ignore_ascii_case("Checking for updates")
        || outcome.starts_with("up to date")
        || outcome.starts_with("staged ")
        || outcome.contains("ready to apply")
        || outcome.starts_with("a verified stage already covers")
        || outcome.starts_with("update check deferred");
    let said_above = update.failing_persistent
        || update.channel_unreadable
        || update.apply_trouble.is_some()
        || !update.installable.is_installable();
    if routine || said_above {
        return None;
    }
    Some(outcome.split('\n').collect::<Vec<_>>().join(" "))
}

const PLATFORM_UPDATE_LANE: &str = "Pull, rebuild and reinstall from your aterm checkout.";

fn update_automatic_caption(
    width: SettingsWidth,
    macos_updater: bool,
    linux_updater: bool,
    installable: UpdateInstallability,
) -> String {
    let compact = width == SettingsWidth::Compact;
    let install = prefs::UPDATE_INSTALL_LABEL;
    if macos_updater && installable.cannot_install() {
        "These switches take effect in an installed copy of aterm.".to_string()
    } else if linux_updater {
        if compact {
            "Automatic checks start or stop next launch; without automatic installs, aterm \
             downloads only (then `aterm update apply`)."
                .to_string()
        } else {
            format!(
                "Automatic checks start or stop next launch. Installing replaces aterm on \
                 disk; with {install} off, aterm downloads only \u{2014} then run \
                 `aterm update apply`."
            )
        }
    } else if macos_updater {
        if compact {
            "Automatic checks start or stop next launch; installing keeps your sessions."
                .to_string()
        } else {
            format!(
                "Automatic checks start or stop next launch. Updates install within a minute \
                 and keep your sessions running; turn {install} off to install only when \
                 you press the button."
            )
        }
    } else if compact {
        "Updater unavailable \u{b7} no effect here.".to_string()
    } else {
        "These switches do nothing here.".to_string()
    }
}

fn update_switches_fit_inline(state: &SettingsViewState, text_width: f32) -> bool {
    let room = inline_row_label_width(&EditKind::Bool, text_width, true);
    let worst = update_switch_tags(true);
    [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"]
        .iter()
        .filter_map(|key| state.field_by_key(key))
        .all(|field| {
            row_name_lines(field.label, room).len() == 1
                && row_tag_fit(field.label, &worst, room).state
        })
}

fn update_switch_tags(changed: bool) -> RowTags {
    RowTags {
        state: changed
            .then(|| CHANGED_WORD.to_string())
            .into_iter()
            .collect(),
        facts: Vec::new(),
    }
}

fn update_automatic_cards(
    state: &SettingsViewState,
    linux_updater: bool,
    availability: SettingsAvailability,
    width: SettingsWidth,
    text_width: f32,
    height_budget: Option<f32>,
) -> Vec<(UiNode, f32)> {
    let keys = [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"];
    let fits_inline = update_switches_fit_inline(state, text_width)
        && (width != SettingsWidth::Compact
            || compact_row_inline(&EditKind::Bool, text_width, true));
    let compact_inline = fits_inline && width == SettingsWidth::Compact;
    let row_width = if !fits_inline {
        SettingsWidth::Compact
    } else if compact_inline {
        SettingsWidth::Medium
    } else {
        width
    };
    let label_room = if fits_inline {
        inline_row_label_width(&EditKind::Bool, text_width, true)
    } else {
        text_width
    };
    let mut rows = Vec::with_capacity(2);
    for key in keys {
        let Some(index) = state.field_index_of(key) else {
            return Vec::new();
        };
        let wording = state.legacy.fields[index].label;
        let mut row = setting_row(state, index, &state.legacy.fields[index], false, row_width);
        if compact_inline {
            row.layout.height = Length::Fixed(compact_inline_row_height());
        }
        if !state.is_explicit(key) {
            reserve_reset_slot(&mut row, key);
        }
        let label_room = if row_width == SettingsWidth::Compact {
            seat_stacked_reset(&mut row, wording, text_width);
            row_label_room(&row, true, text_width)
        } else {
            label_room.min(one_line_label_room(&row, text_width))
        };
        let placement = lay_out_row_label(
            &mut row,
            wording,
            &update_switch_tags(state.is_explicit(key)),
            &update_switch_tags(true),
            label_room,
            row_width == SettingsWidth::Compact,
            false,
        );
        let detail = row_second_line(&placement, None, None, text_width);
        let mut row = with_row_detail(row, key, &detail, row_width == SettingsWidth::Compact);
        if !native_updater_here(availability) && !linux_updater {
            fn disable_switch(node: &mut UiNode) -> bool {
                if let UiContent::Switch(switch) = &mut node.content {
                    switch.state.enabled = false;
                    return true;
                }
                node.children.iter_mut().any(disable_switch)
            }
            let disabled = disable_switch(&mut row);
            debug_assert!(disabled, "each [update] row carries exactly one switch");
        }
        rows.push(row);
    }
    let text_scale = settings_text_scale();
    let caption_line_height = 24.0_f32.max(20.0 * text_scale);
    let row_height = if compact_inline {
        compact_inline_row_height()
    } else {
        row_width.row_height()
    };
    let compact = width == SettingsWidth::Compact;
    let title_height = 20.0_f32.max(16.0 * text_scale);
    const TITLE: &str = "AUTOMATIC UPDATES";
    let (title_px, title_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let titled = crate::tray_raster::ui_text_width_for(title_face, TITLE, title_px) <= text_width;
    let title_block = if titled { title_height + 8.0 } else { 0.0 };
    let rows_height = rows
        .iter()
        .map(fixed_height)
        .sum::<f32>()
        .max(2.0 * row_height)
        + 8.0;
    let room =
        height_budget.map(|budget| (budget - (40.0 + title_block + rows_height + 8.0)).max(0.0));
    let linux_caption = linux_updater || (!availability.macos && native_updater_here(availability));
    let unread = (availability.macos || (native_updater_here(availability) && !linux_updater))
        && availability.update_installable == UpdateInstallability::Unobserved;
    let mut rungs = vec![update_automatic_caption(
        width,
        availability.macos,
        linux_caption,
        availability.update_installable,
    )];
    if unread {
        rungs.clear();
    } else if !compact {
        rungs.push(update_automatic_caption(
            SettingsWidth::Compact,
            availability.macos,
            linux_caption,
            availability.update_installable,
        ));
    }
    let (caption_text, caption) = rungs
        .into_iter()
        .map(|text| {
            let lines = wrap_native_lines(
                std::slice::from_ref(&text),
                text_width,
                13.0 * crate::native_appearance::text_scale(),
            );
            (text, lines)
        })
        .find(|(_, lines)| room.is_none_or(|room| lines.len() as f32 * caption_line_height <= room))
        .unwrap_or_default();
    let caption_height = caption.len() as f32 * caption_line_height;
    let caption_node = (!caption.is_empty()).then(|| {
        UiNode::new(
            "updates/automatic/caption",
            UiContent::Group(GroupSpec {
                label: Some(caption_text),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(caption_height)))
        .children(
            caption
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/automatic/caption/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(caption_line_height)))
                    .paint_only()
                })
                .collect(),
        )
    });
    let caption_block = if caption.is_empty() {
        0.0
    } else {
        caption_height + 8.0
    };
    let card = |key: &str, label: &str, children: Vec<UiNode>, height: f32| {
        (
            UiNode::new(
                key,
                UiContent::Group(GroupSpec::new(label).style(StyleRef::Secondary)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .padding(Insets::all(20.0))
                    .gap(8.0)
                    .clipped(),
            )
            .children(children),
            height,
        )
    };
    let title = titled.then(|| {
        UiNode::new(
            "updates/automatic/title",
            UiContent::Text(TextSpec {
                text: TITLE.to_string(),
                role: SemanticRole::Heading,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(title_height)))
    });
    let install = rows.pop().expect("two rows");
    let check = rows.pop().expect("two rows");
    let mut children: Vec<UiNode> = title.into_iter().collect();
    children.extend([check, install]);
    children.extend(caption_node);
    vec![card(
        "updates/automatic",
        "Automatic updates",
        children,
        40.0 + title_block + rows_height + caption_block,
    )]
}

fn update_page(
    state: &SettingsViewState,
    update: &UpdateProjection,
    availability: SettingsAvailability,
    width: SettingsWidth,
    viewport_width: f32,
    viewport_height: f32,
) -> (Vec<UiNode>, PageLayout) {
    let honest;
    let update = if native_updater_here(availability) || update.enabled || update.linux_host {
        update
    } else {
        honest = UpdateProjection {
            headline: "No in-app updater here.".to_string(),
            detail: Some(PLATFORM_UPDATE_LANE.to_string()),
            ..update.clone()
        };
        &honest
    };
    let text_scale = settings_text_scale();
    let compact = width == SettingsWidth::Compact;
    let viewport = LogicalRect::new(0.0, 0.0, viewport_width, viewport_height);
    let gap = settings_page_gap(state, width, viewport);
    let subtitle = if update.linux_host {
        "Updating keeps open terminals running."
    } else {
        update_page_subtitle(native_updater_here(availability))
    };
    let (heading, heading_height) =
        pinned_heading(state, width, viewport, gap, "Software Update", subtitle);
    let card_titled = !page_named(width, viewport);
    let room = (settings_list_body_height(state, width, viewport) - heading_height)
        .max(scaled_control_height());
    let overhang = settings_list_overhang(state, width, viewport);
    let compact_section_height = room;

    let columns_width =
        settings_page_content_width(viewport_width, width, PageLayout::Columns.maximum(width));
    const WORKBENCH_GAP: f32 = 16.0;
    let shared = columns_width - WORKBENCH_GAP;
    let side_text_width = |status_share: f32| (shared * (1.0 - status_share) - 40.0).max(0.0);
    let (headline_px, headline_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Hero);
    let headline_width =
        crate::tray_raster::ui_text_width_for(headline_face, &update.headline, headline_px);
    let action_height = 36.0_f32.max(32.0 * text_scale);
    let side_by_side_fits = |share: f32| {
        let status_width = (shared * share - 44.0).max(0.0);
        let action = update_action_node(update, action_height, status_width);
        let status = std::iter::once(StatusLineBudget::FULL)
            .chain(StatusLineBudget::desktop_ladder().skip(1))
            .map(|lines| {
                update_status_card(
                    update,
                    width,
                    StatusCardShape {
                        titled: card_titled,
                    },
                    status_width,
                    Some(action.clone()),
                    action_height,
                    lines,
                )
                .1
            })
            .fold(f32::INFINITY, f32::min);
        let automatic = update_automatic_cards(
            state,
            update.linux_host,
            availability,
            width,
            side_text_width(share),
            Some(room),
        )
        .into_iter()
        .map(|(_, height)| height)
        .fold(0.0, f32::max);
        status.max(automatic) <= room + 0.01
    };
    let status_share = (!compact)
        .then(|| {
            [0.62_f32, 0.5].into_iter().find(|share| {
                update_switches_fit_inline(state, side_text_width(*share))
                    && headline_width <= shared * share - 44.0
                    && side_by_side_fits(*share)
            })
        })
        .flatten();
    let layout = if status_share.is_some() {
        PageLayout::Columns
    } else {
        PageLayout::Form
    };
    let notes_width = settings_page_content_width(viewport_width, width, layout.maximum(width));
    let notes_text_width = (notes_width - update_release_notes_padding() * 2.0).max(48.0);
    let (status_text_width, automatic_text_width) = match status_share {
        Some(share) => ((shared * share - 44.0).max(0.0), side_text_width(share)),
        None => ((notes_width - 44.0).max(0.0), (notes_width - 40.0).max(0.0)),
    };
    let action = update_action_node(update, action_height, status_text_width);
    let action_in_card =
        update_action_words(update, status_text_width).is_some_and(|words| !words.contains('\n'));
    let list_action = update_action_node(update, action_height, notes_width);
    let split_action = compact
        && (!action_in_card || {
            let (_, with_action) = update_status_card(
                update,
                width,
                StatusCardShape {
                    titled: card_titled,
                },
                status_text_width,
                Some(action.clone()),
                action_height,
                StatusLineBudget::FULL,
            );
            with_action > room
        });
    let notes_cards = |room: f32| {
        if update.installable.is_installable() || update.linux_host {
            vec![update_release_notes_card(update, room, notes_text_width)]
        } else {
            Vec::new()
        }
    };

    let noncompact_section_room = (!compact).then_some(room);
    let build = |lines: StatusLineBudget| {
        let (status, status_height) = update_status_card(
            update,
            width,
            StatusCardShape {
                titled: card_titled,
            },
            status_text_width,
            (!split_action).then(|| action.clone()),
            action_height,
            lines,
        );
        let automatic = update_automatic_cards(
            state,
            update.linux_host,
            availability,
            width,
            automatic_text_width,
            Some(noncompact_section_room.unwrap_or(compact_section_height)),
        );
        (status, status_height, automatic)
    };
    let mut built = build(StatusLineBudget::FULL);
    if let Some(room) = noncompact_section_room
        && built.1 > room
    {
        for lines in StatusLineBudget::desktop_ladder().skip(1) {
            built = build(lines);
            if built.1 <= room {
                break;
            }
        }
    }
    let (status, status_height, automatic) = built;

    if compact {
        let switches = [
            UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED)),
            UiKey::new("settings/control/update.auto_apply"),
        ];
        let rank = |items: &[(UiNode, f32)]| {
            let listed = items
                .iter()
                .map(|(node, height)| ListItem::of(node.clone(), *height))
                .collect::<Vec<_>>();
            scroll::first_screen_holds(&listed, gap, room, overhang, &switches)
                .map_or(-1, |shown| shown as i32)
        };
        let full = compact_update_full_items(
            status,
            split_action.then(|| list_action.clone()),
            automatic.clone(),
            notes_cards(compact_section_height),
            notes_width,
            action_height,
        );
        let summary = compact_update_summary_items(
            update,
            if action_in_card {
                action.clone()
            } else {
                list_action.clone()
            },
            automatic.clone(),
            notes_cards(compact_section_height),
            SummaryPlace {
                notes_width,
                card_titled,
                room,
                action_height,
            },
        );
        let mut best = (rank(&full), full);
        if let Some(form) = summary {
            let ranked = rank(&form);
            if ranked > best.0 {
                best = (ranked, form);
            }
        }
        return (
            update_list(state, heading, best.1, room, gap, overhang),
            layout,
        );
    }

    let notes = notes_cards(room);
    debug_assert!(automatic.len() <= 1);
    let Some(status_share) = status_share else {
        let mut sections = vec![(status, status_height)];
        sections.extend(automatic);
        sections.extend(with_heights(notes));
        return (
            update_list(state, heading, sections, room, gap, overhang),
            layout,
        );
    };
    let workbench = match automatic.into_iter().next() {
        Some((mut automatic, automatic_height)) => {
            let height = status_height.max(automatic_height);
            automatic.layout.height = Length::Fill;
            UiNode::new(
                "updates/workbench",
                UiContent::Group(GroupSpec::new("Update status and automatic updates")),
            )
            .layout(
                Layout::row()
                    .height(Length::Fixed(height))
                    .gap(WORKBENCH_GAP)
                    .clipped(),
            )
            .children(vec![
                status.layout(
                    Layout::column()
                        .width(Length::Fraction(status_share))
                        .height(Length::Fill)
                        .padding(Insets::symmetric(22.0, 20.0))
                        .gap(8.0),
                ),
                automatic,
            ])
        }
        None => status,
    };
    let mut sections = vec![workbench];
    sections.extend(notes);
    (
        update_list(state, heading, with_heights(sections), room, gap, overhang),
        layout,
    )
}

fn update_list(
    state: &SettingsViewState,
    mut heading: Vec<UiNode>,
    sections: Vec<(UiNode, f32)>,
    room: f32,
    gap: f32,
    overhang: scroll::Overhang,
) -> Vec<UiNode> {
    heading.push(scroll::list_page_peeking(
        state,
        "updates/list",
        "Software Update",
        sections
            .into_iter()
            .map(|(node, height)| ListItem::of(node, height))
            .collect(),
        room,
        gap,
        overhang,
    ));
    heading
}

fn with_heights(sections: Vec<UiNode>) -> Vec<(UiNode, f32)> {
    sections
        .into_iter()
        .map(|node| {
            let height = fixed_height(&node);
            (node, height)
        })
        .collect()
}

const MAX_PACKAGE_PROGRAM_ROWS: usize = 16;

const fn packages_reason_wrap_chars(width: SettingsWidth) -> usize {
    match width {
        SettingsWidth::Compact => 56,
        SettingsWidth::Medium | SettingsWidth::Wide => 96,
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ProgramLine {
    key: String,
    text: String,
    continuation: bool,
    quiet: bool,
    state: Option<String>,
}

fn packages_program_lines(packages: &PackagesProjection, width: SettingsWidth) -> Vec<ProgramLine> {
    let plain = |key: &str, text: String| ProgramLine {
        key: key.to_string(),
        text,
        continuation: false,
        quiet: false,
        state: None,
    };
    if !packages.observed {
        return vec![plain(
            "packages/programs/loading",
            "Reading package status…".to_string(),
        )];
    }
    if packages.programs.is_empty() {
        return vec![plain(
            "packages/programs/empty",
            "No managed programs installed.".to_string(),
        )];
    }
    let mut lines = Vec::new();
    let mut shown = 0usize;
    for row in &packages.programs {
        if shown >= MAX_PACKAGE_PROGRAM_ROWS {
            break;
        }
        shown += 1;
        let wrap = packages_reason_wrap_chars(width);
        let mut text = package_program_display_name(&row.name);
        let plain = crate::packages_screen::plain_state(&row.kind, &row.state);
        let show_state = match row.words.as_ref() {
            Some(words) => {
                text.push_str(FACT_SEPARATOR);
                text.push_str(&words.summary);
                plain.is_none()
            }
            None => {
                if let Some(build) = row.installed_build {
                    text.push_str(FACT_SEPARATOR);
                    text.push_str(&atpkg::vendor_direct::build_words(build));
                }
                if let Some(plain) = plain.as_deref() {
                    text.push_str(FACT_SEPARATOR);
                    text.push_str(plain);
                }
                plain.is_none()
            }
        };
        let mut tail = String::new();
        if let Some(facts) = row.facts.as_ref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(&facts.line());
        }
        if let Some(upstream) = row.upstream.as_deref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(upstream);
        }
        if let Some(annotation) = row.annotation.as_deref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(annotation);
        }
        let state_lines = if show_state && !row.state.is_empty() {
            crate::packages_screen::reason_lines(&row.state, wrap)
        } else {
            Vec::new()
        };
        let inline_state = state_lines.len() == 1
            && crate::packages_screen::fits_one_line(
                &format!("{text}{FACT_SEPARATOR}{}{tail}", row.state),
                wrap,
            );
        if inline_state {
            text.push_str(FACT_SEPARATOR);
            text.push_str(&row.state);
        }
        let below = if inline_state {
            Vec::new()
        } else {
            state_lines
        };
        let detail = row.words.as_ref().and_then(|w| w.detail.clone());
        let detail_lines = match detail {
            Some(detail)
                if below.is_empty()
                    && crate::packages_screen::fits_one_line(
                        &format!("{text}{FACT_SEPARATOR}{detail}{tail}"),
                        wrap,
                    ) =>
            {
                text.push_str(FACT_SEPARATOR);
                text.push_str(&detail);
                Vec::new()
            }
            Some(detail) => packages_detail_lines(&detail, wrap),
            None => Vec::new(),
        };
        let tail_lines = if tail.is_empty()
            || crate::packages_screen::fits_one_line(&format!("{text}{tail}"), wrap)
        {
            text.push_str(&tail);
            Vec::new()
        } else {
            packages_detail_lines(tail.trim_start_matches(FACT_SEPARATOR), wrap)
        };
        lines.push(ProgramLine {
            key: format!("packages/programs/{}", row.name),
            text,
            continuation: false,
            quiet: false,
            state: (!show_state && !row.state.is_empty()).then(|| row.state.clone()),
        });
        lines.extend(
            below
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: format!("packages/programs/{}/reason/{}", row.name, index + 1),
                    text,
                    continuation: true,
                    quiet: false,
                    state: None,
                }),
        );
        let facts = tail_lines.len() > 1;
        lines.extend(
            tail_lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: if facts {
                        format!("packages/programs/{}/facts/{}", row.name, index + 1)
                    } else {
                        format!("packages/programs/{}/facts", row.name)
                    },
                    text,
                    continuation: true,
                    quiet: false,
                    state: None,
                }),
        );
        let many = detail_lines.len() > 1;
        lines.extend(
            detail_lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: if many {
                        format!("packages/programs/{}/detail/{}", row.name, index + 1)
                    } else {
                        format!("packages/programs/{}/detail", row.name)
                    },
                    text,
                    continuation: true,
                    quiet: true,
                    state: None,
                }),
        );
    }
    let total = packages.programs.len();
    if total > shown {
        lines.push(plain(
            "packages/programs/more",
            format!(
                "… and {} more (aterm pkg list shows them all)",
                total - shown
            ),
        ));
    }
    lines
}

fn packages_program_line_node(line: &ProgramLine, row_height: f32) -> UiNode {
    let painted = UiContent::Text(TextSpec {
        text: line.text.clone(),
        role: SemanticRole::Status,
        style: if line.quiet {
            StyleRef::Quiet
        } else {
            StyleRef::Primary
        },
    });
    let text = match line.state.as_deref() {
        Some(state) => program_state_node(line.key.clone(), painted, &line.text, state),
        None => UiNode::new(line.key.clone(), painted),
    };
    text.layout(Layout::default().height(Length::Fixed(row_height)))
}

fn program_state_node(key: String, painted: UiContent, words: &str, state: &str) -> UiNode {
    UiNode::new(
        key.clone(),
        UiContent::Group(GroupSpec {
            label: Some(format!("{words}\n{state}")),
            role: SemanticRole::Status,
            style: StyleRef::Plain,
        }),
    )
    .children(vec![
        UiNode::new(format!("{key}/text"), painted)
            .layout(Layout::default().height(Length::Fill))
            .paint_only(),
    ])
}

fn packages_detail_lines(detail: &str, wrap: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    for part in detail.split(FACT_SEPARATOR) {
        match lines.last_mut() {
            Some(line)
                if crate::packages_screen::fits_one_line(
                    &format!("{line}{FACT_SEPARATOR}{part}"),
                    wrap,
                ) =>
            {
                line.push_str(FACT_SEPARATOR);
                line.push_str(part);
            }
            _ => lines.push(part.to_string()),
        }
    }
    lines
}

const fn packages_has_service_line(packages: &PackagesProjection) -> bool {
    packages.observed
        && packages.available
        && packages.manager_enabled
        && !packages.index_source.is_empty()
}

