fn messages_chip_words(label: &str, width: f32) -> (String, usize) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |line: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, line, px).max(
            crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, line, px),
        )
    };
    let lines = wrap_to_box(label, (width - 20.0).max(0.0), &measure);
    let count = lines.len();
    (lines.join("\n"), count)
}

fn messages_chip_height(label: &str, width: f32, single: f32) -> f32 {
    crate::native_ui::native_button_height_for_lines(messages_chip_words(label, width).1, single)
}

fn messages_tag_chip_rows(
    messages: &MessagesState,
    filter: &MessagesFilter,
    content_width: f32,
    chip_h: f32,
    first: Option<(UiNode, f32)>,
) -> Vec<UiNode> {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |label: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, label, px).max(
            crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, label, px),
        ) + 26.0
    };
    let mut chips: Vec<(String, String, bool)> = vec![(
        MESSAGES_TAGS_ALL.to_string(),
        aterm_messages::page::ALL_TAGS.to_string(),
        filter.tag.is_none(),
    )];
    chips.extend(messages.chips(filter.warn_only).into_iter().map(|chip| {
        (
            format!("settings/messages/filter/tag/{}", chip.tag),
            chip.label(),
            filter
                .tag
                .as_deref()
                .is_some_and(|t| messages_same_chip(t, &chip.tag)),
        )
    }));
    let indent = first.as_ref().map_or(0.0, |(_, width)| width + 6.0);
    let room = (content_width - indent).max(48.0);
    let widths: Vec<f32> = chips
        .iter()
        .map(|(_, label, _)| measure(label).min(room))
        .collect();
    let mut chips = chips.into_iter().zip(widths.iter().copied());
    let lead_h = first
        .as_ref()
        .map_or(chip_h, |(node, _)| fixed_height(node).max(chip_h));
    let mut lead = first.map(|(node, _)| node);
    messages_chip_row_lengths(&widths, 6.0, room)
        .into_iter()
        .enumerate()
        .map(|(index, len)| {
            let mut children: Vec<UiNode> = lead.take().into_iter().collect();
            let mut row_h = if index == 0 { lead_h } else { chip_h };
            children.extend(
                chips
                    .by_ref()
                    .take(len)
                    .map(|((key, label, selected), width)| {
                        row_h = row_h.max(messages_chip_height(&label, width, chip_h));
                        let mut chip = messages_filter_chip(&key, &label, selected, width);
                        chip.layout.height = Length::Fill;
                        chip
                    }),
            );
            UiNode::new(
                format!("settings/messages/filters/row/{index}"),
                UiContent::Group(GroupSpec::new("Tags")),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(row_h + 6.0))
                    .padding(Insets {
                        top: 3.0,
                        right: 0.0,
                        bottom: 3.0,
                        left: if index == 0 { 0.0 } else { indent },
                    })
                    .gap(6.0),
            )
            .children(children)
        })
        .collect()
}

fn messages_chip_row_lengths(widths: &[f32], gap: f32, room: f32) -> Vec<usize> {
    let pack = |cap: f32| {
        let mut rows: Vec<usize> = Vec::new();
        let mut used = 0.0_f32;
        for &width in widths {
            match rows.last_mut() {
                Some(len) if used + gap + width <= cap => {
                    *len += 1;
                    used += gap + width;
                }
                _ => {
                    rows.push(1);
                    used = width;
                }
            }
        }
        rows
    };
    let fewest = pack(room).len();
    let (mut lo, mut hi) = (widths.iter().copied().fold(0.0_f32, f32::max), room);
    if hi <= lo {
        return pack(room);
    }
    for _ in 0..24 {
        let mid = f32::midpoint(lo, hi);
        if pack(mid).len() <= fewest {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    pack(hi)
}

